const missing_dependency = @import("missing_dependency");
const MissingText = missing_dependency.Text;
const std = @import("std");
const consume_diagnostics = @import("build_diagnostics");
const blobs = @import("blob_encoder");
const blob_format = blobs.blob_format;
const blob_catalog = blobs.blob_catalog;
const language_source = @import("language_source.zig");
const presentation_document = @import("presentation_document.zig");

const language_bucket_count = 32;
/// Edition-aware routing is resolved once by the caller. Namespace IDs alone
/// cannot identify a lexical feature across different Wiktionaries.
pub const PageNamespace = struct { id: u32, kind: blob_format.BlobKind };

pub const BuildStats = struct {
    pages_seen: usize = 0,
    main_pages: usize = 0,
    language_records: usize = 0,
    thesaurus_records: usize = 0,
    citations_records: usize = 0,
    reconstruction_records: usize = 0,
    rhymes_records: usize = 0,
    sign_gloss_records: usize = 0,
    supplemental_records: usize = 0,
    language_blobs: usize = 0,
    fallback_pages: usize = 0,
    alias_records: usize = 0,
};

pub const ResolvedLanguage = struct {
    code: []const u8,
    heading: []const u8,
};

fn noLanguageCode(_: ?*const anyopaque, _: []const u8) ?[]const u8 {
    return null;
}

pub const SourceSectionHeading = struct { owner: ?ResolvedLanguage };

pub const ScreenStyleArticle = struct {
    page_id: u64,
    revision_id: u64,
    title: []const u8,
    profile: *const @import("table_style_profile.zig").Profile,
};

pub const LanguageCodes = struct {
    local_link_targets: ?@import("presentation_compile.zig").LocalLinkTargetSource = null,
    // A selected page borrows its Profile from the page arena. Retain the stable
    // global parent here so the next page resets without dereferencing that view.
    screen_style_article: ?ScreenStyleArticle = null,
    screen_style_collection: ?struct {
        baseline: *const @import("table_style_profile.zig").Profile,
        articles: []const ScreenStyleArticle,
    } = null,
    page_style_parent: ?*const @import("table_style_profile.zig").Profile = null,
    figure_sizing: ?presentation_document.FigureSizingSource = null,
    table_styles: ?*const @import("table_style_profile.zig").Profile = null,
    behavior_switches: ?*const @import("namespace_registry").behavior_switches.Registry = null,
    image_options: ?*const @import("namespace_registry").image_options.Registry = null,
    namespace_catalog: ?*const @import("namespace_registry").Registry = null,
    ctx: ?*const anyopaque = null,
    get_fn: *const fn (?*const anyopaque, []const u8) ?[]const u8 = noLanguageCode,
    resolve_fn: ?*const fn (?*const anyopaque, []const u8) ?ResolvedLanguage = null,
    trusted_fn: ?*const fn (?*const anyopaque, []const u8) ?ResolvedLanguage = null,
    strong_fn: ?*const fn (?*const anyopaque, []const u8) ?ResolvedLanguage = null,
    content_fn: ?*const fn (?*const anyopaque) ?ResolvedLanguage = null,
    boundary_fn: ?*const fn (?*const anyopaque, []const u8) bool = null,
    source_banner_fn: ?*const fn (?*const anyopaque, []const u8, []const u8, u8) bool = null,
    source_banner_boundary_fn: ?*const fn (?*const anyopaque, []const u8, []const u8, u8) bool = null,
    source_banner_prefix_fn: ?*const fn (?*const anyopaque, []const u8, []const u8, u8, []const u8) bool = null,
    source_equals_fn: ?*const fn (?*const anyopaque, []const u8) ?[]const u8 = null,
    source_static_support_fn: ?*const fn (?*const anyopaque, []const u8) bool = null,
    source_paragraph_fn: ?*const fn (?*const anyopaque, []const u8, []const u8, []const u8) bool = null,
    source_nom_label_fn: ?*const fn (?*const anyopaque, []const u8) ?[]const u8 = null,
    // Selected source formatter only; false retains the complete older grammar.
    source_nom_name_format: bool = false,
    source_naslov_noun: bool = false,
    source_numbered_pos: [2]bool = .{ false, false },
    source_section_fn: ?*const fn (?*const anyopaque, []const u8) ?SourceSectionHeading = null,
    source_headword_fn: ?*const fn (?*const anyopaque, []const u8) ?ResolvedLanguage = null,
    source_headword_static_prefix: ?[]const u8 = null,
    source_linked_heading_fn: ?*const fn (?*const anyopaque, []const u8) ?ResolvedLanguage = null,
    source_category_ctx: ?*anyopaque = null,
    source_category_fn: ?*const fn (?*anyopaque, []const u8) anyerror!?ResolvedLanguage = null,
    source_category_heading_fn: ?*const fn (?*anyopaque, []const u8, []const u8) anyerror!?ResolvedLanguage = null,
    source_category_agreement_fn: ?*const fn (?*anyopaque, []const u8, ResolvedLanguage) anyerror!bool = null,
    link_trail: blobs.document_ir.LinkTrail = .{},

    pub fn code(self: LanguageCodes, heading: []const u8) ?[]const u8 {
        return self.get_fn(self.ctx, heading);
    }

    pub fn resolve(self: LanguageCodes, value: []const u8) ?ResolvedLanguage {
        if (self.resolve_fn) |resolve_fn| return resolve_fn(self.ctx, value);
        const code_value = self.code(value) orelse return null;
        return .{ .code = code_value, .heading = value };
    }

    pub fn resolveTrusted(self: LanguageCodes, value: []const u8) ?ResolvedLanguage {
        if (self.trusted_fn) |trusted_fn| return trusted_fn(self.ctx, value);
        return self.resolve(value);
    }

    pub fn resolveStrong(self: LanguageCodes, value: []const u8) ?ResolvedLanguage {
        if (self.strong_fn) |strong_fn| return strong_fn(self.ctx, value);
        return null;
    }

    pub fn isLanguageBoundary(self: LanguageCodes, heading: []const u8) bool {
        const boundary_fn = self.boundary_fn orelse return false;
        return boundary_fn(self.ctx, heading);
    }

    pub fn content(self: LanguageCodes) ?ResolvedLanguage {
        const content_fn = self.content_fn orelse return null;
        return content_fn(self.ctx);
    }
};

const Mapped = struct {
    bytes: []align(std.heap.page_size_min) const u8,

    fn deinit(self: *Mapped) void {
        if (self.bytes.len != 0) std.posix.munmap(self.bytes);
        self.bytes = &.{};
    }
};

fn mmapPath(io: std.Io, path: []const u8) !Mapped {
    const fd = try std.posix.openat(std.posix.AT.FDCWD, path, .{ .ACCMODE = .RDONLY, .CLOEXEC = true }, 0);
    var file: std.Io.File = .{ .handle = fd, .flags = .{ .nonblocking = false } };
    defer file.close(io);
    const stat = try file.stat(io);
    const len = std.math.cast(usize, stat.size) orelse return error.FileTooBig;
    if (len == 0) return .{ .bytes = &.{} };
    return .{ .bytes = try std.posix.mmap(null, len, .{ .READ = true }, .{ .TYPE = .PRIVATE }, fd, 0) };
}

const SpoolFile = struct {
    file: std.Io.File,
    path: []const u8,
    offset: u64 = 0,

    fn init(io: std.Io, allocator: std.mem.Allocator, path: []const u8) !SpoolFile {
        const file = try std.Io.Dir.cwd().createFile(io, path, .{ .truncate = true });
        errdefer file.close(io);
        return .{
            .file = file,
            .path = try allocator.dupe(u8, path),
        };
    }

    fn close(self: *SpoolFile, io: std.Io) void {
        self.file.close(io);
    }

    fn deinitPath(self: *SpoolFile, allocator: std.mem.Allocator) void {
        allocator.free(self.path);
        self.path = "";
    }

    fn append(
        self: *SpoolFile,
        io: std.Io,
        allocator: std.mem.Allocator,
        key: []const u8,
        title: []const u8,
        payload: []const u8,
    ) !void {
        const spool_phase = consume_diagnostics.beginConsumePhase(.spool);
        defer consume_diagnostics.endConsumePhase(spool_phase);
        const key_len = std.math.cast(u32, key.len) orelse return error.RecordTooBig;
        const title_len = std.math.cast(u32, title.len) orelse return error.RecordTooBig;
        const payload_len = std.math.cast(u32, payload.len) orelse return error.RecordTooBig;
        const total = std.math.add(usize, 12, key.len + title.len + payload.len) catch return error.RecordTooBig;
        const frame = try allocator.alloc(u8, total);
        std.mem.writeInt(u32, frame[0..4], key_len, .little);
        std.mem.writeInt(u32, frame[4..8], title_len, .little);
        std.mem.writeInt(u32, frame[8..12], payload_len, .little);
        var cursor: usize = 12;
        @memcpy(frame[cursor .. cursor + key.len], key);
        cursor += key.len;
        @memcpy(frame[cursor .. cursor + title.len], title);
        cursor += title.len;
        @memcpy(frame[cursor .. cursor + payload.len], payload);
        try self.file.writePositionalAll(io, frame, self.offset);
        self.offset += frame.len;
    }
};

const SpoolFrame = struct {
    key: []const u8,
    title: []const u8,
    payload: []const u8,
};

const SpoolIterator = struct {
    bytes: []const u8,
    cursor: usize = 0,

    fn next(self: *SpoolIterator) error{InvalidSpool}!?SpoolFrame {
        if (self.cursor == self.bytes.len) return null;
        if (self.cursor > self.bytes.len or 12 > self.bytes.len - self.cursor) return error.InvalidSpool;
        const key_len = std.mem.readInt(u32, self.bytes[self.cursor .. self.cursor + 4][0..4], .little);
        const title_len = std.mem.readInt(u32, self.bytes[self.cursor + 4 .. self.cursor + 8][0..4], .little);
        const payload_len = std.mem.readInt(u32, self.bytes[self.cursor + 8 .. self.cursor + 12][0..4], .little);
        self.cursor += 12;
        const total = std.math.add(usize, key_len, @as(usize, title_len) + payload_len) catch return error.InvalidSpool;
        if (total > self.bytes.len - self.cursor) return error.InvalidSpool;
        const key = self.bytes[self.cursor .. self.cursor + key_len];
        self.cursor += key_len;
        const title = self.bytes[self.cursor .. self.cursor + title_len];
        self.cursor += title_len;
        const payload = self.bytes[self.cursor .. self.cursor + payload_len];
        self.cursor += payload_len;
        if (title.len == 0) return error.InvalidSpool;
        return .{ .key = key, .title = title, .payload = payload };
    }
};

const Spools = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    root: []const u8,
    language: [language_bucket_count]SpoolFile,
    thesaurus: SpoolFile,
    citations: SpoolFile,
    reconstruction: SpoolFile,
    rhymes: SpoolFile,
    sign_gloss: SpoolFile,
    supplemental: SpoolFile,
    aliases: SpoolFile,
    language_owners: std.StringHashMapUnmanaged([]const u8) = .empty,

    fn init(io: std.Io, allocator: std.mem.Allocator, output_root: []const u8) !Spools {
        const spool_root = try std.fmt.allocPrint(allocator, "{s}/.spool", .{output_root});
        defer allocator.free(spool_root);
        try std.Io.Dir.cwd().createDirPath(io, spool_root);

        var language: [language_bucket_count]SpoolFile = undefined;
        var built: usize = 0;
        errdefer while (built != 0) {
            built -= 1;
            language[built].close(io);
            language[built].deinitPath(allocator);
        };
        for (&language, 0..) |*slot, idx| {
            const path = try std.fmt.allocPrint(allocator, "{s}/lang-{d:0>2}.tmp", .{ spool_root, idx });
            defer allocator.free(path);
            slot.* = try SpoolFile.init(io, allocator, path);
            built += 1;
        }

        const initFixed = struct {
            fn f(io2: std.Io, a: std.mem.Allocator, root: []const u8, name: []const u8) !SpoolFile {
                const path = try std.fmt.allocPrint(a, "{s}/{s}.tmp", .{ root, name });
                defer a.free(path);
                return SpoolFile.init(io2, a, path);
            }
        }.f;

        const owned_root = try allocator.dupe(u8, spool_root);
        errdefer allocator.free(owned_root);
        const fixed_names = [_][]const u8{ "thesaurus", "citations", "reconstruction", "rhymes", "sign-gloss", "supplemental", "aliases" };
        var fixed: [fixed_names.len]SpoolFile = undefined;
        var fixed_built: usize = 0;
        errdefer while (fixed_built != 0) {
            fixed_built -= 1;
            fixed[fixed_built].close(io);
            fixed[fixed_built].deinitPath(allocator);
        };
        for (fixed_names, 0..) |name, idx| {
            fixed[idx] = try initFixed(io, allocator, spool_root, name);
            fixed_built += 1;
        }

        return .{
            .allocator = allocator,
            .io = io,
            .root = owned_root,
            .language = language,
            .thesaurus = fixed[0],
            .citations = fixed[1],
            .reconstruction = fixed[2],
            .rhymes = fixed[3],
            .sign_gloss = fixed[4],
            .supplemental = fixed[5],
            .aliases = fixed[6],
        };
    }

    fn close(self: *Spools) void {
        for (&self.language) |*spool| spool.close(self.io);
        self.thesaurus.close(self.io);
        self.citations.close(self.io);
        self.reconstruction.close(self.io);
        self.rhymes.close(self.io);
        self.sign_gloss.close(self.io);
        self.supplemental.close(self.io);
        self.aliases.close(self.io);
    }

    fn cleanup(self: *Spools) void {
        var owners = self.language_owners.iterator();
        while (owners.next()) |owner| {
            self.allocator.free(owner.key_ptr.*);
            self.allocator.free(owner.value_ptr.*);
        }
        self.language_owners.deinit(self.allocator);
        for (&self.language) |*spool| {
            std.Io.Dir.cwd().deleteFile(self.io, spool.path) catch {};
            spool.deinitPath(self.allocator);
        }
        inline for (.{ &self.thesaurus, &self.citations, &self.reconstruction, &self.rhymes, &self.sign_gloss, &self.supplemental, &self.aliases }) |spool| {
            std.Io.Dir.cwd().deleteFile(self.io, spool.path) catch {};
            spool.deinitPath(self.allocator);
        }
        std.Io.Dir.cwd().deleteDir(self.io, self.root) catch {};
        self.allocator.free(self.root);
        self.root = "";
    }

    fn appendLanguage(self: *Spools, allocator: std.mem.Allocator, owner: ResolvedLanguage, title: []const u8, payload: []const u8) !void {
        // Source-proved names need not be ordinary heading aliases. Retain the
        // resolved identity across page arenas and finalization, never resolve
        // its display name again or merge disagreeing owners under one heading.
        var inserted = false;
        errdefer if (inserted) {
            const removed = self.language_owners.fetchRemove(owner.heading).?;
            self.allocator.free(removed.key);
            self.allocator.free(removed.value);
        };
        if (self.language_owners.get(owner.heading)) |code_value| {
            if (!std.mem.eql(u8, code_value, owner.code)) return error.ConflictingLanguageOwner;
        } else {
            const heading = try self.allocator.dupe(u8, owner.heading);
            errdefer self.allocator.free(heading);
            const code_value = try self.allocator.dupe(u8, owner.code);
            errdefer self.allocator.free(code_value);
            try self.language_owners.put(self.allocator, heading, code_value);
            inserted = true;
        }
        const bucket: usize = @intCast(std.hash.Wyhash.hash(0, owner.heading) % language_bucket_count);
        try self.language[bucket].append(self.io, allocator, owner.heading, title, payload);
    }
};

fn localNamespaceTitle(title: []const u8) []const u8 {
    const colon = std.mem.indexOfScalar(u8, title, ':') orelse return title;
    if (colon + 1 >= title.len) return title;
    return title[colon + 1 ..];
}

pub fn languageBlobPathAlloc(allocator: std.mem.Allocator, output_root: []const u8, heading: []const u8) ![]u8 {
    var filename_buf: [blob_catalog.language_blob_filename_len]u8 = undefined;
    const filename = blob_catalog.languageBlobFilename(heading, &filename_buf);
    return std.fmt.allocPrint(allocator, "{s}/{s}/{s}", .{ output_root, blob_catalog.language_directory, filename });
}

fn fixedBlobPathAlloc(allocator: std.mem.Allocator, output_root: []const u8, name: []const u8) ![]u8 {
    return std.fmt.allocPrint(allocator, "{s}/{s}.wikblb", .{ output_root, name });
}

fn recordLess(_: void, lhs: blob_format.RecordInput, rhs: blob_format.RecordInput) bool {
    return std.mem.order(u8, lhs.title, rhs.title) == .lt;
}

fn sortAndValidate(records: []blob_format.RecordInput) !void {
    if (records.len < 2) return;
    std.sort.pdq(blob_format.RecordInput, records, {}, recordLess);
    for (records[1..], records[0..records.len -| 1]) |current, previous| {
        if (std.mem.order(u8, previous.title, current.title) != .lt) return error.DuplicateRecord;
    }
}

fn writeBlobFile(
    io: std.Io,
    path: []const u8,
    kind: blob_format.BlobKind,
    metadata: []const u8,
    records: []blob_format.RecordInput,
    observer: ?RecordObserver,
) !void {
    try sortAndValidate(records);
    try blob_format.validateMetadata(kind, metadata);
    for (records) |record| try blob_format.validateRecordInput(record);
    const header = blob_format.encodeHeader(kind);

    var file = try std.Io.Dir.cwd().createFile(io, path, .{ .truncate = true });
    defer file.close(io);
    var buffer: [256 * 1024]u8 = undefined;
    var writer = file.writer(io, &buffer);
    const w = &writer.interface;
    try w.writeAll(&header);
    try w.writeAll(metadata);
    for (records) |record| {
        try w.writeAll(record.title);
        try w.writeByte(0);
        var length_buf: [blob_format.max_varuint_len]u8 = undefined;
        try w.writeAll(blob_format.encodePayloadLength(record.payload.len, &length_buf));
        try w.writeAll(record.payload);
        if (observer) |watch| try watch.observe(watch.ctx, kind, record);
    }
    try w.flush();
}

fn collectFixedRecordsAlloc(allocator: std.mem.Allocator, mapped: []const u8) ![]blob_format.RecordInput {
    var records: std.ArrayList(blob_format.RecordInput) = .empty;
    defer records.deinit(allocator);
    var it: SpoolIterator = .{ .bytes = mapped };
    while (try it.next()) |frame| {
        if (frame.key.len != 0) return error.InvalidSpool;
        try records.append(allocator, .{ .title = frame.title, .payload = frame.payload });
    }
    return records.toOwnedSlice(allocator);
}

fn finalizeFixedSpool(
    io: std.Io,
    allocator: std.mem.Allocator,
    spool: *const SpoolFile,
    output_root: []const u8,
    name: []const u8,
    kind: blob_format.BlobKind,
    observer: ?RecordObserver,
) !void {
    var mapped = try mmapPath(io, spool.path);
    defer mapped.deinit();
    const records = try collectFixedRecordsAlloc(allocator, mapped.bytes);
    defer allocator.free(records);
    if (records.len == 0) return;
    const path = try fixedBlobPathAlloc(allocator, output_root, name);
    defer allocator.free(path);
    try writeBlobFile(io, path, kind, "", records, observer);
}

const LanguageGroup = struct {
    heading: []const u8,
    records: std.ArrayListUnmanaged(blob_format.RecordInput) = .empty,
};

fn finalizeLanguageBucket(
    io: std.Io,
    allocator: std.mem.Allocator,
    spool: *const SpoolFile,
    output_root: []const u8,
    manifest: *std.ArrayList([]const u8),
    owners: *const std.StringHashMapUnmanaged([]const u8),
    observer: ?RecordObserver,
) !usize {
    var mapped = try mmapPath(io, spool.path);
    defer mapped.deinit();
    if (mapped.bytes.len == 0) return 0;

    var groups = std.StringHashMapUnmanaged(LanguageGroup){};
    defer {
        var values = groups.valueIterator();
        while (values.next()) |group| group.records.deinit(allocator);
        groups.deinit(allocator);
    }
    var it: SpoolIterator = .{ .bytes = mapped.bytes };
    while (try it.next()) |frame| {
        if (frame.key.len == 0) return error.InvalidSpool;
        const gop = try groups.getOrPut(allocator, frame.key);
        if (!gop.found_existing) gop.value_ptr.* = .{ .heading = frame.key };
        try gop.value_ptr.records.append(allocator, .{ .title = frame.title, .payload = frame.payload });
    }

    var ordered: std.ArrayList(*LanguageGroup) = .empty;
    defer ordered.deinit(allocator);
    var values = groups.valueIterator();
    while (values.next()) |group| try ordered.append(allocator, group);
    const lessGroup = struct {
        fn f(_: void, lhs: *LanguageGroup, rhs: *LanguageGroup) bool {
            return std.mem.order(u8, lhs.heading, rhs.heading) == .lt;
        }
    }.f;
    std.sort.pdq(*LanguageGroup, ordered.items, {}, lessGroup);

    var count: usize = 0;
    for (ordered.items) |group| {
        const code_value = owners.get(group.heading) orelse return error.InvalidSpool;
        const metadata = try blob_format.buildLanguageMetadataAlloc(allocator, code_value, group.heading);
        defer allocator.free(metadata);
        const path = try languageBlobPathAlloc(allocator, output_root, group.heading);
        defer allocator.free(path);
        try writeBlobFile(io, path, .language, metadata, group.records.items, observer);
        const heading = try allocator.dupe(u8, group.heading);
        errdefer allocator.free(heading);
        try manifest.append(allocator, heading);
        count += 1;
    }
    return count;
}

fn resolveTrimmed(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    // Apostrophes can belong to an exact registered name, such as Urak Lawoi'.
    if (codes.resolve(std.mem.trim(u8, value, " \t\r\n"))) |resolved| return resolved;
    const candidate = std.mem.trim(u8, value, " \t\r\n'\"[]");
    if (candidate.len == 0) return null;
    return codes.resolve(candidate);
}

fn resolveTemplateName(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const trimmed = std.mem.trim(u8, value, " \t\r\n=-");
    if (resolveTrimmed(codes, trimmed)) |resolved| return resolved;

    var end_at = trimmed.len;
    while (std.mem.lastIndexOfScalar(u8, trimmed[0..end_at], ' ')) |space| {
        const prefix = std.mem.trim(u8, trimmed[0..space], " \t");
        if (resolveTrimmed(codes, prefix)) |resolved| return resolved;
        end_at = space;
    }
    var start_at: usize = 0;
    while (std.mem.indexOfScalarPos(u8, trimmed, start_at, ' ')) |space| {
        start_at = space + 1;
        const suffix = std.mem.trim(u8, trimmed[start_at..], " \t");
        if (resolveTrimmed(codes, suffix)) |resolved| return resolved;
    }
    return null;
}

fn resolveTemplateCandidates(codes: LanguageCodes, text: []const u8) ?ResolvedLanguage {
    const syntax = blobs.wikitext_syntax;
    var search: usize = 0;
    while (search < text.len) {
        if (syntax.protectedEnd(text, search)) |end| {
            search = end;
            continue;
        }
        if (text[search] == '<') if (syntax.tagAt(text, search)) |tag| {
            search = tag.end;
            continue;
        };
        if (!std.mem.startsWith(u8, text[search..], "{{")) {
            search += 1;
            continue;
        }
        const pair = syntax.balanced(text, search) orelse return null;
        const body = text[search + 2 .. pair.inner_end];
        // Nested calls are not independent evidence that the outer call renders a language.
        if (std.mem.indexOf(u8, body, "{{") == null) {
            const name_end = syntax.delimiter(body, "|", 0) orelse body.len;
            // This installed source role requires its paired emitted heading.
            // A rejected formatter must not recover ownership from an argument.
            if (codes.source_nom_label_fn != null and std.mem.eql(u8, std.mem.trim(u8, body[0..name_end], " \t\r\n"), "langue")) {
                search = pair.end;
                continue;
            }
            if (resolveTemplateName(codes, body[0..name_end])) |resolved| return resolved;
            var field_start = @min(name_end + 1, body.len);
            while (field_start < body.len) {
                const field_end = syntax.delimiter(body, "|", field_start) orelse body.len;
                const field = body[field_start..field_end];
                const eq = syntax.delimiter(field, "=", 0);
                const candidate = if (eq) |at| field[at + 1 ..] else field;
                if (resolveTrimmed(codes, candidate)) |resolved| return resolved;
                field_start = @min(field_end + 1, body.len);
            }
        }
        search = pair.end;
    }
    return null;
}

fn valueConfirmsLanguage(codes: LanguageCodes, value_source: []const u8, wanted: []const u8) bool {
    const exact = std.mem.trim(u8, value_source, " \t\r\n");
    if (exact.len == 0) return false;
    const value = std.mem.trim(u8, value_source, " \t\r\n=-\'\"[]");
    const resolved = codes.resolve(exact) orelse codes.resolve(value) orelse return false;
    return std.mem.eql(u8, resolved.code, wanted);
}

// SIMPLE's published entry-format policy uses English POS headings instead of
// language headings. This requires independently trusted English and exact raw
// and expanded physical POS roots; content-language alone grants no owner.
fn simpleEnglishPosCandidate(codes: LanguageCodes, raw: []const language_source.Section, rendered: []const language_source.Section, aligned: bool) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.wiki, "simplewiktionary") or
        !aligned or raw.len == 0 or raw.len != rendered.len) return null;
    const trusted = codes.trusted_fn orelse return null;
    const english = trusted(codes.ctx, "English") orelse return null;
    if (!std.mem.eql(u8, english.code, "en")) return null;
    for (raw, rendered) |authored, expanded| {
        // Cheap candidates only: renderer-established root scope is checked
        // separately before this authority can be used for an unresolved page.
        if (!language_source.literalL2Section(authored, null) or
            !language_source.literalL2Section(expanded, null)) return null;
        const raw_pos = @import("presentation_layout.zig").partOfSpeech(authored.heading) orelse return null;
        const expanded_pos = @import("presentation_layout.zig").partOfSpeech(expanded.heading) orelse return null;
        // Localized POS aliases added for other editions organize existing
        // owners; they are not additional SIMPLE format declarations.
        if (!@import("blob_encoder").part_kind.named(authored.heading, raw_pos) or
            !@import("blob_encoder").part_kind.named(expanded.heading, expanded_pos)) return null;
        if (!std.mem.eql(u8, raw_pos, expanded_pos) or
            codes.isLanguageBoundary(authored.heading) or codes.isLanguageBoundary(expanded.heading) or
            codes.resolve(authored.heading) != null or codes.resolve(expanded.heading) != null) return null;
    }
    return english;
}

fn simpleRawProofUnavailable(err: anyerror) anyerror!?presentation_document.HeadingObservation {
    // Only optional UNEXPANDED raw observation uses this narrow boundary.
    switch (err) {
        error.RenderLimit, error.UncompiledTemplate => return null,
        else => return err,
    }
}
fn simpleRawHeadingProof(a: std.mem.Allocator, codes: LanguageCodes, title: []const u8, raw: []const u8) !?presentation_document.HeadingObservation {
    // This optional raw-syntax probe may be declined by its caller. Its
    // validation must not become evidence for a later fatal expanded field.
    const rejection_scope = presentation_document.RejectedFieldCapture.suspendCapture();
    defer rejection_scope.deinit();
    const references = presentation_document.referenceDefinitionsAlloc(a, raw) catch |err| return simpleRawProofUnavailable(err);
    const observed = presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(
        a, title, MissingText.untracked(raw), codes.link_trail, codes.namespace_catalog,
        codes.behavior_switches, codes.image_options, references, null, true,
    ) catch |err| return simpleRawProofUnavailable(err);
    // Soft limits also decline the proof. Opaque raw template tokens do not
    // establish ownership, but their presence alone is not a traversal limit.
    return if (observed.page_wiki_scope_complete) observed else null;
}
// One optional raw proof belongs to this page's heading arena. A declined
// proof is a completed observation too; fatal errors never publish a result.
const PageRawHeadingProof = struct {
    a: std.mem.Allocator,
    codes: LanguageCodes,
    title: []const u8,
    raw: ?[]const u8,
    evaluated: bool = false,
    observation: ?presentation_document.HeadingObservation = null,

    fn get(self: *PageRawHeadingProof) !?presentation_document.HeadingObservation {
        if (!self.evaluated) {
            self.observation = if (self.raw) |raw|
                simpleRawHeadingProof(self.a, self.codes, self.title, raw) catch |err| switch (err) {
                    error.UncompiledPresentation => null,
                    else => return err,
                }
            else
                null;
            self.evaluated = true;
        }
        return self.observation;
    }
};

fn simpleApplyRootScope(source: []const u8, sections: []language_source.Section, openings: []const usize) void {
    const scopes: language_source.LinkHeadingScopes = .{ .source = source, .openings = openings };
    for (sections) |*section| {
        section.root_wiki_heading = false;
        const start = std.math.sub(usize, @intFromPtr(section.source.ptr), @intFromPtr(source.ptr)) catch continue;
        if (start <= source.len and section.source.len <= source.len - start)
            section.root_wiki_heading = scopes.admits(source, start);
    }
}

fn simpleApplyRootRules(source: []const u8, sections: []language_source.Section, openings: []const usize) void {
    const scopes: language_source.LinkHeadingScopes = .{ .source = source, .openings = openings };
    for (sections) |*section| {
        section.adjacent_root_rule = null;
        if (!section.root_wiki_heading) continue;
        const rule = language_source.adjacentPhysicalRule(source, section.*) orelse continue;
        if (scopes.admits(source, rule.start)) section.adjacent_root_rule = rule.start;
    }
}

fn sourceConfirmsLanguage(codes: LanguageCodes, source: []const u8, wanted: []const u8) bool {
    const limit = @min(source.len, 4096);
    var search: usize = 0;
    const bounded = source[0..limit];
    while (search < bounded.len) {
        const open = if (std.mem.indexOfAny(u8, bounded[search..], "<{")) |relative| search + relative else break;
        if (bounded[open] == '<') {
            if (blobs.wikitext_syntax.protectedEnd(bounded, open)) |end| {
                search = end;
                continue;
            }
            if (blobs.wikitext_syntax.tagAt(bounded, open)) |tag| {
                search = tag.end;
                continue;
            }
        }
        if (!std.mem.startsWith(u8, bounded[open..], "{{")) {
            search = open + 1;
            continue;
        }
        const close = std.mem.indexOfPos(u8, source[0..limit], open + 2, "}}") orelse break;
        const body = source[open + 2 .. close];
        if (std.mem.indexOf(u8, body, "{{") == null) {
            var fields = std.mem.splitScalar(u8, body, '|');
            if (fields.next()) |name| {
                if (valueConfirmsLanguage(codes, name, wanted)) return true;
                const trimmed_name = std.mem.trim(u8, name, " \t\r\n=-");
                if (std.mem.indexOfScalar(u8, trimmed_name, '-')) |dash| {
                    if (valueConfirmsLanguage(codes, trimmed_name[0..dash], wanted)) return true;
                    if (dash + 1 < trimmed_name.len and valueConfirmsLanguage(codes, trimmed_name[dash + 1 ..], wanted)) return true;
                }
                while (fields.next()) |field| {
                    const eq = std.mem.indexOfScalar(u8, field, '=');
                    if (eq == null) {
                        if (valueConfirmsLanguage(codes, field, wanted)) return true;
                        continue;
                    }
                    const key = std.mem.trim(u8, field[0..eq.?], " \t");
                    if (std.ascii.eqlIgnoreCase(key, "lang") or
                        std.ascii.eqlIgnoreCase(key, "language") or
                        std.ascii.eqlIgnoreCase(key, "code"))
                    {
                        if (valueConfirmsLanguage(codes, field[eq.? + 1 ..], wanted)) return true;
                    }
                }
            }
        }
        search = close + 2;
    }
    return false;
}

// AM entries also write their explicit category-language heading as an
// external link to this edition. Require its captured current-wiki URL and
// agreement between the category title and the complete visible language name.
fn resolveAmExternalCategoryHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "am") or value.len > 4096) return null;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    if (!std.mem.startsWith(u8, heading, "[") or std.mem.startsWith(u8, heading, "[[") or
        !std.mem.endsWith(u8, heading, "]")) return null;
    const body = heading[1 .. heading.len - 1];
    if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null) return null;
    const separator = std.mem.indexOfAny(u8, body, " \t") orelse return null;
    const url = body[0..separator];
    const label = std.mem.trim(u8, body[separator + 1 ..], " \t");
    const displayed = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return null;
    for (namespaces.interwiki_rows) |row| {
        if (!row.is_current_wiki) continue;
        const marker = std.mem.indexOf(u8, row.url, "$1") orelse continue;
        const prefix = row.url[0..marker];
        const suffix = row.url[marker + 2 ..];
        if (std.mem.indexOf(u8, suffix, "$1") != null or
            url.len < prefix.len + suffix.len or
            !std.mem.startsWith(u8, url, prefix) or !std.mem.endsWith(u8, url, suffix)) continue;
        const encoded = url[prefix.len .. url.len - suffix.len];
        if (encoded.len == 0 or std.mem.indexOfAny(u8, encoded, "?#") != null) return null;
        var buffer: [4096]u8 = undefined;
        @memcpy(buffer[0..encoded.len], encoded);
        const decoded = std.Uri.percentDecodeInPlace(buffer[0..encoded.len]);
        const title = namespaces.ofTitle(decoded);
        if (title.id != 14) return null;
        const name = std.mem.trim(u8, title.text, " \t\r\n");
        const target = codes.resolveStrong(name) orelse codes.resolveTrusted(name) orelse return null;
        return if (std.mem.eql(u8, target.code, displayed.code)) displayed else null;
    }
    return null;
}

// An observed static SVG icon contributes no language authority. Both complete
// linked names must independently resolve through the existing trusted registry.
fn resolveNeutralIconLinkedHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    if (heading.len > 4096 or !std.unicode.utf8ValidateSlice(heading) or
        !std.mem.startsWith(u8, heading, "[[")) return null;
    const icon_end = std.mem.indexOf(u8, heading, "]]") orelse return null;
    const icon = heading[2..icon_end];
    if (std.mem.indexOfAny(u8, icon, "[]{}<>&#\r\n") != null) return null;
    const pipe = std.mem.indexOfScalar(u8, icon, '|') orelse return null;
    const file_target = icon[0..pipe];
    const file = namespaces.ofTitle(file_target);
    if (file.id != 6 or std.mem.trim(u8, file.text, " \t").len == 0 or
        !std.ascii.endsWithIgnoreCase(file.text, ".svg")) return null;
    var options = std.mem.splitScalar(u8, icon[pipe + 1 ..], '|');
    var size = options.next() orelse return null;
    if (std.mem.eql(u8, size, "border")) size = options.next() orelse return null;
    if (options.next() != null or size.len < 3 or !std.mem.endsWith(u8, size, "px")) return null;
    const digits = size[0 .. size.len - 2];
    for (digits) |digit| if (digit < '0' or digit > '9') return null;
    const width = std.fmt.parseInt(u16, digits, 10) catch return null;
    if (width == 0 or width > 4096) return null;
    const suffix = heading[icon_end + 2 ..];
    if (suffix.len == 0 or suffix[0] != ' ') return null;
    const linked = std.mem.trim(u8, suffix, " ");
    if (!std.mem.startsWith(u8, linked, "[[") or !std.mem.endsWith(u8, linked, "]]")) return null;
    const body = linked[2 .. linked.len - 2];
    if (std.mem.indexOfAny(u8, body, "[]{}<>&#:\r\n\t\"'") != null) return null;
    const separator = std.mem.indexOfScalar(u8, body, '|') orelse return null;
    const target = std.mem.trim(u8, body[0..separator], " ");
    const label = std.mem.trim(u8, body[separator + 1 ..], " ");
    if (std.mem.indexOfScalar(u8, label, '|') != null or target.len == 0 or label.len == 0) return null;
    const owner = codes.resolveStrong(target) orelse codes.resolveTrusted(target) orelse return null;
    const displayed = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return null;
    return if (std.mem.eql(u8, owner.code, displayed.code)) owner else null;
}

fn resolveLinkedHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    if (resolveNeutralIconLinkedHeading(codes, value)) |resolved| return resolved;
    if (resolveAmExternalCategoryHeading(codes, value)) |resolved| return resolved;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    if (!std.mem.startsWith(u8, heading, "[[") or !std.mem.endsWith(u8, heading, "]]")) return null;
    const body = heading[2 .. heading.len - 2];
    if (std.mem.indexOfAny(u8, body, "[]{}<>") != null) return null;
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
    var target = std.mem.trim(u8, body[0..pipe], " \t\r\n");
    if (std.mem.startsWith(u8, target, ":")) target = std.mem.trim(u8, target[1..], " \t");
    // A section fragment controls navigation, not the language named by the page.
    if (std.mem.indexOfScalar(u8, target, '#')) |fragment|
        target = std.mem.trim(u8, target[0..fragment], " \t\r\n");
    if (target.len == 0) return null;
    if (codes.namespace_catalog) |namespaces| {
        const title = namespaces.ofTitle(target);
        if (title.id == 14 and std.mem.eql(u8, namespaces.content_language, "am"))
            target = std.mem.trim(u8, title.text, " \t\r\n");
    }
    const arabic = if (codes.namespace_catalog) |namespaces| std.mem.eql(u8, namespaces.content_language, "ar") else false;
    const exact_target = codes.resolveStrong(target) orelse codes.resolveTrusted(target);
    var target_buffer: [256]u8 = undefined;
    const resolved = exact_target orelse blk: {
        if (!arabic) return null;
        const normalized = arabicDeclarationToken(target, &target_buffer) orelse return null;
        break :blk codes.resolveStrong(normalized) orelse codes.resolveTrusted(normalized) orelse return null;
    };
    if (pipe < body.len) {
        const label = std.mem.trim(u8, body[pipe + 1 ..], " \t\r\n");
        if (arabic and std.mem.indexOfScalar(u8, label, '|') != null) return null;
        var displayed = codes.resolveStrong(label) orelse codes.resolveTrusted(label);
        var label_buffer: [256]u8 = undefined;
        if (arabic and displayed == null) {
            if (arabicDeclarationToken(label, &label_buffer)) |normalized| {
                displayed = codes.resolveStrong(normalized) orelse codes.resolveTrusted(normalized);
            }
        }
        if (displayed) |language| {
            if (!std.mem.eql(u8, resolved.code, language.code)) return null;
        } else if (exact_target == null) return null;
    }
    return resolved;
}

// A mixed plain-text/wikilink AR heading can spell an exact registered
// language (e.g. ال[[عربية]]). Resolve that complete visible spelling, and
// require every link target to independently name the same trusted owner.
// No template expansion, entity decoding, category or script inference.
fn resolveMixedArabicLinkedHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "ar") or value.len > 4096) return null;
    const heading = std.mem.trim(u8, value, " \t");
    var visible: [4096]u8 = undefined;
    var length: usize = 0;
    var cursor: usize = 0;
    var linked_owner: ?ResolvedLanguage = null;
    var plain = false;
    while (cursor < heading.len) {
        if (std.mem.startsWith(u8, heading[cursor..], "[[")) {
            const pair = blobs.wikitext_syntax.balanced(heading, cursor) orelse return null;
            const body = heading[cursor + 2 .. pair.inner_end];
            if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null) return null;
            const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
            if (pipe < body.len and std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null) return null;
            const target = std.mem.trim(u8, body[0..pipe], " \t");
            const label = if (pipe < body.len) body[pipe + 1 ..] else target;
            if (target.len == 0 or label.len == 0) return null;
            const owner = codes.resolveStrong(target) orelse codes.resolveTrusted(target) orelse return null;
            if (linked_owner) |previous| if (!std.mem.eql(u8, previous.code, owner.code)) return null;
            linked_owner = owner;
            @memcpy(visible[length .. length + label.len], label);
            length += label.len;
            cursor = pair.end;
        } else {
            const byte = heading[cursor];
            if (std.mem.indexOfScalar(u8, "[]{}<>|=\r\n'", byte) != null) return null;
            if (!std.ascii.isWhitespace(byte)) plain = true;
            visible[length] = byte;
            length += 1;
            cursor += 1;
        }
    }
    if (!plain or linked_owner == null) return null;
    const whole = std.mem.trim(u8, visible[0..length], " \t");
    const owner = codes.resolveStrong(whole) orelse codes.resolveTrusted(whole) orelse return null;
    return if (std.mem.eql(u8, owner.code, linked_owner.?.code)) owner else null;
}

// Frozen AN language templates emit this complete toc declaration. Resolve the
// banner itself; raw support headings can legitimately change boundary counts.
const AnBannerDeclaration = struct { target: []const u8, label: []const u8, suffix: []const u8 };

fn anBannerDeclaration(codes: LanguageCodes, value: []const u8) ?AnBannerDeclaration {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "an") or value.len > 4096) return null;
    const syntax = blobs.wikitext_syntax;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    const outer = syntax.tagAt(heading, 0) orelse return null;
    if (!outer.is("div") or outer.closing or outer.self_closing or
        !std.mem.eql(u8, outer.attr("id") orelse "", "toc") or
        !std.mem.eql(u8, outer.attr("class") orelse "", "toccolours") or
        !std.mem.endsWith(u8, heading, "</div>") or outer.end + 6 > heading.len) return null;
    var rest = std.mem.trim(u8, heading[outer.end .. heading.len - 6], " \t");
    if (std.mem.startsWith(u8, rest, "[[")) {
        const image = syntax.balanced(rest, 0) orelse return null;
        const body = rest[2..image.inner_end];
        const pipe = syntax.delimiter(body, "|", 0) orelse return null;
        if (namespaces.ofTitle(body[0..pipe]).id != 6 or
            !std.mem.eql(u8, std.mem.trim(u8, body[pipe + 1 ..], " \t"), "40px")) return null;
        rest = std.mem.trimStart(u8, rest[image.end..], " \t");
    }
    if (!std.mem.startsWith(u8, rest, "'''''[[")) return null;
    rest = rest[5..];
    const link = syntax.balanced(rest, 0) orelse return null;
    const body = rest[2..link.inner_end];
    const pipe = syntax.delimiter(body, "|", 0) orelse return null;
    if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null or
        std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null) return null;
    var target = std.mem.trim(u8, body[0..pipe], " \t");
    if (std.mem.startsWith(u8, target, "Wiktionary:")) target = target[11..];
    const label = std.mem.trim(u8, body[pipe + 1 ..], " \t");
    rest = std.mem.trimStart(u8, rest[link.end..], " \t");
    if (!std.mem.startsWith(u8, rest, "'''''")) return null;
    rest = std.mem.trimStart(u8, rest[5..], " \t");
    if (rest.len == 0) return .{ .target = target, .label = label, .suffix = "" };
    if (rest.len < 21 or !std.mem.startsWith(u8, rest, "<small>- ''") or !std.mem.endsWith(u8, rest, "''</small>")) return null;
    return .{ .target = target, .label = label, .suffix = rest[11 .. rest.len - 10] };
}

fn resolveAnBannerHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const declaration = anBannerDeclaration(codes, value) orelse return null;
    const language = codes.resolve(declaration.label) orelse return null;
    const target_language = codes.resolve(declaration.target) orelse return null;
    // A complete suffixless declaration is independently authored in AN
    // escoltar (page2904/rev29039). The exact target/label must agree; no
    // trailing text, second link or weak category inference can provide it.
    if (declaration.suffix.len == 0) {
        if (!std.mem.eql(u8, declaration.target, declaration.label) or
            !std.mem.eql(u8, language.code, target_language.code)) return null;
        return language;
    }
    const suffix_language = codes.resolve(declaration.suffix) orelse return null;
    if (!std.mem.eql(u8, language.code, target_language.code) or
        !std.mem.eql(u8, language.code, suffix_language.code)) return null;
    return language;
}

// These thirteen complete AN banners are independently captured declarations.
// Their local names are not necessarily registry aliases; the aligned raw
// hyphen code and exact banner together supply the canonical identity. POS
// abbreviations, arbitrary banners and another edition cannot borrow it.
fn corroboratedAnHyphenMarker(codes: LanguageCodes, raw: language_source.Section, rendered: language_source.Section) bool {
    if (!raw.hyphen_marker) return false;
    const declaration = anBannerDeclaration(codes, rendered.heading) orelse return false;
    const declared = codes.resolve(raw.heading) orelse return false;
    if (!std.mem.eql(u8, declared.code, raw.heading)) return false;
    const rows = [_]struct { code: []const u8, target: []const u8, label: []const u8, suffix: []const u8 }{
        .{ .code = "pms", .target = "Piemontés", .label = "Piemontés", .suffix = "Piemontèis" },
        .{ .code = "lad", .target = "Chodigoespañol", .label = "Chodigoespañol", .suffix = "Djudeoespanyol" },
        .{ .code = "fur", .target = "Friulán", .label = "Friulán", .suffix = "Furlan" },
        .{ .code = "ms", .target = "Malayo", .label = "Malayo", .suffix = "Bahasa Melayu بهاس ملايو" },
        .{ .code = "zh", .target = "Chinés", .label = "Chinés", .suffix = "中文" },
        .{ .code = "th", .target = "Tailandés", .label = "Tailandés", .suffix = "Tailandés" },
        .{ .code = "bg", .target = "Bulgaro", .label = "Bulgaro", .suffix = "Български" },
        .{ .code = "lt", .target = "Lituán", .label = "Lituán", .suffix = "Lietuvių kalba" },
        .{ .code = "tk", .target = "Turquemán", .label = "Turquemán", .suffix = "Türkmençe" },
        .{ .code = "mul", .target = "internacional", .label = "Internacional", .suffix = "" },
        .{ .code = "haw", .target = "Hawayán", .label = "Hawayán", .suffix = "‘Ōlelo Hawai‘i" },
        .{ .code = "rap", .target = "Rapanui", .label = "Rapa nui", .suffix = "Vananga Rapa Nui" },
        .{ .code = "sw", .target = "Swahili", .label = "Swahili", .suffix = "Kiswahili" },
    };
    for (rows) |row| {
        if (std.mem.eql(u8, raw.heading, row.code) and
            std.mem.eql(u8, declaration.target, row.target) and
            std.mem.eql(u8, declaration.label, row.label) and
            std.mem.eql(u8, declaration.suffix, row.suffix)) return true;
    }
    return false;
}

// The Arabic declaration form links the words "in language" before the
// language itself. Require the whole declaration, rather than treating any
// language link inside an arbitrary heading as attribution evidence.
// Orthographic matching is confined to the complete Arabic declaration.
// Original source bytes remain the renderer's input; never normalize lemmas.
fn arabicDeclarationToken(value: []const u8, scratch: []u8) ?[]const u8 {
    var i: usize = 0;
    var n: usize = 0;
    while (i < value.len) {
        if (i + 1 < value.len and value[i] == 0xd9) {
            const next = value[i + 1];
            if ((next >= 0x8b and next <= 0x92) or next == 0xb0) {
                i += 2;
                continue;
            }
            if (next == 0xb1) {
                if (n + 2 > scratch.len) return null;
                scratch[n] = 0xd8;
                scratch[n + 1] = 0xa7;
                n += 2;
                i += 2;
                continue;
            }
        }
        if (n == scratch.len) return null;
        scratch[n] = value[i];
        n += 1;
        i += 1;
    }
    return scratch[0..n];
}

// A complete Arabic "language <name>" heading is an explicit declaration.
// Resolve only an authenticated whole label; never derive ownership from a lemma.
fn resolveArabicLanguageHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "ar")) return null;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    for ([_][]const u8{ "لغة", "اللغة" }) |prefix| {
        if (!std.mem.startsWith(u8, heading, prefix) or heading.len <= prefix.len or
            (heading[prefix.len] != ' ' and heading[prefix.len] != '\t')) continue;
        const label = std.mem.trim(u8, heading[prefix.len..], " \t");
        if (label.len == 0 or std.mem.indexOfAny(u8, label, "[]{}<>|=\r\n") != null) return null;
        return codes.resolveStrong(label) orelse codes.resolveTrusted(label);
    }
    return null;
}

// The two captured AR Norwegian wrappers declare a variant after the umbrella
// language. Parse only their complete linked declaration; never infer an owner
// from an arbitrary parenthesis or from a bare Norwegian heading.
// Complete source-authored Arabic declaration forms used by chrome and
// d’Alembertian. Keep recognition separate from resolution so an unknown or
// conflicting declaration remains a boundary instead of borrowing an owner.
const ArabicLinkedOwner = struct { target: []const u8, label: []const u8, phrase: bool };
fn arabicLinkedOwner(codes: LanguageCodes, value: []const u8) ?ArabicLinkedOwner {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "ar") or value.len > 4096) return null;
    const Link = struct {
        fn take(rest: *[]const u8) ?struct { target: []const u8, label: []const u8 } {
            if (!std.mem.startsWith(u8, rest.*, "[[")) return null;
            const close = std.mem.indexOf(u8, rest.*, "]]") orelse return null;
            const body = rest.*[2..close];
            if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null) return null;
            const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
            if (pipe < body.len and std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null) return null;
            const target = std.mem.trim(u8, body[0..pipe], " \t");
            const label = std.mem.trim(u8, if (pipe < body.len) body[pipe + 1 ..] else target, " \t");
            if (target.len == 0 or label.len == 0) return null;
            rest.* = std.mem.trimStart(u8, rest.*[close + 2 ..], " \t");
            return .{ .target = target, .label = label };
        }
    };
    var rest = std.mem.trim(u8, value, " \t\r\n");
    const first = Link.take(&rest) orelse return null;
    var target_buffer: [256]u8 = undefined;
    var label_buffer: [512]u8 = undefined;
    const first_target = arabicDeclarationToken(first.target, &target_buffer) orelse return null;
    const first_label = arabicDeclarationToken(first.label, &label_buffer) orelse return null;
    if (std.mem.eql(u8, first_target, "لغة") and std.mem.eql(u8, first_label, "لغة")) {
        const language = Link.take(&rest) orelse return null;
        if (rest.len != 0) return null;
        return .{ .target = language.target, .label = language.label, .phrase = false };
    }
    if (!std.mem.eql(u8, rest, ":") or !std.mem.startsWith(u8, first_label, "في اللغة ") or first_label.len == "في اللغة ".len) return null;
    return .{ .target = first.target, .label = first.label, .phrase = true };
}
fn resolveArabicLinkedOwner(codes: LanguageCodes, declaration: ArabicLinkedOwner) ?ResolvedLanguage {
    var target_buffer: [256]u8 = undefined;
    var label_buffer: [512]u8 = undefined;
    const target = arabicDeclarationToken(declaration.target, &target_buffer) orelse return null;
    const whole_label = arabicDeclarationToken(declaration.label, &label_buffer) orelse return null;
    const label = if (declaration.phrase) whole_label["في اللغة ".len..] else whole_label;
    const target_owner = codes.resolveStrong(target) orelse codes.resolveTrusted(target) orelse return null;
    const label_owner = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return null;
    return if (std.mem.eql(u8, target_owner.code, label_owner.code)) target_owner else null;
}

const ArabicNorwegianDeclaration = enum { nb, nn };

fn arabicNorwegianDeclaration(codes: LanguageCodes, value: []const u8) ?ArabicNorwegianDeclaration {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "ar") or value.len > 1024 or
        std.mem.indexOfAny(u8, value, "\r\n") != null) return null;
    var buffer: [1024]u8 = undefined;
    const normalized = arabicDeclarationToken(value, &buffer) orelse return null;
    var rest = std.mem.trim(u8, normalized, " \t");
    const Link = struct {
        fn take(text: *[]const u8, wanted: []const u8) bool {
            if (!std.mem.startsWith(u8, text.*, "[[")) return false;
            const close = std.mem.indexOf(u8, text.*, "]]") orelse return false;
            const body = text.*[2..close];
            if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null) return false;
            const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
            if (!std.mem.eql(u8, std.mem.trim(u8, body[0..pipe], " \t"), wanted)) return false;
            // A label cannot silently change the declaration's meaning.
            if (pipe < body.len and !std.mem.eql(u8, std.mem.trim(u8, body[pipe + 1 ..], " \t"), wanted)) return false;
            text.* = std.mem.trimStart(u8, text.*[close + 2 ..], " \t");
            return true;
        }
    };
    if (!Link.take(&rest, "في") or !std.mem.startsWith(u8, rest, "ال")) return null;
    rest = rest["ال".len..];
    if (!Link.take(&rest, "نرويجية") or !std.mem.startsWith(u8, rest, "(")) return null;
    rest = std.mem.trimStart(u8, rest[1..], " \t");
    const variant: ArabicNorwegianDeclaration = if (Link.take(&rest, "بوكمول"))
        .nb
    else if (Link.take(&rest, "نينوشك"))
        .nn
    else
        return null;
    if (!std.mem.startsWith(u8, rest, ")")) return null;
    rest = std.mem.trimStart(u8, rest[1..], " \t");
    if (!std.mem.eql(u8, rest, ":")) return null;
    return variant;
}

fn resolveArabicNorwegianDeclaration(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const variant = arabicNorwegianDeclaration(codes, value) orelse return null;
    const umbrella = codes.resolveTrusted("نرويجية") orelse return null;
    if (!std.mem.eql(u8, umbrella.code, "no")) return null;
    // These exact combined names are the captured named-table authority:
    // وحدة:لغات/بيانات page214436/rev996464, not invented bare-variant aliases.
    const code = if (variant == .nb) "nb" else "nn";
    const label = if (variant == .nb) "نرويجية بوكمول" else "نرويجية نينوشك";
    const named = codes.resolveTrusted(label) orelse return null;
    const canonical = codes.resolve(code) orelse return null;
    if (!std.mem.eql(u8, named.code, code) or !std.mem.eql(u8, canonical.code, code)) return null;
    return canonical;
}

// Only the combining marks already accepted inside Arabic declaration tokens
// may trail a complete link. Preserve the original heading for presentation.
fn afterArabicDeclarationLink(value: []const u8) []const u8 {
    var rest = value;
    while (rest.len >= 2 and rest[0] == 0xd9) {
        var scratch: [2]u8 = undefined;
        const token = arabicDeclarationToken(rest[0..2], &scratch) orelse break;
        if (token.len != 0) break;
        rest = rest[2..];
    }
    return std.mem.trimStart(u8, rest, " \t");
}

fn resolveLinkedDeclaration(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "ar")) return null;
    var rest = std.mem.trim(u8, value, " \t\r\n");
    for ([_][]const u8{ "في", "لغة" }) |target| {
        if (!std.mem.startsWith(u8, rest, "[[")) return null;
        const close = std.mem.indexOf(u8, rest, "]]") orelse return null;
        const body = rest[2..close];
        const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
        var token_buffer: [256]u8 = undefined;
        const token = arabicDeclarationToken(body[0..pipe], &token_buffer) orelse return null;
        if (!std.mem.eql(u8, token, target)) return null;
        if (std.mem.indexOfAny(u8, body, "[]{}<>") != null or (pipe < body.len and std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null)) return null;
        rest = afterArabicDeclarationLink(rest[close + 2 ..]);
    }
    if (!std.mem.startsWith(u8, rest, "[[")) return null;
    const close = std.mem.indexOf(u8, rest, "]]") orelse return null;
    if (!std.mem.eql(u8, afterArabicDeclarationLink(rest[close + 2 ..]), ":")) return null;
    const body = rest[2..close];
    if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null) return null;
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
    if (pipe < body.len and std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null) return null;
    var target_buffer: [256]u8 = undefined;
    var label_buffer: [256]u8 = undefined;
    var raw_target = std.mem.trim(u8, body[0..pipe], " \t");
    if (std.mem.startsWith(u8, raw_target, ":")) raw_target = std.mem.trim(u8, raw_target[1..], " \t");
    const target = arabicDeclarationToken(raw_target, &target_buffer) orelse return null;
    const target_language = codes.resolveStrong(target) orelse codes.resolveTrusted(target);
    const label_language = if (pipe < body.len) blk: {
        const label = arabicDeclarationToken(std.mem.trim(u8, body[pipe + 1 ..], " \t"), &label_buffer) orelse return null;
        break :blk codes.resolveStrong(label) orelse codes.resolveTrusted(label);
    } else null;
    if (target_language != null and label_language != null and !std.mem.eql(u8, target_language.?.code, label_language.?.code)) return null;
    return target_language orelse label_language;
}

// A single independently trusted visible language link can precede hidden
// topic categories. Category titles never create or corroborate an owner here.
// Preserve the original source for rendering; accept no other visible tail.
fn resolveCategorizedLinkedHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (value.len > 4096) return null;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    // Use the same active-control matcher as display compilation. Localized
    // aliases need not use underscores. A changed target is outside this proof.
    for (0..heading.len) |at| {
        const control = if (codes.behavior_switches) |registry|
            registry.matchAt(std.heap.page_allocator, heading, at) catch return null
        else
            blobs.wikitext_syntax.behaviorSwitchEnd(heading, at);
        if (control != null) return null;
    }
    var tokens: blobs.document_ir.InlineIterator = .{ .input = heading, .renderer_boundaries = true, .link_trail = codes.link_trail };
    const first = tokens.next() orelse return null;
    if (first.kind != .link or first.link_has_pipe or first.trail.len != 0 or
        !std.mem.startsWith(u8, heading, "[[") or tokens.cursor < 4) return null;
    const label = first.target;
    // Plain local title syntax avoids entity/HTML/current-wiki transformations.
    if (label.len == 0 or std.mem.indexOfAny(u8, label, "[]{}<>|&#:") != null) return null;
    for (label) |byte| if (byte < 0x20 or byte == 0x7f) return null;
    const language = resolveLinkedHeading(codes, heading[0..tokens.cursor]) orelse return null;
    var categories: usize = 0;
    while (true) {
        const start = tokens.cursor;
        const token = tokens.next() orelse {
            // InlineIterator can consume formatting delimiters without a token.
            // Admission requires every original byte to remain accounted for.
            if (std.mem.trim(u8, heading[start..tokens.cursor], " \t").len != 0) return null;
            break;
        };
        if (token.kind == .text and std.mem.trim(u8, heading[start..tokens.cursor], " \t").len == 0) continue;
        if (token.kind != .link or token.trail.len != 0 or tokens.cursor < start + 4) return null;
        const authored = heading[start..tokens.cursor];
        if (!std.mem.startsWith(u8, authored, "[[") or !std.mem.endsWith(u8, authored, "]]")) return null;
        const body = authored[2 .. authored.len - 2];
        // These rejected transformations precede namespace suppression in the
        // renderer: protected/nested labels, entities, HTML and raw newlines.
        if (std.mem.indexOfAny(u8, body, "[]{}<>&") != null) return null;
        for (body) |byte| if (byte < 0x20 or byte == 0x7f) return null;
        const target = std.mem.trim(u8, token.target, " ");
        if (target.len == 0 or target[0] == ':') return null;
        const category = namespaces.ofTitle(target);
        if (category.id != 14 or std.mem.trim(u8, category.text, " ").len == 0) return null;
        categories += 1;
    }
    return if (categories != 0) language else null;
}

// Both the exact Help target and the complete visible label must already be
// trusted names for the same language. Source-authenticated code templates can
// supply such a target; stripping a namespace or reading a category cannot.
fn resolveSourceLinkedBanner(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (value.len > 4096) return null;
    const syntax = blobs.wikitext_syntax;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    const tag = syntax.tagAt(heading, 0) orelse return null;
    if (!tag.is("span") or tag.closing or tag.self_closing) return null;
    const classes = tag.attr("class") orelse return null;
    if (classes.len == 0) return null;
    for (classes) |byte| if (!std.ascii.isAlphanumeric(byte) and byte != '-' and byte != '_' and byte != ' ') return null;
    const attrs = std.mem.trim(u8, tag.attrs, " \t");
    if (attrs.len != classes.len + "class=\"\"".len or
        !std.mem.startsWith(u8, attrs, "class=\"") or attrs[attrs.len - 1] != '"') return null;
    const pair = syntax.matchingTag(heading, tag) orelse return null;
    if (pair.end != heading.len) return null;
    var rest = std.mem.trim(u8, heading[tag.end..pair.inner_end], " \t");
    if (!std.mem.startsWith(u8, rest, "[[")) return null;
    const end = std.mem.indexOf(u8, rest, "]]") orelse return null;
    const body = rest[2..end];
    if (std.mem.indexOfAny(u8, body, "[]{}<>&\r\n") != null) return null;
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return null;
    const target = std.mem.trim(u8, body[0..pipe], " \t");
    const label = std.mem.trim(u8, body[pipe + 1 ..], " \t");
    if (target.len == 0 or target[0] == ':' or std.mem.indexOfAny(u8, target, "#|") != null or
        label.len == 0 or std.mem.indexOfScalar(u8, label, '|') != null or namespaces.ofTitle(target).id != 12) return null;
    const owner = codes.resolveTrusted(target) orelse return null;
    const displayed = codes.resolveTrusted(label) orelse return null;
    if (!std.mem.eql(u8, owner.code, displayed.code)) return null;
    rest = std.mem.trim(u8, rest[end + 2 ..], " \t");
    while (rest.len != 0) {
        if (!std.mem.startsWith(u8, rest, "[[")) return null;
        const close = std.mem.indexOf(u8, rest, "]]") orelse return null;
        const category = rest[2..close];
        if (std.mem.indexOfAny(u8, category, "[]{}<>&\r\n") != null) return null;
        const delimiter = std.mem.indexOfScalar(u8, category, '|') orelse category.len;
        const title = std.mem.trim(u8, category[0..delimiter], " \t");
        if (title.len == 0 or title[0] == ':' or std.mem.indexOfScalar(u8, title, '#') != null or
            namespaces.ofTitle(title).id != 14 or std.mem.trim(u8, namespaces.ofTitle(title).text, " \t").len == 0 or
            (delimiter != category.len and std.mem.indexOfScalar(u8, category[delimiter + 1 ..], '|') != null)) return null;
        rest = std.mem.trim(u8, rest[close + 2 ..], " \t");
    }
    return owner;
}

// The retained VI declaration repeats its registered code in class and data-iso.
// Neither field nor the inert title supplies ownership without a trusted whole name.
fn resolveIsoClassSpanHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const syntax = blobs.wikitext_syntax;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    if (heading.len > 4096) return null;
    const span = syntax.tagAt(heading, 0) orelse return null;
    if (!span.is("span") or span.closing or span.self_closing) return null;
    const attrs = std.mem.trim(u8, span.attrs, " \t");
    var classes: ?[]const u8 = null;
    var iso: ?[]const u8 = null;
    var title: ?[]const u8 = null;
    var at: usize = 0;
    while (at < attrs.len) {
        const start = at;
        while (at < attrs.len and (std.ascii.isAlphabetic(attrs[at]) or attrs[at] == '-')) : (at += 1) {}
        if (start == at) return null;
        const key = attrs[start..at];
        while (at < attrs.len and (attrs[at] == ' ' or attrs[at] == '\t')) : (at += 1) {}
        if (at == attrs.len or attrs[at] != '=') return null;
        at += 1;
        while (at < attrs.len and (attrs[at] == ' ' or attrs[at] == '\t')) : (at += 1) {}
        if (at == attrs.len or attrs[at] != '"') return null;
        at += 1;
        const begin = at;
        while (at < attrs.len and attrs[at] != '"') : (at += 1) {
            const byte = attrs[at];
            if (byte < 0x20 or byte == 0x7f or std.mem.indexOfScalar(u8, "<>&{}[]|", byte) != null) return null;
        }
        if (at == attrs.len or at == begin) return null;
        const content = attrs[begin..at];
        const slot: *?[]const u8 = if (std.mem.eql(u8, key, "class")) &classes else if (std.mem.eql(u8, key, "data-iso")) &iso else if (std.mem.eql(u8, key, "title")) &title else return null;
        if (slot.* != null) return null;
        slot.* = content;
        at += 1;
        if (at < attrs.len and attrs[at] != ' ' and attrs[at] != '\t') return null;
        while (at < attrs.len and (attrs[at] == ' ' or attrs[at] == '\t')) : (at += 1) {}
    }
    const code = iso orelse return null;
    const class = classes orelse return null;
    const decoration = title orelse return null;
    if (decoration.len > 256 or code.len < 2 or code.len > 128) return null;
    for (code) |byte| if (!std.ascii.isLower(byte) and !std.ascii.isDigit(byte) and byte != '-') return null;
    if (!std.mem.startsWith(u8, class, "lang lang-") or !std.mem.eql(u8, class["lang lang-".len..], code)) return null;
    const registered = codes.resolve(code) orelse return null;
    const pair = syntax.matchingTag(heading, span) orelse return null;
    if (pair.end != heading.len) return null;
    const close = syntax.tagAt(heading, pair.inner_end) orelse return null;
    if (!close.is("span") or !close.closing or close.self_closing or
        std.mem.trim(u8, close.attrs, " \t").len != 0 or close.end != pair.end) return null;
    const label = heading[span.end..pair.inner_end];
    if (label.len == 0 or !std.mem.eql(u8, label, std.mem.trim(u8, label, " \t\r\n")) or
        std.mem.indexOfAny(u8, label, "[]{}<>&|\r\n\t") != null) return null;
    for (label) |byte| if (byte < 0x20 or byte == 0x7f) return null;
    const named = codes.resolveStrong(label) orelse
        (if (codes.trusted_fn) |trusted| trusted(codes.ctx, label) else null) orelse return null;
    // Registered aliases such as vie canonicalize to vi. Do not guess ISO aliases.
    if (!std.mem.eql(u8, named.code, registered.code) or std.mem.eql(u8, label, named.code)) return null;
    return named;
}

// Samafomot:pükatiäd (p25264/r160421) repeats the explicit code in
// span.id and a small suffix. Keep the whole heading; the trusted name and
// both code fields must independently agree before it can name an owner.
fn resolveCodedSpanHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const syntax = blobs.wikitext_syntax;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    const span = syntax.tagAt(heading, 0) orelse return null;
    if (!span.is("span") or span.closing or span.self_closing) return null;
    const attrs = std.mem.trim(u8, span.attrs, " \t");
    if (!std.mem.startsWith(u8, attrs, "id=")) return null;
    const code = attrs[3..];
    if (code.len < 2 or code.len > 128) return null;
    for (code) |byte| if (!std.ascii.isLower(byte) and !std.ascii.isDigit(byte) and byte != '-') return null;
    const registered = codes.resolve(code) orelse return null;
    if (!std.mem.eql(u8, registered.code, code)) return null;
    const pair = syntax.matchingTag(heading, span) orelse return null;
    const body = heading[span.end..pair.inner_end];
    const suffix_at = std.mem.indexOf(u8, body, " <small>(") orelse return null;
    const label = body[0..suffix_at];
    if (label.len == 0 or !std.mem.eql(u8, label, std.mem.trim(u8, label, " \t\r\n")) or
        std.mem.indexOfAny(u8, label, "[]{}<>&|\r\n\t") != null) return null;
    const suffix = body[suffix_at + " <small>(".len ..];
    if (suffix.len != code.len + ")</small>".len or !std.mem.startsWith(u8, suffix, code) or
        !std.mem.endsWith(u8, suffix, ")</small>")) return null;
    const named = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return null;
    if (!std.mem.eql(u8, named.code, code)) return null;
    var tail = std.mem.trim(u8, heading[pair.end..], " \t");
    while (tail.len != 0) {
        const namespaces = codes.namespace_catalog orelse return null;
        if (!std.mem.startsWith(u8, tail, "[[")) return null;
        const end = std.mem.indexOf(u8, tail, "]]") orelse return null;
        const link = tail[2..end];
        if (link.len == 0 or link[0] == ':' or std.mem.indexOfAny(u8, link, "[]{}<>&|\r\n") != null) return null;
        const category = namespaces.ofTitle(link);
        if (category.id != 14 or category.text.len == 0) return null;
        if (codes.resolve(category.text)) |other| if (!std.mem.eql(u8, code, other.code)) return null;
        tail = std.mem.trim(u8, tail[end + 2 ..], " \t");
    }
    return named;
}

// Language templates can append invisible category links inside a heading.
// Accept only a whole trusted name followed by categories for that same language.
// A neutral file icon decorates one independently trusted whole language name.
// Neither the filename nor a code-shaped template title supplies ownership.
// A complete decorative banner supplies a whole independently Strong name.
// Its File identity, sizing, wrappers and the edition never supply a language.
fn decorativeBannerAttrs(tag: blobs.wikitext_syntax.Tag) bool {
    const attrs = std.mem.trim(u8, tag.attrs, " \t");
    if (attrs.len == 0) return true;
    if (!tag.is("div") or attrs.len > 128) return false;
    var at: usize = 0;
    var id = false;
    var class = false;
    while (at < attrs.len) {
        while (at < attrs.len and (attrs[at] == ' ' or attrs[at] == '\t')) : (at += 1) {}
        if (at == attrs.len) break;
        const key_start = at;
        while (at < attrs.len and std.ascii.isAlphabetic(attrs[at])) : (at += 1) {}
        if (key_start == at) return false;
        const key = attrs[key_start..at];
        while (at < attrs.len and (attrs[at] == ' ' or attrs[at] == '\t')) : (at += 1) {}
        if (at == attrs.len or attrs[at] != '=') return false;
        at += 1;
        while (at < attrs.len and (attrs[at] == ' ' or attrs[at] == '\t')) : (at += 1) {}
        if (at == attrs.len) return false;
        const quote = attrs[at];
        const quoted = quote == '\'' or quote == '"';
        if (quoted) at += 1;
        const value_start = at;
        while (at < attrs.len and (if (quoted) attrs[at] != quote else attrs[at] != ' ' and attrs[at] != '\t')) : (at += 1) {}
        const value = attrs[value_start..at];
        if (quoted) {
            if (at == attrs.len) return false;
            at += 1;
            if (at < attrs.len and attrs[at] != ' ' and attrs[at] != '\t') return false;
        }
        if (std.ascii.eqlIgnoreCase(key, "id") and !id and std.mem.eql(u8, value, "toc")) id = true else if
            (std.ascii.eqlIgnoreCase(key, "class") and !class and std.mem.eql(u8, value, "toccolours")) class = true else return false;
    }
    return id and class;
}
fn resolveDecorativeFileBanner(codes: LanguageCodes, section: language_source.Section) ?ResolvedLanguage {
    if (section.hyphen_marker or section.source.len == 0 or section.heading.len > 4096) return null;
    const syntax = blobs.wikitext_syntax;
    const line_end = std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len;
    const line = std.mem.trimEnd(u8, section.source[0..line_end], "\r");
    const physical = syntax.controlHeading(line, null) orelse return null;
    if (physical.level != 2 or !std.mem.eql(u8, physical.title, section.heading)) return null;
    if (!std.unicode.utf8ValidateSlice(section.heading)) return null;
    for (section.heading) |byte| if (std.ascii.isControl(byte) and byte != '\t') return null;
    var body = std.mem.trim(u8, section.heading, " \t");
    const outer = syntax.tagAt(body, 0) orelse return null;
    if (!outer.is("div") or outer.closing or outer.self_closing or !decorativeBannerAttrs(outer)) return null;
    const outer_pair = syntax.matchingTag(body, outer) orelse return null;
    if (outer_pair.end != body.len) return null;
    const outer_close = syntax.tagAt(body, outer_pair.inner_end) orelse return null;
    if (!outer_close.closing or outer_close.self_closing or std.mem.trim(u8, outer_close.attrs, " \t").len != 0) return null;
    body = std.mem.trim(u8, body[outer.end..outer_pair.inner_end], " \t");
    var big_count: usize = 0;
    while (body.len != 0 and body[0] == '<') {
        if (big_count == 3) return null;
        const big = syntax.tagAt(body, 0) orelse return null;
        if (!big.is("big") or big.closing or big.self_closing or !decorativeBannerAttrs(big)) return null;
        const pair = syntax.matchingTag(body, big) orelse return null;
        if (pair.end != body.len) return null;
        const big_close = syntax.tagAt(body, pair.inner_end) orelse return null;
        if (!big_close.closing or big_close.self_closing or std.mem.trim(u8, big_close.attrs, " \t").len != 0) return null;
        body = std.mem.trim(u8, body[big.end..pair.inner_end], " \t");
        big_count += 1;
    }
    if (big_count == 0 or !std.mem.startsWith(u8, body, "[[")) return null;
    const pair = syntax.balanced(body, 0) orelse return null;
    const image = body[2..pair.inner_end];
    if (std.mem.indexOfAny(u8, image, "[]{}<>&#\r\n") != null) return null;
    const pipe = std.mem.indexOfScalar(u8, image, '|') orelse return null;
    const target = std.mem.trim(u8, image[0..pipe], " \t");
    if (target.len == 0 or target[0] == ':') return null;
    const namespaces = codes.namespace_catalog orelse return null;
    const file = namespaces.ofTitle(target);
    if (file.id != 6 or @import("presentation_media.zig").referencedKind(file.text) != .image) return null;
    var width = false;
    var border = false;
    var options = std.mem.splitScalar(u8, image[pipe + 1 ..], '|');
    while (options.next()) |part| {
        const option = std.mem.trim(u8, part, " \t");
        if (option.len == 0) return null;
        const option_module = @import("namespace_registry").image_options;
        const matched = (if (codes.image_options) |registry| registry.match(option, .image) else option_module.matchEnglish(option, .image)) orelse return null;
        if (std.mem.eql(u8, matched.id, "img_width") and !width) {
            const number = matched.value orelse return null;
            for (number) |byte| if (!std.ascii.isDigit(byte)) return null;
            const pixels = std.fmt.parseInt(u16, number, 10) catch return null;
            if (pixels == 0 or pixels > 4096) return null;
            width = true;
        } else if (std.mem.eql(u8, matched.id, "img_border") and !border) border = true else return null;
    }
    if (!width or pair.end >= body.len or (body[pair.end] != ' ' and body[pair.end] != '\t')) return null;
    const label = std.mem.trim(u8, body[pair.end..], " \t");
    if (label.len == 0 or std.mem.indexOfAny(u8, label, "[]{}<>&|=\"'\r\n\t") != null or knownOuterSupportOrPos(label)) return null;
    return codes.resolveStrong(label);
}

fn resolveFlaggedLanguageHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    const heading = std.mem.trim(u8, value, " \t");
    if (heading.len > 4096 or !std.mem.startsWith(u8, heading, "<big>") or
        !std.mem.endsWith(u8, heading, "</big>")) return null;
    const body = heading[5 .. heading.len - 6];
    if (!std.mem.startsWith(u8, body, "[[")) return null;
    const end = std.mem.indexOf(u8, body, "]]") orelse return null;
    const image = body[2..end];
    const pipe = std.mem.indexOfScalar(u8, image, '|') orelse return null;
    const target = image[0..pipe];
    if (std.mem.indexOfAny(u8, target, "[]{}<>&#\r\n") != null) return null;
    const file = namespaces.ofTitle(target);
    if (file.id != 6 or std.mem.trim(u8, file.text, " \t").len == 0) return null;
    var option = image[pipe + 1 ..];
    // An empty final file option does not introduce a link target or caption.
    if (std.mem.endsWith(u8, option, "|")) option = option[0 .. option.len - 1];
    if (option.len < 3 or !std.mem.endsWith(u8, option, "px")) return null;
    const digits = option[0 .. option.len - 2];
    for (digits) |digit| if (digit < '0' or digit > '9') return null;
    const width = std.fmt.parseInt(u16, digits, 10) catch return null;
    if (width == 0 or width > 4096) return null;
    const suffix = body[end + 2 ..];
    if (suffix.len == 0 or suffix[0] != ' ') return null;
    const label = std.mem.trim(u8, suffix, " ");
    if (label.len == 0 or std.mem.indexOfAny(u8, label, "[]{}<>&|=\"'\r\n\t") != null) return null;
    const language = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return null;
    if (std.mem.eql(u8, label, language.code)) return null;
    return language;
}

// A visible trusted name and hidden language category independently agree.
// The navigation target supplies no owner; a known conflicting target vetoes it.
// Only the captured capitalization wrapper is transparent to this proof.
fn resolveCategorizedDecoratedLinkHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    const syntax = blobs.wikitext_syntax;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    if (heading.len > 4096 or !std.unicode.utf8ValidateSlice(heading) or
        !std.mem.startsWith(u8, heading, "[[")) return null;
    for (0..heading.len) |at| {
        const control = if (codes.behavior_switches) |registry|
            registry.matchAt(std.heap.page_allocator, heading, at) catch return null
        else
            syntax.behaviorSwitchEnd(heading, at);
        if (control != null) return null;
    }
    const close = std.mem.indexOf(u8, heading, "]]") orelse return null;
    const body = heading[2..close];
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return null;
    const target = std.mem.trim(u8, body[0..pipe], " \t");
    if (target.len == 0 or std.mem.indexOfAny(u8, target, "[]{}<>&|#\r\n\t") != null or target[0] == ':') return null;
    if (namespaces.ofTitle(target).id != 0) return null;
    var target_name = target;
    if (std.mem.indexOfScalar(u8, target, ':')) |colon| {
        const prefix = target[0..colon];
        var visible_interwiki = false;
        for (namespaces.interwiki_rows) |row| {
            if (std.ascii.eqlIgnoreCase(prefix, row.prefix) and !row.is_interlanguage) {
                visible_interwiki = true;
                break;
            }
        }
        if (!visible_interwiki) return null;
        target_name = std.mem.trim(u8, target[colon + 1 ..], " ");
        if (target_name.len == 0 or std.mem.indexOfScalar(u8, target_name, ':') != null) return null;
    }
    var label = std.mem.trim(u8, body[pipe + 1 ..], " \t");
    if (std.mem.startsWith(u8, label, "<")) {
        const tag = syntax.tagAt(label, 0) orelse return null;
        if (!tag.is("span") or tag.closing or tag.self_closing or
            !std.mem.eql(u8, std.mem.trim(u8, tag.attrs, " \t"), "style=\"text-transform: capitalize\"")) return null;
        const pair = syntax.matchingTag(label, tag) orelse return null;
        if (pair.end != label.len) return null;
        label = label[tag.end..pair.inner_end];
    }
    if (label.len == 0 or std.mem.indexOfAny(u8, label, "[]{}<>&|\r\n\t") != null) return null;
    const owner = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return null;
    if (std.mem.eql(u8, label, owner.code)) return null;
    for ([_][]const u8{ target, target_name }) |spelling| {
        if (codes.isLanguageBoundary(spelling)) return null;
        if (codes.resolve(spelling)) |target_owner|
            if (!std.mem.eql(u8, owner.code, target_owner.code)) return null;
    }
    var rest = std.mem.trim(u8, heading[close + 2 ..], " \t");
    var categories: usize = 0;
    while (rest.len != 0) {
        if (!std.mem.startsWith(u8, rest, "[[")) return null;
        const end = std.mem.indexOf(u8, rest, "]]") orelse return null;
        const category_body = rest[2..end];
        if (std.mem.indexOfAny(u8, category_body, "[]{}<>&\r\n\t") != null) return null;
        const separator = std.mem.indexOfScalar(u8, category_body, '|') orelse category_body.len;
        const category_target = std.mem.trim(u8, category_body[0..separator], " ");
        if (category_target.len == 0 or category_target[0] == ':') return null;
        const category = namespaces.ofTitle(category_target);
        if (category.id != 14) return null;
        const named = std.mem.trim(u8, category.text, " ");
        const category_owner = codes.resolveStrong(named) orelse codes.resolveTrusted(named) orelse return null;
        if (!std.mem.eql(u8, category_owner.code, owner.code)) return null;
        categories += 1;
        rest = std.mem.trim(u8, rest[end + 2 ..], " \t");
    }
    return if (categories != 0) owner else null;
}

// A neutral id wrapper cannot name a language itself. Its whole trusted name,
// hidden categories and independently registered id must all agree.
fn resolveCategorizedSpanHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const syntax = blobs.wikitext_syntax;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    const span = syntax.tagAt(heading, 0) orelse return null;
    if (!span.is("span") or span.closing or span.self_closing) return null;
    const attrs = std.mem.trim(u8, span.attrs, " \t");
    if (!std.mem.startsWith(u8, attrs, "id=")) return null;
    var code = attrs[3..];
    if (code.len >= 2 and (code[0] == '"' or code[0] == '\'')) {
        if (code[code.len - 1] != code[0]) return null;
        code = code[1 .. code.len - 1];
    }
    if (code.len < 2 or code.len > 128) return null;
    for (code) |byte| if (!std.ascii.isLower(byte) and !std.ascii.isDigit(byte) and byte != '-') return null;
    const canonical = codes.resolve(code) orelse return null;
    const pair = syntax.matchingTag(heading, span) orelse return null;
    if (pair.end != heading.len) return null;
    const close = syntax.tagAt(heading, pair.inner_end) orelse return null;
    if (!close.is("span") or !close.closing or close.self_closing or
        std.mem.trim(u8, close.attrs, " \t").len != 0 or close.end != pair.end) return null;
    const body = heading[span.end..pair.inner_end];
    const named = resolveCategorizedNameHeading(codes, body) orelse
        resolveSpanLcfirstCategoryHeading(codes, body, canonical) orelse return null;
    return if (std.mem.eql(u8, named.code, canonical.code)) named else null;
}

// MG Endrika:=langue= p2731/r6297822 displays ucfirst(name) while its hidden
// category uses lcfirst(name). This relation does not add a language alias:
// the whole visible name and independently registered span id own the region.
// Keep this ASCII-first-letter arm narrow; other scripts need their own proof.
fn resolveSpanLcfirstCategoryHeading(codes: LanguageCodes, value: []const u8, id_owner: ResolvedLanguage) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    const open = std.mem.indexOf(u8, value, "[[") orelse return null;
    const name = std.mem.trim(u8, value[0..open], " \t\r\n");
    if (name.len == 0 or !std.ascii.isUpper(name[0]) or
        std.mem.indexOfAny(u8, name, "[]{}<>&|\r\n\t") != null) return null;
    const owner = codes.resolveStrong(name) orelse
        (if (codes.trusted_fn) |trusted| trusted(codes.ctx, name) else null) orelse return null;
    if (!std.mem.eql(u8, owner.code, id_owner.code) or codes.isLanguageBoundary(name)) return null;
    var rest = value[open..];
    while (rest.len != 0) {
        if (!std.mem.startsWith(u8, rest, "[[")) return null;
        const close = std.mem.indexOf(u8, rest, "]]") orelse return null;
        const body = rest[2..close];
        if (std.mem.indexOfAny(u8, body, "[]{}<>&\r\n\t") != null) return null;
        const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
        const target = std.mem.trim(u8, body[0..pipe], " ");
        if (target.len == 0 or target[0] == ':') return null;
        const category = namespaces.ofTitle(target);
        const label = std.mem.trim(u8, category.text, " ");
        if (category.id != 14 or label.len != name.len or
            label[0] != std.ascii.toLower(name[0]) or !std.mem.eql(u8, label[1..], name[1..]) or
            codes.isLanguageBoundary(label)) return null;
        // A present conflicting alias vetoes lexical agreement. An absent
        // category label never supplies ownership or becomes a registry alias.
        if (codes.resolve(label)) |other| if (!std.mem.eql(u8, other.code, owner.code)) return null;
        rest = std.mem.trim(u8, rest[close + 2 ..], " \t");
    }
    return owner;
}

fn resolveCategorizedHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    if (resolveIsoClassSpanHeading(codes, value)) |language| return language;
    if (resolveCategorizedDecoratedLinkHeading(codes, value)) |language| return language;
    if (resolveFlaggedLanguageHeading(codes, value)) |language| return language;
    if (resolveCodedSpanHeading(codes, value)) |language| return language;
    if (resolveCategorizedSpanHeading(codes, value)) |language| return language;
    if (resolveSourceLinkedBanner(codes, value)) |language| return language;
    if (resolveCategorizedLinkedHeading(codes, value)) |language| return language;
    return resolveCategorizedNameHeading(codes, value);
}

fn resolveCategorizedNameHeading(codes: LanguageCodes, value: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    const open = std.mem.indexOf(u8, heading, "[[") orelse return null;
    const name = std.mem.trim(u8, heading[0..open], " \t\r\n");
    const language = codes.resolveStrong(name) orelse codes.resolveTrusted(name) orelse return null;
    var rest = heading[open..];
    while (rest.len != 0) {
        if (!std.mem.startsWith(u8, rest, "[[")) return null;
        const close = std.mem.indexOf(u8, rest, "]]") orelse return null;
        const body = rest[2..close];
        if (std.mem.indexOfAny(u8, body, "[]{}<>") != null) return null;
        const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
        const target = std.mem.trim(u8, body[0..pipe], " \t\r\n");
        // Leading ':' creates a visible link, rather than hidden category metadata.
        if (std.mem.startsWith(u8, target, ":")) return null;
        const title = namespaces.ofTitle(target);
        if (title.id != 14) return null;
        const category = codes.resolveStrong(std.mem.trim(u8, title.text, " \t\r\n")) orelse
            codes.resolveTrusted(std.mem.trim(u8, title.text, " \t\r\n")) orelse return null;
        if (!std.mem.eql(u8, language.code, category.code)) return null;
        rest = std.mem.trim(u8, rest[close + 2 ..], " \t\r\n");
    }
    return language;
}

// Exact captured AZ Dil declaration output, not arbitrary HTML/template inference.
fn azDecoratedDeclaration(codes: LanguageCodes, raw: []const u8) ?[]const u8 {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "az")) return null;
    const heading = std.mem.trim(u8, raw, " \t\r\n");
    const tag = blobs.wikitext_syntax.tagAt(heading, 0) orelse return null;
    if (!tag.is("div") or tag.closing or tag.self_closing or
        !std.mem.eql(u8, std.mem.trim(u8, tag.attrs, " \t"), "style=\"background:#EEEEFF\"") or
        !std.mem.endsWith(u8, heading, "</div>")) return null;
    const body = heading[tag.end .. heading.len - 6];
    if (!std.mem.startsWith(u8, body, "[[")) return null;
    const close = std.mem.indexOf(u8, body, "]]") orelse return null;
    const link = body[2..close];
    const pipe = std.mem.indexOfScalar(u8, link, '|') orelse return null;
    const label = link[0..pipe];
    if (label.len == 0 or !std.mem.eql(u8, label, link[pipe + 1 ..]) or
        std.mem.indexOfAny(u8, label, "[]{}<>|=:\r\n") != null) return null;
    const category = body[close + 2 ..];
    if (!std.mem.startsWith(u8, category, "[[") or !std.mem.endsWith(u8, category, "]]")) return null;
    const target = category[2 .. category.len - 2];
    if (std.mem.indexOfAny(u8, target, "[]{}<>|") != null or std.mem.startsWith(u8, target, ":")) return null;
    const title = namespaces.ofTitle(target);
    if (title.id != 14 or !std.mem.startsWith(u8, title.text, label) or
        !std.mem.eql(u8, title.text[label.len..], "ndəki sözlər")) return null;
    return label;
}

fn declarationLabel(codes: LanguageCodes, heading: []const u8) ?[]const u8 {
    const namespaces = codes.namespace_catalog orelse return null;
    return language_source.explicitLanguageDeclaration(heading, namespaces.content_language) orelse
        azDecoratedDeclaration(codes, heading);
}

fn arabicLemmaDeclaration(codes: LanguageCodes, section: language_source.Section) language_source.ArabicNounSubtree {
    const namespaces = codes.namespace_catalog orelse return .{};
    if (!std.mem.eql(u8, namespaces.content_language, "ar")) return .{};
    const heading = std.mem.trim(u8, section.heading, " \t\r\n");
    // A trusted L2 language declaration must not be reassigned by nested POS.
    if (codes.resolveStrong(heading) != null or codes.resolveTrusted(heading) != null or
        resolveLinkedHeading(codes, heading) != null or resolveLinkedDeclaration(codes, heading) != null or
        resolveMixedArabicLinkedHeading(codes, heading) != null or
        resolveArabicLanguageHeading(codes, heading) != null or
        hasExplicitLanguageDeclaration(codes, section)) return .{};
    const markers: LanguageMarkers = .{ .codes = &codes };
    return language_source.arabicNounSubtree(section, languageSections(section.source, &markers).control_matcher);
}

// A template name and its single canonical-code argument can disagree without
// either proving the rendered language. Isolate that ambiguity; the argument
// never supplies an owner. This deliberately leaves other template forms alone.
fn rawTemplateCodeConflict(codes: LanguageCodes, raw: language_source.Section, resolved_code: ?[]const u8) bool {
    if (raw.hyphen_marker) return false;
    const newline = std.mem.indexOfScalar(u8, raw.source, '\n') orelse raw.source.len;
    const line = std.mem.trim(u8, raw.source[0..newline], " \t\r");
    if (line.len < 5 or !std.mem.startsWith(u8, line, "==") or line[2] == '=' or
        !std.mem.endsWith(u8, line, "==") or line[line.len - 3] == '=') return false;
    const heading = std.mem.trim(u8, line[2 .. line.len - 2], " \t");
    if (!std.mem.eql(u8, heading, std.mem.trim(u8, raw.heading, " \t\r\n")) or
        !std.mem.startsWith(u8, heading, "{{") or !std.mem.endsWith(u8, heading, "}}")) return false;
    const body = heading[2 .. heading.len - 2];
    // Excluding inner delimiters proves this is one complete balanced call,
    // without adding another nested-pair scan to the heading parser.
    if (std.mem.indexOfAny(u8, body, "{}[]<>=\r\n") != null) return false;
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return false;
    if (std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null) return false;
    const name = std.mem.trim(u8, body[0..pipe], " \t");
    const argument = std.mem.trim(u8, body[pipe + 1 ..], " \t");
    const named = codes.resolve(name) orelse return false;
    const supplied = codes.resolve(argument) orelse return false;
    if (!std.mem.eql(u8, name, named.code) or !std.mem.eql(u8, argument, supplied.code) or
        (resolved_code != null and !std.mem.eql(u8, named.code, resolved_code.?)) or std.mem.eql(u8, named.code, supplied.code)) return false;
    return true;
}
// A bare template title can collide with a weak ISO/name alias. Its spelling
// alone does not prove what the selected template emits. Decline only that raw
// candidate; rendered headings and authenticated source roles still resolve below.
fn rawTemplateNameIsWeakAlias(codes: LanguageCodes, section: language_source.Section, owner: ResolvedLanguage) bool {
    if (section.hyphen_marker) return false;
    const heading = std.mem.trim(u8, section.heading, " \t\r\n");
    if (!std.mem.startsWith(u8, heading, "{{") or !std.mem.endsWith(u8, heading, "}}") or heading.len < 5) return false;
    const name = std.mem.trim(u8, heading[2 .. heading.len - 2], " \t");
    if (name.len == 0 or std.mem.indexOfAny(u8, name, "{}|[]<>=\r\n") != null) return false;
    const alias = codes.resolve(name) orelse return false;
    if (!std.mem.eql(u8, alias.code, owner.code) or std.mem.eql(u8, name, owner.code)) return false;
    if (codes.strong_fn) |strong| if (strong(codes.ctx, name) != null) return false;
    if (codes.trusted_fn) |trusted| if (trusted(codes.ctx, name) != null) return false;
    return true;
}

fn unresolvedTemplateCodeCollision(codes: LanguageCodes, raw: language_source.Section, rendered: language_source.Section, resolved_code: []const u8) bool {
    return rawTemplateCodeConflict(codes, raw, resolved_code) and
        boundaryLanguage(codes, rendered) == null and resolveSection(codes, rendered) == null;
}

const RawTemplateCodeConflicts = struct { present: bool = false, unemitted: bool = false };

// The ordinary language iterator can deliberately keep an unknown L2 under L1.
// Inventory only exact conflicting-code calls with the same protected-domain
// parser. A monotonic source-pointer merge proves which calls were emitted.
fn rawTemplateCodeConflicts(codes: LanguageCodes, original: language_source.Iterator, emitted: []const language_source.Section) RawTemplateCodeConflicts {
    if (std.mem.indexOf(u8, original.source, "{{") == null or std.mem.indexOfScalar(u8, original.source, '|') == null) return .{};
    var active = original;
    active.heading_filter = .{ .ctx = null, .accepts = struct {
        fn accepts(_: ?*const anyopaque, _: []const u8) bool { return true; }
    }.accepts };
    var result: RawTemplateCodeConflicts = .{};
    var index: usize = 0;
    while (active.next()) |section| {
        if (!rawTemplateCodeConflict(codes, section, null)) continue;
        result.present = true;
        const start = @intFromPtr(section.source.ptr);
        while (index < emitted.len and @intFromPtr(emitted[index].source.ptr) < start) : (index += 1) {}
        if (index == emitted.len or @intFromPtr(emitted[index].source.ptr) != start) result.unemitted = true;
    }
    return result;
}


// Classification borrows the complete label after one decorative image. It
// never edits the source rendered by the Writer, or reads a caption as a label.
// Require an actual physical L2 section: heading_filter's source-empty probe
// must not promote icon-bearing POS/support subsections across depth levels.
fn imageLanguageLabel(codes: LanguageCodes, section: language_source.Section) ?[]const u8 {
    if (section.hyphen_marker or section.source.len == 0) return null;
    const syntax = blobs.wikitext_syntax;
    const line_end = std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len;
    const line = std.mem.trimEnd(u8, section.source[0..line_end], "\r");
    if (!std.mem.startsWith(u8, line, "==") or std.mem.startsWith(u8, line, "===")) return null;
    const parsed = syntax.controlHeading(line, null) orelse return null;
    if (parsed.level != 2 or !std.mem.eql(u8, parsed.title, section.heading)) return null;
    const heading = section.heading;
    if (!std.mem.startsWith(u8, heading, "[[")) return null;
    const pair = syntax.balanced(heading, 0) orelse return null;
    const body = heading[2..pair.inner_end];
    if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null) return null;
    const pipe = syntax.delimiter(body, "|", 0) orelse body.len;
    const target = std.mem.trim(u8, body[0..pipe], " \t");
    if (target.len == 0 or target[0] == ':' or std.mem.indexOfScalar(u8, target, '#') != null) return null;
    const namespaces = codes.namespace_catalog orelse return null;
    const file = namespaces.ofTitle(target);
    if (file.id != 6 or @import("presentation_media.zig").referencedKind(file.text) != .image) return null;
    // Width, border and middle vertical alignment only decorate the file.
    // Captions, alt/link overrides, horizontal placement and arbitrary
    // parameters cannot supply language evidence.
    if (pipe < body.len) {
        var width = false;
        var border = false;
        var middle = false;
        var parts = std.mem.splitScalar(u8, body[pipe + 1 ..], '|');
        while (parts.next()) |part| {
            const option = std.mem.trim(u8, part, " \t");
            const options = @import("namespace_registry").image_options;
            const matched = (if (codes.image_options) |registry| registry.match(option, .image) else options.matchEnglish(option, .image)) orelse return null;
            if (std.mem.eql(u8, matched.id, "img_width")) {
                if (width) return null;
                width = true;
            } else if (std.mem.eql(u8, matched.id, "img_border")) {
                if (border) return null;
                border = true;
            } else if (std.mem.eql(u8, matched.id, "img_middle")) {
                if (middle) return null;
                middle = true;
            } else return null;
        }
    }
    if (pair.end >= heading.len or (heading[pair.end] != ' ' and heading[pair.end] != '\t')) return null;
    const label = std.mem.trim(u8, heading[pair.end..], " \t");
    if (label.len == 0 or std.mem.indexOfAny(u8, label, "[]{}<>|=\r\n\"'") != null or knownOuterSupportOrPos(label)) return null;
    return label;
}

// A captured Italian banner links its complete name to a main or appendix page.
// The namespace and decorative file confer no owner: both the local page name
// and complete visible label must independently agree through trusted names.
fn supplementalIconLanguage(codes: LanguageCodes, section: language_source.Section) ?ResolvedLanguage {
    if (section.hyphen_marker or section.source.len == 0) return null;
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "it")) return null;
    const syntax = blobs.wikitext_syntax;
    const line = std.mem.trimEnd(u8, section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len], "\r");
    const physical = syntax.controlHeading(line, null) orelse return null;
    if (physical.level != 2 or !std.mem.eql(u8, physical.title, section.heading)) return null;
    var rest = std.mem.trim(u8, section.heading, " \t");
    if (rest.len > 4096 or !std.unicode.utf8ValidateSlice(rest)) return null;
    // Only ordinary hidden category links may precede the icon. Their names are
    // never consulted for ownership; visible colon-links and sort keys decline.
    var category_count: usize = 0;
    while (std.mem.startsWith(u8, rest, "[[")) {
        const pair = syntax.balanced(rest, 0) orelse return null;
        const body = rest[2..pair.inner_end];
        if (body.len == 0 or body[0] == ':' or std.mem.indexOfAny(u8, body, "[]{}<>&#\r\n") != null) return null;
        const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
        const target = std.mem.trim(u8, body[0..pipe], " \t");
        const title = namespaces.ofTitle(target);
        if (title.id != 14) break;
        if (pipe != body.len or title.text.len == 0 or category_count == 4) return null;
        category_count += 1;
        rest = std.mem.trimStart(u8, rest[pair.end..], " \t");
    }
    if (!std.mem.startsWith(u8, rest, "[[")) return null;
    const icon_pair = syntax.balanced(rest, 0) orelse return null;
    const icon = rest[2..icon_pair.inner_end];
    if (std.mem.indexOfAny(u8, icon, "[]{}<>&#\r\n") != null) return null;
    const pipe = std.mem.indexOfScalar(u8, icon, '|') orelse return null;
    const target = std.mem.trim(u8, icon[0..pipe], " \t");
    if (target.len == 0 or target[0] == ':') return null;
    const file = namespaces.ofTitle(target);
    if (file.id != 6 or @import("presentation_media.zig").referencedKind(file.text) != .image) return null;
    var width = false;
    var border = false;
    var caption = false;
    var options = std.mem.splitScalar(u8, icon[pipe + 1 ..], '|');
    while (options.next()) |part| {
        const option = std.mem.trim(u8, part, " \t");
        if (option.len == 0) return null;
        const image_options = @import("namespace_registry").image_options;
        const matched = if (codes.image_options) |registry| registry.match(option, .image) else image_options.matchEnglish(option, .image);
        if (matched) |value| {
            if (std.mem.eql(u8, value.id, "img_width")) {
                if (width or !std.mem.endsWith(u8, option, "px")) return null;
                const number = std.fmt.parseInt(u16, option[0 .. option.len - 2], 10) catch return null;
                if (number == 0 or number > 4096) return null;
                width = true;
            } else if (std.mem.eql(u8, value.id, "img_border")) {
                if (border) return null;
                border = true;
            } else return null;
        } else {
            // One plain caption is tooltip text, not a visible language label.
            // Recognized width/border options may follow it, as in ordinary
            // image parsing; a second caption or action/layout still declines.
            if (caption or std.mem.indexOfAny(u8, option, "=:\"'[]{}<>&#\r\n") != null) return null;
            caption = true;
        }
    }
    if (!width or icon_pair.end == rest.len or (rest[icon_pair.end] != ' ' and rest[icon_pair.end] != '\t')) return null;
    rest = std.mem.trim(u8, rest[icon_pair.end..], " \t");
    if (!std.mem.startsWith(u8, rest, "[[")) return null;
    const label_pair = syntax.balanced(rest, 0) orelse return null;
    if (label_pair.end != rest.len) return null;
    const body = rest[2..label_pair.inner_end];
    if (std.mem.indexOfAny(u8, body, "[]{}<>&#\r\n\"'") != null) return null;
    const separator = std.mem.indexOfScalar(u8, body, '|') orelse return null;
    if (std.mem.indexOfScalar(u8, body[separator + 1 ..], '|') != null) return null;
    const linked = std.mem.trim(u8, body[0..separator], " \t");
    const label = std.mem.trim(u8, body[separator + 1 ..], " \t");
    if (linked.len == 0 or linked[0] == ':' or label.len == 0 or std.mem.indexOfScalar(u8, label, ':') != null) return null;
    const local = namespaces.ofTitle(linked);
    const spec = namespaces.byId(local.id) orelse return null;
    const main_target = local.id == 0 and spec.role == .main;
    const appendix_target = spec.role == .supplemental and std.mem.eql(u8, spec.canonical_name, "Appendice");
    if ((!main_target and !appendix_target) or
        local.text.len == 0 or std.mem.indexOfScalar(u8, local.text, ':') != null) return null;
    const owner = codes.resolveStrong(local.text) orelse codes.resolveTrusted(local.text) orelse return null;
    const displayed = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return null;
    if (!std.mem.eql(u8, owner.code, displayed.code)) return null;
    if (codes.resolve(linked)) |known| if (!std.mem.eql(u8, known.code, owner.code)) return null;
    if (codes.isLanguageBoundary(linked)) return null;
    return owner;
}

// The retained Naslov header format names its language in a project link.
// Its page-name prefix and the edition's content language confer no owner.
const ProjectParentheticalDeclaration = struct {
    target: []const u8,
    name: []const u8,
    label: []const u8,
};

// Шаблон:-mul- p320871/r689000 emits this exact static H2. The authored
// first root marker and independently Strong canonical name supply its owner;
// the decorative label/icon never become registry aliases.
const sr_mul_heading = "<div id=\"toc\" class=\"toccolours\" ><big><big><big>[[File:Flag of the United Nations.svg|border|32px]] ''међународно''</big></big></big></div>";

fn srFirstMarkerPrefix(prefix: []const u8) bool {
    if (prefix.len > 4096 or !std.unicode.utf8ValidateSlice(prefix)) return false;
    var lines = std.mem.splitScalar(u8, prefix, '\n');
    while (lines.next()) |raw_line| {
        const line = std.mem.trimEnd(u8, raw_line, "\r");
        if (line.len == 0) continue;
        // The retained 日 prefix also invokes the complete commonscat media box
        // (Шаблон:commonscat p228553/r476696). Only its no-argument spelling
        // joins the hatnote/character-info family; root/source proof is still
        // mandatory after expansion, so this grants no owner by itself.
        if (std.mem.eql(u8, line, "{{commonscat}}")) continue;
        // Complete flat syntax also refuses an enclosing scope.
        if (!std.mem.startsWith(u8, line, "{{") or !std.mem.endsWith(u8, line, "}}") or line.len < 5) return false;
        const body = line[2 .. line.len - 2];
        if (std.mem.indexOfAny(u8, body, "{}[]<>&=\"'\r\n") != null) return false;
        for (body) |byte| if (std.ascii.isControl(byte)) return false;
        const name = std.mem.trim(u8, body[0 .. std.mem.indexOfScalar(u8, body, '|') orelse body.len], " ");
        if (!std.mem.eql(u8, name, "also") and !std.mem.eql(u8, name, "character info")) return false;
        var fields = std.mem.splitScalar(u8, body, '|');
        if (!std.mem.eql(u8, fields.next().?, name)) return false;
        var arguments: usize = 0;
        while (fields.next()) |argument| {
            if (std.mem.trim(u8, argument, " ").len == 0) return false;
            arguments += 1;
        }
        if ((std.mem.eql(u8, name, "also") and arguments == 0) or
            (std.mem.eql(u8, name, "character info") and arguments > 1)) return false;
    }
    return true;
}

fn sourceSrFirstMulOwner(codes: LanguageCodes, raw: []const u8, source: MissingText,
    authored: language_source.Section, expanded: language_source.Section,
    observed: presentation_document.HeadingObservation) ?ResolvedLanguage
{
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.wiki, "srwiktionary") or !std.mem.eql(u8, namespaces.content_language, "sr") or
        !authored.hyphen_marker or !std.mem.eql(u8, authored.heading, "mul") or expanded.hyphen_marker or
        !std.mem.eql(u8, expanded.heading, sr_mul_heading) or !observed.page_wiki_scope_complete) return null;
    const owner = codes.resolveStrong("Међународни") orelse return null;
    const code = codes.resolve("mul") orelse return null;
    if (!std.mem.eql(u8, owner.code, "mul") or !std.mem.eql(u8, code.code, owner.code)) return null;
    for ([_][]const u8{ "mul", "Међународни", "међународно" }) |name| {
        if (codes.isLanguageBoundary(name)) return null;
        if (codes.resolve(name)) |other| if (!std.mem.eql(u8, other.code, owner.code)) return null;
    }
    const raw_at = std.math.sub(usize, @intFromPtr(authored.source.ptr), @intFromPtr(raw.ptr)) catch return null;
    if (raw_at > raw.len or authored.source.len > raw.len - raw_at or !srFirstMarkerPrefix(raw[0..raw_at])) return null;
    const raw_end = std.mem.indexOfScalar(u8, authored.source, '\n') orelse authored.source.len;
    if (!std.mem.eql(u8, std.mem.trimEnd(u8, authored.source[0..raw_end], "\r"), "{{-mul-}}")) return null;
    const expanded_at = std.math.sub(usize, @intFromPtr(expanded.source.ptr), @intFromPtr(source.bytes.ptr)) catch return null;
    if (expanded_at > source.bytes.len or expanded.source.len > source.bytes.len - expanded_at or
        observed.page_wiki_all_openings.len == 0 or observed.page_wiki_all_openings[0] != expanded_at or
        !sourceCategoryHeaderRangesClean(source, expanded)) return null;
    const observed_source = observed.page_html_source orelse return null;
    if (observed_source.ptr != source.bytes.ptr or observed_source.len != source.bytes.len) return null;
    for (observed.page_html_openings) |at| if (at < expanded_at) return null;
    const end = std.mem.indexOfScalar(u8, expanded.source, '\n') orelse expanded.source.len;
    const physical = blobs.wikitext_syntax.controlHeading(std.mem.trimEnd(u8, expanded.source[0..end], "\r"), null) orelse return null;
    if (physical.level != 2 or !std.mem.eql(u8, physical.title, sr_mul_heading)) return null;
    return owner;
}

fn projectParentheticalDeclaration(codes: LanguageCodes, section: language_source.Section) ?ProjectParentheticalDeclaration {
    if (section.hyphen_marker or section.source.len == 0) return null;
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "sr")) return null;
    const line = std.mem.trimEnd(u8, section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len], "\r");
    const physical = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
    if (physical.level != 2 or !std.mem.eql(u8, physical.title, section.heading)) return null;
    const heading = section.heading;
    if (heading.len > 4096 or !std.unicode.utf8ValidateSlice(heading)) return null;
    const opener = " <span style=\"font-size:80%;\">([[";
    const closer = "]])</span>";
    const at = std.mem.indexOf(u8, heading, opener) orelse return null;
    if (at == 0 or !std.mem.endsWith(u8, heading, closer)) return null;
    var headword = std.mem.trim(u8, heading[0..at], " \t");
    // A complete literal conversion wrapper bounds the lemma independently of
    // the language declaration. It is recognized here, never rewritten/rendered.
    if (std.mem.startsWith(u8, headword, "-{") and std.mem.endsWith(u8, headword, "}-")) {
        const inner = headword[2 .. headword.len - 2];
        if (!linkedPeerTargetCodepointsValid(inner) or std.mem.indexOfAny(u8, inner, ":;") != null) return null;
        headword = std.mem.trim(u8, inner, " ");
    }
    if (headword.len == 0 or std.mem.indexOfAny(u8, headword, "[]{}<>&|=\r\n\"'") != null) return null;
    const start = at + opener.len;
    if (start >= heading.len - closer.len) return null;
    const body = heading[start .. heading.len - closer.len];
    if (std.mem.indexOfAny(u8, body, "[]{}<>&#\r\n\"'") != null) return null;
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return null;
    const target = body[0..pipe];
    const label = body[pipe + 1 ..];
    if (target.len == 0 or target[0] == ':' or label.len == 0 or
        std.mem.indexOfAny(u8, label, "|:") != null or
        !std.mem.eql(u8, target, std.mem.trim(u8, target, " \t")) or
        !std.mem.eql(u8, label, std.mem.trim(u8, label, " \t"))) return null;
    const local = namespaces.ofTitle(target);
    if (local.id != 4 or local.text.len == 0 or std.mem.indexOfAny(u8, local.text, ":|") != null) return null;
    return .{ .target = target, .name = local.text, .label = label };
}

fn resolveProjectParenthetical(codes: LanguageCodes, declaration: ProjectParentheticalDeclaration) ?ResolvedLanguage {
    // Only a source-backed canonical name supplies the owner. Lowercasing
    // verifies the displayed label; it neither installs nor resolves an alias.
    const owner = codes.resolveStrong(declaration.name) orelse return null;
    var buffer: [4096]u8 = undefined;
    var lowered = std.Io.Writer.fixed(&buffer);
    @import("namespace_registry").writeLower(&lowered, declaration.name) catch return null;
    if (!std.mem.eql(u8, lowered.buffered(), declaration.label)) return null;
    for ([_][]const u8{ declaration.target, declaration.name, declaration.label }) |spelling| {
        if (codes.isLanguageBoundary(spelling)) return null;
        if (codes.resolve(spelling)) |known| if (!std.mem.eql(u8, known.code, owner.code)) return null;
    }
    return owner;
}

// The authenticated nom formatter binds its exact raw code to this complete
// emitted heading. The linked target/label is never a global language alias.
fn sourceNomHeadingOwner(codes: LanguageCodes, source: MissingText, raw: language_source.Section, expanded: language_source.Section) ?ResolvedLanguage {
    const label_for = codes.source_nom_label_fn orelse return null;
    const ns = codes.namespace_catalog orelse return null;
    if (source.unknown or !raw.root_wiki_heading or !expanded.root_wiki_heading or raw.hyphen_marker or expanded.hyphen_marker or
        !sourceCategoryHeaderRangesClean(source, expanded)) return null;
    missing_dependency.generated_link.validateRanges(source.bytes, source.generated_source, source.generated_links) catch return null;
    const syntax = blobs.wikitext_syntax;
    const raw_end = std.mem.indexOfScalar(u8, raw.source, '\n') orelse raw.source.len;
    const authored = syntax.controlHeading(std.mem.trimEnd(u8, raw.source[0..raw_end], "\r"), null) orelse return null;
    if (authored.level != 2 or !std.mem.eql(u8, authored.title, raw.heading) or
        !std.mem.startsWith(u8, authored.title, "{{langue|") or !std.mem.endsWith(u8, authored.title, "}}")) return null;
    const code = std.mem.trim(u8, authored.title[9 .. authored.title.len - 2], " \t");
    if (code.len == 0 or std.mem.indexOfAny(u8, code, "{}[]<>&|=\"' \t\r\n") != null) return null;
    const owner = codes.resolve(code) orelse return null;
    if (!std.mem.eql(u8, owner.code, code) or codes.isLanguageBoundary(code)) return null;
    const label = label_for(codes.ctx, code) orelse return null;
    // The captured provider's ASCII ucfirst branch is sufficient here. Other
    // casing/portal shapes remain unproved rather than borrowing a name.
    if (label.len == 0 or label.len > 4096 or label[0] >= 0x80 or
        std.mem.indexOfAny(u8, label, "{}[]<>&|=:\r\n\"'") != null) return null;
    var capital_buffer: [4096]u8 = undefined;
    @memcpy(capital_buffer[0..label.len], label);
    capital_buffer[0] = std.ascii.toUpper(capital_buffer[0]);
    const capital = capital_buffer[0..label.len];
    const end = std.mem.indexOfScalar(u8, expanded.source, '\n') orelse expanded.source.len;
    const emitted = syntax.controlHeading(std.mem.trimEnd(u8, expanded.source[0..end], "\r"), null) orelse return null;
    if (emitted.level != 2 or !std.mem.eql(u8, emitted.title, expanded.heading)) return null;
    const heading = emitted.title;
    if (codes.source_nom_name_format) {
        // This independently proved formatter uses single quotes and places
        // its category after the span. No arbitrary HTML/portal shape is added.
        const prefix = "<span class='sectionlangue' id='";
        if (!std.mem.startsWith(u8, heading, prefix)) return null;
        const code_end = prefix.len + code.len;
        if (code_end + 2 > heading.len or !std.mem.eql(u8, heading[prefix.len..code_end], code) or
            !std.mem.startsWith(u8, heading[code_end..], "'>")) return null;
        const body_start = code_end + 2;
        if (capital.len > heading.len - body_start or !std.mem.eql(u8, heading[body_start..][0..capital.len], capital)) return null;
        const close = body_start + capital.len;
        if (!std.mem.startsWith(u8, heading[close..], "</span>")) return null;
        const tail = heading[close + 7 ..];
        if (tail.len != 0) {
            if (!std.mem.startsWith(u8, tail, "[[") or !std.mem.endsWith(u8, tail, "]]")) return null;
            const target = tail[2 .. tail.len - 2];
            if (target.len == 0 or target[0] == ':' or std.mem.indexOfAny(u8, target, "[]{}|<>&") != null) return null;
            const category = ns.ofTitle(target);
            if (category.id != 14 or !std.mem.eql(u8, category.text, label)) return null;
        }
        return owner;
    }
    const prefix = "<span class=\"sectionlangue\" id=\"";
    if (!std.mem.startsWith(u8, heading, prefix) or !std.mem.endsWith(u8, heading, "</span>")) return null;
    const code_end = prefix.len + code.len;
    if (code_end + 2 + 7 > heading.len or !std.mem.eql(u8, heading[prefix.len..code_end], code) or
        !std.mem.startsWith(u8, heading[code_end..], "\">")) return null;
    var body = heading[code_end + 2 .. heading.len - 7];
    if (std.mem.startsWith(u8, body, "[[")) {
        const close = std.mem.indexOf(u8, body, "]]") orelse return null;
        const link = body[2..close];
        const pipe = std.mem.indexOfScalar(u8, link, '|') orelse return null;
        if (!std.mem.eql(u8, link[0..pipe], label) or !std.mem.eql(u8, link[pipe + 1 ..], capital)) return null;
        body = body[close + 2 ..];
    } else {
        if (!std.mem.startsWith(u8, body, capital)) return null;
        body = body[capital.len..];
    }
    if (body.len != 0) {
        if (!std.mem.startsWith(u8, body, "[[") or !std.mem.endsWith(u8, body, "]]")) return null;
        const target = body[2 .. body.len - 2];
        if (target.len == 0 or target[0] == ':' or std.mem.indexOfAny(u8, target, "[]{}|<>&") != null) return null;
        const category = ns.ofTitle(target);
        if (category.id != 14 or !std.mem.eql(u8, category.text, label)) return null;
    }
    return owner;
}

// The selected Наслов/Значење source pair declares POS independently of its
// displayed H2. Only the first complete single-owner noun region is supported;
// neither category spelling, edition nor the unused third argument supplies it.
fn sourceNumberedLexemes(a: std.mem.Allocator, codes: LanguageCodes, raw: ?[]const u8,
    source: MissingText, owner: ResolvedLanguage, observed: presentation_document.HeadingObservation,
) ![]presentation_document.SourceNumberedLexeme {
    if ((!codes.source_numbered_pos[0] and !codes.source_numbered_pos[1]) or owner.code.len == 0 or
        source.unknown or source.lost_missing_range or !observed.page_wiki_scope_complete) return &.{};
    const authored = raw orelse return &.{};
    const observed_source = observed.page_html_source orelse return &.{};
    if (observed_source.ptr != source.bytes.ptr or observed_source.len != source.bytes.len) return &.{};
    var result: std.ArrayList(presentation_document.SourceNumberedLexeme) = .empty;
    defer result.deinit(a);
    for ([_][]const u8{ "{{-noun-}}", "{{-adj-}}" }, 0..) |marker, role| {
        if (!codes.source_numbered_pos[role]) continue;
        if (std.mem.count(u8, authored, marker) != 1) continue;
        const call_at = std.mem.indexOf(u8, authored, marker).?;
        if ((call_at != 0 and authored[call_at - 1] != '\n') or
            !language_source.outsideNestedOrOpaque(authored, call_at)) continue;
        const call_end = std.mem.indexOfScalarPos(u8, authored, call_at, '\n') orelse authored.len;
        if (!std.mem.eql(u8, std.mem.trimEnd(u8, authored[call_at..call_end], " \t\r"), marker)) continue;
        var lines: [64][]const u8 = undefined;
        var count: usize = 0;
        var placeholders: usize = 0;
        var at = if (call_end < authored.len) call_end + 1 else call_end;
        var invalid = false;
        while (at < authored.len) {
            const end = std.mem.indexOfScalarPos(u8, authored, at, '\n') orelse authored.len;
            const line = std.mem.trimEnd(u8, authored[at..end], "\r");
            if (blobs.wikitext_syntax.controlHeading(line, null) != null or std.mem.startsWith(u8, line, "{{-")) break;
            if (std.mem.startsWith(u8, line, ":#") or std.mem.startsWith(u8, line, ";#")) {
                if (count == lines.len or !language_source.outsideNestedOrOpaque(authored, at) or
                    (line.len > 2 and std.mem.indexOfScalar(u8, ":;#*", line[2]) != null)) { invalid = true; break; }
                lines[count] = line; count += 1;
                if (std.mem.eql(u8, std.mem.trim(u8, line[2..], " \t"), "...")) placeholders += 1;
            }
            at = if (end < authored.len) end + 1 else end;
        }
        if (invalid or count == 0) continue;
        const title = if (role == 0) "নাম" else "বিশেষণ";
        var heading_at: ?usize = null;
        var title_at: usize = 0;
        var body_at: usize = 0;
        var body_end = source.bytes.len;
        for (observed.page_wiki_openings) |opening| {
            if (opening >= source.bytes.len) { invalid = true; break; }
            const end = std.mem.indexOfScalarPos(u8, source.bytes, opening, '\n') orelse source.bytes.len;
            const heading = blobs.wikitext_syntax.controlHeading(source.bytes[opening..end], null) orelse continue;
            if (heading_at != null and opening > heading_at.? and body_end == source.bytes.len) body_end = opening;
            if (heading.level != 2 or !std.mem.eql(u8, heading.title, title)) continue;
            if (heading_at != null or !calibratedBoundaryRangesClean(source, opening, end)) { invalid = true; break; }
            heading_at = opening;
            title_at = @intFromPtr(heading.title.ptr) - @intFromPtr(source.bytes.ptr);
            body_at = if (end < source.bytes.len) end + 1 else end;
        }
        if (invalid or heading_at == null) continue;
        var actual: usize = 0;
        at = body_at;
        while (at < body_end) {
            const end = @min(std.mem.indexOfScalarPos(u8, source.bytes, at, '\n') orelse body_end, body_end);
            const line = std.mem.trimEnd(u8, source.bytes[at..end], "\r");
            if (std.mem.startsWith(u8, line, ":#") or std.mem.startsWith(u8, line, ";#")) {
                if (actual == count or !std.mem.eql(u8, line, lines[actual]) or
                    !calibratedBoundaryRangesClean(source, at, end)) { invalid = true; break; }
                actual += 1;
            }
            at = if (end < body_end) end + 1 else end;
        }
        if (invalid or actual != count) continue;
        try result.append(a, .{ .source = source.bytes, .heading_offset = title_at,
            .kind = if (role == 0) "Noun" else "Adjective", .numbered_count = count, .placeholder_count = placeholders });
    }
    return try result.toOwnedSlice(a);
}

fn sourceNaslovLexeme(codes: LanguageCodes, title: []const u8, raw: ?[]const u8,
    source: MissingText, owner: ResolvedLanguage, observed: presentation_document.HeadingObservation,
) ?presentation_document.SourceLexeme {
    if (!codes.source_naslov_noun or source.unknown or source.lost_missing_range or
        !std.mem.eql(u8, owner.code, "sr") or !observed.page_wiki_scope_complete) return null;
    const ns = codes.namespace_catalog orelse return null;
    const observed_source = observed.page_html_source orelse return null;
    if (observed_source.ptr != source.bytes.ptr or observed_source.len != source.bytes.len) return null;
    const authored = raw orelse return null;
    const first_end = std.mem.indexOfScalar(u8, authored, '\n') orelse return null;
    const first = std.mem.trimEnd(u8, authored[0..first_end], "\r");
    const prefix = "{{Наслов|Српски|Именица";
    if (!std.mem.startsWith(u8, first, prefix) or !std.mem.endsWith(u8, first, "}}") or
        std.mem.count(u8, authored, "{{Наслов") != 1) return null;
    const tail = first[prefix.len .. first.len - 2];
    // The selected Serbian template does not consume arg3. Accept a literal
    // positional value without interpreting it; named/nested overrides refuse.
    if (tail.len != 0 and (tail[0] != '|' or tail.len == 1 or
        std.mem.indexOfAny(u8, tail[1..], "|={}[]<>&\r\n") != null)) return null;
    const resolved = codes.resolveStrong("Српски") orelse return null;
    if (!std.mem.eql(u8, resolved.code, owner.code) or !std.mem.eql(u8, resolved.heading, owner.heading)) return null;
    const marker = "\n{{Значење}}\n";
    const call_at = std.mem.indexOf(u8, authored, marker) orelse return null;
    if (std.mem.count(u8, authored, marker) != 1 or
        !language_source.outsideNestedOrOpaque(authored, call_at + 1)) return null;
    const definition_at = call_at + marker.len;
    const definition_end = std.mem.indexOfScalarPos(u8, authored, definition_at, '\n') orelse return null;
    const line = authored[definition_at..definition_end];
    if (!std.mem.startsWith(u8, line, ":[1] ") or line.len <= ":[1] ".len or
        std.mem.indexOfAny(u8, line[5..], "[]{}<>&'\"\t\r") != null or
        std.mem.trim(u8, line[5..], " ").len != line.len - 5 or
        !std.unicode.utf8ValidateSlice(line)) return null;
    // No second sense/continuation is silently omitted by this first subset.
    const after = std.mem.trimStart(u8, authored[definition_end..], "\r\n");
    if (!std.mem.startsWith(u8, after, "{{")) return null;
    const emitted_marker = "<p style=\"margin-bottom: -0.5em; cursor: help;\" title=\"Смисао или семантичко објашњење\">'''Значења:''' {{{1}}}</p>\n";
    const emitted_at = std.mem.indexOf(u8, source.bytes, emitted_marker) orelse return null;
    if (std.mem.count(u8, source.bytes, emitted_marker) != 1) return null;
    const text_at = emitted_at + emitted_marker.len;
    if (line.len >= source.bytes.len - text_at or !std.mem.eql(u8, source.bytes[text_at..][0..line.len], line) or
        source.bytes[text_at + line.len] != '\n' or
        std.mem.count(u8, source.bytes, line) != 1 or
        !calibratedBoundaryRangesClean(source, text_at, text_at + line.len)) return null;
    var header: ?blobs.wikitext_syntax.ControlHeading = null;
    var header_at: usize = 0;
    // Reuse the completed native root-heading observation. A second H2 cannot
    // inherit this declaration, even if normal grouping chose the same language.
    for (observed.page_wiki_openings) |opening| {
        if (opening >= source.bytes.len) return null;
        const end = std.mem.indexOfScalarPos(u8, source.bytes, opening, '\n') orelse source.bytes.len;
        const heading = blobs.wikitext_syntax.controlHeading(source.bytes[opening..end], null) orelse continue;
        if (heading.level != 2) continue;
        if (header != null) return null;
        header = heading; header_at = opening;
    }
    const heading = header orelse return null;
    if (header_at >= emitted_at or !calibratedBoundaryRangesClean(source, header_at,
        std.mem.indexOfScalarPos(u8, source.bytes, header_at, '\n') orelse source.bytes.len)) return null;
    const declaration = projectParentheticalDeclaration(codes, .{ .heading = heading.title,
        .source = source.bytes[header_at..], .root_wiki_heading = true }) orelse return null;
    if (!std.mem.eql(u8, declaration.name, "Српски") or !std.mem.eql(u8, declaration.label, "српски")) return null;
    const emitted_owner = resolveProjectParenthetical(codes, declaration) orelse return null;
    if (!std.mem.eql(u8, emitted_owner.code, owner.code)) return null;
    const title_end = std.mem.indexOf(u8, heading.title, " <span style=") orelse return null;
    if (!std.mem.eql(u8, heading.title[0..title_end], title) or ns.ofTitle(declaration.target).id != 4) return null;
    return .{ .source = source.bytes, .heading_offset = @intFromPtr(heading.title.ptr) - @intFromPtr(source.bytes.ptr),
        .kind = "Noun", .definition_text = source.bytes[text_at + 1 .. text_at + line.len] };
}

fn sourceSectionPhysicalHeading(section: language_source.Section) ?[]const u8 {
    if (section.hyphen_marker or section.source.len == 0 or section.source[0] != '=') return null;
    const line = std.mem.trimEnd(u8, section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len], "\r");
    const physical = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
    if (physical.level != 2 or !std.mem.eql(u8, physical.title, section.heading) or physical.title.len == 0 or
        std.mem.indexOfAny(u8, physical.title, "{}[]<>&|=\"'\r\n") != null) return null;
    return line;
}

fn sourceSectionHeadingPair(codes: LanguageCodes, source: []const u8, openings: []const usize, raw: ?language_source.Section, expanded: language_source.Section) ?SourceSectionHeading {
    const callback = codes.source_section_fn orelse return null;
    const expanded_line = sourceSectionPhysicalHeading(expanded) orelse return null;
    const start = std.math.sub(usize, @intFromPtr(expanded.source.ptr), @intFromPtr(source.ptr)) catch return null;
    if (start > source.len or expanded.source.len > source.len - start) return null;
    const scopes: language_source.LinkHeadingScopes = .{ .source = source, .openings = openings };
    if (!scopes.admits(source, start)) return null;
    const matched = callback(codes.ctx, expanded.heading) orelse return null;
    const refused: SourceSectionHeading = .{ .owner = null };
    const original = raw orelse return refused;
    const raw_line = sourceSectionPhysicalHeading(original) orelse return refused;
    if (!std.mem.eql(u8, raw_line, expanded_line) or !original.root_wiki_heading) return refused;
    return matched;
}


const kayan_heading = "ကယန်း(ပတောင်ႏ)";

// A local qualifier alone is ambiguous. Require each head declaration and its
// emitted language-bearing headword to agree within the same physical POS.
fn kayanHeadingsMatch(raw: []const u8, expanded: []const u8, source: MissingText) bool {
    var raw_lines = std.mem.splitScalar(u8, raw, '\n');
    var output_lines = std.mem.splitScalar(u8, expanded, '\n');
    var output_heading: []const u8 = "";
    var raw_heading: []const u8 = "";
    var count: usize = 0;
    const marker = "<span class=\"headword-line\">";
    const prefix = marker ++ "<strong class=\"Latn headword\" lang=\"pdu\">";
    while (raw_lines.next()) |line| {
        if (blobs.wikitext_syntax.controlHeading(line, null)) |heading| raw_heading = if (heading.level > 2) heading.title else "";
        if (!std.mem.startsWith(u8, line, "{{head|")) continue;
        const declaration = SourceHeadword.call(line) orelse return false;
        const offset = SourceHeadword.offset(raw, line) orelse return false;
        if (raw_heading.len == 0 or !std.mem.eql(u8, declaration.code, "pdu") or !language_source.outsideNestedOrOpaque(raw, offset)) return false;
        while (output_lines.next()) |rendered| {
            if (blobs.wikitext_syntax.controlHeading(rendered, null)) |heading| output_heading = if (heading.level > 2) heading.title else "";
            if (!std.mem.startsWith(u8, rendered, marker)) continue;
            if (!std.mem.eql(u8, output_heading, raw_heading) or !std.mem.startsWith(u8, rendered, prefix) or
                std.mem.indexOfPos(u8, rendered, prefix.len, "</strong></span>[[Category:ကယန်း") == null or !SourceHeadword.clean(source, rendered)) return false;
            break;
        } else return false;
        count += 1;
    }
    while (output_lines.next()) |line| if (std.mem.startsWith(u8, line, marker)) return false;
    return count != 0;
}

// This selected source formatter is admitted only at an observed physical H2.
// Its complete heading remains ordinary body/action data; no target alias is
// installed and copied, generated or unresolved header bytes cannot own a page.
fn sourceLinkedHeadingOwner(codes: LanguageCodes, source: MissingText, section: language_source.Section) ?ResolvedLanguage {
    const resolve = codes.source_linked_heading_fn orelse return null;
    if (source.unknown or !section.root_wiki_heading or section.hyphen_marker or section.source.len == 0 or
        section.source[0] != '=' or !sourceCategoryHeaderRangesClean(source, section)) return null;
    missing_dependency.generated_link.validateRanges(source.bytes, source.generated_source, source.generated_links) catch return null;
    const end = std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len;
    const physical = blobs.wikitext_syntax.controlHeading(std.mem.trimEnd(u8, section.source[0..end], "\r"), null) orelse return null;
    if (physical.level != 2 or !std.mem.eql(u8, physical.title, section.heading)) return null;
    return resolve(codes.ctx, section.heading);
}

// A source-authenticated head declaration owns only its paired language
// container. The local container label is never added to the registry.
const SourceHeadword = struct {
    const Child = struct { heading: []const u8, start: usize, body: usize, end: usize };
    const Call = struct { code: []const u8 };

    fn lineEnd(source: []const u8, start: usize) usize {
        return std.mem.indexOfScalarPos(u8, source, start, '\n') orelse source.len;
    }
    fn afterLine(source: []const u8, start: usize) usize {
        const end = lineEnd(source, start);
        return if (end < source.len) end + 1 else end;
    }
    fn offset(full: []const u8, part: []const u8) ?usize {
        const start = std.math.sub(usize, @intFromPtr(part.ptr), @intFromPtr(full.ptr)) catch return null;
        if (start > full.len or part.len > full.len - start) return null;
        return start;
    }
    fn root(openings: []const usize, at: usize) bool {
        return std.mem.indexOfScalar(usize, openings, at) != null;
    }
    fn children(a: std.mem.Allocator, full: []const u8, source: []const u8, openings: []const usize) !?[]const Child {
        const base = offset(full, source) orelse return null;
        if (!root(openings, base)) return null;
        var result: std.ArrayList(Child) = .empty;
        defer result.deinit(a);
        var at = afterLine(source, 0);
        while (at < source.len) {
            const end = lineEnd(source, at);
            const line = std.mem.trimEnd(u8, source[at..end], "\r");
            if (blobs.wikitext_syntax.controlHeading(line, null)) |heading| if (root(openings, base + at)) {
                if (heading.level != 3 or heading.title.len == 0 or std.mem.indexOfAny(u8, heading.title, "{}[]<>&|=\"'") != null) return null;
                if (result.items.len != 0) result.items[result.items.len - 1].end = at;
                try result.append(a, .{ .heading = heading.title, .start = at, .body = afterLine(source, at), .end = source.len });
            };
            at = afterLine(source, at);
        }
        if (result.items.len == 0) return null;
        return try result.toOwnedSlice(a);
    }
    fn firstBodyLine(source: []const u8) struct { line: []const u8, rest: []const u8 } {
        const body = std.mem.trimStart(u8, source, " \t\r\n");
        const end = lineEnd(body, 0);
        return .{ .line = std.mem.trimEnd(u8, body[0..end], " \t\r"), .rest = body[afterLine(body, 0)..] };
    }
    fn call(line: []const u8) ?Call {
        if (!std.mem.startsWith(u8, line, "{{head|") or !std.mem.endsWith(u8, line, "}}") or line.len > 4096) return null;
        const body = line[7 .. line.len - 2];
        if (std.mem.indexOfAny(u8, body, "{}[]<>&\r\n") != null) return null;
        var fields = std.mem.splitScalar(u8, body, '|');
        const code = std.mem.trim(u8, fields.next() orelse return null, " \t");
        if (code.len < 2 or code.len > 3) return null;
        for (code) |byte| if (byte < 'a' or byte > 'z') return null;
        const pos = std.mem.trim(u8, fields.next() orelse return null, " \t");
        if (pos.len == 0 or std.mem.indexOfAny(u8, pos, "=:#*;\"'") != null) return null;
        var transliteration = false;
        while (fields.next()) |field| {
            // This first source slice supports one literal tr only. Named
            // numeric bindings, duplicates and additional positional values
            // cannot override the first argument behind this certificate.
            if (transliteration or !std.mem.startsWith(u8, field, "tr=") or field.len == 3 or
                std.mem.indexOfScalar(u8, field[3..], '=') != null) return null;
            transliteration = true;
        }
        return .{ .code = code };
    }
    fn definitions(source: []const u8) bool {
        var lines = std.mem.splitScalar(u8, source, '\n');
        var count: usize = 0;
        while (lines.next()) |input| {
            const line = std.mem.trim(u8, input, " \t\r");
            if (line.len == 0) continue;
            if (line[0] != '#' or line.len < 2 or std.mem.indexOfScalar(u8, "#*:;", line[1]) != null or
                std.mem.trim(u8, line[1..], " \t").len == 0 or std.mem.indexOfAny(u8, line, "{}<>") != null) return false;
            count += 1;
        }
        return count != 0;
    }
    fn support(source: []const u8) bool {
        var lines = std.mem.splitScalar(u8, source, '\n');
        var count: usize = 0;
        while (lines.next()) |input| {
            const line = std.mem.trim(u8, input, " \t\r");
            if (line.len == 0) continue;
            // Literal top-level bullet support only. No unproved template,
            // definition, HTML, table or nested declaration can inherit here.
            if (line[0] != '*' or line.len < 2 or std.mem.indexOfScalar(u8, "#*:;=", line[1]) != null or
                std.mem.indexOfAny(u8, line, "{}<>") != null) return false;
            count += 1;
        }
        return count != 0;
    }
    fn outputHead(title: []const u8, line: []const u8, code: []const u8) bool {
        const tag = blobs.wikitext_syntax.tagAt(line, 0) orelse return false;
        if (!tag.is("strong") or tag.closing or tag.self_closing or !std.mem.startsWith(u8, tag.attrs, " class=\"") or !std.mem.endsWith(u8, tag.attrs, "\"")) return false;
        const split = std.mem.indexOf(u8, tag.attrs, "\" lang=\"") orelse return false;
        const class_text = tag.attrs[" class=\"".len .. split];
        const language = tag.attrs[split + "\" lang=\"".len .. tag.attrs.len - 1];
        if (!std.mem.eql(u8, language, code)) return false;
        for (class_text) |byte| if (!std.ascii.isAlphanumeric(byte) and byte != ' ' and byte != '-' and byte != '_') return false;
        var classes = std.mem.tokenizeScalar(u8, class_text, ' ');
        var found = false;
        while (classes.next()) |class| if (std.mem.eql(u8, class, "headword")) { found = true; };
        if (!found) return false;
        const close = std.mem.indexOfPos(u8, line, tag.end, "</strong>") orelse return false;
        if (!std.mem.eql(u8, line[tag.end..close], title)) return false;
        const tail = line[close + "</strong>".len ..];
        return std.mem.indexOf(u8, tail, "headword") == null and std.mem.indexOf(u8, tail, "<strong") == null;
    }
    fn clean(source: MissingText, bytes: []const u8) bool {
        const start = offset(source.bytes, bytes) orelse return false;
        return calibratedBoundaryRangesClean(source, start, start + bytes.len);
    }
    fn prefix(a: std.mem.Allocator, codes: LanguageCodes, raw: []const u8, expanded: []const u8) !bool {
        const authored = std.mem.trim(u8, raw, " \t\r\n");
        const emitted = std.mem.trim(u8, expanded, " \t\r\n");
        if (authored.len == 0) return emitted.len == 0;
        const pattern = codes.source_headword_static_prefix orelse return false;
        const start = "{{Alban əlifbası|c=";
        if (!std.mem.startsWith(u8, authored, start) or !std.mem.endsWith(u8, authored, "}}")) return false;
        const value = authored[start.len .. authored.len - 2];
        if (value.len == 0 or value.len > 32) return false;
        for (value) |byte| if (byte < 'A' or byte > 'Z') return false;
        const expected = try std.mem.replaceOwned(u8, a, pattern, "{{{c}}}", value);
        defer a.free(expected);
        return std.mem.eql(u8, std.mem.trim(u8, expected, " \t\r\n"), emitted);
    }
    fn owner(a: std.mem.Allocator, codes: LanguageCodes, title: []const u8, raw_page: []const u8, source: MissingText, raw: language_source.Section, rendered: language_source.Section, raw_roots: []const usize, rendered_roots: []const usize) !?ResolvedLanguage {
        const resolve = codes.source_headword_fn orelse return null;
        if (source.unknown or raw.hyphen_marker or rendered.hyphen_marker) return null;
        missing_dependency.generated_link.validateRanges(source.bytes, source.generated_source, source.generated_links) catch return null;
        const raw_header = raw.source[0..lineEnd(raw.source, 0)];
        const expanded_header = rendered.source[0..lineEnd(rendered.source, 0)];
        const header = blobs.wikitext_syntax.controlHeading(raw_header, null) orelse return null;
        const actual = blobs.wikitext_syntax.controlHeading(expanded_header, null) orelse return null;
        if (header.level != 2 or actual.level != 2 or !std.mem.startsWith(u8, header.title, "{{Dil|") or !std.mem.endsWith(u8, header.title, "}}")) return null;
        const label = header.title[6 .. header.title.len - 2];
        if (label.len == 0 or !std.mem.eql(u8, label, std.mem.trim(u8, label, " \t")) or std.mem.indexOfAny(u8, label, "{}[]<>&|=\"'\r\n") != null) return null;
        const expected_header = try std.fmt.allocPrint(a, "<div style=\"background:#EEEEFF\">[[{s}|{s}]][[Kateqoriya:{s}ndəki sözlər]]</div>", .{ label, label, label });
        defer a.free(expected_header);
        if (!std.mem.eql(u8, expected_header, actual.title) or !clean(source, expanded_header)) return null;
        const authored = (try children(a, raw_page, raw.source, raw_roots)) orelse return null;
        defer a.free(authored);
        const expanded = (try children(a, source.bytes, rendered.source, rendered_roots)) orelse return null;
        defer a.free(expanded);
        const expanded_prefix = rendered.source[afterLine(rendered.source, 0)..expanded[0].start];
        if (authored.len != expanded.len or !clean(source, expanded_prefix) or !try prefix(a, codes, raw.source[afterLine(raw.source, 0)..authored[0].start], expanded_prefix)) return null;
        var found: ?ResolvedLanguage = null;
        var conflicting = false;
        for (authored, expanded) |before, after| {
            if (!std.mem.eql(u8, before.heading, after.heading) or !clean(source, rendered.source[after.start..after.body])) return null;
            const raw_body = raw.source[before.body..before.end];
            const body = rendered.source[after.body..after.end];
            if (!clean(source, body)) return null;
            const raw_first = firstBodyLine(raw_body);
            const first = firstBodyLine(body);
            if (call(raw_first.line)) |declaration| {
                const language = resolve(codes.ctx, declaration.code) orelse return null;
                if (!definitions(raw_first.rest) or !std.mem.eql(u8, std.mem.trim(u8, raw_first.rest, " \t\r\n"), std.mem.trim(u8, first.rest, " \t\r\n")) or
                    !outputHead(title, first.line, declaration.code) or !clean(source, first.line)) return null;
                if (found) |previous| if (!std.mem.eql(u8, previous.code, language.code)) { conflicting = true; };
                found = language;
            } else {
                if (!support(raw_body) or !std.mem.eql(u8, std.mem.trim(u8, raw_body, " \t\r\n"), std.mem.trim(u8, body, " \t\r\n"))) return null;
            }
        }
        if (found) |language| {
            if (codes.resolveStrong(label) orelse codes.resolveTrusted(label)) |other| if (!std.mem.eql(u8, other.code, language.code)) { conflicting = true; };
            if (codes.isLanguageBoundary(label)) conflicting = true;
        }
        if (conflicting) return .{ .code = "", .heading = "Unclassified" };
        return found;
    }
};

// A weak registry name still needs authored language evidence. When an
// unrelated template adds a page heading, pair only this unique literal L2;
// never lend a different region's raw body through positional alignment.
fn literalL2Name(section: language_source.Section) ?[]const u8 {
    if (section.hyphen_marker) return null;
    const end = std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len;
    const line = std.mem.trimEnd(u8, section.source[0..end], "\r");
    const header = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
    if (header.level != 2 or header.title.len == 0 or
        std.mem.indexOfAny(u8, header.title, "{}[]<>&|=\"'") != null or
        !std.mem.eql(u8, header.title, section.heading)) return null;
    return header.title;
}

fn literalAliasPairCandidate(codes: LanguageCodes, sections: []const language_source.Section) bool {
    for (sections) |section| {
        const label = literalL2Name(section) orelse continue;
        if (!codes.isLanguageBoundary(label) and codes.resolve(label) != null and
            codes.resolveStrong(label) == null and codes.resolveTrusted(label) == null) return true;
    }
    return false;
}

// Finnish literal vocabulary pages independently name each language in a
// namespace-14 category. Accept this exact sort-key format only when every
// authored peer has its own registered name and category.
fn finnishLiteralCategoryPage(codes: LanguageCodes, title: []const u8, raw_page: []const u8,
    sections: []const language_source.Section) bool
{
    const namespaces = codes.namespace_catalog orelse return false;
    if (!std.mem.eql(u8, namespaces.wiki, "fiwiktionary") or title.len <= 2 or raw_page.len > 4096 or
        sections.len == 0 or sections.len > 8 or std.mem.indexOfAny(u8, raw_page, "{}<>") != null or
        std.mem.indexOf(u8, raw_page, "n sanat-") == null) return false;
    if (!std.ascii.isLower(title[0]) or !std.ascii.isLower(title[1])) return false;
    for (sections, 0..) |section, i| {
        const label = literalL2Name(section) orelse return false;
        if (codes.isLanguageBoundary(label) or knownOuterSupportOrPos(label)) return false;
        const owner = codes.resolve(label) orelse return false;
        if (owner.code.len == 0 or !std.mem.eql(u8, owner.heading, label)) return false;
        for (sections[0..i]) |peer| if (std.mem.eql(u8, label, peer.heading)) return false;
        var found = false;
        var lines = std.mem.splitScalar(u8, raw_page, '\n');
        while (lines.next()) |raw_line| {
            const line = std.mem.trimEnd(u8, raw_line, "\r");
            if (!std.mem.startsWith(u8, line, "[[") or !std.mem.endsWith(u8, line, "]]")) continue;
            const body = line[2 .. line.len - 2];
            const pipe = std.mem.indexOfScalar(u8, body, '|') orelse continue;
            if (!std.mem.startsWith(u8, body, "Luokka:") or !std.mem.eql(u8, body[pipe + 1 ..], title[2..])) continue;
            const category = namespaces.ofTitle(body[0..pipe]);
            if (category.id != 14 or !std.mem.startsWith(u8, category.text, label)) continue;
            const suffix = category.text[label.len..];
            const marker = "n sanat-";
            if (!std.mem.startsWith(u8, suffix, marker) or !std.mem.eql(u8, suffix[marker.len..], title[0..2])) continue;
            if (found) return false;
            found = true;
        }
        if (!found) return false;
    }
    return true;
}

fn pairedLiteralAliasOwner(codes: LanguageCodes, raw_page: []const u8, source: MissingText,
    raw_sections: []const language_source.Section, rendered_sections: []const language_source.Section,
    section: language_source.Section, raw_roots: []const usize, rendered_roots: []const usize,
    category_proven: bool) ?ResolvedLanguage
{
    if (source.lost_missing_range) return null;
    missing_dependency.generated_link.validateRanges(source.bytes, source.generated_source, source.generated_links) catch return null;
    const label = literalL2Name(section) orelse return null;
    if (codes.isLanguageBoundary(label)) return null;
    const owner = codes.resolve(label) orelse return null;
    const rendered_scope: language_source.LinkHeadingScopes = .{ .source = source.bytes, .openings = rendered_roots };
    const raw_scope: language_source.LinkHeadingScopes = .{ .source = raw_page, .openings = raw_roots };
    const at = SourceHeadword.offset(source.bytes, section.source) orelse return null;
    if (!rendered_scope.admits(source.bytes, at) or !sourceCategoryHeaderRangesClean(source, section)) return null;
    var rendered_count: usize = 0;
    for (rendered_sections) |candidate| if (literalL2Name(candidate)) |name| {
        if (std.mem.eql(u8, label, name)) rendered_count += 1;
    };
    if (rendered_count != 1) return null;
    var matched: ?language_source.Section = null;
    for (raw_sections) |candidate| if (literalL2Name(candidate)) |name| {
        if (!std.mem.eql(u8, label, name)) continue;
        if (matched != null) return null;
        matched = candidate;
    };
    const raw = matched orelse return null;
    const raw_at = SourceHeadword.offset(raw_page, raw.source) orelse return null;
    if (!raw_scope.admits(raw_page, raw_at)) return null;
    const raw_end = std.mem.indexOfScalar(u8, raw.source, '\n') orelse raw.source.len;
    const rendered_end = std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len;
    if (!std.mem.eql(u8, std.mem.trimEnd(u8, raw.source[0..raw_end], "\r"),
        std.mem.trimEnd(u8, section.source[0..rendered_end], "\r"))) return null;
    // Use the existing weak-name corroboration rule on the matched raw region,
    // not inline lang attributes, inferred defaults, or surrounding owners.
    if (!category_proven and !sourceConfirmsLanguage(codes, raw.source, owner.code)) return null;
    return owner;
}

fn resolveSection(codes: LanguageCodes, section: language_source.Section) ?ResolvedLanguage {
    if (resolveDecorativeFileBanner(codes, section)) |owner| return owner;
    if (projectParentheticalDeclaration(codes, section)) |declaration| return resolveProjectParenthetical(codes, declaration);
    if (supplementalIconLanguage(codes, section)) |owner| return owner;
    if (imageLanguageLabel(codes, section)) |label|
        return codes.resolveStrong(label) orelse codes.resolveTrusted(label);
    if (arabicLinkedOwner(codes, section.heading)) |declaration| return resolveArabicLinkedOwner(codes, declaration);
    if (codes.namespace_catalog) |namespaces| if (std.mem.eql(u8, namespaces.content_language, "ar")) {
        // Plain "لغة NAME" already has the Strong/Trusted resolver below.
        // Only the literal template declaration adds the generic-code route.
        if (std.mem.startsWith(u8, std.mem.trim(u8, section.heading, " \t\r\n"), "{{"))
            if (declarationLabel(codes, section.heading)) |label| return codes.resolve(label);
    };
    // A balanced equals declaration names its owner in the first field.
    // Sort/display arguments, including nested calls, cannot lend one.
    if (equalsSectionDeclaration(section)) |code| return codes.resolve(code);
    if (arabicNorwegianDeclaration(codes, section.heading) != null)
        return resolveArabicNorwegianDeclaration(codes, section.heading);
    const noun = arabicLemmaDeclaration(codes, section);
    if (noun.present) return if (noun.code) |code| codes.resolve(code) else null;
    if (codes.namespace_catalog) |namespaces| if (std.mem.eql(u8, namespaces.content_language, "az")) {
        if (declarationLabel(codes, section.heading)) |label| return codes.resolve(label);
    };
    if (resolveAnBannerHeading(codes, section.heading)) |resolved| return resolved;
    const classified = language_source.classificationSection(section);
    if (resolveCategorizedHeading(codes, classified)) |resolved| return resolved;

    if (!std.mem.eql(u8, classified, section.heading))
        if (resolveTrimmed(codes, classified)) |resolved| return resolved;

    if (resolveArabicLanguageHeading(codes, classified)) |resolved| return resolved;
    if (resolveLinkedHeading(codes, classified)) |resolved| return resolved;
    if (resolveMixedArabicLinkedHeading(codes, classified)) |resolved| return resolved;
    if (resolveLinkedDeclaration(codes, classified)) |resolved| return resolved;

    const candidates = [_][]const u8{
        std.mem.trim(u8, classified, " \t\r\n"),
        std.mem.trim(u8, classified, " \t\r\n\'\"[]"),
    };
    for (candidates) |plain| {
        if (plain.len == 0) continue;
        if (codes.resolveStrong(plain)) |resolved| return resolved;

        // Exact edition-local MediaWiki preferred names are language evidence.
        // ISO names and other aliases still need an explicit source marker.
        if (codes.resolveTrusted(plain)) |resolved| return resolved;

        if (codes.resolve(plain)) |resolved|
            if (sourceConfirmsLanguage(codes, section.source, resolved.code)) return resolved;
    }

    return resolveTemplateCandidates(codes, section.heading);
}

// The first raw declaration can corroborate its complete expanded banner even
// when nested POS headings change section counts. The linked target contributes
// no owner or alias; an independently registered conflicting target vetoes it.
fn sourceCategoryHeaderRangesClean(source: MissingText, section: language_source.Section) bool {
    const start = std.math.sub(usize, @intFromPtr(section.source.ptr), @intFromPtr(source.bytes.ptr)) catch return false;
    if (start > source.bytes.len or section.source.len > source.bytes.len - start) return false;
    const length = std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len;
    const end = start + length;
    for (source.ranges) |range| {
        if (range.start >= range.end or range.end > source.bytes.len or range.occurrence == 0) return false;
        if (range.start < end and start < range.end) return false;
    }
    for (source.literal_curly_ranges) |range| {
        if (range.start >= range.end or range.end > source.bytes.len) return false;
        if (range.start < end and start < range.end) return false;
    }
    for (source.generated_links) |range| {
        if (range.start >= range.end or range.end > source.bytes.len) return false;
        if (range.start < end and start < range.end) return false;
    }
    return true;
}

// The icon supplies no language evidence. Ownership comes only from the normal
// indexed category declaration after both authored/expanded physical H2 scopes
// are observed. This grammar preserves the entire heading and all body bytes.
fn sourceCategoryBannerTarget(codes: LanguageCodes, section: language_source.Section, page_title: []const u8) ?[]const u8 {
    const ns = codes.namespace_catalog orelse return null;
    const syntax = blobs.wikitext_syntax;
    if (section.hyphen_marker or section.heading.len > 4096 or section.source.len == 0) return null;
    const line_end = std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len;
    const heading = syntax.controlHeading(std.mem.trimEnd(u8, section.source[0..line_end], "\r"), null) orelse return null;
    if (heading.level != 2 or !std.mem.eql(u8, heading.title, section.heading)) return null;
    const body = heading.title;
    if (!std.mem.startsWith(u8, body, "[[")) return null;
    const image_pair = syntax.balanced(body, 0) orelse return null;
    const image = body[2..image_pair.inner_end];
    if (std.mem.indexOfAny(u8, image, "[]{}<>&#\r\n\t") != null) return null;
    const pipe = std.mem.indexOfScalar(u8, image, '|') orelse return null;
    const target = image[0..pipe];
    if (target.len == 0 or target[0] == ':' or ns.ofTitle(target).id != 6 or ns.ofTitle(target).text.len == 0) return null;
    var width = false;
    var border = false;
    var options = std.mem.splitScalar(u8, image[pipe + 1 ..], '|');
    while (options.next()) |option| {
        const image_options = @import("namespace_registry").image_options;
        const matched = (if (codes.image_options) |registry| registry.match(option, .image) else image_options.matchEnglish(option, .image)) orelse return null;
        if (std.mem.eql(u8, matched.id, "img_width") and !width) {
            const number = matched.value orelse return null;
            for (number) |byte| if (!std.ascii.isDigit(byte)) return null;
            const pixels = std.fmt.parseInt(u16, number, 10) catch return null;
            if (pixels == 0 or pixels > 4096) return null;
            width = true;
        } else if (std.mem.eql(u8, matched.id, "img_border") and !border) border = true else return null;
    }
    if (!width or !border) return null;
    var rest = body[image_pair.end..];
    if (std.mem.startsWith(u8, rest, "&nbsp;")) rest = rest[6..] else return null;
    if (!std.mem.startsWith(u8, rest, "[[:")) return null;
    const visible_pair = syntax.balanced(rest, 0) orelse return null;
    const visible = rest[3..visible_pair.inner_end];
    if (std.mem.indexOfAny(u8, visible, "[]{}<>&#\r\n\t") != null) return null;
    const separator = std.mem.indexOfScalar(u8, visible, '|') orelse return null;
    const category_target = visible[0..separator];
    const label = visible[separator + 1 ..];
    const category = ns.ofTitle(category_target);
    if (category.id != 14 or label.len == 0 or !std.mem.eql(u8, label, category.text) or
        std.mem.indexOfScalar(u8, label, '|') != null) return null;
    rest = rest[visible_pair.end..];
    if (!std.mem.startsWith(u8, rest, "[[")) return null;
    const hidden_pair = syntax.balanced(rest, 0) orelse return null;
    if (hidden_pair.end != rest.len) return null;
    const hidden = rest[2..hidden_pair.inner_end];
    if (std.mem.indexOfAny(u8, hidden, "[]{}<>&#\r\n\t") != null) return null;
    const sort = std.mem.indexOfScalar(u8, hidden, '|') orelse return null;
    const sort_key = hidden[sort + 1 ..];
    if (!std.mem.eql(u8, hidden[0..sort], category_target)) return null;
    if (!std.mem.eql(u8, sort_key, page_title)) {
        // The indexed provider applies MediaWiki ucfirst to PAGENAME. Map one
        // codepoint only: every suffix byte (including combining marks) is literal.
        if (page_title.len == 0 or !std.unicode.utf8ValidateSlice(page_title)) return null;
        const first_len = std.unicode.utf8ByteSequenceLength(page_title[0]) catch return null;
        var storage: [64]u8 = undefined;
        var scratch = std.heap.FixedBufferAllocator.init(&storage);
        const first = ns.mapper.firstAlloc(scratch.allocator(), page_title[0..first_len]) catch return null;
        if (!std.mem.startsWith(u8, sort_key, first) or !std.mem.eql(u8, sort_key[first.len..], page_title[first_len..])) return null;
    }
    return category_target;
}
fn sourceCategoryRawTemplate(codes: LanguageCodes, section: language_source.Section) ?[]const u8 {
    if (section.hyphen_marker or section.source.len == 0) return null;
    const syntax = blobs.wikitext_syntax;
    const end = std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len;
    const heading = syntax.controlHeading(std.mem.trimEnd(u8, section.source[0..end], "\r"), null) orelse return null;
    if (heading.level != 2 or !std.mem.eql(u8, heading.title, section.heading)) return null;
    const call = heading.title;
    if (!std.mem.startsWith(u8, call, "{{") or !std.mem.endsWith(u8, call, "}}")) return null;
    const name = call[2 .. call.len - 2];
    if (name.len == 0 or std.mem.indexOfAny(u8, name, "{}[]<>&|=:#'\" \t\r\n") != null or
        codes.isLanguageBoundary(name)) return null;
    return name;
}
fn sourceCategoryBannerCandidate(codes: LanguageCodes, title: []const u8, raw: language_source.Section, expanded: language_source.Section) bool {
    if (codes.source_category_heading_fn == null) return false;
    return sourceCategoryRawTemplate(codes, raw) != null and sourceCategoryBannerTarget(codes, expanded, title) != null;
}
fn sourceCategoryBannerOwner(codes: LanguageCodes, title: []const u8, raw: language_source.Section, expanded: language_source.Section) !?ResolvedLanguage {
    if (!raw.root_wiki_heading or !expanded.root_wiki_heading) return null;
    const callback = codes.source_category_heading_fn orelse return null;
    const template = sourceCategoryRawTemplate(codes, raw) orelse return null;
    const target = sourceCategoryBannerTarget(codes, expanded, title) orelse return null;
    const owner = (try callback(codes.source_category_ctx, template, target)) orelse return null;
    const ns = codes.namespace_catalog orelse return null;
    // The callback proved this selected template's complete declaration. A weak
    // code alias with the same title is not its meaning (for example jav/jv).
    // Independently trusted template-name owners still veto a contradiction.
    if (codes.isLanguageBoundary(template)) return null;
    if (codes.resolveStrong(template) orelse codes.resolveTrusted(template)) |other|
        if (!std.mem.eql(u8, other.code, owner.code)) return null;
    for ([_][]const u8{ ns.ofTitle(target).text, owner.code }) |spelling| {
        if (codes.isLanguageBoundary(spelling)) return null;
        if (codes.resolve(spelling)) |other| if (!std.mem.eql(u8, other.code, owner.code)) return null;
    }
    return owner;
}

fn sourceBannerPrelude(codes: LanguageCodes, prefix: []const u8) bool {
    if (prefix.len == 0 or std.mem.eql(u8, prefix, "__NOEDITSECTION__")) return true;
    if (prefix.len > 4096) return false;
    const ns = codes.namespace_catalog orelse return false;
    const syntax = blobs.wikitext_syntax;
    var rest = prefix;
    if (!std.mem.startsWith(u8, rest, "[[")) return false;
    const pair = syntax.balanced(rest, 0) orelse return false;
    const target = rest[2..pair.inner_end];
    if (target.len == 0 or target[0] == ':' or std.mem.indexOfAny(u8, target, "[]{}<>&|#\r\n\t") != null) return false;
    const category = ns.ofTitle(target);
    if (category.id != 14 or std.mem.trim(u8, category.text, " ").len == 0) return false;
    rest = std.mem.trimStart(u8, rest[pair.end..], " \t\r\n");
    const control = "__NOEDITSECTION__";
    if (!std.mem.startsWith(u8, rest, control)) return false;
    rest = std.mem.trimStart(u8, rest[control.len..], " \t\r\n");
    const tag = syntax.tagAt(rest, 0) orelse return false;
    return tag.is("br") and !tag.closing and
        std.mem.trim(u8, tag.attrs, " \t\r\n").len == 0 and
        std.mem.trim(u8, rest[tag.end..], " \t\r\n").len == 0;
}

fn sourceBannerRetainsBreak(codes: LanguageCodes, complete_partition: bool, prefix: []const u8) bool {
    const trimmed = std.mem.trim(u8, prefix, " \t\r\n");
    return complete_partition and std.mem.startsWith(u8, trimmed, "[[") and sourceBannerPrelude(codes, trimmed);
}

fn sourceBannerPrefixOwner(codes: LanguageCodes, complete_partition: bool, raw: []const language_source.Section, rendered: []const language_source.Section, prefix: []const u8) ?ResolvedLanguage {
    if (!sourceBannerRetainsBreak(codes, complete_partition, prefix) or raw.len == 0 or rendered.len != raw.len) return null;
    const matches = codes.source_banner_prefix_fn orelse return null;
    const first = rendered[0];
    const line = first.source[0 .. std.mem.indexOfScalar(u8, first.source, '\n') orelse first.source.len];
    const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
    const code = raw[0].heading;
    if (!matches(codes.ctx, code, heading.title, heading.level, prefix)) return null;
    const owner = codes.resolve(code) orelse return null;
    return if (std.mem.eql(u8, owner.code, code)) owner else null;
}

// A selected static provider may emit hidden categories before its heading.
// This receipt proves only that exact first prefix; the full ordered partition
// below still independently proves every original and rendered boundary.
fn sourceBannerDeclaredPrelude(codes: LanguageCodes, raw: language_source.Section, rendered: language_source.Section, prefix: []const u8) bool {
    if (prefix.len == 0 or prefix.len > 4096 or !raw.hyphen_marker or rendered.hyphen_marker) return false;
    const matches = codes.source_banner_prefix_fn orelse return false;
    const line = rendered.source[0 .. std.mem.indexOfScalar(u8, rendered.source, '\n') orelse rendered.source.len];
    const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return false;
    return matches(codes.ctx, raw.heading, heading.title, heading.level, prefix);
}

fn sourceBannerPartition(codes: LanguageCodes, original: []const u8, source: MissingText, raw: []const language_source.Section, rendered: []const language_source.Section) bool {
    return sourceBannerPartitionWithPrelude(codes, original, source, raw, rendered, false);
}

fn sourceBannerPartitionWithPrelude(codes: LanguageCodes, original: []const u8, source: MissingText, raw: []const language_source.Section, rendered: []const language_source.Section, unowned_prelude: bool) bool {
    if (raw.len < 2 or raw.len > 64 or raw.len != rendered.len or source.unknown or source.lost_missing_range) return false;
    const matches = codes.source_banner_fn orelse return false;
    var raw_cursor = std.math.sub(usize, @intFromPtr(raw[0].source.ptr), @intFromPtr(original.ptr)) catch return false;
    var cursor = std.math.sub(usize, @intFromPtr(rendered[0].source.ptr), @intFromPtr(source.bytes.ptr)) catch return false;
    if (raw_cursor > original.len or cursor > source.bytes.len) return false;
    if (!unowned_prelude and std.mem.trim(u8, original[0..raw_cursor], " \t\r\n").len != 0) return false;
    const prefix = std.mem.trim(u8, source.bytes[0..cursor], " \t\r\n");
    if ((!unowned_prelude and !sourceBannerPrelude(codes, prefix) and !sourceBannerDeclaredPrelude(codes, raw[0], rendered[0], prefix)) or
        !calibratedBoundaryRangesClean(source, 0, cursor)) return false;
    if (unowned_prelude) {
        if (std.mem.trim(u8, original[0..raw_cursor], " \t\r\n").len == 0 or prefix.len == 0) return false;
        for (rendered) |expanded| if (!expanded.root_wiki_heading) return false;
    }
    var first_code: ?[]const u8 = null;
    var distinct = false;
    for (raw, rendered) |authored, expanded| {
        if (!authored.hyphen_marker or expanded.hyphen_marker or authored.source.len == 0 or expanded.source.len == 0 or
            authored.source.len > original.len - raw_cursor or expanded.source.len > source.bytes.len - cursor or
            @intFromPtr(authored.source.ptr) != @intFromPtr(original.ptr) + raw_cursor or
            @intFromPtr(expanded.source.ptr) != @intFromPtr(source.bytes.ptr) + cursor) return false;
        if (unowned_prelude and !language_source.outsideNestedOrOpaque(original, raw_cursor)) return false;
        raw_cursor += authored.source.len; cursor += expanded.source.len;
        const raw_line = authored.source[0 .. std.mem.indexOfScalar(u8, authored.source, '\n') orelse authored.source.len];
        if (raw_line.len < 8 or !std.mem.startsWith(u8, raw_line, "{{-") or !std.mem.endsWith(u8, raw_line, "-}}")) return false;
        const code = raw_line[3 .. raw_line.len - 3];
        if (!std.mem.eql(u8, code, authored.heading) or codes.isLanguageBoundary(code)) return false;
        const owner = codes.resolve(code) orelse return false;
        if (!std.mem.eql(u8, owner.code, code)) return false;
        const line = expanded.source[0 .. std.mem.indexOfScalar(u8, expanded.source, '\n') orelse expanded.source.len];
        const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return false;
        if ((heading.level != 1 and heading.level != 2) or !std.mem.eql(u8, heading.title, expanded.heading) or
            !sourceCategoryHeaderRangesClean(source, expanded)) return false;
        const owned = matches(codes.ctx, code, heading.title, heading.level);
        const boundary = if (codes.source_banner_boundary_fn) |f| f(codes.ctx, code, heading.title, heading.level) else false;
        if (!owned and !boundary) return false;
        if (owned) if (boundaryLanguage(codes, expanded)) |other| if (!std.mem.eql(u8, other.code, code) or !std.mem.eql(u8, other.heading, owner.heading)) return false;
        if (first_code) |first| distinct = distinct or !std.mem.eql(u8, first, code) else first_code = code;
    }
    return distinct and raw_cursor == original.len and cursor == source.bytes.len;
}

fn sourceBannerPairMatches(codes: LanguageCodes, raw: language_source.Section, rendered: language_source.Section) bool {
    if (!raw.hyphen_marker or rendered.hyphen_marker) return false;
    const matches = codes.source_banner_fn orelse return false;
    const line = rendered.source[0 .. std.mem.indexOfScalar(u8, rendered.source, '\n') orelse rendered.source.len];
    const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return false;
    return std.mem.eql(u8, rendered.heading, heading.title) and matches(codes.ctx, raw.heading, heading.title, heading.level);
}

fn sourceBannerBoundaryOnly(codes: LanguageCodes, raw: language_source.Section, rendered: language_source.Section) bool {
    const matches = codes.source_banner_fn orelse return false;
    const boundary = codes.source_banner_boundary_fn orelse return false;
    const line = rendered.source[0 .. std.mem.indexOfScalar(u8, rendered.source, '\n') orelse rendered.source.len];
    const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return false;
    return !matches(codes.ctx, raw.heading, heading.title, heading.level) and
        boundary(codes.ctx, raw.heading, heading.title, heading.level);
}

fn rawPrefixBannerLanguage(codes: LanguageCodes, raw: []const u8, raw_sections: []const language_source.Section, rendered: []const language_source.Section, paired_prefix: bool) ?ResolvedLanguage {
    if (raw_sections.len == 0 or rendered.len == 0) return null;
    const first = raw_sections[0];
    if (!first.hyphen_marker) return null;
    const start = @intFromPtr(first.source.ptr) - @intFromPtr(raw.ptr);
    if (start > raw.len or std.mem.trim(u8, raw[0..start], " \t\r\n").len != 0) return null;
    const canonical = resolveSection(codes, first) orelse return null;
    if (!std.mem.eql(u8, first.heading, canonical.code)) return null;
    const raw_line = std.mem.trim(u8, first.source[0 .. std.mem.indexOfScalar(u8, first.source, '\n') orelse first.source.len], " \t\r");
    if (raw_line.len != canonical.code.len + 6 or !std.mem.startsWith(u8, raw_line, "{{-") or
        !std.mem.endsWith(u8, raw_line, "-}}") or !std.mem.eql(u8, raw_line[3 .. raw_line.len - 3], canonical.code)) return null;

    const section = rendered[0];
    const line = std.mem.trim(u8, section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len], " \t\r");
    const parsed = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
    if (parsed.level < 1 or parsed.level > 2) return null;
    const heading = parsed.title;
    if (heading.len > 4096 or !std.mem.eql(u8, heading, section.heading)) return null;
    if (paired_prefix) return canonical;
    // This exact root invocation must have an authenticated literal template
    // banner proof. No ordinary alias or code-shaped POS name is promoted.
    if (codes.source_banner_fn) |matches| if (matches(codes.ctx, canonical.code, heading, parsed.level)) {
        // This receipt owns the first physical region only. Later peer
        // headings are isolated by the caller instead of vetoing this owner.
        return canonical;
    };
    if (parsed.level != 1) return null;
    const prefix = "<div id=\"";
    const middle = "\" class=\"toccolours\" >'''[[";
    const suffix = "]]'''</div>";
    if (!std.mem.startsWith(u8, heading, prefix)) return null;
    const code_end = std.mem.indexOfScalarPos(u8, heading, prefix.len, '"') orelse return null;
    if (!std.mem.eql(u8, heading[prefix.len..code_end], canonical.code) or
        !std.mem.startsWith(u8, heading[code_end..], middle) or !std.mem.endsWith(u8, heading, suffix) or
        code_end + middle.len + suffix.len > heading.len) return null;
    const body = heading[code_end + middle.len .. heading.len - suffix.len];
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return null;
    if (std.mem.indexOfAny(u8, body, "[]{}<>&\r\n") != null or std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null) return null;
    const target = std.mem.trim(u8, body[0..pipe], " \t");
    const label = std.mem.trim(u8, body[pipe + 1 ..], " \t");
    if (target.len == 0 or std.mem.indexOfAny(u8, target, ":#") != null or !std.mem.eql(u8, label, canonical.heading)) return null;
    const trusted = codes.trusted_fn orelse return null;
    const displayed = trusted(codes.ctx, label) orelse return null;
    if (!std.mem.eql(u8, displayed.code, canonical.code)) return null;
    if (codes.resolve(target)) |linked| if (!std.mem.eql(u8, linked.code, canonical.code)) return null;
    // This exception cannot lend the first owner to a later unresolved peer.
    // Ordinary nested support remains in the first section under the existing
    // Iterator; subsequent independently resolved owners retain their boundary.
    for (rendered[1..]) |later| if (resolveSection(codes, later) == null) return null;
    return canonical;
}

// Both standalone and explicitly authored L2 equals declarations name a code.
// The latter must occupy the complete original heading; arguments or a rendered
// label cannot lend an owner to an unknown code.
fn equalsSectionDeclaration(section: language_source.Section) ?[]const u8 {
    if (language_source.equalsLanguageDeclaration(section.source)) |code|
        return if (std.mem.eql(u8, code, section.heading)) code else null;
    const line = section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len];
    const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
    if (heading.level != 2 or !std.mem.eql(u8, heading.title, section.heading)) return null;
    return language_source.equalsLanguageDeclaration(heading.title);
}

// Borrow only the two physical first H2 lines. This is a boundary precheck,
// not permission to pair every raw and expanded section by ordinal.
fn equalsPrefixCode(raw: []const u8, source: []const u8, original: language_source.Section, section: language_source.Section) ?[]const u8 {
    const syntax = blobs.wikitext_syntax;
    if (original.hyphen_marker or section.hyphen_marker) return null;
    const raw_at = SourceHeadword.offset(raw, original.source) orelse return null;
    const at = SourceHeadword.offset(source, section.source) orelse return null;
    if (std.mem.trim(u8, raw[0..raw_at], "\r\n").len != 0 or
        std.mem.trim(u8, source[0..at], "\r\n").len != 0) return null;
    const raw_line = original.source[0 .. std.mem.indexOfScalar(u8, original.source, '\n') orelse original.source.len];
    const authored = syntax.controlHeading(std.mem.trimEnd(u8, raw_line, "\r"), null) orelse return null;
    if (authored.level != 2 or !std.mem.eql(u8, authored.title, original.heading)) return null;
    const code = language_source.equalsLanguageDeclaration(authored.title) orelse return null;
    if (!std.mem.startsWith(u8, authored.title, "{{=") or !std.mem.endsWith(u8, authored.title, "=}}") or
        authored.title.len != code.len + 6 or !std.mem.eql(u8, authored.title[3 .. authored.title.len - 3], code)) return null;
    const line = section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len];
    const rendered = syntax.controlHeading(std.mem.trimEnd(u8, line, "\r"), null) orelse return null;
    if (rendered.level != 2 or !std.mem.eql(u8, rendered.title, section.heading)) return null;
    return code;
}

fn equalsPrefixCertificate(codes: LanguageCodes, source: MissingText, code: []const u8, section: language_source.Section) ?ResolvedLanguage {
    if (source.lost_missing_range or !sourceCategoryHeaderRangesClean(source, section)) return null;
    missing_dependency.generated_link.validateRanges(source.bytes, source.generated_source, source.generated_links) catch return null;
    const callback = codes.source_equals_fn orelse return null;
    const label = callback(codes.ctx, code) orelse return null;
    if (!std.mem.eql(u8, label, section.heading) or codes.isLanguageBoundary(code) or codes.isLanguageBoundary(label)) return null;
    const owner = codes.resolve(code) orelse return null;
    if (codes.resolve(label)) |other| if (!std.mem.eql(u8, other.code, owner.code)) return null;
    return owner;
}

// Exact selected =code= output certifies the first native root H2 even when a
// later authored malformed table changes section counts. Unknown body ranges
// elsewhere do not invalidate this independently complete static heading.
fn sourceEqualsPrefix(codes: LanguageCodes, raw: []const u8, source: MissingText,
    original: language_source.Section, section: language_source.Section, openings: []const usize) ?ResolvedLanguage
{
    const code = equalsPrefixCode(raw, source.bytes, original, section) orelse return null;
    const at = SourceHeadword.offset(source.bytes, section.source) orelse return null;
    const scopes: language_source.LinkHeadingScopes = .{ .source = source.bytes, .openings = openings };
    if (!scopes.admits(source.bytes, at)) return null;
    return equalsPrefixCertificate(codes, source, code, section);
}

// The original SS/ZU providers in sswiktionary emit this exact H1 and
// immediately following included category. The frame is a boundary; only an
// independently trusted language name supplies ownership. Template case is
// never normalized or used as a language code here.
fn ssBoldBannerLabel(codes: LanguageCodes, value: []const u8) ?[]const u8 {
    const ns = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, ns.wiki, "sswiktionary") or !std.mem.eql(u8, ns.content_language, "ss") or value.len > 4096) return null;
    const prefix = "<div id=\"toc\" class=\"toccolours\" >'''";
    const suffix = "'''</div>";
    if (value.len <= prefix.len + suffix.len or !std.mem.startsWith(u8, value, prefix) or !std.mem.endsWith(u8, value, suffix)) return null;
    const label = value[prefix.len .. value.len - suffix.len];
    if (label.len == 0 or !std.mem.eql(u8, label, std.mem.trim(u8, label, " \t")) or
        std.mem.indexOfAny(u8, label, "<>{}[]|\"'\r\n") != null or
        blobs.part_kind.classify(label) != null or @import("presentation_layout.zig").partOfSpeech(label) != null) return null;
    for ([_][]const u8{ "Pronunciation", "Usage notes", "Alternative forms" }) |name|
        if (blobs.part_kind.named(label, name)) return null;
    return label;
}

fn ssBoldBannerDeclaration(codes: LanguageCodes, section: language_source.Section) ?[]const u8 {
    const label = ssBoldBannerLabel(codes, section.heading) orelse return null;
    if (section.hyphen_marker) return null;
    const end = std.mem.indexOfScalar(u8, section.source, '\n') orelse return null;
    const heading = blobs.wikitext_syntax.controlHeading(section.source[0..end], null) orelse return null;
    if (heading.level != 1 or !std.mem.eql(u8, heading.title, section.heading)) return null;
    const tail = section.source[end + 1 ..];
    const category = tail[0 .. std.mem.indexOfScalar(u8, tail, '\n') orelse tail.len];
    if (!std.mem.startsWith(u8, category, "[[Category:") or !std.mem.endsWith(u8, category, "]]")) return null;
    const parsed = codes.namespace_catalog.?.ofTitle(category[2 .. category.len - 2]);
    if (parsed.id != 14 or !std.mem.eql(u8, parsed.text, label)) return null;
    return label;
}

fn ssBoldBannerOwner(codes: LanguageCodes, section: language_source.Section) ?[]const u8 {
    const label = ssBoldBannerDeclaration(codes, section) orelse return null;
    if (codes.isLanguageBoundary(label)) return null;
    _ = codes.resolveStrong(label) orelse
        (if (codes.trusted_fn) |trusted| trusted(codes.ctx, label) else null) orelse return null;
    return label;
}

fn hasExplicitLanguageDeclaration(codes: LanguageCodes, section: language_source.Section) bool {
    if (ssBoldBannerDeclaration(codes, section) != null) return true;
    if (projectParentheticalDeclaration(codes, section) != null) return true;
    if (arabicLinkedOwner(codes, section.heading) != null) return true;
    if (arabicNorwegianDeclaration(codes, section.heading) != null) return true;
    if (equalsSectionDeclaration(section) != null) return true;
    return declarationLabel(codes, section.heading) != null;
}

fn boundaryLanguage(codes: LanguageCodes, section: language_source.Section) ?ResolvedLanguage {
    if (resolveDecorativeFileBanner(codes, section)) |owner| return owner;
    if (projectParentheticalDeclaration(codes, section)) |declaration| return resolveProjectParenthetical(codes, declaration);
    if (supplementalIconLanguage(codes, section)) |owner| return owner;
    if (imageLanguageLabel(codes, section)) |label|
        return codes.resolveStrong(label) orelse codes.resolveTrusted(label);
    if (arabicLinkedOwner(codes, section.heading)) |declaration| return resolveArabicLinkedOwner(codes, declaration);
    if (arabicNorwegianDeclaration(codes, section.heading) != null)
        return resolveArabicNorwegianDeclaration(codes, section.heading);
    const noun = arabicLemmaDeclaration(codes, section);
    if (noun.present) return if (noun.code) |code| codes.resolve(code) else null;
    const heading = language_source.classificationSection(section);
    if (resolveCategorizedHeading(codes, heading)) |resolved| return resolved;
    if (resolveArabicLanguageHeading(codes, heading)) |resolved| return resolved;
    if (codes.resolve(std.mem.trim(u8, heading, " \t\r\n"))) |resolved| return resolved;
    if (codes.resolve(std.mem.trim(u8, heading, " \t\r\n\'\""))) |resolved| return resolved;
    if (resolveLinkedHeading(codes, heading)) |resolved| return resolved;
    if (resolveMixedArabicLinkedHeading(codes, heading)) |resolved| return resolved;
    var cursor: usize = 0;
    var found: ?ResolvedLanguage = null;
    while (std.mem.indexOfPos(u8, heading, cursor, "[[")) |open| {
        const close = std.mem.indexOfPos(u8, heading, open + 2, "]]") orelse return null;
        cursor = close + 2;
        const body = heading[open + 2 .. close];
        if (std.mem.indexOfAny(u8, body, "[]{}<>") != null) return null;
        const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
        const target = std.mem.trim(u8, body[0..pipe], " \t\r\n:");
        const target_language = codes.resolve(target);
        const label_language = if (pipe < body.len) codes.resolve(std.mem.trim(u8, body[pipe + 1 ..], " \t\r\n")) else null;
        if (target_language != null and label_language != null and !std.mem.eql(u8, target_language.?.code, label_language.?.code)) return null;
        const language = target_language orelse label_language orelse continue;
        if (found) |previous| if (!std.mem.eql(u8, previous.code, language.code)) return null;
        found = language;
    }
    return found;
}

// Complete page-wide hatnotes retain their meaning despite a later heading warning.
// Arbitrary prefix prose and incomplete wrappers keep the existing owner policy.
fn pageWideHatnotePrefix(a: std.mem.Allocator, codes: LanguageCodes, prefix: []const u8) std.mem.Allocator.Error!bool {
    const syntax = blobs.wikitext_syntax;
    var cursor: usize = 0;
    var found = false;
    while (cursor < prefix.len) {
        if (std.ascii.isWhitespace(prefix[cursor])) {
            cursor += 1;
            continue;
        }
        if (std.mem.startsWith(u8, prefix[cursor..], "<!--")) {
            const end = std.mem.indexOfPos(u8, prefix, cursor + 4, "-->") orelse return false;
            cursor = end + 3;
            continue;
        }
        const control_end = if (codes.behavior_switches) |registry|
            try registry.matchAt(a, prefix, cursor)
        else
            syntax.behaviorSwitchEnd(prefix, cursor);
        if (control_end) |end| {
            cursor = end;
            continue;
        }
        const tag = syntax.tagAt(prefix, cursor) orelse return false;
        if (!tag.is("div") or tag.closing or tag.self_closing) return false;
        const classes = tag.attr("class") orelse return false;
        var tokens = std.mem.tokenizeAny(u8, classes, " \t\r\n");
        const class = tokens.next() orelse return false;
        if ((!std.mem.eql(u8, class, "disambig-see-also") and
            !std.mem.eql(u8, class, "disambig-see-also-2")) or tokens.next() != null) return false;
        const pair = syntax.matchingTag(prefix, tag) orelse return false;
        cursor = pair.end;
        found = true;
    }
    return found;
}

// Only a purely decorative image prefix may be shared between language entries.
// Retain exact source and let each normal renderer own captions, refs and dedup.
fn sharedImagePrefix(a: std.mem.Allocator, codes: LanguageCodes, prefix: []const u8) std.mem.Allocator.Error!?[]const u8 {
    const namespaces = codes.namespace_catalog orelse return null;
    const syntax = blobs.wikitext_syntax;
    var cursor: usize = 0;
    var found = false;
    var separated = true;
    while (cursor < prefix.len) {
        if (std.ascii.isWhitespace(prefix[cursor])) {
            if (prefix[cursor] == '\n' or prefix[cursor] == '\r') separated = true;
            cursor += 1;
            continue;
        }
        if (std.mem.startsWith(u8, prefix[cursor..], "<!--")) {
            const end = std.mem.indexOfPos(u8, prefix, cursor + 4, "-->") orelse return null;
            if (std.mem.indexOfScalar(u8, prefix[cursor..end], '\n') != null) separated = true;
            cursor = end + 3;
            continue;
        }
        const control_end = if (codes.behavior_switches) |registry|
            try registry.matchAt(a, prefix, cursor)
        else
            syntax.behaviorSwitchEnd(prefix, cursor);
        if (control_end) |end| {
            cursor = end;
            continue;
        }
        if (!separated or !std.mem.startsWith(u8, prefix[cursor..], "[[")) return null;
        const pair = syntax.balanced(prefix, cursor) orelse return null;
        const body = prefix[cursor + 2 .. pair.inner_end];
        const pipe = syntax.delimiter(body, "|", 0) orelse body.len;
        const target = std.mem.trim(u8, body[0..pipe], " \t\r\n");
        if (std.mem.startsWith(u8, target, ":") or std.mem.indexOfAny(u8, target, "[]{}<>") != null) return null;
        const title = namespaces.ofTitle(target);
        if (title.id != 6 or @import("presentation_media.zig").referencedKind(title.text) != .image) return null;
        cursor = pair.end;
        separated = false;
        found = true;
    }
    return if (found) prefix else null;
}

// Project active controls only for language classification. The original section
// source stays intact for rendering; protected bodies, attributes and entity-
// authored spellings follow the same boundary rules as display compilation.
fn classificationControlHeadingAlloc(a: std.mem.Allocator, codes: LanguageCodes, value: []const u8) !?[]u8 {
    const syntax = blobs.wikitext_syntax;
    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(a);
    var emitted: usize = 0;
    var scan: usize = 0;
    while (scan < value.len) {
        if (value[scan] == '<') {
            if (syntax.protectedEnd(value, scan)) |end| {
                scan = end;
                continue;
            }
            if (syntax.tagAt(value, scan)) |tag| {
                scan = tag.end;
                continue;
            }
        }
        const matched = if (codes.behavior_switches) |registry|
            try registry.matchAt(a, value, scan)
        else
            syntax.behaviorSwitchEnd(value, scan);
        if (matched) |end| {
            const toc = if (codes.behavior_switches) |registry|
                try registry.tocMatchAt(a, value, scan)
            else if (std.ascii.eqlIgnoreCase(value[scan..end], "__TOC__")) end else null;
            if (toc != null and toc.? == end) {
                scan = end;
                continue;
            }
            try out.appendSlice(a, value[emitted..scan]);
            emitted = end;
            scan = end;
        } else scan += 1;
    }
    if (emitted == 0) return null;
    try out.appendSlice(a, value[emitted..]);
    return try out.toOwnedSlice(a);
}

// Captured language banners put a maintenance request after a whole language
// name. Recognize the complete warning, not an arbitrary small-text suffix.
// The edit code only corroborates an independently trusted visible label.
fn translationWarningHeading(codes: LanguageCodes, value: []const u8) ?[]const u8 {
    if (value.len > 4096) return null;
    const heading = std.mem.trim(u8, value, " \t\r\n");
    const prefix = "<div id=\"toc\" class=\"toccolours\" ><big><big><big> ";
    const annotation = "<small><small><small>'''(Please translate \"";
    const suffix = "</small></small></small> </big></big></big></div>";
    if (heading.len < prefix.len + suffix.len or !std.mem.startsWith(u8, heading, prefix) or !std.mem.endsWith(u8, heading, suffix)) return null;
    const body = heading[prefix.len .. heading.len - suffix.len];
    const at = std.mem.indexOf(u8, body, annotation) orelse return null;
    const label = std.mem.trim(u8, body[0..at], " \t");
    if (label.len == 0 or std.mem.indexOfAny(u8, label, "<>{}[]\"\r\n") != null) return null;
    // The captured label and quoted warning retain their exact bytes. A single
    // trailing LRM is display direction metadata, not language-name authority.
    // Use the unmarked spelling only after exact independent lookup fails.
    var lookup = label;
    const language = codes.resolveStrong(label) orelse
        (if (codes.trusted_fn) |trusted| trusted(codes.ctx, label) else null) orelse normalized: {
        const lrm = "\u{200e}";
        if (!std.mem.endsWith(u8, label, lrm) or codes.isLanguageBoundary(label)) return null;
        lookup = label[0 .. label.len - lrm.len];
        if (lookup.len == 0 or std.mem.indexOf(u8, lookup, lrm) != null) return null;
        const owner = codes.resolveStrong(lookup) orelse
            (if (codes.trusted_fn) |trusted| trusted(codes.ctx, lookup) else null) orelse return null;
        if (codes.resolve(label)) |known| if (!std.mem.eql(u8, known.code, owner.code)) return null;
        break :normalized owner;
    };
    var rest = body[at + annotation.len ..];
    if (!std.mem.startsWith(u8, rest, label)) return null;
    rest = rest[label.len..];
    const edit = "\" [http://ik.wiktionary.org/w/index.php?title=Template:-";
    const end = "-&action=edit here])'''";
    if (!std.mem.startsWith(u8, rest, edit) or !std.mem.endsWith(u8, rest, end) or rest.len < edit.len + end.len) return null;
    const code = rest[edit.len .. rest.len - end.len];
    return if (std.mem.eql(u8, code, language.code)) lookup else null;
}

fn classificationHeadingProjectionAlloc(a: std.mem.Allocator, codes: LanguageCodes, value: []const u8) !?[]u8 {
    const controlled = try classificationControlHeadingAlloc(a, codes, value);
    errdefer if (controlled) |owned| a.free(owned);
    if (translationWarningHeading(codes, controlled orelse value)) |label| {
        const projected = try a.dupe(u8, label);
        if (controlled) |owned| a.free(owned);
        return projected;
    }
    return controlled;
}

// AY's captured -syn- emits a lower-level support heading, while syn is also
// Senaya's ISO code. Admit only the corroborated noun/synonym shape after -ay-.
fn corroboratedAySynonymSupport(raw: []const language_source.Section, rendered: []const language_source.Section) bool {
    if (raw.len != 2 or rendered.len != 1 or !raw[0].hyphen_marker or !raw[1].hyphen_marker or
        !std.mem.eql(u8, raw[0].heading, "ay") or !std.mem.eql(u8, raw[1].heading, "syn")) return false;
    const noun = "==<div><big><big>[[suti|Suti]]</big></big></div>==";
    const synonym = "===<big>[[aru masi|Aru masi]]\u{200b}naka</big>===";
    const translations = "===[[Image:Nuvola filesystems www.png|30px]] Yaqha arunaka===";
    var headings = language_source.Iterator.init(rendered[0].source);
    headings.all_heading_levels = true;
    // all_heading_levels admits candidates; the filter also permits depth
    // transitions so the exact sequence checks below can see active L3 support.
    headings.heading_filter = .{ .ctx = null, .accepts = struct {
        fn accepts(_: ?*const anyopaque, _: []const u8) bool { return true; }
    }.accepts };
    const first = headings.next() orelse return false;
    if (!std.mem.startsWith(u8, first.source, noun) or
        (first.source.len > noun.len and first.source[noun.len] != '\n' and first.source[noun.len] != '\r')) return false;
    const second = headings.next() orelse return false;
    if (!std.mem.startsWith(u8, second.source, synonym) or
        (second.source.len > synonym.len and second.source[synonym.len] != '\n' and second.source[synonym.len] != '\r')) return false;
    if (headings.next()) |third| {
        if (!std.mem.startsWith(u8, third.source, translations) or
            (third.source.len > translations.len and third.source[translations.len] != '\n' and third.source[translations.len] != '\r')) return false;
        if (headings.next() != null) return false;
    }
    return true;
}

fn appendClassifiedSection(a: std.mem.Allocator, codes: LanguageCodes, sections: *std.ArrayList(language_source.Section), owned_headings: *std.ArrayList([]u8), section: language_source.Section) !void {
    var projected = section;
    if (ssBoldBannerOwner(codes, section)) |label| {
        const heading = try a.dupe(u8, label);
        errdefer a.free(heading);
        try owned_headings.append(a, heading);
        projected.heading = heading;
    } else if (try classificationHeadingProjectionAlloc(a, codes, section.heading)) |heading| {
        errdefer a.free(heading);
        try owned_headings.append(a, heading);
        projected.heading = heading;
    }
    try sections.append(a, projected);
}

// These retained Italian page-support headings declare no language. This is
// consulted only after ordinary boundary/isolation checks selected the existing
// continuation branch; it cannot choose an owner or clear an earlier refusal.
fn italianSupportContinuation(codes: LanguageCodes, source: MissingText, section: language_source.Section) bool {
    const ns = codes.namespace_catalog orelse return false;
    if (!std.mem.eql(u8, ns.wiki, "itwiktionary") or !std.mem.eql(u8, ns.content_language, "it") or
        source.unknown or source.lost_missing_range or section.hyphen_marker or
        !sourceCategoryHeaderRangesClean(source, section)) return false;
    missing_dependency.generated_link.validateRanges(source.bytes, source.generated_source, source.generated_links) catch return false;
    const line = std.mem.trimEnd(u8, section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len], "\r");
    const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return false;
    if (heading.level != 2 or !std.mem.eql(u8, heading.title, section.heading)) return false;
    if (std.mem.eql(u8, section.heading, "Altri progetti")) return true;
    // The exact emitted -ref- label is independently Notes / References; the
    // decorative file and both links remain untouched in the rendered body.
    if (!std.mem.eql(u8, section.heading,
        "[[Image:Nuvola apps bookcase.svg|30px|]] [[note|Note]] / [[riferimenti|Riferimenti]]")) return false;
    return ns.ofTitle("Image:Nuvola apps bookcase.svg").id == 6 and
        ns.ofTitle("note").id == 0 and ns.ofTitle("riferimenti").id == 0;
}

// Known support/POS vocabulary only; it does not classify any language.
fn knownOuterSupportOrPos(heading: []const u8) bool {
    const part = blobs.part_kind;
    const title = std.mem.trim(u8, heading, " \t\r\n");
    if (part.classify(title) != null or @import("presentation_layout.zig").partOfSpeech(title) != null) return true;
    for ([_][]const u8{ "Pronunciation", "Usage notes", "Alternative forms" }) |name|
        if (part.named(title, name)) return true;
    return false;
}

fn crossReferencedUnknownPeer(codes: LanguageCodes, title: []const u8, raw_before: language_source.Section, before: language_source.Section, raw_peer: language_source.Section, peer: language_source.Section, current_code: []const u8) bool {
    if (current_code.len == 0 or knownOuterSupportOrPos(peer.heading) or knownOuterSupportOrPos(before.heading) or
        !std.mem.eql(u8, raw_before.heading, before.heading) or !std.mem.eql(u8, raw_peer.heading, peer.heading) or
        !std.mem.eql(u8, raw_peer.source, peer.source)) return false;
    inline for (.{ raw_before, before, raw_peer, peer }) |section|
        if (!language_source.literalL2Section(section, null)) return false;
    const raw_owner = resolveSection(codes, raw_before) orelse return false;
    const owner = resolveSection(codes, before) orelse return false;
    if (!std.mem.eql(u8, raw_owner.code, current_code) or !std.mem.eql(u8, owner.code, current_code)) return false;
    const CanonicalCode = struct {
        fn accepts(ctx: ?*const anyopaque, code: []const u8) bool {
            const registry: *const LanguageCodes = @ptrCast(@alignCast(ctx.?));
            const language = registry.resolve(code) orelse return false;
            return std.mem.eql(u8, language.code, code);
        }
    };
    const filter: language_source.Iterator.MarkerFilter = .{ .ctx = &codes, .accepts = CanonicalCode.accepts };
    const raw_code = language_source.peerLanguageReferenceCode(raw_before.source, peer.heading, title, filter) orelse return false;
    const expanded_code = language_source.peerLanguageReferenceCode(before.source, peer.heading, title, filter) orelse return false;
    return std.mem.eql(u8, raw_code, expanded_code);
}

// Paired literal headings calibrate a page convention, never a new alias.
// The preflight only requests root observation; the final call requires the
// actual paired root proofs and clean adjacent separators for known peers.
fn calibratedLiteralPeerOwners(codes: LanguageCodes, raw_source: []const u8, source: MissingText, raw: []const language_source.Section, rendered: []const language_source.Section, require_root: bool) bool {
    if (raw.len != rendered.len or raw.len < 3) return false;
    var first_code: ?[]const u8 = null;
    for (raw, rendered, 0..) |authored, expanded, index| {
        if (!std.mem.eql(u8, authored.heading, expanded.heading) or
            !language_source.literalL2Section(authored, null) or !language_source.literalL2Section(expanded, null) or
            !sourceCategoryHeaderRangesClean(source, expanded)) continue;
        const raw_owner = resolveSection(codes, authored) orelse continue;
        const owner = resolveSection(codes, expanded) orelse continue;
        if (owner.code.len == 0 or !std.mem.eql(u8, raw_owner.code, owner.code)) continue;
        if (require_root) {
            if (!authored.root_wiki_heading or !expanded.root_wiki_heading) continue;
            if (index != 0) {
                _ = language_source.adjacentRootRule(raw_source, authored) orelse continue;
                const rule = language_source.adjacentRootRule(source.bytes, expanded) orelse continue;
                if (!calibratedBoundaryRangesClean(source, rule.start, rule.end)) continue;
            }
        }
        if (first_code) |first| {
            if (!std.mem.eql(u8, first, owner.code)) return true;
        } else first_code = owner.code;
    }
    return false;
}

fn calibratedBoundaryRangesClean(source: MissingText, start: usize, end: usize) bool {
    if (start > end or end > source.bytes.len) return false;
    for (source.ranges) |range| {
        if (range.start >= range.end or range.end > source.bytes.len or range.occurrence == 0) return false;
        if (range.start < end and start < range.end) return false;
    }
    for (source.literal_curly_ranges) |range| {
        if (range.start >= range.end or range.end > source.bytes.len) return false;
        if (range.start < end and start < range.end) return false;
    }
    for (source.generated_links) |range| {
        if (range.start >= range.end or range.end > source.bytes.len) return false;
        if (range.start < end and start < range.end) return false;
    }
    // Unknown remains unknown. This grants only a boundary between authored
    // paired literal regions, not missing-template completeness or an owner.
    return true;
}

fn calibratedUnknownLexicalShape(authored: language_source.Section, expanded: language_source.Section) bool {
    return std.mem.eql(u8, authored.heading, expanded.heading) and
        !knownOuterSupportOrPos(authored.heading) and !knownOuterSupportOrPos(expanded.heading) and
        language_source.authoredL2LexicalSubtreeWithLiteralTail(authored, null) and
        language_source.authoredL2LexicalSubtreeWithLiteralTail(expanded, null);
}

fn calibratedUnknownPreflight(codes: LanguageCodes, raw_source: []const u8, source: MissingText, raw: []const language_source.Section, rendered: []const language_source.Section) bool {
    if (raw.len != rendered.len) return false;
    for (raw, rendered) |authored, expanded| {
        if (resolveSection(codes, authored) != null or resolveSection(codes, expanded) != null or
            !calibratedUnknownLexicalShape(authored, expanded)) continue;
        _ = language_source.adjacentPhysicalRule(raw_source, authored) orelse continue;
        const rule = language_source.adjacentPhysicalRule(source.bytes, expanded) orelse continue;
        if (calibratedBoundaryRangesClean(source, rule.start, rule.end)) return true;
    }
    return false;
}

fn calibratedUnknownLexicalBoundary(raw_source: []const u8, source: MissingText, authored: language_source.Section, expanded: language_source.Section) bool {
    if (!authored.root_wiki_heading or !expanded.root_wiki_heading or !calibratedUnknownLexicalShape(authored, expanded)) return false;
    _ = language_source.adjacentRootRule(raw_source, authored) orelse return false;
    const rule = language_source.adjacentRootRule(source.bytes, expanded) orelse return false;
    const start = std.math.sub(usize, @intFromPtr(expanded.source.ptr), @intFromPtr(source.bytes.ptr)) catch return false;
    if (start > source.bytes.len or expanded.source.len > source.bytes.len - start) return false;
    return calibratedBoundaryRangesClean(source, rule.start, start + expanded.source.len);
}

// Calibrate a boundary-only marker convention from this page's authored POS
// calls and independently owned expanded banners. No unknown code/name becomes
// a registry alias. The complete filtered sequences must have one unique,
// order-preserving correspondence, including every known peer and one unknown.
const TemplatePeerBoundary = struct {
    const Raw = struct { code: []const u8, family: []const u8, end: usize };
    const Expanded = struct { pos: []const u8, pos_start: usize, end: usize };

    fn letters(value: []const u8) bool {
        if (value.len < 2 or value.len > 12) return false;
        for (value) |byte| if (byte < 'a' or byte > 'z') return false;
        return true;
    }
    fn physical(section: language_source.Section) ?blobs.wikitext_syntax.ControlHeading {
        if (section.source.len == 0 or section.source[0] != '=') return null;
        const end = SourceHeadword.lineEnd(section.source, 0);
        const heading = blobs.wikitext_syntax.controlHeading(std.mem.trimEnd(u8, section.source[0..end], "\r"), null) orelse return null;
        if (heading.level != 2 or !std.mem.eql(u8, heading.title, section.heading)) return null;
        return heading;
    }
    fn firstBodyLine(source: []const u8) []const u8 {
        var start = SourceHeadword.afterLine(source, 0);
        while (start < source.len) {
            const end = SourceHeadword.lineEnd(source, start);
            const line = std.mem.trimEnd(u8, source[start..end], "\r");
            if (std.mem.trim(u8, line, " \t").len != 0) return line;
            start = SourceHeadword.afterLine(source, start);
        }
        return source[source.len..];
    }
    fn raw(section: language_source.Section) ?Raw {
        const heading = physical(section) orelse return null;
        if (heading.title.len < 6 or !std.mem.startsWith(u8, heading.title, "{{-") or !std.mem.endsWith(u8, heading.title, "-}}")) return null;
        const code = heading.title[3 .. heading.title.len - 3];
        if (!letters(code) or code.len > 3) return null;
        const line = firstBodyLine(section.source);
        if (!std.mem.startsWith(u8, line, "{{-") or !std.mem.endsWith(u8, line, "}}")) return null;
        const pipe = std.mem.indexOfScalar(u8, line, '|') orelse return null;
        if (pipe < 5 or line[pipe - 1] != '-') return null;
        const family = line[3 .. pipe - 1];
        if (!letters(family) or !std.mem.eql(u8, line[pipe + 1 .. line.len - 2], code)) return null;
        const offset = SourceHeadword.offset(section.source, line) orelse return null;
        return .{ .code = code, .family = family, .end = offset + line.len };
    }
    fn expanded(section: language_source.Section) ?Expanded {
        _ = physical(section) orelse return null;
        const line = firstBodyLine(section.source);
        if (line.len == 0 or line[0] != '=') return null;
        const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
        if (heading.level != 3 or heading.title.len == 0 or
            !language_source.authoredL2LexicalBody(section, null, false)) return null;
        const start = SourceHeadword.offset(section.source, line) orelse return null;
        return .{ .pos = line, .pos_start = start, .end = start + line.len };
    }
    fn unknownLink(codes: LanguageCodes, section: language_source.Section) bool {
        const heading = (physical(section) orelse return false).title;
        if (!std.mem.startsWith(u8, heading, "[[")) return false;
        const pair = blobs.wikitext_syntax.balanced(heading, 0) orelse return false;
        if (pair.end != heading.len) return false;
        const body = heading[2..pair.inner_end];
        const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return false;
        const target = body[0..pipe];
        const label = body[pipe + 1 ..];
        inline for (.{target, label}) |value| {
            if (value.len == 0 or !std.unicode.utf8ValidateSlice(value) or
                !std.mem.eql(u8, value, std.mem.trim(u8, value, " \t")) or
                std.mem.indexOfAny(u8, value, ":#%&{}[]<>|=\r\n\"'") != null or
                knownOuterSupportOrPos(value) or codes.resolve(value) != null or codes.isLanguageBoundary(value)) return false;
        }
        return resolveSection(codes, section) == null;
    }
    fn candidate(codes: LanguageCodes, authored: []const language_source.Section) bool {
        for (authored) |section| if (raw(section)) |value| {
            if (codes.resolve(value.code) == null) return true;
        };
        return false;
    }
    fn boundary(codes: LanguageCodes, raw_source: []const u8, source: MissingText,
        authored: []const language_source.Section, rendered: []const language_source.Section,
        raw_roots: []const usize, roots: []const usize, content_roots: []const usize) ?usize
    {
        var family: ?[]const u8 = null;
        // Multiple unresolved declarations cannot borrow an arbitrary pairing.
        for (authored) |section| if (raw(section)) |value| {
            if (codes.resolve(value.code) == null) {
                if (family != null) return null;
                family = value.family;
            }
        };
        const selected_family = family orelse return null;
        var pos: ?[]const u8 = null;
        // A known raw code establishes no expanded location on its own. Obtain
        // the shared first POS only from independently authenticated banners.
        for (rendered) |section| {
            if (supplementalIconLanguage(codes, section) == null) continue;
            const value = expanded(section) orelse continue;
            for (authored) |raw_section| {
                const declaration = raw(raw_section) orelse continue;
                if (!std.mem.eql(u8, declaration.family, selected_family)) continue;
                const owner = codes.resolve(declaration.code) orelse continue;
                const banner = supplementalIconLanguage(codes, section).?;
                if (!std.mem.eql(u8, owner.code, declaration.code) or !std.mem.eql(u8, owner.code, banner.code)) continue;
                if (pos) |previous| {
                    if (!std.mem.eql(u8, previous, value.pos)) return null;
                } else pos = value.pos;
            }
        }
        const selected_pos = pos orelse return null;
        var raw_cursor: usize = 0;
        var first_code: ?[]const u8 = null;
        var distinct = false;
        var unknown: ?usize = null;
        var paired: usize = 0;
        for (rendered, 0..) |section, index| {
            const value = expanded(section) orelse continue;
            if (!std.mem.eql(u8, value.pos, selected_pos)) continue;
            var raw_section: ?language_source.Section = null;
            var declaration: ?Raw = null;
            while (raw_cursor < authored.len) {
                const next = authored[raw_cursor];
                raw_cursor += 1;
                const marker = raw(next) orelse continue;
                if (!std.mem.eql(u8, marker.family, selected_family)) continue;
                raw_section = next;
                declaration = marker;
                break;
            }
            const original = raw_section orelse return null;
            const marker = declaration.?;
            const raw_start = SourceHeadword.offset(raw_source, original.source) orelse return null;
            const start = SourceHeadword.offset(source.bytes, section.source) orelse return null;
            if (!SourceHeadword.root(raw_roots, raw_start) or !SourceHeadword.root(roots, start) or
                !SourceHeadword.root(content_roots, start + value.pos_start) or
                !calibratedBoundaryRangesClean(source, start, start + value.end)) return null;
            // Repeated codes (including aliases for a known code) would make
            // order alone ambiguous. Refuse instead of selecting one match.
            for (authored[0 .. raw_cursor - 1]) |prior| if (raw(prior)) |previous| {
                if (std.mem.eql(u8, previous.family, selected_family) and std.mem.eql(u8, previous.code, marker.code)) return null;
            };
            if (codes.resolve(marker.code)) |owner| {
                const banner = supplementalIconLanguage(codes, section) orelse return null;
                if (!std.mem.eql(u8, marker.code, owner.code) or !std.mem.eql(u8, banner.code, owner.code)) return null;
                if (first_code) |first| distinct = distinct or !std.mem.eql(u8, first, owner.code)
                else first_code = owner.code;
            } else {
                if (unknown != null or !unknownLink(codes, section)) return null;
                unknown = index;
            }
            paired += 1;
        }
        for (authored[raw_cursor..]) |section| if (raw(section)) |value| {
            if (std.mem.eql(u8, value.family, selected_family)) return null;
        };
        return if (paired >= 3 and distinct) unknown else null;
    }
};

// A leading authored lexical region has no established owner to inherit.
// Preserve it as ambiguous data, not as a newly inferred language. Restrict
// this recovery to unchanged source and an independently known literal peer.
fn leadingUnownedLexicalRegion(codes: LanguageCodes, raw: []const language_source.Section, rendered: []const language_source.Section) bool {
    if (raw.len != rendered.len or raw.len < 2) return false;
    const first = rendered[0];
    if (!std.mem.eql(u8, raw[0].heading, first.heading) or
        !std.mem.eql(u8, raw[0].source, first.source) or
        knownOuterSupportOrPos(first.heading) or
        !language_source.authoredL2LexicalSubtree(first, null)) return false;
    for (raw[1..], rendered[1..]) |authored, expanded| {
        if (!std.mem.eql(u8, authored.heading, expanded.heading) or
            !std.mem.eql(u8, authored.source, expanded.source) or
            !language_source.literalL2Section(expanded, null)) continue;
        const owner = boundaryLanguage(codes, expanded) orelse continue;
        const raw_owner = boundaryLanguage(codes, authored) orelse continue;
        if (std.mem.eql(u8, owner.code, raw_owner.code)) return true;
    }
    return false;
}

// A direct numbered meaning under an unresolved leading H2 is a separate
// authored region. It gains no language; the paired known H2 only proves where
// its bytes stop. Ordinary raw/rendered root observations remain mandatory.
const LeadingDirectDefinition = struct {
    fn prefix(codes: LanguageCodes, raw_source: []const u8, source: MissingText,
        raw: []const language_source.Section, rendered: []const language_source.Section,
        require_root: bool) ?[]const u8
    {
        if (raw.len != 2 or rendered.len != 2 or source.lost_missing_range or source.generated_source != null) return null;
        if (resolveSection(codes, raw[0]) != null or resolveSection(codes, rendered[0]) != null or
            knownOuterSupportOrPos(raw[0].heading)) return null;
        for (raw, rendered) |authored, expanded| {
            if (!std.mem.eql(u8, authored.heading, expanded.heading) or
                !language_source.literalL2Section(authored, null) or
                !language_source.literalL2Section(expanded, null)) return null;
            if (require_root and (!authored.root_wiki_heading or !expanded.root_wiki_heading)) return null;
            _ = SourceHeadword.offset(raw_source, authored.source) orelse return null;
            _ = SourceHeadword.offset(source.bytes, expanded.source) orelse return null;
            const raw_line = authored.source[0..SourceHeadword.lineEnd(authored.source, 0)];
            const line = expanded.source[0..SourceHeadword.lineEnd(expanded.source, 0)];
            if (!std.mem.eql(u8, raw_line, line) or !sourceCategoryHeaderRangesClean(source, expanded)) return null;
        }
        const owner = boundaryLanguage(codes, rendered[1]) orelse return null;
        const original_owner = boundaryLanguage(codes, raw[1]) orelse return null;
        if (owner.code.len == 0 or !std.mem.eql(u8, owner.code, original_owner.code) or
            !std.mem.eql(u8, owner.heading, original_owner.heading)) return null;
        const original = SourceNomLeadingRegion.lexicalPrefix(raw[0]) orelse return null;
        const meaning = SourceNomLeadingRegion.lexicalPrefix(rendered[0]) orelse return null;
        if (!std.mem.eql(u8, original, meaning)) return null;
        const at = SourceHeadword.offset(source.bytes, rendered[0].source) orelse return null;
        const meaning_at = SourceHeadword.offset(rendered[0].source, meaning) orelse return null;
        if (!calibratedBoundaryRangesClean(source, at, at + meaning_at + meaning.len)) return null;
        return meaning;
    }

    fn boundary(a: std.mem.Allocator, title: []const u8, codes: LanguageCodes, raw_source: []const u8,
        source: MissingText, raw: []const language_source.Section, rendered: []const language_source.Section) !bool
    {
        const meaning = prefix(codes, raw_source, source, raw, rendered, true) orelse return false;
        return SourceNomLeadingRegion.hasMeaning(a, title, codes, meaning);
    }
};

// A transformed leading H2 can delimit an unknown lexical region without
// naming its language. Its unchanged ordinary definition prefix and every
// ordered root pair must be proved independently of the later named owner.
const SourceNomLeadingRegion = struct {
    fn lexicalPrefix(section: language_source.Section) ?[]const u8 {
        const body = SourceHeadword.afterLine(section.source, 0);
        var cursor = body;
        while (cursor < section.source.len) {
            const end = SourceHeadword.lineEnd(section.source, cursor);
            const line = std.mem.trimEnd(u8, section.source[cursor..end], "\r");
            // No table, HTML, template, protected or indented scope may lend
            // the direct definition. Balanced ordinary links remain body data.
            if (std.mem.indexOfAny(u8, line, "{}<>") != null or
                (line.len != 0 and (line[0] == '=' or line[0] == ' ' or line[0] == '\t'))) return null;
            var pos: usize = 0;
            while (pos < line.len) {
                if (line[pos] == '[') {
                    if (!std.mem.startsWith(u8, line[pos..], "[[")) return null;
                    const pair = blobs.wikitext_syntax.balanced(line, pos) orelse return null;
                    pos = pair.end;
                } else {
                    if (line[pos] == ']') return null;
                    pos += 1;
                }
            }
            if (line.len > 1 and line[0] == '#' and std.mem.indexOfScalar(u8, "#*:;", line[1]) == null and
                std.mem.trim(u8, line[1..], " \t").len != 0) return section.source[body..end];
            cursor = SourceHeadword.afterLine(section.source, cursor);
        }
        return null;
    }

    fn unknownHeading(codes: LanguageCodes, raw: language_source.Section, rendered: language_source.Section) bool {
        if (resolveSection(codes, raw) != null or resolveSection(codes, rendered) != null) return false;
        const authored = raw.heading;
        if (!std.mem.startsWith(u8, authored, "{{") or !std.mem.endsWith(u8, authored, "}}") or authored.len <= 4) return false;
        const name = authored[2 .. authored.len - 2];
        if (!std.mem.eql(u8, name, std.mem.trim(u8, name, " \t")) or
            std.mem.indexOfAny(u8, name, "{}[]<>|=:#\r\n") != null or knownOuterSupportOrPos(name)) return false;
        // This closed emitted decoration supplies only a plain unknown label;
        // neither its ID nor its category creates an owner or a registry alias.
        const prefix = "<span id=\"";
        const heading = rendered.heading;
        if (!std.mem.startsWith(u8, heading, prefix)) return false;
        const id_end = std.mem.indexOfPos(u8, heading, prefix.len, "\">") orelse return false;
        if (id_end == prefix.len) return false;
        for (heading[prefix.len..id_end]) |byte|
            if (!std.ascii.isAlphanumeric(byte) and byte != '-' and byte != '_') return false;
        const start = id_end + 2;
        const close = std.mem.indexOfPos(u8, heading, start, "</span>") orelse return false;
        const label = heading[start..close];
        if (label.len == 0 or std.mem.indexOfAny(u8, label, "{}[]<>&|=\r\n") != null or knownOuterSupportOrPos(label) or
            codes.resolve(label) != null or codes.isLanguageBoundary(label)) return false;
        const tail = heading[close + 7 ..];
        if (tail.len != 0) {
            if (!std.mem.startsWith(u8, tail, "[[") or !std.mem.endsWith(u8, tail, "]]")) return false;
            const target = tail[2 .. tail.len - 2];
            if (target.len == 0 or target[0] == ':' or std.mem.indexOfAny(u8, target, "{}[]<>&|=\r\n") != null) return false;
            const ns = codes.namespace_catalog orelse return false;
            const category = ns.ofTitle(target);
            if (category.id != 14 or category.text.len == 0) return false;
        }
        return true;
    }

    fn hasMeaning(a: std.mem.Allocator, title: []const u8, codes: LanguageCodes, prefix: []const u8) !bool {
        const compiler = @import("presentation_compile.zig");
        const start = if (std.mem.lastIndexOfScalar(u8, prefix, '\n')) |newline| newline + 1 else 0;
        var arena = std.heap.ArenaAllocator.init(a);
        defer arena.deinit();
        // Query only the definition's ordinary semantic output. This does not
        // issue paint, source ownership or language authority for the probe.
        const rejection_scope = presentation_document.RejectedFieldCapture.suspendCapture();
        defer rejection_scope.deinit();
        var renderer: compiler.Renderer = .{ .a = arena.allocator(), .context = .{ .title = title,
            .link_trail = codes.link_trail, .namespace_catalog = codes.namespace_catalog,
            .behavior_switches = codes.behavior_switches, .image_options = codes.image_options } };
        const blocks = renderer.renderBody(prefix[start..]) catch |err| switch (err) {
            error.UncompiledPresentation, error.UncompiledTemplate, error.RenderLimit => return false,
            else => return err,
        };
        if (renderer.fallbacks.any() or blocks.len != 1 or blocks[0].kind != .definition) return false;
        for (blocks[0].spans) |span| {
            if (span.ruby != null) {
                const fallback = compiler.plainText(arena.allocator(), &.{span}) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    else => return false,
                };
                if (std.mem.trim(u8, fallback, " \t\r\n\x0c").len != 0) return true;
                continue;
            }
            if (span.image != null or (span.kind != .text and span.kind != .link and span.kind != .external_link)) continue;
            if (std.mem.trim(u8, span.text, " \t\r\n").len != 0) return true;
        }
        return false;
    }

    fn boundary(a: std.mem.Allocator, title: []const u8, codes: LanguageCodes, raw_source: []const u8, source: MissingText,
        raw: []const language_source.Section, rendered: []const language_source.Section) !bool
    {
        if (!codes.source_nom_name_format or raw.len < 2 or raw.len != rendered.len or source.unknown or
            !calibratedBoundaryRangesClean(source, 0, source.bytes.len)) return false;
        var raw_cursor: usize = 0;
        var cursor: usize = 0;
        var named_peer = false;
        var lexical_prefix: ?[]const u8 = null;
        for (raw, rendered, 0..) |authored, expanded, index| {
            if (authored.source.len == 0 or raw_cursor > raw_source.len or authored.source.len > raw_source.len - raw_cursor or
                authored.source.ptr != raw_source[raw_cursor..].ptr or
                expanded.source.len == 0 or cursor > source.bytes.len or expanded.source.len > source.bytes.len - cursor or
                expanded.source.ptr != source.bytes[cursor..].ptr or
                !authored.root_wiki_heading or !expanded.root_wiki_heading or authored.hyphen_marker or expanded.hyphen_marker) return false;
            inline for (.{ authored, expanded }) |section| {
                const line = std.mem.trimEnd(u8, section.source[0..SourceHeadword.lineEnd(section.source, 0)], "\r");
                const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return false;
                if (heading.level != 2 or !std.mem.eql(u8, heading.title, section.heading)) return false;
            }
            if (index == 0) {
                if (!unknownHeading(codes, authored, expanded)) return false;
                const original = lexicalPrefix(authored) orelse return false;
                const observed = lexicalPrefix(expanded) orelse return false;
                if (!std.mem.eql(u8, original, observed)) return false;
                lexical_prefix = observed;
            } else if (sourceNomHeadingOwner(codes, source, authored, expanded) != null) {
                named_peer = true;
            } else if (!std.mem.eql(u8, authored.heading, expanded.heading) or
                !std.mem.eql(u8, authored.source, expanded.source)) return false;
            raw_cursor += authored.source.len;
            cursor += expanded.source.len;
        }
        if (!named_peer or raw_cursor != raw_source.len or cursor != source.bytes.len) return false;
        return hasMeaning(a, title, codes, lexical_prefix.?);
    }
};

// An unchanged complete page can explicitly delimit one unknown lexical
// region and a later known language using the same simple linked-H2 convention.
// Bound every peer independently; the known peer lends no owner to its neighbors.
fn linkedPeerPartition(codes: LanguageCodes, raw_source: []const u8, source: MissingText, raw: []const language_source.Section, rendered: []const language_source.Section, require_root: bool) bool {
    if (raw.len < 2 or raw.len != rendered.len or source.unknown) return false;
    const first_label = language_source.linkedL2Section(raw[0], null) orelse return false;
    if (knownOuterSupportOrPos(first_label) or resolveSection(codes, raw[0]) != null or
        resolveSection(codes, rendered[0]) != null) return false;
    if (!std.mem.eql(u8, raw_source, source.bytes) or
        !calibratedBoundaryRangesClean(source, 0, source.bytes.len) or
        !language_source.authoredLinkedL2LexicalSubtree(raw[0], null) or
        !language_source.authoredLinkedL2LexicalSubtree(rendered[0], null)) return false;
    var cursor: usize = 0;
    var known_linked_peer = false;
    for (raw, rendered, 0..) |authored, expanded, index| {
        if (authored.source.len == 0 or cursor > raw_source.len or
            authored.source.len > raw_source.len - cursor or
            authored.source.ptr != raw_source[cursor..].ptr or
            expanded.source.ptr != source.bytes[cursor..].ptr or
            expanded.source.len != authored.source.len or
            !std.mem.eql(u8, authored.heading, expanded.heading) or
            !std.mem.eql(u8, authored.source, expanded.source)) return false;
        if (require_root and (!authored.root_wiki_heading or !expanded.root_wiki_heading)) return false;
        const linked = language_source.linkedL2Section(authored, null);
        if (linked) |target| {
            const other = language_source.linkedL2Section(expanded, null) orelse return false;
            if (!std.mem.eql(u8, target, other) or codes.isLanguageBoundary(target)) return false;
            const raw_owner = resolveSection(codes, authored);
            const owner = resolveSection(codes, expanded);
            if ((raw_owner == null) != (owner == null)) return false;
            if (raw_owner) |r| {
                const resolved = owner.?;
                const direct = codes.resolve(target) orelse return false;
                if (r.code.len == 0 or !std.mem.eql(u8, r.code, resolved.code) or
                    !std.mem.eql(u8, r.heading, resolved.heading) or
                    !std.mem.eql(u8, direct.code, resolved.code)) return false;
                if (index != 0) known_linked_peer = true;
            }
        } else if (!language_source.literalL2Section(authored, null) or
            !language_source.literalL2Section(expanded, null)) return false;
        cursor += authored.source.len;
    }
    return cursor == source.bytes.len and known_linked_peer;
}

// A known lexical region and one later, unresolved link-only peer can use the
// same authored linked-H2 convention. This proves a boundary, never the peer's
// language or POS. The separate first-unknown linkedPeerPartition is unchanged.
fn knownFirstLinkedPeerPartition(codes: LanguageCodes, raw_source: []const u8, source: MissingText, raw: []const language_source.Section, rendered: []const language_source.Section, require_root: bool) bool {
    if (raw.len != 2 or rendered.len != 2 or source.unknown or
        !std.mem.eql(u8, raw_source, source.bytes) or
        std.mem.indexOf(u8, raw_source, "{{") != null or
        !calibratedBoundaryRangesClean(source, 0, source.bytes.len)) return false;
    var cursor: usize = 0;
    for (raw, rendered, 0..) |authored, expanded, index| {
        if (authored.source.len == 0 or cursor > raw_source.len or
            authored.source.len > raw_source.len - cursor or
            authored.source.ptr != raw_source[cursor..].ptr or
            expanded.source.ptr != source.bytes[cursor..].ptr or
            expanded.source.len != authored.source.len or
            !std.mem.eql(u8, authored.heading, expanded.heading) or
            !std.mem.eql(u8, authored.source, expanded.source)) return false;
        if (require_root and (!authored.root_wiki_heading or !expanded.root_wiki_heading)) return false;
        const target = language_source.linkedL2Section(authored, null) orelse return false;
        const other = language_source.linkedL2Section(expanded, null) orelse return false;
        if (!std.mem.eql(u8, target, other) or !linkedPeerTargetCodepointsValid(target) or knownOuterSupportOrPos(target) or
            codes.isLanguageBoundary(target)) return false;
        if (index == 0) {
            // resolveTrusted's legacy fallback is not an independent trust
            // certificate when no trusted callback is installed.
            const trusted = codes.resolveStrong(target) orelse
                (if (codes.trusted_fn != null) codes.resolveTrusted(target) else null) orelse return false;
            const direct = codes.resolve(target) orelse return false;
            const raw_owner = resolveSection(codes, authored) orelse return false;
            const owner = resolveSection(codes, expanded) orelse return false;
            if (trusted.code.len == 0 or !std.mem.eql(u8, trusted.code, direct.code) or
                !std.mem.eql(u8, trusted.heading, direct.heading) or
                !std.mem.eql(u8, trusted.code, raw_owner.code) or
                !std.mem.eql(u8, trusted.heading, raw_owner.heading) or
                !std.mem.eql(u8, trusted.code, owner.code) or
                !std.mem.eql(u8, trusted.heading, owner.heading) or
                !language_source.authoredLinkedL2LexicalSubtree(authored, null) or
                !language_source.authoredLinkedL2LexicalSubtree(expanded, null)) return false;
        } else {
            if (codes.resolve(target) != null or codes.resolveStrong(target) != null or
                codes.resolveTrusted(target) != null or resolveSection(codes, authored) != null or
                resolveSection(codes, expanded) != null or
                !linkedPeerSingleLocalLinkBody(authored) or !linkedPeerSingleLocalLinkBody(expanded)) return false;
        }
        cursor += authored.source.len;
    }
    return cursor == source.bytes.len;
}

fn linkedPeerSingleLocalLinkBody(section: language_source.Section) bool {
    const first_end = std.mem.indexOfScalar(u8, section.source, '\n') orelse return false;
    // Only blank physical lines may surround the link. Leading indentation,
    // support prose, wrappers, templates and rich/piped labels do not qualify.
    const body = std.mem.trim(u8, section.source[first_end + 1 ..], "\r\n");
    if (!std.mem.startsWith(u8, body, "[[")) return false;
    const link = blobs.wikitext_syntax.balanced(body, 0) orelse return false;
    if (link.end != body.len) return false;
    const target = body[2..link.inner_end];
    if (target.len == 0 or !std.mem.eql(u8, target, std.mem.trim(u8, target, " \t")) or
        std.mem.indexOfAny(u8, target, ":#%&{}[]<>|='\\\r\n\t\x7f") != null or
        !linkedPeerTargetCodepointsValid(target)) return false;
    return true;
}

// Same codepoint eligibility as compiler safeInternalTarget. This is only a
// necessary validity check; the callers retain their narrower source grammar.
fn linkedPeerTargetCodepointsValid(target: []const u8) bool {
    for (target) |byte| if (byte < 0x20 or byte == 0x7f) return false;
    if (!std.unicode.utf8ValidateSlice(target)) return false;
    var view = std.unicode.Utf8View.initUnchecked(target);
    var it = view.iterator();
    while (it.nextCodepoint()) |cp| if ((cp >= 0x80 and cp <= 0x9f) or cp == 0xfffd) return false;
    return true;
}

const LanguageMarkers = struct {
    codes: *const LanguageCodes,
    represented: ?[]const []const u8 = null,
    expanded_sections: []const language_source.Section = &.{},
    raw_source: ?[]const u8 = null,
    expanded_source: ?[]const u8 = null,
    expanded_missing: ?MissingText = null,
};

// The selected template proof describes one first root declaration. Never
// search a later template/category, infer an edition, or borrow body ownership.
fn sourceCategoryH1Prefix(raw_context: ?*const anyopaque, line: []const u8) bool {
    const markers: *const LanguageMarkers = @ptrCast(@alignCast(raw_context orelse return false));
    const codes = markers.codes.*;
    const raw = markers.raw_source orelse return false;
    const expanded = markers.expanded_source orelse return false;
    const tracked = markers.expanded_missing orelse return false;
    if (tracked.bytes.ptr != expanded.ptr or tracked.bytes.len != expanded.len) return false;
    const start = std.math.sub(usize, @intFromPtr(line.ptr), @intFromPtr(expanded.ptr)) catch return false;
    if (start > expanded.len or line.len > expanded.len - start or
        std.mem.trim(u8, expanded[0..start], "\r\n").len != 0) return false;
    if (!sourceCategoryHeaderRangesClean(tracked, .{ .heading = "", .source = line })) return false;
    const original = std.mem.trimStart(u8, raw, "\r\n");
    const raw_line = std.mem.trimEnd(u8, original[0 .. std.mem.indexOfScalar(u8, original, '\n') orelse original.len], "\r");
    if (raw_line.len < 8 or !std.mem.startsWith(u8, raw_line, "{{-") or !std.mem.endsWith(u8, raw_line, "-}}")) return false;
    const code = raw_line[3 .. raw_line.len - 3];
    if (std.mem.indexOfAny(u8, code, "{}[]<>&|=:#'\" \t\r\n") != null or codes.isLanguageBoundary(code)) return false;
    const owner = codes.resolve(code) orelse return false;
    if (!std.mem.eql(u8, owner.code, code)) return false;
    const label = language_source.categoryLinkedLineHtmlH1(line, codes.namespace_catalog) orelse return false;
    const named = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return false;
    if (!std.mem.eql(u8, named.code, code) or codes.isLanguageBoundary(label)) return false;
    const tag = blobs.wikitext_syntax.tagAt(line, 0) orelse return false;
    const pair = blobs.wikitext_syntax.matchingTag(line, tag) orelse return false;
    const matches = codes.source_banner_fn orelse return false;
    return matches(codes.ctx, code, line[0..pair.end], 1);
}

// An unknown raw equals marker is a boundary only when actual expanded L2
// independently repeats its code in a whole linked declaration. This does
// not resolve the code or assign the linked target's language to that region.
fn expandedEqualsDeclaration(section: language_source.Section, code: []const u8) bool {
    const source = std.mem.trimStart(u8, section.source, " \t\r");
    if (!std.mem.startsWith(u8, source, "==") or source.len < 3 or source[2] == '=') return false;
    const heading = std.mem.trim(u8, section.heading, " \t\r\n");
    if (!std.mem.startsWith(u8, heading, "[[") or !std.mem.endsWith(u8, heading, "]]")) return false;
    const body = heading[2 .. heading.len - 2];
    if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null) return false;
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return false;
    if (std.mem.trim(u8, body[0..pipe], " \t").len == 0 or std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null) return false;
    const label = std.mem.trim(u8, body[pipe + 1 ..], " \t");
    if (label.len < code.len + 3 or label[label.len - 1] != ')') return false;
    const open = label.len - code.len - 2;
    return label[open] == '(' and open > 0 and std.ascii.isWhitespace(label[open - 1]) and
        std.mem.eql(u8, label[open + 1 .. label.len - 1], code);
}

fn arabicTableBoundaryOwner(codes: LanguageCodes, heading: []const u8) ?ResolvedLanguage {
    return resolveCategorizedHeading(codes, heading) orelse codes.resolveStrong(std.mem.trim(u8, heading, " \t\r\n")) orelse codes.resolveTrusted(std.mem.trim(u8, heading, " \t\r\n"));
}
fn corroboratedArabicTableBoundary(markers: *const LanguageMarkers, heading: []const u8) bool {
    const namespaces = markers.codes.namespace_catalog orelse return false;
    if (!std.mem.eql(u8, namespaces.content_language, "ar")) return false;
    const raw_source = markers.raw_source orelse return false;
    const expanded = markers.expanded_source orelse return false;
    const owner = arabicTableBoundaryOwner(markers.codes.*, heading) orelse return false;
    const raw_markers: LanguageMarkers = .{ .codes = markers.codes };
    var raw_sections = languageSections(raw_source, &raw_markers);
    var declarations: usize = 0;
    while (raw_sections.next()) |section| {
        // Only the standalone literal template form, outside raw tables and
        // opaque bodies, corroborates this recovery. Ordinary POS/translation
        // headings and raw heading-like cell text cannot provide evidence.
        const offset = @intFromPtr(section.source.ptr) - @intFromPtr(raw_source.ptr);
        if (!language_source.outsideNestedOrOpaque(raw_source, offset)) continue;
        const label = declarationLabel(markers.codes.*, section.heading) orelse continue;
        const trimmed = std.mem.trim(u8, section.heading, " \t\r\n");
        if (!std.mem.startsWith(u8, trimmed, "{{")) continue;
        const raw_owner = markers.codes.resolve(label) orelse continue;
        if (std.mem.eql(u8, owner.code, raw_owner.code)) declarations += 1;
    }
    if (declarations != 1) return false;
    const Match = struct {
        codes: LanguageCodes,
        code: []const u8,
        fn accepts(ctx: ?*const anyopaque, value: []const u8) bool {
            const self: *const @This() = @ptrCast(@alignCast(ctx.?));
            const candidate = arabicTableBoundaryOwner(self.codes, value) orelse return false;
            return std.mem.eql(u8, candidate.code, self.code);
        }
    };
    const match: Match = .{ .codes = markers.codes.*, .code = owner.code };
    return language_source.countUnprotectedL2Headings(expanded, null, .{ .ctx = &match, .accepts = Match.accepts }) == 1;
}

fn languageSections(source: []const u8, context: *const LanguageMarkers) language_source.Iterator {
    var iterator = language_source.Iterator.initWithMarkerFilter(source, .{
        .ctx = context,
        .accepts = struct {
            fn accepts(raw: ?*const anyopaque, value: []const u8) bool {
                const markers: *const LanguageMarkers = @ptrCast(@alignCast(raw.?));
                if (markers.codes.source_static_support_fn) |is_support| {
                    if (is_support(markers.codes.ctx, value)) return false;
                }
                const language = markers.codes.resolve(value) orelse return false;
                if (markers.represented) |codes| {
                    for (codes) |code| if (std.mem.eql(u8, code, language.code)) return true;
                    // Exact captured AN banners corroborate their raw codes
                    // even when a local name is absent or collides in the registry.
                    for (markers.expanded_sections) |section| {
                        if (corroboratedAnHyphenMarker(markers.codes.*, .{ .heading = value, .source = "", .hyphen_marker = true }, section)) return true;
                    }
                    return false;
                }
                return true;
            }
        }.accepts,
        .accepts_equals = struct {
            fn accepts(raw: ?*const anyopaque, value: []const u8) bool {
                const markers: *const LanguageMarkers = @ptrCast(@alignCast(raw.?));
                if (markers.codes.resolve(value) != null) return true;
                for (markers.expanded_sections) |section|
                    if (expandedEqualsDeclaration(section, value)) return true;
                return false;
            }
        }.accepts,
    });
    iterator.control_matcher = .{
        .ctx = context,
        .match = struct {
            fn match(raw: ?*const anyopaque, line: []const u8, at: usize) ?usize {
                const markers: *const LanguageMarkers = @ptrCast(@alignCast(raw.?));
                // Registry matching uses fixed scratch storage; no allocation.
                if (markers.codes.behavior_switches) |registry|
                    return registry.matchAt(std.heap.page_allocator, line, at) catch null;
                return blobs.wikitext_syntax.behaviorSwitchEnd(line, at);
            }
        }.match,
        .toc_match = struct {
            fn match(raw: ?*const anyopaque, line: []const u8, at: usize) ?usize {
                const markers: *const LanguageMarkers = @ptrCast(@alignCast(raw.?));
                if (markers.codes.behavior_switches) |registry|
                    return registry.tocMatchAt(std.heap.page_allocator, line, at) catch null;
                const end = blobs.wikitext_syntax.behaviorSwitchEnd(line, at) orelse return null;
                return if (std.ascii.eqlIgnoreCase(line[at..end], "__TOC__")) end else null;
            }
        }.match,
    };
    iterator.heading_filter = .{
        .ctx = context,
        .accepts = struct {
            fn accepts(raw: ?*const anyopaque, heading: []const u8) bool {
                const markers: *const LanguageMarkers = @ptrCast(@alignCast(raw.?));
                const normalized = classificationHeadingProjectionAlloc(std.heap.page_allocator, markers.codes.*, heading) catch return false;
                defer if (normalized) |value| std.heap.page_allocator.free(value);
                const projected = normalized orelse heading;
                if (ssBoldBannerLabel(markers.codes.*, projected) != null) return true;
                const section: language_source.Section = .{ .heading = projected, .source = "" };
                if (hasExplicitLanguageDeclaration(markers.codes.*, section)) return true;
                const classified = language_source.classificationHeading(projected);
                if (resolveCategorizedHeading(markers.codes.*, classified) != null) return true;
                if (resolveLinkedHeading(markers.codes.*, classified) != null or
                    resolveLinkedDeclaration(markers.codes.*, classified) != null) return true;
                // A template name/argument can coincide with an ISO/POS code.
                // Only whole trusted names and actual declarations may change
                // depth; generic template-candidate attribution is not proof.
                // Exact registered punctuation belongs to the name; try it
                // before the legacy decorative quote projection.
                const candidates = [_][]const u8{ std.mem.trim(u8, classified, " \t\r\n"), std.mem.trim(u8, classified, " \t\r\n\'\"") };
                for (candidates) |plain|
                    if (markers.codes.resolveStrong(plain) != null or markers.codes.resolveTrusted(plain) != null) return true;
                return false;
            }
        }.accepts,
    };
    iterator.table_boundary_filter = .{
        .ctx = context,
        .accepts = struct {
            fn accepts(raw: ?*const anyopaque, heading: []const u8) bool {
                const markers: *const LanguageMarkers = @ptrCast(@alignCast(raw.?));
                return corroboratedArabicTableBoundary(markers, heading);
            }
        }.accepts,
    };
    return iterator;
}

const RawCodeDeclaration = struct { name: []const u8, code: []const u8 };

fn rawCodeDeclarationLine(codes: LanguageCodes, line: []const u8, required_level: ?u8) ?RawCodeDeclaration {
    if (line.len == 0 or line[0] != '=') return null;
    const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
    if (required_level) |level| if (heading.level != level) return null;
    const text = std.mem.trim(u8, heading.title, " \t");
    if (!std.mem.startsWith(u8, text, "{{") or !std.mem.endsWith(u8, text, "}}")) return null;
    const body = text[2 .. text.len - 2];
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return null;
    var name = std.mem.trim(u8, body[0..pipe], " \t");
    const code = std.mem.trim(u8, body[pipe + 1 ..], " \t");
    if (name.len == 0 or code.len == 0 or code.len > 64 or
        std.mem.indexOfAny(u8, name, "{}[]<>|=&\r\n") != null or
        std.mem.indexOfAny(u8, code, "{}[]<>|=&:# \t\r\n") != null) return null;
    if (std.mem.indexOfScalar(u8, name, ':') != null) {
        const ns = codes.namespace_catalog orelse return null;
        const target = ns.ofTitle(name);
        if (target.id != 10) return null;
        name = target.text;
    }
    return .{ .name = name, .code = code };
}

fn rawPrefixParagraphLanguage(codes: LanguageCodes, raw_source: ?[]const u8, tracked: MissingText, raw_sections: []const language_source.Section, rendered: []const language_source.Section) ?ResolvedLanguage {
    const raw = raw_source orelse return null;
    const source = tracked.bytes;
    const namespaces = codes.namespace_catalog orelse return null;
    const matches = codes.source_paragraph_fn orelse return null;
    if (rendered.len != 0 or raw_sections.len != 1) return null;
    const first = raw_sections[0];
    const offset = @intFromPtr(first.source.ptr) - @intFromPtr(raw.ptr);
    if (offset > raw.len or std.mem.trim(u8, raw[0..offset], "\r\n").len != 0) return null;
    const line = std.mem.trimEnd(u8, first.source[0 .. std.mem.indexOfScalar(u8, first.source, '\n') orelse first.source.len], "\r");
    const declaration: ?RawCodeDeclaration = if (first.hyphen_marker) null else rawCodeDeclarationLine(codes, line, 2) orelse equals: {
        const opening = "=={{=";
        const closing = "=}}==";
        if (!std.mem.startsWith(u8, line, opening) or !std.mem.endsWith(u8, line, closing)) return null;
        const code = equalsSectionDeclaration(first) orelse return null;
        if (line.len != opening.len + code.len + closing.len or !std.mem.eql(u8, line[opening.len..][0..code.len], code)) return null;
        break :equals .{ .name = line[4 .. line.len - 4], .code = code };
    };
    const canonical = if (declaration) |call| codes.resolve(call.code) orelse return null else resolveSection(codes, first) orelse return null;
    // Preserve the emitted paragraph rather than manufacturing a heading.
    // A selected declaration source may emit a category on the following line;
    // MediaWiki has already passed heading recognition before removing it.
    const expanded = std.mem.trimStart(u8, source, "\r\n");
    const first_end = std.mem.indexOfScalar(u8, expanded, '\n') orelse expanded.len;
    if (first.hyphen_marker) {
        if (line.len != canonical.code.len + 6 or !std.mem.startsWith(u8, line, "{{-") or
            !std.mem.endsWith(u8, line, "-}}") or !std.mem.eql(u8, line[3 .. line.len - 3], canonical.code)) return null;
        const expanded_line = std.mem.trimEnd(u8, expanded[0..first_end], "\r");
        if (!matches(codes.ctx, canonical.code, "", expanded_line)) return null;
    } else {
        const call = declaration orelse return null;
        if (!std.mem.eql(u8, call.code, canonical.code) or first_end == expanded.len) return null;
        const second_end = std.mem.indexOfScalarPos(u8, expanded, first_end + 1, '\n') orelse expanded.len;
        if (second_end > 4096) return null;
        const prefix = expanded[0..second_end];
        if (!matches(codes.ctx, canonical.code, call.name, prefix)) return null;
        if (call.name[0] == '=') {
            const start = source.len - expanded.len;
            if (tracked.unknown or tracked.lost_missing_range or !calibratedBoundaryRangesClean(tracked, start, start + second_end)) return null;
        }
        // One raw H2 alone is insufficient: later declared deep headings must
        // not inherit its owner, even if expansion erased their visible heading.
        var every_heading = language_source.Iterator.init(raw);
        every_heading.all_heading_levels = true;
        // Eligibility alone does not split different heading depths. Observe
        // every physical heading here, then apply the language veto below.
        every_heading.heading_filter = .{ .ctx = null, .accepts = struct {
            fn accepts(_: ?*const anyopaque, _: []const u8) bool { return true; }
        }.accepts };
        while (every_heading.next()) |later| {
            if (later.source.ptr == first.source.ptr) continue;
            // A recognized or ambiguous language boundary vetoes inheritance
            // even when it lacks the stronger evidence required to own a page.
            const boundary_heading = std.mem.trim(u8, language_source.classificationSection(later), " \t\r\n");
            if (codes.isLanguageBoundary(boundary_heading) or boundaryLanguage(codes, later) != null or
                resolveSection(codes, later) != null or hasExplicitLanguageDeclaration(codes, later)) return null;
            const later_line = later.source[0 .. std.mem.indexOfScalar(u8, later.source, '\n') orelse later.source.len];
            if (call.name[0] == '=') if (blobs.wikitext_syntax.controlHeading(later_line, null)) |heading| {
                if (language_source.equalsLanguageDeclaration(heading.title) != null) return null;
            };
            if (rawCodeDeclarationLine(codes, later_line, null)) |other|
                if (matches(codes.ctx, canonical.code, other.name, prefix)) return null;
        }
    }
    var categories: language_source.CategoryIterator = .{ .source = source };
    while (categories.next()) |target| {
        const title = namespaces.ofTitle(target);
        if (title.id != 14) continue;
        if (codes.resolve(title.text)) |other| if (!std.mem.eql(u8, canonical.code, other.code)) return null;
    }
    return canonical;
}

fn plainBoldPrefixAuthority(codes: LanguageCodes, name: []const u8) ?ResolvedLanguage {
    return (if (codes.strong_fn) |resolve| resolve(codes.ctx, name) else null) orelse
        (if (codes.trusted_fn) |resolve| resolve(codes.ctx, name) else null);
}

fn plainBoldPrefixOwner(codes: LanguageCodes, source: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.startsWith(u8, source, "'''")) return null;
    const line = source[0 .. std.mem.indexOfScalar(u8, source, '\n') orelse source.len];
    const end = std.mem.indexOf(u8, line[3..], ":''' ") orelse return null;
    const name = line[3 .. 3 + end];
    if (name.len == 0 or std.mem.indexOfAny(u8, name, "'{}[]<>|=:\t\r\n") != null or
        !std.mem.eql(u8, name, std.mem.trim(u8, name, " "))) return null;
    const body = std.mem.trim(u8, line[3 + end + 5 ..], " \t\r");
    if (body.len == 0 or std.mem.indexOfAny(u8, body, "'{}[]<>|=") != null) return null;
    // The anchored authored label may be an ordinary registered alias. It
    // cannot establish ownership without a separate trusted category below.
    const resolve_prefix = codes.resolve_fn orelse return null;
    const owner = resolve_prefix(codes.ctx, name) orelse return null;
    var headings = language_source.Iterator.init(source);
    headings.all_heading_levels = true;
    if (headings.next() != null) return null;
    var categories: language_source.CategoryIterator = .{ .source = source };
    var corroborated: ?ResolvedLanguage = null;
    while (categories.next()) |target| {
        const title = namespaces.ofTitle(target);
        if (title.id != 14) continue;
        // Even an ordinary recognized conflicting category vetoes recovery;
        // only Strong/Trusted category authority can positively corroborate it.
        if (resolve_prefix(codes.ctx, title.text)) |recognized|
            if (!std.mem.eql(u8, owner.code, recognized.code)) return null;
        const category_owner = plainBoldPrefixAuthority(codes, title.text) orelse continue;
        if (!std.mem.eql(u8, owner.code, category_owner.code)) return null;
        corroborated = category_owner;
    }
    return corroborated;
}

fn tsongaBilingualHeadword(codes: LanguageCodes, title: []const u8, raw: []const u8, expanded: []const u8) ?ResolvedLanguage {
    if (!std.mem.eql(u8, raw, expanded)) return null;
    var lines = std.mem.tokenizeScalar(u8, raw, '\n');
    var count: usize = 0;
    while (lines.next()) |line| {
        const prefix = "Tsonga: '''";
        if (!std.mem.startsWith(u8, line, prefix)) return null;
        const body = line[prefix.len..];
        const end = std.mem.indexOf(u8, body, "'''. English") orelse return null;
        const spelling = body[0..end];
        if (spelling.len == 0 or std.mem.indexOfAny(u8, spelling, "'{}[]<>=|:") != null) return null;
        if (count == 0 and !std.ascii.eqlIgnoreCase(spelling, title)) return null;
        const gloss = body[end + "'''. English".len ..];
        const start: []const u8 = if (count == 0) " (verb): " else ": ";
        if (!std.mem.startsWith(u8, gloss, start) or gloss.len == start.len or
            std.mem.indexOfAny(u8, gloss[start.len..], "'{}[]<>=|:") != null) return null;
        count += 1;
    }
    if (count < 2) return null;
    const label = codes.resolve("Tsonga") orelse return null;
    const owner = plainBoldPrefixAuthority(codes, "Xitsonga") orelse return null;
    return if (std.mem.eql(u8, owner.code, "ts") and std.mem.eql(u8, label.code, owner.code)) owner else null;
}

// These entries introduce the headword directly and expand a translation
// heading below it. A translation's language does not own the entry.
fn tsongaLabelledHeadword(codes: LanguageCodes, title: []const u8, raw_source: ?[]const u8, expanded: MissingText) ?ResolvedLanguage {
    const ns = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, ns.wiki, "tswiktionary") or !std.mem.eql(u8, ns.content_language, "ts")) return null;
    const raw = raw_source orelse return null;
    if (title.len == 0 or expanded.unknown or expanded.lost_missing_range or expanded.ranges.len != 0 or
        expanded.literal_curly_ranges.len != 0 or expanded.generated_links.len != 0 or expanded.generated_source != null) return null;
    if (std.mem.startsWith(u8, raw, "Tsonga: ")) return tsongaBilingualHeadword(codes, title, raw, expanded.bytes);
    const raw_count = tsongaTranslationSections(ns, title, raw, false) orelse return null;
    const expanded_count = tsongaTranslationSections(ns, title, expanded.bytes, true) orelse return null;
    if (raw_count != expanded_count) return null;
    const owner = plainBoldPrefixAuthority(codes, "Xitsonga") orelse return null;
    if (!std.mem.eql(u8, owner.code, "ts") or !std.mem.eql(u8, ns.wiki, "tswiktionary") or
        !std.mem.eql(u8, ns.content_language, "ts")) return null;
    return owner;
}

fn tsongaTranslationSections(ns: *const @import("namespace_registry").Registry, title: []const u8, text: []const u8, expanded: bool) ?usize {
    const after_label = for ([_][]const u8{ "'''Xitsonga:'''", "''Xitsonga:''", "''Xitsonga: ku''" }) |label| {
        if (std.mem.startsWith(u8, text, label)) break text[label.len..];
    } else return null;
    if (after_label.len == 0 or (after_label[0] != ' ' and after_label[0] != '\t')) return null;
    const end = std.mem.indexOfAny(u8, after_label, "<\n") orelse return null;
    if (!std.mem.eql(u8, std.mem.trim(u8, after_label[0..end], " \t\r"), title)) return null;

    const heading = if (expanded) "=====[[vuhundzuluxi|Vuhundzuluxi]]=====" else "{{-vuhundzuluxi-}}";
    var sections: usize = 0;
    var rest = after_label[end..];
    while (std.mem.indexOfAny(u8, rest, "<={}")) |offset| {
        rest = rest[offset..];
        if (std.mem.startsWith(u8, rest, heading)) {
            sections += 1;
            rest = rest[heading.len..];
        } else if (std.mem.startsWith(u8, rest, "<br />")) {
            rest = rest["<br />".len..];
        } else return null;
    }
    // The edition's authored category is a separate record at the end of this
    // form. An escaped link or a template inside a category sort key is insufficient.
    if (sections == 0 or !std.mem.endsWith(u8, std.mem.trimEnd(u8, text, " \t\r\n"), "[[Category:Marito a Xitsonga]]")) return null;
    var categories: language_source.CategoryIterator = .{ .source = text };
    var corroborated = false;
    while (categories.next()) |target| {
        const category = ns.ofTitle(target);
        if (category.id != 14) continue;
        if (corroborated or !std.mem.eql(u8, category.text, "Marito a Xitsonga")) return null;
        corroborated = true;
    }
    return if (corroborated) sections else null;
}

const PairedOrthographyField = struct { language: []const u8, variant: []const u8 };

fn pairedOrthographyField(line: []const u8) ?PairedOrthographyField {
    if (!std.mem.startsWith(u8, line, "'''")) return null;
    const close = std.mem.indexOfPos(u8, line, 3, ":''' ") orelse return null;
    const label = line[3..close];
    const middle = std.mem.indexOf(u8, label, " word (") orelse return null;
    const suffix = " orthography)";
    if (middle == 0 or !std.mem.endsWith(u8, label, suffix)) return null;
    const name = label[0..middle];
    const variant_start = middle + " word (".len;
    if (variant_start >= label.len - suffix.len or std.mem.indexOfAny(u8, name, "'{}[]<>&|=:\t\r\n") != null or
        !std.mem.eql(u8, name, std.mem.trim(u8, name, " "))) return null;
    const value = std.mem.trim(u8, line[close + 5..], " \t\r");
    if (value.len == 0 or std.mem.indexOfAny(u8, value, "'{}[]<>&|\t\r\n") != null or !std.unicode.utf8ValidateSlice(value)) return null;
    return .{ .language = name, .variant = label[variant_start .. label.len - suffix.len] };
}

fn pairedOrthographyCategoryLine(ns: *const @import("namespace_registry").Registry, line: []const u8) bool {
    if (!std.mem.startsWith(u8, line, "[[") or !std.mem.endsWith(u8, line, "]]")) return false;
    const target = line[2 .. line.len - 2];
    return target.len != 0 and target[0] != ':' and std.mem.indexOfAny(u8, target, "[]{}<>|") == null and ns.ofTitle(target).id == 14;
}

fn pairedOrthographyBreakLine(line: []const u8) bool {
    const tag = blobs.wikitext_syntax.tagAt(line, 0) orelse return false;
    return tag.is("br") and !tag.closing and tag.end == line.len and std.mem.trim(u8, tag.attrs, " \t\r\n").len == 0;
}

fn pairedOrthographyBareFileLine(ns: *const @import("namespace_registry").Registry, line: []const u8) bool {
    if (!std.mem.startsWith(u8, line, "[[") or !std.mem.endsWith(u8, line, "]]")) return false;
    const target = line[2 .. line.len - 2];
    if (target.len == 0 or target[0] == ':' or std.mem.indexOfAny(u8, target, "[]{}<>|\t\r\n") != null or
        !std.unicode.utf8ValidateSlice(target)) return false;
    const file = ns.ofTitle(target);
    return file.id == 6 and std.mem.trim(u8, file.text, " ").len != 0;
}

fn pairedOrthographyQualifiers(tail: []const u8) bool {
    var remaining = tail;
    while (remaining.len != 0) {
        const square = remaining[0] == '[';
        if (remaining[0] != '(' and !square) return false;
        const close = std.mem.indexOfScalar(u8, remaining, if (square) @as(u8, ']') else ')') orelse return false;
        const value = remaining[1..close];
        if (std.mem.trim(u8, value, " \t").len == 0 or std.mem.indexOfAny(u8, value, "'{}[]<>&|()\r\n") != null) return false;
        // A square qualifier is plain annotation, never an external link.
        if (square) for (value) |byte| {
            if (!std.ascii.isAlphanumeric(byte) and byte != ' ' and byte != '-' and byte != '\t') return false;
        };
        remaining = remaining[close + 1..];
        if (remaining.len != 0 and remaining[0] != ' ' and remaining[0] != '\t') return false;
        remaining = std.mem.trimStart(u8, remaining, " \t");
    }
    return true;
}

fn pairedOrthographyPrefix(ns: *const @import("namespace_registry").Registry, raw: []const u8) bool {
    // Ordinary pages leave this global fallback after at most 4096 bytes,
    // before comparing the complete raw/expanded buffers or inspecting a body.
    const prefix = raw[0..@min(raw.len, 4096)];
    var leading_file = false; var needs_break = false; var category_seen = false;
    var lines = std.mem.splitScalar(u8, prefix, '\n');
    while (lines.next()) |raw_line| {
        const line = std.mem.trim(u8, raw_line, " \t\r");
        if (line.len == 0) continue;
        if (raw_line[0] == ' ' or raw_line[0] == '\t') return false;
        if (needs_break) {
            if (!pairedOrthographyBreakLine(line)) return false;
            needs_break = false; continue;
        }
        if (pairedOrthographyCategoryLine(ns, line)) { category_seen = true; continue; }
        if (!leading_file and !category_seen and pairedOrthographyBareFileLine(ns, line)) {
            leading_file = true; needs_break = true; continue;
        }
        if (leading_file and !category_seen) return false;
        const field = pairedOrthographyField(line) orelse return false;
        return std.mem.eql(u8, field.variant, "South African");
    }
    return false;
}

// This proof admits only root DIV-wrapped tables following the complete word
// card. Their contents cannot supply language declarations or categories.
const PairedOrthographyTable = struct {
    const Kind = enum { div, table, tr, td, font, b, i };
    stack: [8]Kind = undefined,
    depth: usize = 0,
    has_table: bool = false,

    fn attributes(kind: Kind, bytes: []const u8) bool {
        const allowed: []const []const u8 = switch (kind) {
            .table => &.{ "border", "cellspacing", "bordercolor", "cellpadding" },
            .td => &.{"align"},
            .font => &.{ "size", "face" },
            else => &.{},
        };
        var remaining = std.mem.trim(u8, bytes, " \t\r");
        var seen: u8 = 0;
        while (remaining.len != 0) {
            var end: usize = 0;
            while (end < remaining.len and std.ascii.isAlphabetic(remaining[end])) : (end += 1) {}
            if (end == 0) return false;
            const name = remaining[0..end];
            const bit: u8 = for (allowed, 0..) |candidate, index| {
                if (std.ascii.eqlIgnoreCase(name, candidate)) break @as(u8, 1) << @intCast(index);
            } else return false;
            if (seen & bit != 0) return false;
            seen |= bit;
            remaining = std.mem.trimStart(u8, remaining[end..], " \t\r");
            if (remaining.len < 3 or remaining[0] != '=') return false;
            remaining = std.mem.trimStart(u8, remaining[1..], " \t\r");
            if (remaining.len < 2 or (remaining[0] != '"' and remaining[0] != '\'')) return false;
            const quote = remaining[0];
            const close = std.mem.indexOfScalarPos(u8, remaining, 1, quote) orelse return false;
            const value = remaining[1..close];
            if (value.len == 0 or std.mem.indexOfAny(u8, value, "'\"{}[]<>&|\r\n") != null) return false;
            remaining = remaining[close + 1 ..];
            if (remaining.len != 0 and !std.ascii.isWhitespace(remaining[0])) return false;
            remaining = std.mem.trimStart(u8, remaining, " \t\r");
        }
        return true;
    }

    fn accept(self: *PairedOrthographyTable, tag: blobs.wikitext_syntax.Tag) bool {
        const kind: Kind = inline for (@typeInfo(Kind).@"enum".field_names) |name| {
            if (tag.is(name)) break @field(Kind, name);
        } else return false;
        if (tag.closing) {
            if (self.depth == 0 or self.stack[self.depth - 1] != kind or
                std.mem.trim(u8, tag.attrs, " \t\r").len != 0) return false;
            if (kind == .div and !self.has_table) return false;
            self.depth -= 1;
            return true;
        }
        if (tag.self_closing or self.depth == self.stack.len or !attributes(kind, tag.attrs)) return false;
        if (self.depth == 0) {
            if (kind != .div) return false;
            self.has_table = false;
        } else switch (self.stack[self.depth - 1]) {
            .div => {
                if (kind != .table or self.has_table) return false;
                self.has_table = true;
            },
            .table => if (kind != .tr) return false,
            .tr => if (kind != .td) return false,
            .td, .font, .b, .i => {
                if (kind != .font and kind != .b and kind != .i) return false;
                for (self.stack[0..self.depth]) |ancestor| if (ancestor == kind) return false;
            },
        }
        self.stack[self.depth] = kind;
        self.depth += 1;
        return true;
    }

    fn inCell(self: PairedOrthographyTable) bool {
        return self.depth >= 4 and self.stack[3] == .td;
    }
};

// The two authored orthography fields declare a language, while an independent
// trusted category corroborates it. Neither the edition nor a gloss owns it.
fn unsectionedPairedOrthographyLanguage(codes: LanguageCodes, raw_source: ?[]const u8, expanded: MissingText) ?ResolvedLanguage {
    const ns = codes.namespace_catalog orelse return null;
    const raw = raw_source orelse return null;
    if (!pairedOrthographyPrefix(ns, raw)) return null;
    if (expanded.unknown or expanded.lost_missing_range or expanded.ranges.len != 0 or expanded.literal_curly_ranges.len != 0 or
        expanded.generated_links.len != 0 or expanded.generated_source != null or !std.mem.eql(u8, raw, expanded.bytes)) return null;
    const ordinary = codes.resolve_fn orelse return null;
    var owner: ?ResolvedLanguage = null;
    var category_owner: ?ResolvedLanguage = null;
    var recognized_category: ?ResolvedLanguage = null;
    var variants: u8 = 0;
    var gloss = false;
    var started = false;
    var leading_file = false; var needs_break = false;
    var bracket_depth: usize = 0;
    var bracket_start: usize = 0;
    var position: usize = 0;
    var table: PairedOrthographyTable = .{};
    var lines = std.mem.splitScalar(u8, raw, '\n');
    while (lines.next()) |raw_line| {
        const start = position; position += raw_line.len + 1;
        const root = bracket_depth == 0 and table.depth == 0;
        var table_line = table.depth != 0;
        // A monotonic census quarantines links and closed table bodies.
        // Templates, comments and all other HTML remain outside this proof.
        var at: usize = 0;
        while (at < raw_line.len) {
            const byte = raw_line[at];
            if (byte == '{' or byte == '}' or byte == 0) return null;
            if (byte == '<') {
                const tag = blobs.wikitext_syntax.tagAt(raw_line, at) orelse return null;
                if (tag.is("br")) {
                    if (tag.closing or std.mem.trim(u8, tag.attrs, " \t\r\n").len != 0 or
                        (table_line and !table.inCell())) return null;
                } else {
                    if (bracket_depth != 0) return null;
                    if (table.depth == 0) {
                        if (!root or table_line or variants != 3 or !gloss or at != 0 or
                            std.mem.trimEnd(u8, raw_line[tag.end..], " \t\r").len != 0) return null;
                        table_line = true;
                    }
                    if (!table.accept(tag)) return null;
                }
                at = tag.end; continue;
            }
            if (table_line and !table.inCell() and !std.ascii.isWhitespace(byte)) return null;
            if (byte == '[') {
                if (bracket_depth == 2) return null;
                if (bracket_depth == 0) bracket_start = start + at;
                bracket_depth += 1;
            } else if (byte == ']') {
                if (bracket_depth == 0) return null;
                bracket_depth -= 1;
                if (bracket_depth == 0) {
                    const link = raw[bracket_start .. start + at + 1];
                    // Only disjoint outer link bodies are inspected, once each.
                    if (std.mem.startsWith(u8, link, "[[") and std.mem.endsWith(u8, link, "]]")) {
                        const body = link[2 .. link.len - 2];
                        if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") == null) {
                            const pipe = std.mem.indexOfScalar(u8, body, '|') orelse body.len;
                            const target = std.mem.trim(u8, body[0..pipe], " \t");
                            const category = ns.ofTitle(target);
                            if (target.len != 0 and target[0] != ':' and category.id == 14) {
                                if (table_line) return null;
                                if (ordinary(codes.ctx, category.text)) |recognized| {
                                    if (recognized_category) |prior| if (!std.mem.eql(u8, prior.code, recognized.code)) return null;
                                    recognized_category = recognized;
                                }
                                if (plainBoldPrefixAuthority(codes, category.text)) |trusted| {
                                    if (category_owner) |prior| if (!std.mem.eql(u8, prior.code, trusted.code)) return null;
                                    category_owner = trusted;
                                }
                            }
                        }
                    }
                }
            }
            at += 1;
        }
        const line = std.mem.trim(u8, raw_line, " \t\r");
        if (table_line) {
            if (std.mem.indexOf(u8, line, " word (") != null or
                std.mem.indexOf(u8, line, "English translation:") != null or
                (line.len != 0 and line[0] == '=')) return null;
            continue;
        }
        if (line.len == 0 or !root) continue;
        if (raw_line[0] == ' ' or raw_line[0] == '\t' or line[0] == '=') return null;
        if (!started and needs_break) {
            if (!pairedOrthographyBreakLine(line)) return null;
            needs_break = false; continue;
        }
        if (pairedOrthographyCategoryLine(ns, line)) continue;
        if (!started and !leading_file and pairedOrthographyBareFileLine(ns, line)) {
            leading_file = true; needs_break = true; continue;
        }
        if (pairedOrthographyField(line)) |field| {
            const language = ordinary(codes.ctx, field.language) orelse return null;
            const trusted = plainBoldPrefixAuthority(codes, field.language) orelse return null;
            if (!std.mem.eql(u8, language.code, trusted.code)) return null;
            if (owner) |prior| { if (!std.mem.eql(u8, prior.code, trusted.code)) return null; } else owner = trusted;
            const bit: u8 = if (std.mem.eql(u8, field.variant, "South African")) 1 else if (std.mem.eql(u8, field.variant, "Lesotho")) 2 else return null;
            if ((variants & bit) != 0 or gloss or (variants == 0 and bit != 1)) return null;
            variants |= bit; started = true;
            continue;
        }
        if (!started) return null;
        const gloss_label = "'''English translation:''' ''";
        if (std.mem.startsWith(u8, line, gloss_label)) {
            if (variants != 3 or gloss or ordinary(codes.ctx, "English") == null) return null;
            const body = line[gloss_label.len..];
            const close = std.mem.indexOf(u8, body, "''") orelse return null;
            const meaning = body[0..close];
            if (std.mem.trim(u8, meaning, " \t\r").len == 0 or std.mem.indexOfAny(u8, meaning, "'{}[]<>&|\t\r\n") != null) return null;
            const tail = std.mem.trim(u8, body[close + 2..], " \t\r");
            if (!pairedOrthographyQualifiers(tail)) return null;
            gloss = true;
        } else if (std.mem.indexOf(u8, line, " word (") != null or std.mem.startsWith(u8, line, "'''English translation:")) return null;
    }
    const declared = owner orelse return null;
    const category = category_owner orelse return null;
    if (bracket_depth != 0 or table.depth != 0 or variants != 3 or !gloss or !std.mem.eql(u8, category.code, declared.code)) return null;
    if (recognized_category) |recognized| if (!std.mem.eql(u8, recognized.code, declared.code)) return null;
    return declared;
}

fn unsectionedPlainBoldPrefixLanguage(codes: LanguageCodes, raw_source: ?[]const u8, source: []const u8) ?ResolvedLanguage {
    const raw = raw_source orelse return null;
    // A root label and a literal category must independently agree in both
    // representations. Translation labels later in the body grant no owner.
    const raw_owner = plainBoldPrefixOwner(codes, raw) orelse return null;
    const expanded_owner = plainBoldPrefixOwner(codes, source) orelse return null;
    if (!std.mem.eql(u8, raw_owner.code, expanded_owner.code)) return null;
    return raw_owner;
}

fn unsectionedLanguage(codes: LanguageCodes, source: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    // The pinned Amharic entry form declares its language in a category even
    // when the entry has no language-level heading. Other editions retain
    // their section conventions rather than inheriting this local rule.
    if (!std.mem.eql(u8, namespaces.content_language, "am")) return null;
    var categories: language_source.CategoryIterator = .{ .source = source };
    var found: ?ResolvedLanguage = null;
    while (categories.next()) |target| {
        const title = namespaces.ofTitle(target);
        if (title.id != 14) continue;
        const name = std.mem.trim(u8, title.text, " \t\r\n");
        const language = codes.resolveStrong(name) orelse codes.resolveTrusted(name) orelse continue;
        if (found) |previous| if (!std.mem.eql(u8, previous.code, language.code)) return null;
        found = language;
    }
    return found;
}

// The captured Amharic translation entry uses these two L2 support headings,
// not language declarations. Never extend category attribution to arbitrary
// unknown boundaries or to expanded-only evidence.
fn amharicSupportSections(codes: LanguageCodes, sections: []const language_source.Section) bool {
    if (sections.len != 2) return false;
    var seen: u8 = 0;
    for (sections) |section| {
        if (section.hyphen_marker or hasExplicitLanguageDeclaration(codes, section) or
            resolveSection(codes, section) != null) return false;
        const heading = std.mem.trim(u8, section.heading, " \t\r\n");
        const bit: u8 = if (std.mem.eql(u8, heading, "ተመሳሳይ ቃላት")) 1 else if (std.mem.eql(u8, heading, "ትርጉሞች በየቋንቋው")) 2 else return false;
        if ((seen & bit) != 0) return false;
        seen |= bit;
        const body = std.mem.trimStart(u8, section.source, " \t\r\n");
        if (body.len < 3 or body[0] != '=' or body[1] != '=' or body[2] == '=') return false;
    }
    return seen == 3;
}

// Captured aswiktionary assamese p1964/r4743 starts with {{en}}; that
// template emits an ordinary paragraph, followed by noun/adjective templates.
// Recover only this corroborated support form, without changing its body.
fn assameseEnglishCategory(codes: LanguageCodes, source: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    var categories: language_source.CategoryIterator = .{ .source = source };
    var found: ?ResolvedLanguage = null;
    while (categories.next()) |target| {
        const title = namespaces.ofTitle(target);
        if (title.id != 14) continue;
        const name = std.mem.trim(u8, title.text, " \t\r\n");
        const owner = codes.resolveStrong(name) orelse codes.resolveTrusted(name) orelse continue;
        if (!std.mem.eql(u8, owner.code, "en")) return null;
        if (std.mem.eql(u8, name, "ইংৰাজী")) found = owner;
    }
    return found;
}

fn assameseSupportLanguage(codes: LanguageCodes, source: []const u8, raw_source: ?[]const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "as")) return null;
    const raw = raw_source orelse return null;
    const owner = assameseEnglishCategory(codes, raw) orelse return null;
    _ = assameseEnglishCategory(codes, source) orelse return null;
    const markers: LanguageMarkers = .{ .codes = &codes };
    const every_heading: language_source.Iterator.MarkerFilter = .{
        .ctx = null,
        .accepts = struct {
            fn accepts(_: ?*const anyopaque, _: []const u8) bool { return true; }
        }.accepts,
    };
    var original = languageSections(raw, &markers);
    // Inspect every authored marker, including POS names that are not codes.
    original.marker_filter = null;
    original.all_heading_levels = true;
    original.heading_filter = every_heading;
    var expanded = languageSections(source, &markers);
    expanded.all_heading_levels = true;
    expanded.heading_filter = every_heading;
    const forms = [_]struct { marker: []const u8, heading: []const u8 }{
        .{ .marker = "{{-noun-}}", .heading = "নাম" },
        .{ .marker = "{{-adj-}}", .heading = "বিশেষণ" },
    };
    var allowed_offsets: [3]usize = .{ 0, 0, 0 };
    for (forms, 0..) |form, index| {
        const authored = original.next() orelse return null;
        const rendered = expanded.next() orelse return null;
        const raw_offset = @intFromPtr(authored.source.ptr) - @intFromPtr(raw.ptr);
        const expanded_offset = @intFromPtr(rendered.source.ptr) - @intFromPtr(source.ptr);
        if (index == 0) {
            // Do not trim initial spaces: an indented line is preformatted.
            if (!std.mem.eql(u8, std.mem.trimEnd(u8, raw[0..raw_offset], "\r\n"), "{{en}}") or
                !std.mem.eql(u8, std.mem.trimEnd(u8, source[0..expanded_offset], "\r\n"), "ইংৰাজী")) return null;
        }
        const raw_end = std.mem.indexOfScalar(u8, authored.source, '\n') orelse authored.source.len;
        if (!authored.hyphen_marker or !std.mem.eql(u8, std.mem.trimEnd(u8, authored.source[0..raw_end], "\r"), form.marker)) return null;
        if (rendered.hyphen_marker or !std.mem.eql(u8, std.mem.trim(u8, rendered.heading, " \t\r\n"), form.heading) or
            hasExplicitLanguageDeclaration(codes, rendered) or resolveSection(codes, rendered) != null) return null;
        if (rendered.source.len < 3 or !std.mem.startsWith(u8, rendered.source, "==") or rendered.source[2] == '=') return null;
        allowed_offsets[index + 1] = raw_offset;
    }
    if (original.next() != null or expanded.next() != null) return null;
    // Other active transclusions, including a second bare language banner,
    // are outside this captured convention. Conservatively refuse protected
    // template examples too; this recovery supports only the captured form.
    var cursor: usize = 0;
    while (std.mem.indexOfPos(u8, raw, cursor, "{{")) |offset| {
        cursor = offset + 2;
        var allowed = false;
        for (allowed_offsets) |expected| if (offset == expected) {
            allowed = true;
            break;
        };
        if (!allowed) return null;
    }
    // Registry-owned slices remain valid through grouping and encoding.
    return owner;
}

fn amharicSupportCategoryLanguage(
    codes: LanguageCodes,
    source: []const u8,
    raw_source: ?[]const u8,
    raw_sections: []const language_source.Section,
    page_sections: []const language_source.Section,
) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "am")) return null;
    const raw = raw_source orelse return null;
    if (!amharicSupportSections(codes, raw_sections) or !amharicSupportSections(codes, page_sections)) return null;
    const raw_language = unsectionedLanguage(codes, raw) orelse return null;
    const expanded_language = unsectionedLanguage(codes, source) orelse return null;
    if (!std.mem.eql(u8, raw_language.code, expanded_language.code)) return null;
    return raw_language;
}

// Live arwiktionary bit page10972/rev1142865 has one المعاني L2 and an
// explicit language category. Both authored and expanded forms must agree.
fn arabicMeaningsSupportSections(codes: LanguageCodes, source: []const u8, sections: []const language_source.Section) bool {
    if (sections.len != 1 or sections[0].hyphen_marker or
        !std.mem.eql(u8, std.mem.trim(u8, sections[0].heading, " \t\r\n"), "المعاني") or
        hasExplicitLanguageDeclaration(codes, sections[0]) or resolveSection(codes, sections[0]) != null) return false;
    const section = sections[0];
    const prefix_end = @intFromPtr(section.source.ptr) - @intFromPtr(source.ptr);
    if (std.mem.trim(u8, source[0..prefix_end], " \t\r\n").len != 0) return false;
    const first_line = std.mem.trim(u8, section.source[0..(std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len)], " \t\r");
    if (first_line.len < 3 or first_line[0] != '=' or first_line[1] != '=' or first_line[2] == '=') return false;
    // Reuse the protected declaration filter at every heading depth: ordinary
    // POS headings stay support content, but an L3+ language cannot be hidden.
    const markers: LanguageMarkers = .{ .codes = &codes };
    var nested = languageSections(source, &markers);
    nested.all_heading_levels = true;
    _ = nested.next() orelse return false;
    return nested.next() == null;
}

fn arabicMeaningsCategory(codes: LanguageCodes, source: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    var categories: language_source.CategoryIterator = .{ .source = source };
    var found: ?ResolvedLanguage = null;
    while (categories.next()) |target| {
        const title = namespaces.ofTitle(target);
        if (title.id != 14) continue;
        const name = std.mem.trim(u8, title.text, " \t\r\n");
        const language = codes.resolveStrong(name) orelse codes.resolveTrusted(name) orelse continue;
        if (found) |previous| if (!std.mem.eql(u8, previous.code, language.code)) return null;
        found = language;
    }
    return found;
}

fn arabicMeaningsSupportCategoryLanguage(codes: LanguageCodes, source: []const u8, raw_source: ?[]const u8, raw_sections: []const language_source.Section, page_sections: []const language_source.Section) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "ar")) return null;
    const raw = raw_source orelse return null;
    if (!arabicMeaningsSupportSections(codes, raw, raw_sections) or
        !arabicMeaningsSupportSections(codes, source, page_sections)) return null;
    const raw_language = arabicMeaningsCategory(codes, raw) orelse return null;
    const expanded_language = arabicMeaningsCategory(codes, source) orelse return null;
    if (!std.mem.eql(u8, raw_language.code, expanded_language.code)) return null;
    return raw_language;
}

// The captured headingless SL nouns retain the same explicit headword line,
// one translation support heading, and one literal category before/after
// expansion. Only the category's independently loaded declaration owns them.
fn slovenianSupportCategoryLanguage(codes: LanguageCodes, title: []const u8, source: []const u8, raw_source: ?[]const u8, raw_sections: []const language_source.Section, page_sections: []const language_source.Section) !?ResolvedLanguage {
    const ns = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, ns.content_language, "sl") or raw_sections.len != 0 or page_sections.len != 0) return null;
    const raw = raw_source orelse return null;
    const corroborate = codes.source_category_fn orelse return null;
    const Observe = struct {
        fn anyHeading(_: ?*const anyopaque, _: []const u8) bool { return true; }
        fn firstLine(text: []const u8) []const u8 {
            return std.mem.trim(u8, text[0 .. std.mem.indexOfScalar(u8, text, '\n') orelse text.len], " \t\r");
        }
        fn headword(line: []const u8, lemma: []const u8) bool {
            if (!std.mem.startsWith(u8, line, "''")) return false;
            const end = std.mem.indexOfPos(u8, line, 2, "'', [[samostalnik]] ") orelse return false;
            if (!std.mem.eql(u8, line[2..end], lemma)) return false;
            const gender = line[end + "'', [[samostalnik]] ".len ..];
            return std.mem.eql(u8, gender, "ženskega [[spol]]a") or std.mem.eql(u8, gender, "srednjega [[spol]]a");
        }
        fn owner(value: LanguageCodes, text: []const u8, catalog: *const @import("namespace_registry").Registry, callback: *const fn (?*anyopaque, []const u8) anyerror!?ResolvedLanguage) !?ResolvedLanguage {
            var categories: language_source.CategoryIterator = .{ .source = text };
            var found: ?ResolvedLanguage = null;
            while (categories.next()) |target| {
                const category = catalog.ofTitle(target);
                if (category.id != 14) continue;
                // Other or duplicate categories are outside the two captured
                // forms; neither an unknown peer nor a mixed owner is guessed.
                if (found != null or !std.mem.eql(u8, category.text, "Slovenski samostalniki")) return null;
                const language = (try callback(value.source_category_ctx, target)) orelse return null;
                if (!std.mem.eql(u8, language.code, "sl")) return null;
                found = language;
            }
            return found;
        }
    };
    const first = Observe.firstLine(raw);
    if (!Observe.headword(first, title) or !std.mem.eql(u8, first, Observe.firstLine(source))) return null;
    const markers: LanguageMarkers = .{ .codes = &codes };
    var authored_headings = languageSections(raw, &markers);
    authored_headings.all_heading_levels = true;
    // This audit must see every unprotected depth, not just peers of the
    // iterator's first active level. It never changes the grouping iterator.
    authored_headings.heading_filter = .{ .ctx = null, .accepts = Observe.anyHeading };
    if (authored_headings.next() != null) return null;
    var expanded_headings = languageSections(source, &markers);
    expanded_headings.all_heading_levels = true;
    expanded_headings.heading_filter = .{ .ctx = null, .accepts = Observe.anyHeading };
    const support = expanded_headings.next() orelse return null;
    if (support.hyphen_marker or !std.mem.eql(u8, std.mem.trim(u8, support.heading, " \t\r\n"), "Prevodi") or
        !std.mem.eql(u8, Observe.firstLine(support.source), "==== Prevodi ====") or expanded_headings.next() != null) return null;
    const authored = (try Observe.owner(codes, raw, ns, corroborate)) orelse return null;
    const expanded = (try Observe.owner(codes, source, ns, corroborate)) orelse return null;
    return if (std.mem.eql(u8, authored.code, expanded.code) and std.mem.eql(u8, authored.heading, expanded.heading)) authored else null;
}

// TE's captured grammar form has no language heading or populated POS field.
// Its authored category can supply an owner only with current source evidence;
// empty support fields never acquire a lexical sense or POS here.
fn teluguSupportCategoryLanguage(codes: LanguageCodes, source: []const u8, raw_source: ?[]const u8, raw_sections: []const language_source.Section, page_sections: []const language_source.Section) !?ResolvedLanguage {
    const ns = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, ns.content_language, "te")) return null;
    const corroborate = codes.source_category_fn orelse return null;
    const raw = raw_source orelse return null;
    const scaffold = [_][]const u8{ "వ్యాకరణ విశేషాలు", "అర్థ వివరణ", "పదాలు", "పద ప్రయోగాలు", "అనువాదాలు", "మూలాలు, వనరులు", "బయటి లింకులు" };
    if (raw_sections.len != scaffold.len or page_sections.len < 5 or page_sections.len > scaffold.len) return null;
    for (raw_sections, scaffold) |section, heading| if (!std.mem.eql(u8, std.mem.trim(u8, section.heading, " \t\r\n"), heading)) return null;
    for (page_sections, 0..) |section, i| if (!std.mem.eql(u8, std.mem.trim(u8, section.heading, " \t\r\n"), scaffold[i])) return null;
    const Observe = struct {
        fn owner(value: LanguageCodes, text: []const u8, catalog: *const @import("namespace_registry").Registry, callback: *const fn (?*anyopaque, []const u8) anyerror!?ResolvedLanguage) !?ResolvedLanguage {
            var categories: language_source.CategoryIterator = .{ .source = text };
            var found: ?ResolvedLanguage = null;
            while (categories.next()) |target| {
                const title = catalog.ofTitle(target);
                if (title.id != 14 or !(std.mem.endsWith(u8, title.text, " పదాలు") or std.mem.endsWith(u8, title.text, "_పదాలు"))) continue;
                const language = (try callback(value.source_category_ctx, target)) orelse continue;
                if (found) |previous| if (!std.mem.eql(u8, previous.code, language.code)) return null;
                found = language;
            }
            const established_owner = found orelse return null;
            // A dependency edge can only corroborate an already established
            // owner. Unknown peers still veto unless their source agrees.
            categories = .{ .source = text };
            while (categories.next()) |target| {
                const title = catalog.ofTitle(target);
                if (title.id != 14 or !(std.mem.endsWith(u8, title.text, " పదాలు") or std.mem.endsWith(u8, title.text, "_పదాలు"))) continue;
                if (try callback(value.source_category_ctx, target) != null) continue;
                const agrees = value.source_category_agreement_fn orelse return null;
                if (!try agrees(value.source_category_ctx, target, established_owner)) return null;
            }
            return established_owner;
        }
    };
    const authored = (try Observe.owner(codes, raw, ns, corroborate)) orelse return null;
    const expanded = (try Observe.owner(codes, source, ns, corroborate)) orelse return null;
    return if (std.mem.eql(u8, authored.code, expanded.code)) authored else null;
}

// The pinned Bulgarian Noun/Verb/Adjective/Adverb templates have no language
// heading. Their category uses the expanded language-name parameter. Resolve
// only those exact edition-local wrappers through the trusted registry.
fn unsectionedExpandedLanguage(codes: LanguageCodes, source: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "bg")) return null;
    var categories: language_source.CategoryIterator = .{ .source = source };
    var found: ?ResolvedLanguage = null;
    while (categories.next()) |target| {
        const title = namespaces.ofTitle(target);
        if (title.id != 14) continue;
        const name = std.mem.trim(u8, title.text, " \t\r\n");
        const prefix = for ([_][]const u8{
            "Съществителни имена (",
            "Глаголи (",
            "Прилагателни имена (",
            "Наречия (",
        }) |candidate| {
            if (std.mem.startsWith(u8, name, candidate)) break candidate;
        } else continue;
        if (!std.mem.endsWith(u8, name, ")")) return null;
        const label = std.mem.trim(u8, name[prefix.len .. name.len - 1], " \t\r\n");
        const language = codes.resolveStrong(label) orelse codes.resolveTrusted(label) orelse return null;
        if (found) |previous| if (!std.mem.eql(u8, previous.code, language.code)) return null;
        found = language;
    }
    return found;
}

// AF source templates and reviewed authored categories provide a finite owner
// convention. The edition scopes this evidence; it never supplies the owner.
fn unsectionedAfrikaansExpandedLanguage(codes: LanguageCodes, source: []const u8) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "af")) return null;
    const Rule = struct { category: []const u8, label: []const u8, code: []const u8 };
    const rules = [_]Rule{
        .{ .category = "Woorde in Japannees", .label = "Japannees", .code = "ja" },
        .{ .category = "Voornaamwoorde in Japannees", .label = "Japannees", .code = "ja" },
        .{ .category = "Selfstandige naamwoorde in Japannees", .label = "Japannees", .code = "ja" },
        .{ .category = "Werkwoorde in Japannees", .label = "Japannees", .code = "ja" },
        .{ .category = "Byvoeglike naamwoorde in Japannees", .label = "Japannees", .code = "ja" },
        .{ .category = "Woorde in Duits", .label = "Duits", .code = "de" },
        .{ .category = "Woorde in Nederlands", .label = "Nederlands", .code = "nl" },
        .{ .category = "Vervoeging in Nederlands", .label = "Nederlands", .code = "nl" },
        .{ .category = "Selfstandige naamwoorde in Afrikaans", .label = "Afrikaans", .code = "af" },
        .{ .category = "Selfstandige naamwoordvorme in Afrikaans", .label = "Afrikaans", .code = "af" },
        .{ .category = "Werkwoorde in Afrikaans", .label = "Afrikaans", .code = "af" },
    };
    var categories: language_source.CategoryIterator = .{ .source = source };
    var found: ?ResolvedLanguage = null;
    var constrained: ?ResolvedLanguage = null;
    while (categories.next()) |target| {
        const title = namespaces.ofTitle(target);
        if (title.id != 14) continue;
        const name = std.mem.trim(u8, title.text, " \t\r\n");
        var label: ?[]const u8 = null;
        var required_code: ?[]const u8 = null;
        // Preserve the source178 AF-only participle convention and its trust
        // rules, including its exact registered same-owner aliases.
        for ([_][]const u8{
            "Deelwoorde in ",           "Werkwoordvorme in ",
            "Voltooide deelwoorde in ", "Teenwoordige deelwoorde in ",
        }) |prefix| {
            if (std.mem.eql(u8, name, std.mem.trimEnd(u8, prefix, " "))) return null;
            if (std.mem.startsWith(u8, name, prefix)) {
                label = std.mem.trim(u8, name[prefix.len..], " \t\r\n");
                required_code = "af";
                break;
            }
        }
        if (label == null) {
            for (rules) |rule| {
                if (std.mem.eql(u8, name, rule.category)) {
                    label = rule.label;
                    required_code = rule.code;
                    break;
                }
            }
            if (label == null) {
                // An unsupported wrapper cannot supply positive authority.
                // Its trusted owner still constrains compatibility with a
                // separately proved owner; unknown/conflicting labels refuse.
                for ([_][]const u8{
                    "Woorde in ",                      "Voornaamwoorde in ",        "Selfstandige naamwoorde in ",
                    "Werkwoorde in ",                  "Byvoeglike naamwoorde in ", "Vervoeging in ",
                    "Selfstandige naamwoordvorme in ",
                }) |prefix| {
                    if (std.mem.eql(u8, name, std.mem.trimEnd(u8, prefix, " "))) return null;
                    if (std.mem.startsWith(u8, name, prefix)) {
                        label = std.mem.trim(u8, name[prefix.len..], " \t\r\n");
                        break;
                    }
                }
                if (label == null) continue;
            }
        }
        const language = codes.resolveStrong(label.?) orelse codes.resolveTrusted(label.?) orelse return null;
        if (required_code) |expected| if (!std.mem.eql(u8, language.code, expected)) return null;
        if (constrained) |previous| if (!std.mem.eql(u8, previous.code, language.code)) return null;
        constrained = language;
        if (required_code != null) found = language;
    }
    return found;
}

const PageSourceFragment = struct {
    source: []const u8,
    original_start: ?usize = null,
};

const PageLanguageGroup = struct {
    language: ResolvedLanguage,
    fragments: std.ArrayList(PageSourceFragment) = .empty,

    fn appendSource(self: *PageLanguageGroup, a: std.mem.Allocator, fragment: PageSourceFragment) !void {
        if (fragment.source.len != 0) try self.fragments.append(a, fragment);
    }
};

fn missingOwnerSourceAlloc(a: std.mem.Allocator, source: MissingText, fragments: []const PageSourceFragment, prefix: []const u8) !MissingText {
    var out: missing_dependency.Builder = .{};
    errdefer out.deinit(a);
    if (prefix.len != 0) try out.appendSlice(a, source, 0, prefix.len);
    for (fragments) |fragment| {
        if (fragment.original_start) |start| {
            if (start > source.bytes.len or fragment.source.len > source.bytes.len - start) return error.InvalidPreContext;
            try out.appendSlice(a, source, start, start + fragment.source.len);
        } else try out.append(a, MissingText.transformedFrom(source, fragment.source));
    }
    return out.finish(a);
}

// Match missingOwnerSourceAlloc's concatenation without changing the renderer's
// existing owner-fragment boundaries or reparsing any heading source here.
fn ownerHeadingSourceRangesAlloc(a: std.mem.Allocator, fragments: []const PageSourceFragment, prefix_len: usize) ![]const presentation_document.HeadingSourceRange {
    var ranges: std.ArrayList(presentation_document.HeadingSourceRange) = .empty;
    errdefer ranges.deinit(a);
    var owner_start: usize = prefix_len;
    if (prefix_len != 0) try ranges.append(a, .{ .owner_start = 0, .page_start = 0, .len = prefix_len });
    for (fragments) |fragment| {
        if (fragment.original_start) |page_start|
            try ranges.append(a, .{ .owner_start = owner_start, .page_start = page_start, .len = fragment.source.len });
        owner_start = try std.math.add(usize, owner_start, fragment.source.len);
    }
    return ranges.toOwnedSlice(a);
}

fn preCandidate(input: []const u8) bool {
    var at: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, at, '<')) |opening| {
        at = opening + 1;
        if (input.len - at >= 3 and std.ascii.eqlIgnoreCase(input[at .. at + 3], "pre")) return true;
    }
    return false;
}

fn freeObservedScopes(a: std.mem.Allocator, scopes: []const presentation_document.ObservedPreScope) void {
    for (scopes) |scope| {
        a.free(scope.target);
        a.free(scope.attributes.classes);
        a.free(scope.attributes.css_ancestor_classes);
        a.free(scope.attributes.language);
        a.free(scope.attributes.direction);
        if (scope.attributes.captured_direction) |value| a.free(value);
        a.free(scope.attributes.explanation);
        if (scope.attributes.tooltip) |title| a.free(title);
        if (scope.attributes.foreground) |color| a.free(color);
    }
    if (scopes.len != 0) a.free(scopes);
}

fn freePreObservation(a: std.mem.Allocator, observation: presentation_document.PreObservation) void {
    observation.deinitTextAncestry(a);
    freeObservedScopes(a, observation.scopes);
    a.free(observation.refused_link_openings);
}

const ControlledFigureFixture = struct {
    const T = @import("blob_encoder").presentation_types;
    const Ns = @import("namespace_registry").Registry;
    file: []const u8,
    width: u32,
    fn resolve(raw: ?*const anyopaque, _: std.mem.Allocator, file: []const u8, format_value: T.FigureFormat, width: ?u32, height: ?u32) std.mem.Allocator.Error!?T.FigureSizingPolicy {
        const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
        if (!std.mem.eql(u8, file, self.file) or format_value != .thumbnail or width != self.width or height != null) return null;
        return .requested_fit;
    }
    fn source(self: *const @This(), ns: *const Ns) presentation_document.FigureSizingSource {
        return .{ .ctx = self, .resolve_fn = resolve, .source_context = .{
            .namespace_sha256 = ns.source_sha256,
            .defaults = .{ .rtl = false, .default_thumbnail_width = 275 },
        } };
    }
    const namespace_bytes = "# wikidict-namespace-registry-v1\n# wiki\tenwiktionary\n# dump-date\t20261001\n# content-language\ten\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\twikitext\tmain\tentries\n" ++
        "6\tFile\tFile\tcase-sensitive\t0\t0\t0\twikitext\tcompile_only\tmedia\n" ++
        "10\tTemplate\tTemplate\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\ttemplates\n" ++
        "14\tCategory\tCategory\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\tcategories\n";
    fn countBlocks(blocks: []const T.Block) usize {
        var total: usize = 0;
        for (blocks) |block| {
            if (block.flow) |parts| total += countFlow(parts);
            if (block.figure) |figure| { total += 1; if (figure.caption_blocks) |children| total += countBlocks(children); }
            if (block.table) |table| total += countTable(table);
        }
        return total;
    }
    fn countFlow(parts: []const T.FlowPart) usize {
        var total: usize = 0;
        for (parts) |part| switch (part.kind) {
            .@"inline" => {},
            .figure => if (part.figure) |figure| { total += 1; if (figure.caption_blocks) |children| total += countBlocks(children); },
            .scope => if (part.scope) |scope| { total += countFlow(scope.parts); },
        };
        return total;
    }
    fn countTable(table: T.Table) usize {
        var total: usize = 0;
        if (table.caption_blocks) |children| total += countBlocks(children);
        for (table.rows) |row| for (row.cells) |cell| {
            if (cell.blocks) |children| total += countBlocks(children);
            if (cell.nested_table) |nested| total += countTable(nested);
        };
        return total;
    }
    fn count(entry: T.Entry) usize {
        var total: usize = 0;
        for (entry.sections) |section| total += countBlocks(section.blocks);
        for (entry.references) |reference| if (reference.blocks) |blocks| { total += countBlocks(blocks); };
        return total;
    }
};

test "CSS ancestor observations release owned classes on success and allocation failure" {
    const Case = struct {
        fn run(a: std.mem.Allocator) !void {
            const source = "<div class=\"First\">first body</div>\n<div class=\"Second\">second body</div>";
            const observation = try presentation_document.observePreScopesAlloc(a, "CSS ownership", source, .{}, null, null, null, .{}, null);
            defer freePreObservation(a, observation);
            try std.testing.expectEqual(@as(usize, 2), observation.scopes.len);
            for (observation.scopes, [_][]const u8{ "First", "Second" }, [_][]const u8{ "first body", "second body" }) |scope, classes, body| {
                try std.testing.expect(scope.kind == .css_block and scope.matched);
                try std.testing.expectEqualStrings(classes, scope.attributes.css_ancestor_classes);
                try std.testing.expectEqualStrings(body, source[scope.body_start..scope.body_end]);
            }
        }
    };
    // Multiple scopes exercise unwind after an earlier observation was retained.
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Case.run, .{});
}

fn linkOpeningsAlloc(a: std.mem.Allocator, scopes: []const presentation_document.ObservedPreScope, refused_link_openings: []const usize) ![]const usize {
    var openings: std.ArrayList(usize) = .empty;
    errdefer openings.deinit(a);
    for (scopes) |scope| if (scope.kind == .link) try openings.append(a, scope.opening_start);
    try openings.appendSlice(a, refused_link_openings);
    std.mem.sort(usize, openings.items, {}, std.sort.asc(usize));
    var unique: usize = 0;
    for (openings.items) |opening| {
        if (unique == 0 or openings.items[unique - 1] != opening) {
            openings.items[unique] = opening;
            unique += 1;
        }
    }
    openings.items = openings.items[0..unique];
    return openings.toOwnedSlice(a);
}

fn refusedOpeningInFragments(source: []const u8, fragments: []const PageSourceFragment, refused_openings: []const usize) !bool {
    for (fragments) |fragment| {
        const start = fragment.original_start orelse continue;
        if (start > source.len or fragment.source.len > source.len - start or fragment.source.ptr != source[start..].ptr)
            return error.InvalidPreContext;
        const index = firstQuoteCutAtOrAfter(refused_openings, start);
        if (index < refused_openings.len and refused_openings[index] < start + fragment.source.len) return true;
    }
    return false;
}

fn lastPreOpeningBefore(scopes: []const presentation_document.ObservedPreScope, at: usize) ?usize {
    var low: usize = 0;
    var high: usize = scopes.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        if (scopes[middle].opening_start < at) low = middle + 1 else high = middle;
    }
    return if (low == 0) null else low - 1;
}

const ScopeQuoteCuts = struct {
    positions: []const usize = &.{},
    seeds: []const presentation_document.QuoteSeed = &.{},
    fn at(self: @This(), position: usize) !presentation_document.QuoteSeed {
        const index = firstQuoteCutAtOrAfter(self.positions, position);
        if (index == self.positions.len or self.positions[index] != position) return error.InvalidPreContext;
        return self.seeds[index];
    }
    fn deinit(self: @This(), a: std.mem.Allocator) void {
        a.free(self.positions);
        a.free(self.seeds);
    }
};
const PageQuoteCuts = struct {
    outer: ScopeQuoteCuts = .{},
    links: []ScopeQuoteCuts = &.{},
    fn deinit(self: @This(), a: std.mem.Allocator) void {
        self.outer.deinit(a);
        for (self.links) |cuts| cuts.deinit(a);
        a.free(self.links);
    }
};
fn firstQuoteCutAtOrAfter(cuts: []const usize, position: usize) usize {
    var low: usize = 0;
    var high = cuts.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        if (cuts[middle] < position) low = middle + 1 else high = middle;
    }
    return low;
}
fn enclosingLinkScope(scopes: []const presentation_document.ObservedPreScope, position: usize) ?usize {
    var cursor = lastPreOpeningBefore(scopes, position);
    while (cursor) |index| {
        const scope = scopes[index];
        if (scope.kind == .link and scope.opening_start < position and position < scope.resume_at) return index;
        cursor = scope.parent;
    }
    return null;
}
fn appendQuoteCut(a: std.mem.Allocator, cuts: *std.ArrayList(usize), position: usize) !void {
    if (cuts.items.len != 0) {
        const previous = cuts.items[cuts.items.len - 1];
        if (position < previous) return error.InvalidPreContext;
        if (position == previous) return;
    }
    try cuts.append(a, position);
}
fn pageQuoteCutsAlloc(a: std.mem.Allocator, source: []const u8, sections: []const language_source.Section, scopes: []const presentation_document.ObservedPreScope, context: presentation_document.QuoteContext) !PageQuoteCuts {
    var positions: std.ArrayList(usize) = .empty;
    defer positions.deinit(a);
    try appendQuoteCut(a, &positions, 0);
    for (sections) |section| {
        const base = @intFromPtr(source.ptr);
        const pointer = @intFromPtr(section.source.ptr);
        if (pointer < base or pointer - base > source.len or section.source.len > source.len - (pointer - base)) return error.InvalidPreContext;
        const start = pointer - base;
        try appendQuoteCut(a, &positions, start);
        try appendQuoteCut(a, &positions, start + section.source.len);
    }
    try appendQuoteCut(a, &positions, source.len);
    var outside: std.ArrayList(usize) = .empty;
    defer outside.deinit(a);
    for (positions.items) |position| if (enclosingLinkScope(scopes, position) == null) try outside.append(a, position);
    const outer_positions = try outside.toOwnedSlice(a);
    errdefer a.free(outer_positions);
    const outer_seeds = try presentation_document.bodyQuoteCutSeedsWithContextAlloc(a, source, outer_positions, context);
    errdefer a.free(outer_seeds);
    if (outer_positions.len != outer_seeds.len) return error.InvalidPreContext;
    const links = try a.alloc(ScopeQuoteCuts, scopes.len);
    @memset(links, .{});
    errdefer {
        for (links) |cuts| cuts.deinit(a);
        a.free(links);
    }
    for (scopes, links) |scope, *output| {
        if (scope.kind != .link) continue;
        const observed = scope.link_quotes orelse return error.InvalidPreContext;
        var cuts: std.ArrayList(usize) = .empty;
        defer cuts.deinit(a);
        try appendQuoteCut(a, &cuts, scope.body_start);
        var cursor = firstQuoteCutAtOrAfter(positions.items, scope.body_start);
        while (cursor < positions.items.len and positions.items[cursor] <= scope.body_end) : (cursor += 1)
            try appendQuoteCut(a, &cuts, positions.items[cursor]);
        try appendQuoteCut(a, &cuts, scope.body_end);
        const relative = try a.alloc(usize, cuts.items.len);
        defer a.free(relative);
        for (cuts.items, relative) |absolute, *offset| offset.* = absolute - scope.body_start;
        const seeds = try presentation_document.linkQuoteCutSeedsWithContextAlloc(a, source[scope.body_start..scope.body_end], relative, observed.entry, context);
        errdefer a.free(seeds);
        if (seeds.len != cuts.items.len) return error.InvalidPreContext;
        output.* = .{ .positions = try cuts.toOwnedSlice(a), .seeds = seeds };
    }
    return .{ .outer = .{ .positions = outer_positions, .seeds = outer_seeds }, .links = links };
}

fn fragmentPreContextAlloc(a: std.mem.Allocator, start: usize, end: usize, scopes: []const presentation_document.ObservedPreScope, quotes: PageQuoteCuts) !presentation_document.FragmentPreContext {
    var initial: std.ArrayList(presentation_document.FragmentPreContext.Initial) = .empty;
    errdefer initial.deinit(a);
    var trailing: std.ArrayList(presentation_document.FragmentPreContext.Trailing) = .empty;
    errdefer trailing.deinit(a);
    var newest_open: ?usize = null;
    var newest_close: usize = 0;
    var cursor = lastPreOpeningBefore(scopes, start);
    // Source-backed body scopes are properly nested. Only ancestors of the
    // last opening can contain this cut, so ordinary earlier roots are skipped.
    while (cursor) |index| {
        const scope = scopes[index];
        if (scope.body_start <= start and start < scope.body_end) {
            try initial.append(a, .{
                .body_end = @min(scope.body_end, end) - start,
                .resume_at = @min(scope.resume_at, end) - start,
                .kind = scope.kind,
                .formatting = scope.formatting,
                .attributes = scope.attributes,
                .target = scope.target,
                .tag_name = scope.tag_name,
                .quote = if (scope.kind == .link) try quotes.links[index].at(start) else null,
                .resume_quote = if (scope.kind == .link) (scope.link_quotes orelse return error.InvalidPreContext).resume_quote else null,
            });
            if (scope.kind == .pre) newest_open = @max(newest_open orelse 0, scope.body_start);
        }
        if (scope.kind == .pre and scope.matched and scope.resume_at <= start) newest_close = @max(newest_close, scope.resume_at);
        cursor = scope.parent;
    }
    cursor = lastPreOpeningBefore(scopes, end);
    while (cursor) |index| {
        const scope = scopes[index];
        if (scope.opening_start >= start and scope.body_start <= end and scope.body_end >= end)
            try trailing.append(a, .{ .opening_start = scope.opening_start - start, .body_start = scope.body_start - start, .kind = scope.kind, .formatting = scope.formatting, .attributes = scope.attributes, .target = scope.target, .tag_name = scope.tag_name, .quote = if (scope.kind == .link) (scope.link_quotes orelse return error.InvalidPreContext).entry else null });
        cursor = scope.parent;
    }
    // Initial ancestors were appended inner-first. Trailing opens need the
    // opposite order so the adapter consumes their actual tag intervals.
    std.mem.reverse(presentation_document.FragmentPreContext.Trailing, trailing.items);
    const initial_owned = try initial.toOwnedSlice(a);
    errdefer a.free(initial_owned);
    const trailing_owned = try trailing.toOwnedSlice(a);
    errdefer a.free(trailing_owned);
    return .{
        .quote = if (enclosingLinkScope(scopes, start)) |index| try quotes.links[index].at(start) else try quotes.outer.at(start),
        .initial = initial_owned,
        .trailing = trailing_owned,
        .initial_block_pre = if (newest_open) |opened| opened > newest_close else false,
    };
}

// A whole-page content boundary is not inherited by owner fragments. In
// particular, existing scope recovery need not retain an ID-only DIV at a cut.
fn completeContentRanges(source: []const u8, fragments: []const PageSourceFragment, prefix: []const u8) bool {
    if (prefix.len > source.len or (prefix.len != 0 and prefix.ptr != source.ptr)) return false;
    var at = prefix.len;
    for (fragments) |fragment| {
        const start = fragment.original_start orelse return false;
        if (start != at or fragment.source.len > source.len - at or fragment.source.ptr != source[at..].ptr) return false;
        at += fragment.source.len;
    }
    return at == source.len;
}

const observedContentBoundary = @import("presentation_compile.zig").containsSortedOffset;

// Both ends must be actual top-level page boundaries. A nested heading or an
// ID-only DIV cut cannot borrow a parser-output root from a sibling section.
// Preparing an entire page is not permission to erase a prefix ancestor.
// Existing Figure/root semantics remain unchanged; only the new table proof
// additionally requires identical original bytes through each completed table.
// Tail-only page preparation cannot erase the earlier original ancestry proof.
// Only the separate strict, nonnested top-level observer list may survive a
// later page preparation edit. Its entire original prefix through the completed
// physical close must still be byte-identical; an unchanged opener is not enough.
fn originalTopLevelTablePrefix(source: []const u8, original: []const u8, openings: []const usize) []const usize {
    var common: usize = 0;
    const limit = @min(source.len, original.len);
    while (common < limit and source[common] == original[common]) : (common += 1) {}
    var kept: usize = 0;
    for (openings, 0..) |opening, index| {
        if (opening >= common or common - opening < 2 or
            (index != 0 and opening <= openings[index - 1]) or
            (opening != 0 and source[opening - 1] != '\n') or
            !std.mem.startsWith(u8, source[opening..], "{|")) break;
        var line = opening;
        var completed = false;
        while (line < common) {
            const end = std.mem.indexOfScalarPos(u8, source, line, '\n') orelse source.len;
            const after = end + @as(usize, @intFromBool(end < source.len));
            if (after > common) break;
            if (line != opening and std.mem.startsWith(u8, source[line..end], "|}")) {
                if (std.mem.trim(u8, source[line + 2 .. end], " \t\r").len == 0) completed = true;
                break;
            }
            if (after == source.len) break;
            line = after;
        }
        if (!completed) break;
        kept += 1;
    }
    return openings[0..kept];
}

fn bindOwnerRootTableSource(source: []const u8, original: []const u8, observed: presentation_document.HeadingObservation, fragment: *presentation_document.SourceFragment) void {
    bindOwnerContentRoot(source, observed, fragment);
    // Root/source ownership is necessary but not a class-preserving rewrite
    // certificate. Only exact bytes may retain the original observation source.
    if (std.mem.eql(u8, source, original)) {
        if (fragment.parser_output_range) |*proof| proof.original_page = original;
    }
    if (!std.mem.eql(u8, source, original)) {
        if (fragment.parser_output_range) |*proof| {
            proof.root_wiki_table_openings = &.{};
            proof.top_level_wiki_table_openings = originalTopLevelTablePrefix(source, original, proof.top_level_wiki_table_openings);
        }
    }
}

fn bindOwnerSourceElements(source: []const u8, original: []const u8, projection: ?*const presentation_document.SourceElementProjection, fragment: *presentation_document.SourceFragment) void {
    const range = if (fragment.parser_output_range) |*value| value else return;
    range.source_element_projection = null;
    const issued = projection orelse return;
    if (range.page.ptr != source.ptr or range.page.len != source.len or
        issued.prepared.ptr != source.ptr or issued.prepared.len != source.len or
        issued.original.bytes.ptr != original.ptr or issued.original.bytes.len != original.len) return;
    range.source_element_projection = issued;
}

// Numbering deliberately withholds transformed-source projections for phase
// inputs. An exact selected Table can still borrow Builder's unchanged complete
// page, without class ancestry or permission to cross a transformed interval.
fn unchangedTableSourceProjection(sizing: ?presentation_document.FigureSizingSource, original: MissingText,
    prepared: MissingText, copy: *[1]presentation_document.SourceElementProjection.Copy) ?presentation_document.SourceElementProjection
{
    const selected = sizing orelse return null;
    var owns_original = false;
    for ([_]?@import("presentation_compile.zig").TableContainingDirectionSource{ selected.table_containing_direction, selected.table_float_source }) |maybe| if (maybe) |table| {
        if (table.source.ptr == original.bytes.ptr and table.source.len == original.bytes.len) owns_original = true;
    };
    if (!owns_original or original.bytes.len == 0 or !std.mem.eql(u8, original.bytes, prepared.bytes)) return null;
    for ([_]MissingText{ original, prepared }) |tracked| {
        if (tracked.unknown or tracked.lost_missing_range or tracked.generated_source != null or
            tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or tracked.generated_links.len != 0) return null;
    }
    copy[0] = .{ .original_start = 0, .prepared_start = 0, .len = original.bytes.len };
    return .{ .original = original, .prepared = prepared.bytes, .copies = copy };
}

fn observeSourceElements(sizing: ?presentation_document.FigureSizingSource, source: []const u8) bool {
    const selected = sizing orelse return false;
    if (selected.table_containing_direction) |direction|
        if (direction.source.ptr == source.ptr and direction.source.len == source.len) return true;
    if (selected.table_float_source) |floating|
        if (floating.source.ptr == source.ptr and floating.source.len == source.len) return true;
    const observed = selected.text_class_scope orelse return false;
    return (observed.scope.source_siblings.len != 0 or observed.scope.source_root_tables.len != 0 or (observed.scope.page_styles != null and observed.scope.page_style_root != null)) and
        observed.source.ptr == source.ptr and observed.source.len == source.len;
}

fn bindOwnerNativeSourceClasses(source: []const u8, proof: ?*const presentation_document.NativeSourceClassProof,
    fragment: *presentation_document.SourceFragment) void
{
    const range = if (fragment.parser_output_range) |value| value else return;
    fragment.parser_output_range.?.native_source_class_proof = null;
    const held = proof orelse return;
    const prepared = fragment.missing orelse MissingText.untracked(fragment.source);
    if (source.ptr != held.source.bytes.ptr or source.len != held.source.bytes.len or
        range.page.ptr != source.ptr or range.page.len != source.len or fragment.original_start != range.start or
        range.start > source.len or fragment.source.len > source.len - range.start or
        fragment.source.ptr != source[range.start..].ptr or prepared.bytes.ptr != range.prepared.ptr or
        prepared.bytes.len != range.prepared.len or fragment.pre.initial_block_pre or
        fragment.pre.initial.len != 0 or fragment.pre.trailing.len != 0) return;
    const current: @import("presentation_compile.zig").NativeSourceClassRange = .{ .proof = held, .start = range.start, .prepared = prepared };
    if (!presentation_document.nativeSourceClassRangeCurrent(current, prepared, held.profile)) return;
    fragment.parser_output_range.?.native_source_class_proof = held;
}

fn bindOwnerTextClassTransition(source: []const u8, original: []const u8, numbered: []const u8, transition: ?presentation_document.ClassScopeSourceTransition, fragment: *presentation_document.SourceFragment) void {
    const proof = if (fragment.parser_output_range) |*value| value else return;
    if (proof.original_page != null) return;
    if (proof.page.ptr != source.ptr or proof.page.len != source.len) return;
    const issued = transition orelse return;
    if (issued.original.ptr != original.ptr or issued.original.len != original.len or
        issued.prepared.ptr != numbered.ptr or issued.prepared.len != numbered.len or
        !std.mem.eql(u8, source, numbered)) return;
    // The existing complete-root proof remains mandatory. Only the compiler's
    // selected numeric-label transition may cross the original/prepared gap;
    // any later body/TOC byte edit leaves this capability absent.
    proof.original_page = original;
}

fn bindOwnerContentRoot(source: []const u8, observed: presentation_document.HeadingObservation, fragment: *presentation_document.SourceFragment) void {
    fragment.parser_output_range = null;
    const page = observed.page_html_source orelse return;
    if (!observed.page_wiki_scope_complete or page.ptr != source.ptr or page.len != source.len) return;
    const start = fragment.original_start orelse return;
    if (start > source.len or fragment.source.len > source.len - start or
        fragment.source.ptr != source[start..].ptr or
        fragment.pre.initial.len != 0 or fragment.pre.trailing.len != 0 or fragment.pre.initial_block_pre) return;
    const end = start + fragment.source.len;
    for ([_]usize{ start, end }) |boundary| {
        if (boundary == 0 or boundary == source.len) continue;
        if (!observedContentBoundary(observed.page_wiki_openings, boundary) and
            !observedContentBoundary(observed.page_wiki_content_openings, boundary) and
            !observedContentBoundary(observed.page_html_openings, boundary)) return;
    }
    const prepared = if (fragment.missing) |missing| missing.bytes else fragment.source;
    if (prepared.len != fragment.source.len or !std.mem.eql(u8, prepared, fragment.source)) return;
    // missing is produced above by the ordinary tracked slice operation; this
    // token binds that exact view, not arbitrary future byte-identical copies.
    fragment.parser_output_range = .{ .page = source, .start = start, .prepared = prepared, .root_wiki_table_openings = observed.page_root_wiki_table_openings, .top_level_wiki_table_openings = observed.page_top_level_wiki_table_openings, .quoted_paragraph_openings = observed.page_quoted_paragraph_openings, .static_example_openings = observed.page_static_example_openings };
}

fn observedOwnerContentRanges(source: []const u8, observed: presentation_document.HeadingObservation, fragments: []const PageSourceFragment, prefix: []const u8) bool {
    if (fragments.len == 0) return false;
    if (prefix.len != 0) {
        var head: presentation_document.SourceFragment = .{ .source = prefix, .original_start = 0 };
        bindOwnerContentRoot(source, observed, &head);
        if (head.parser_output_range == null) return false;
    }
    for (fragments) |range| {
        var fragment: presentation_document.SourceFragment = .{ .source = range.source, .original_start = range.original_start };
        bindOwnerContentRoot(source, observed, &fragment);
        if (fragment.parser_output_range == null) return false;
    }
    return true;
}

fn ownerSourceFragmentsAlloc(a: std.mem.Allocator, source: []const u8, fragments: []const PageSourceFragment, prefix: []const u8, scopes: []const presentation_document.ObservedPreScope, quotes: PageQuoteCuts) ![]const presentation_document.SourceFragment {
    return ownerSourceFragmentsWithMissingAlloc(a, MissingText.untracked(source), fragments, prefix, scopes, quotes);
}
fn ownerSourceFragmentsWithMissingAlloc(a: std.mem.Allocator, tracked: MissingText, fragments: []const PageSourceFragment, prefix: []const u8, scopes: []const presentation_document.ObservedPreScope, quotes: PageQuoteCuts) ![]presentation_document.SourceFragment {
    const source = tracked.bytes;
    var ranges: std.ArrayList(PageSourceFragment) = .empty;
    defer ranges.deinit(a);
    if (prefix.len != 0) try ranges.append(a, .{ .source = prefix, .original_start = 0 });
    for (fragments) |fragment| {
        if (ranges.items.len != 0) {
            const previous = &ranges.items[ranges.items.len - 1];
            if (previous.original_start) |left| if (fragment.original_start) |right| {
                if (left + previous.source.len == right) {
                    previous.source = source[left .. right + fragment.source.len];
                    continue;
                }
            };
        }
        try ranges.append(a, fragment);
    }
    const result = try a.alloc(presentation_document.SourceFragment, ranges.items.len);
    var initialized: usize = 0;
    errdefer {
        for (result[0..initialized]) |fragment| {
            a.free(fragment.pre.initial);
            a.free(fragment.pre.trailing);
        }
        a.free(result);
    }
    for (ranges.items, result) |range, *fragment| {
        fragment.* = .{
            .source = range.source,
            .original_start = range.original_start,
            .missing = if (range.original_start) |start| try missing_dependency.slice(a, tracked, start, start + range.source.len) else MissingText.transformedFrom(tracked, range.source),
            .pre = if (range.original_start) |start|
                try fragmentPreContextAlloc(a, start, start + range.source.len, scopes, quotes)
            else
                .{},
        };
        initialized += 1;
    }
    return result;
}

fn groupIndex(groups: []PageLanguageGroup, language: ResolvedLanguage) ?usize {
    for (groups, 0..) |group, index| {
        // Distinct reviewed varieties share a parent code, not a record owner.
        if (std.mem.eql(u8, group.language.code, language.code) and
            std.mem.eql(u8, group.language.heading, language.heading)) return index;
    }
    return null;
}

// An exact equals declaration and its expanded heading independently repeat
// the registered canonical code. Display names can collide across languages;
// neither arbitrary raw text nor a hyphen/POS marker supplies this evidence.
fn corroboratedEqualsDeclaration(codes: LanguageCodes, raw: language_source.Section, rendered: language_source.Section, raw_code: []const u8, rendered_code: []const u8) bool {
    const canonical = codes.resolve(raw_code) orelse return false;
    if (!std.mem.eql(u8, canonical.code, raw_code) or raw.hyphen_marker) return false;
    const declaration = language_source.equalsLanguageDeclaration(raw.source) orelse return false;
    if (!std.mem.eql(u8, declaration, raw_code)) return false;
    const heading = std.mem.trim(u8, rendered.heading, " \t\r\n");
    if (!std.mem.startsWith(u8, heading, "[[") or !std.mem.endsWith(u8, heading, "]]")) return false;
    const body = heading[2 .. heading.len - 2];
    if (std.mem.indexOfAny(u8, body, "[]{}<>\r\n") != null) return false;
    const pipe = std.mem.indexOfScalar(u8, body, '|') orelse return false;
    if (std.mem.indexOfScalar(u8, body[pipe + 1 ..], '|') != null) return false;
    const target_language = codes.resolve(std.mem.trim(u8, body[0..pipe], " \t")) orelse return false;
    if (!std.mem.eql(u8, target_language.code, rendered_code)) return false;
    const label = std.mem.trim(u8, body[pipe + 1 ..], " \t");
    if (label.len < raw_code.len + 3 or label[label.len - 1] != ')') return false;
    const open = label.len - raw_code.len - 2;
    return label[open] == '(' and open > 0 and std.ascii.isWhitespace(label[open - 1]) and
        std.mem.eql(u8, label[open + 1 .. label.len - 1], raw_code);
}

// ANG constitution rev54826 uses the noun role Nama at language depth.
// Its exact en-nama headword template invokes the English noun module. Only
// this aligned continuation of an explicit English section disambiguates the
// homographic Nama language name; ordinary Nama declarations keep their owner.
fn angEnglishNounContinuation(
    codes: LanguageCodes,
    previous_raw: language_source.Section,
    raw: language_source.Section,
    rendered: language_source.Section,
    current_code: []const u8,
) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "ang") or
        !std.mem.eql(u8, current_code, "en") or
        previous_raw.hyphen_marker or raw.hyphen_marker or rendered.hyphen_marker) return null;
    if (!std.mem.eql(u8, std.mem.trim(u8, previous_raw.heading, " \t\r\n"), "{{sprǣc|en}}") or
        !std.mem.eql(u8, std.mem.trim(u8, raw.heading, " \t\r\n"), "Nama") or
        !std.mem.eql(u8, std.mem.trim(u8, rendered.heading, " \t\r\n"), "Nama")) return null;
    const previous_end = std.mem.indexOfScalar(u8, previous_raw.source, '\n') orelse return null;
    const raw_end = std.mem.indexOfScalar(u8, raw.source, '\n') orelse return null;
    const rendered_end = std.mem.indexOfScalar(u8, rendered.source, '\n') orelse return null;
    if (!std.mem.eql(u8, std.mem.trim(u8, previous_raw.source[0..previous_end], " \t\r"), "=={{sprǣc|en}}==") or
        !std.mem.eql(u8, std.mem.trim(u8, raw.source[0..raw_end], " \t\r"), "==Nama==") or
        !std.mem.eql(u8, std.mem.trim(u8, rendered.source[0..rendered_end], " \t\r"), "==Nama==")) return null;
    // Require the literal first non-whitespace token, not a template inside a
    // comment, protected span, nested template, example or later translation.
    const body = std.mem.trimStart(u8, raw.source[raw_end + 1 ..], " \t\r\n");
    const headword = "{{en-nama}}";
    if (!std.mem.startsWith(u8, body, headword) or
        (body.len > headword.len and !std.ascii.isWhitespace(body[headword.len]))) return null;
    const language = codes.resolve("en") orelse return null;
    return if (std.mem.eql(u8, language.code, "en")) language else null;
}

// The captured ANG noun-table convention supplies a grammatical cue independent
// of the homographic Nama language label. Keep both the raw and expanded cue,
// the preceding explicit Old English declaration, and the registered code.
fn angNounTableContinuation(
    codes: LanguageCodes,
    preceding_raw: []const language_source.Section,
    raw: language_source.Section,
    rendered: language_source.Section,
    current_code: []const u8,
) ?ResolvedLanguage {
    const namespaces = codes.namespace_catalog orelse return null;
    if (!std.mem.eql(u8, namespaces.content_language, "ang") or
        !std.mem.eql(u8, current_code, "ang") or raw.hyphen_marker or rendered.hyphen_marker or
        !std.mem.eql(u8, raw.heading, "Nama") or !std.mem.eql(u8, rendered.heading, "Nama")) return null;
    var explicit_ang = false;
    var previous = preceding_raw.len;
    while (previous > 0) {
        previous -= 1;
        const section = preceding_raw[previous];
        if (section.hyphen_marker) return null;
        const end = std.mem.indexOfScalar(u8, section.source, '\n') orelse return null;
        const line = std.mem.trim(u8, section.source[0..end], " \t\r");
        if (std.mem.eql(u8, line, "=={{sprǣc|ang}}==")) {
            explicit_ang = true;
            break;
        }
        // This captured adjective heading is a support section, not another
        // language declaration. An arbitrary intervening heading cannot lend
        // the old declaration to a later homograph.
        if (!std.mem.eql(u8, line, "==Tōgeīecendlic==")) return null;
    }
    if (!explicit_ang) return null;
    const raw_end = std.mem.indexOfScalar(u8, raw.source, '\n') orelse return null;
    const rendered_end = std.mem.indexOfScalar(u8, rendered.source, '\n') orelse return null;
    if (!std.mem.eql(u8, std.mem.trim(u8, raw.source[0..raw_end], " \t\r"), "==Nama==") or
        !std.mem.eql(u8, std.mem.trim(u8, rendered.source[0..rendered_end], " \t\r"), "==Nama==")) return null;
    const body = std.mem.trimStart(u8, raw.source[raw_end + 1 ..], " \t\r\n");
    const heading_end = std.mem.indexOfScalar(u8, body, '\n') orelse return null;
    if (!std.mem.eql(u8, std.mem.trim(u8, body[0..heading_end], " \t\r"), "=== {{m}} {{Wordcynn|Nama}} ===")) return null;
    const table = std.mem.trimStart(u8, body[heading_end + 1 ..], " \t\r\n");
    if (!std.mem.startsWith(u8, table, "{{Naman-Tabule|")) return null;
    _ = blobs.wikitext_syntax.balanced(table, 0) orelse return null;
    const expanded_body = std.mem.trimStart(u8, rendered.source[rendered_end + 1 ..], " \t\r\n");
    const expanded_heading_end = std.mem.indexOfScalar(u8, expanded_body, '\n') orelse return null;
    if (!std.mem.eql(u8, std.mem.trim(u8, expanded_body[0..expanded_heading_end], " \t\r"), "=== Werlic [[Help:Wordcynn|Nama]][[Flocc:Nama]] ===")) return null;
    const language = codes.resolve("ang") orelse return null;
    return if (std.mem.eql(u8, language.code, "ang")) language else null;
}

// Raw AN pages retain ordinary L2 support headings while the captured
// language templates expand to L1 banners. Preserve those support bytes in
// their explicit raw-marker region, but only after every rendered region
// independently agrees with exactly one canonical hyphen marker.
fn coalesceCorroboratedAnRawRegions(codes: LanguageCodes, raw: []const u8, sections: *std.ArrayList(language_source.Section), rendered: []const language_source.Section) void {
    const namespaces = codes.namespace_catalog orelse return;
    if (!std.mem.eql(u8, namespaces.content_language, "an") or sections.items.len == rendered.len) return;
    var count: usize = 0;
    for (sections.items) |section| {
        if (!section.hyphen_marker) {
            if (count == 0 or hasExplicitLanguageDeclaration(codes, section) or resolveSection(codes, section) != null) return;
            continue;
        }
        if (count >= rendered.len) return;
        const owner = codes.resolve(section.heading) orelse return;
        if (!std.mem.eql(u8, owner.code, section.heading)) return;
        const exact_banner = corroboratedAnHyphenMarker(codes, section, rendered[count]);
        const other = boundaryLanguage(codes, rendered[count]);
        if (!exact_banner and (other == null or !std.mem.eql(u8, owner.code, other.?.code))) return;
        count += 1;
    }
    if (count != rendered.len or count == 0) return;
    var written: usize = 0;
    for (sections.items) |section| {
        if (section.hyphen_marker) {
            sections.items[written] = section;
            written += 1;
        } else {
            const previous = &sections.items[written - 1];
            const start = @intFromPtr(previous.source.ptr) - @intFromPtr(raw.ptr);
            const end = @intFromPtr(section.source.ptr) - @intFromPtr(raw.ptr) + section.source.len;
            previous.source = raw[start..end];
        }
    }
    sections.items.len = written;
}

// Missing template output proves a boundary, never the language of its body.
// Keep the original visible link and all subsequent source in that region.
fn missingEqualsCode(codes: LanguageCodes, source: []const u8) ?[]const u8 {
    const ns = codes.namespace_catalog orelse return null;
    if (!std.mem.startsWith(u8, source, "[[") or !std.mem.endsWith(u8, source, "]]")) return null;
    const pair = blobs.wikitext_syntax.balanced(source, 0) orelse return null;
    if (pair.end != source.len) return null;
    var it: blobs.document_ir.InlineIterator = .{ .input = source, .link_trail = codes.link_trail };
    const link = it.next() orelse return null;
    if (link.kind != .link or link.link_has_pipe or link.trail.len != 0 or it.cursor != source.len) return null;
    const target = if (std.mem.startsWith(u8, link.target, ":")) link.target[1..] else link.target;
    const title = ns.ofTitle(target);
    if (title.id != 10 or title.text.len < 3 or title.text[0] != '=' or title.text[title.text.len - 1] != '=') return null;
    const code = title.text[1 .. title.text.len - 1];
    const owner = codes.resolve(code) orelse return null;
    if (!std.mem.eql(u8, code, owner.code)) return null;
    return code;
}

fn exactRawEqualsCode(section: language_source.Section) ?[]const u8 {
    if (section.hyphen_marker) return null;
    const line = section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len];
    const code = language_source.equalsLanguageDeclaration(line) orelse return null;
    if (!std.mem.eql(u8, section.heading, code) or !std.mem.startsWith(u8, line, "{{=") or
        (!std.mem.endsWith(u8, line, "=}}") and !std.mem.endsWith(u8, line, "=|}}"))) return null;
    const suffix: usize = if (std.mem.endsWith(u8, line, "=|}}")) 4 else 3;
    if (line.len != code.len + 3 + suffix or !std.mem.eql(u8, line[3 .. line.len - suffix], code)) return null;
    return code;
}

// A missing-range mismatch must not turn the known first heading into authority
// for every later raw declaration. This predicate only fences ownership.
fn missingEqualsPartitionCandidate(codes: LanguageCodes, raw: []const language_source.Section, source: []const u8) bool {
    if (raw.len < 2 or raw.len > 64 or source.len > 1024 * 1024) return false;
    var lines = std.mem.splitScalar(u8, source, '\n');
    while (lines.next()) |line| {
        const code = missingEqualsCode(codes, line) orelse continue;
        const at = @intFromPtr(line.ptr) - @intFromPtr(source.ptr);
        if (!prefixEvidenceOutside(source, at)) continue;
        for (raw) |section| if (exactRawEqualsCode(section)) |authored| {
            if (std.mem.eql(u8, code, authored)) return true;
        };
    }
    return false;
}

// Return a replacement partition only after every original declaration pairs
// with either a clean real H2 or a complete, tracked missing-template link.
// Empty heading is a private grouping sentinel for the latter; no heading is
// inserted into the compiled body, and no missing code becomes an owner.
fn missingEqualsPartitionAlloc(a: std.mem.Allocator, codes: LanguageCodes, original: []const u8,
    source: MissingText, phase: ?*const missing_dependency.Phase, raw: []const language_source.Section,
    rendered: []const language_source.Section) std.mem.Allocator.Error!?[]language_source.Section
{
    if (raw.len < 2 or raw.len > 64 or rendered.len == 0 or rendered.len >= raw.len or
        source.bytes.len > 1024 * 1024 or source.unknown or source.lost_missing_range or source.generated_links.len != 0 or source.literal_curly_ranges.len != 0) return null;
    const provenance = phase orelse return null;
    const ns = codes.namespace_catalog orelse return null;
    const occurrences = provenance.occurrences();
    if (source.ranges.len == 0 or source.ranges.len > 64) return null;
    var starts: [64]usize = undefined;
    var values: [64]language_source.Section = undefined;
    var count: usize = 0;
    var previous: usize = 0;
    for (rendered, 0..) |section, i| {
        const at = SourceHeadword.offset(source.bytes, section.source) orelse return null;
        if ((i != 0 and at <= previous) or section.heading.len == 0 or section.hyphen_marker) return null;
        const line = section.source[0 .. std.mem.indexOfScalar(u8, section.source, '\n') orelse section.source.len];
        const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
        if (heading.level != 2 or !std.mem.eql(u8, heading.title, section.heading) or
            !sourceCategoryHeaderRangesClean(source, section) or !prefixEvidenceOutside(source.bytes, at)) return null;
        starts[count] = at; values[count] = section; count += 1; previous = at;
    }
    var missing_count: usize = 0;
    previous = 0;
    for (source.ranges) |range| {
        if (range.start < previous or range.start >= range.end or range.end > source.bytes.len or
            range.occurrence == 0 or range.occurrence > occurrences.len) return null;
        previous = range.end;
        const slice = source.bytes[range.start..range.end];
        const code = missingEqualsCode(codes, slice) orelse continue;
        const title = ns.ofTitle(occurrences[range.occurrence - 1].title);
        if (title.id != 10 or title.text.len != code.len + 2 or title.text[0] != '=' or
            title.text[title.text.len - 1] != '=' or !std.mem.eql(u8, title.text[1 .. title.text.len - 1], code) or
            (range.start != 0 and source.bytes[range.start - 1] != '\n') or
            (range.end != source.bytes.len and source.bytes[range.end] != '\n') or
            !prefixEvidenceOutside(source.bytes, range.start) or count == starts.len) return null;
        var at: usize = 0;
        while (at < count and starts[at] < range.start) : (at += 1) {}
        if (at < count and starts[at] == range.start) return null;
        var shift = count;
        while (shift > at) : (shift -= 1) { starts[shift] = starts[shift - 1]; values[shift] = values[shift - 1]; }
        starts[at] = range.start; values[at] = .{ .heading = "", .source = slice }; count += 1; missing_count += 1;
    }
    if (missing_count == 0 or count != raw.len or
        std.mem.trim(u8, source.bytes[0..starts[0]], " \t\r\n").len != 0) return null;
    var raw_cursor: usize = 0;
    for (raw, 0..) |authored, i| {
        if (authored.source.len == 0 or authored.source.len > original.len - raw_cursor or
            @intFromPtr(authored.source.ptr) != @intFromPtr(original.ptr) + raw_cursor or !prefixEvidenceOutside(original, raw_cursor)) return null;
        raw_cursor += authored.source.len;
        const code = exactRawEqualsCode(authored) orelse return null;
        const end = if (i + 1 < count) starts[i + 1] else source.bytes.len;
        if (end <= starts[i]) return null;
        if (values[i].heading.len == 0) {
            const missing_code = missingEqualsCode(codes, values[i].source) orelse return null;
            if (!std.mem.eql(u8, code, missing_code)) return null;
        } else {
            const owner = boundaryLanguage(codes, values[i]) orelse return null;
            if (!std.mem.eql(u8, owner.code, code) or codes.isLanguageBoundary(code)) return null;
        }
        values[i].source = source.bytes[starts[i]..end];
    }
    if (raw_cursor != original.len) return null;
    return try a.dupe(language_source.Section, values[0..count]);
}

fn prefixEvidenceOutside(source: []const u8, offset: usize) bool {
    if (offset > source.len or !language_source.outsideNestedOrOpaque(source, offset)) return false;
    var context = language_source.Iterator.init(source[0..offset]);
    while (context.next() != null) {}
    if (context.balance.tables != 0) return false;
    // The source iterator tracks wiki tables. Ordinary HTML table bodies also
    // remain local; reuse tag matching rather than treating their text as root.
    const syntax = blobs.wikitext_syntax;
    var at: usize = 0;
    while (at < offset) {
        if (syntax.protectedEnd(source, at)) |end| {
            if (end > offset) return false;
            at = end;
            continue;
        }
        if (std.mem.startsWith(u8, source[at..], "{{") or std.mem.startsWith(u8, source[at..], "[[")) {
            const pair = syntax.balanced(source, at) orelse return false;
            if (pair.end > offset) return false;
            at = pair.end;
            continue;
        }
        if (source[at] == '<') if (syntax.tagAt(source, at)) |tag| {
            if (!tag.closing and !tag.self_closing and (tag.is("table") or tag.is("nowiki") or tag.is("pre") or tag.isOpaque())) {
                const pair = syntax.matchingTag(source, tag) orelse return false;
                if (pair.end > offset) return false;
                at = pair.end;
            } else at = tag.end;
            continue;
        };
        at += 1;
    }
    return true;
}

fn wholeMissingMarkerLink(codes: LanguageCodes, source: []const u8, code: []const u8) bool {
    const namespaces = codes.namespace_catalog orelse return false;
    if (!std.mem.startsWith(u8, source, "[[") or !std.mem.endsWith(u8, source, "]]")) return false;
    const pair = blobs.wikitext_syntax.balanced(source, 0) orelse return false;
    if (pair.end != source.len) return false;
    var links: blobs.document_ir.InlineIterator = .{ .input = source, .link_trail = codes.link_trail };
    const link = links.next() orelse return false;
    if (link.kind != .link or link.link_has_pipe or link.trail.len != 0 or links.cursor != source.len) return false;
    var target = link.target;
    if (std.mem.startsWith(u8, target, ":")) target = target[1..];
    const title = namespaces.ofTitle(target);
    return title.id == 10 and title.text.len == code.len + 2 and title.text[0] == '-' and
        title.text[title.text.len - 1] == '-' and std.mem.eql(u8, title.text[1 .. title.text.len - 1], code);
}

fn prefixHasMissingMarkerLink(codes: LanguageCodes, prefix: []const u8, code: []const u8) bool {
    var lines = std.mem.splitScalar(u8, prefix, '\n');
    while (lines.next()) |raw| {
        const line = std.mem.trim(u8, raw, " \t\r");
        if (!wholeMissingMarkerLink(codes, line, code)) continue;
        const offset = @intFromPtr(line.ptr) - @intFromPtr(prefix.ptr);
        if (prefixEvidenceOutside(prefix, offset)) return true;
    }
    return false;
}

fn missingForeignLanguagePrefix(codes: LanguageCodes, source: MissingText, prefix_len: usize, phase: ?*const missing_dependency.Phase, raw_prefix: []const u8, owner_code: []const u8) bool {
    const namespaces = codes.namespace_catalog orelse return false;
    if (prefix_len > source.bytes.len or raw_prefix.len == 0) return false;
    const markers: LanguageMarkers = .{ .codes = &codes };
    var sections = languageSections(raw_prefix, &markers);
    while (sections.next()) |section| {
        if (!section.hyphen_marker) continue;
        const language = codes.resolve(section.heading) orelse continue;
        const code = language.code;
        if (!std.mem.eql(u8, section.heading, code) or std.mem.eql(u8, code, owner_code)) continue;
        const raw_offset = @intFromPtr(section.source.ptr) - @intFromPtr(raw_prefix.ptr);
        if (!prefixEvidenceOutside(raw_prefix, raw_offset)) continue;
        if (!source.unknown) if (phase) |provenance| {
            const occurrences = provenance.occurrences();
            for (source.ranges) |range| {
                if (range.start >= range.end or range.end > prefix_len or range.end > source.bytes.len or
                    range.occurrence == 0 or range.occurrence > occurrences.len) continue;
                const title = namespaces.ofTitle(occurrences[range.occurrence - 1].title);
                if (title.id != 10 or title.text.len != code.len + 2 or title.text[0] != '-' or
                    title.text[title.text.len - 1] != '-' or !std.mem.eql(u8, title.text[1 .. title.text.len - 1], code)) continue;
                if (wholeMissingMarkerLink(codes, source.bytes[range.start..range.end], code) and
                    prefixEvidenceOutside(source.bytes, range.start)) return true;
            }
        };
        // Optional provenance can be absent or incomplete. Only the same exact
        // standalone missing-template link in this expanded prefix corroborates
        // refusal then. Neither raw markers alone nor matching links elsewhere
        // assign an owner; the existing unowned-prefix path retains these bytes.
        if ((phase == null or source.unknown) and prefixHasMissingMarkerLink(codes, source.bytes[0..prefix_len], code)) return true;
    }
    return false;
}

test "missing language prefix refusal requires active matching evidence in its exact domain" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var namespaces = try @import("namespace_registry").Registry.init(a, "# wikidict-namespace-registry-v1\n# wiki\tzawiktionary\n# dump-date\t20261001\n# content-language\tza\n" ++
        "0\t\t\tfirst-letter\t0\t1\t0\twikitext\tmain\tentries\n" ++
        "10\t模板\tTemplate\tfirst-letter\t1\t0\t0\twikitext\tcompile_only\ttemplates\n" ++
        "14\t分类\tCategory\tfirst-letter\t1\t0\t0\twikitext\tcompile_only\tcategories\n");
    defer namespaces.deinit();
    const Local = struct {
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            for ([_][2][]const u8{ .{ "es", "Spanish" }, .{ "pt", "Portuguese" }, .{ "en", "English" }, .{ "adj", "Adioukrou" } }) |row|
                if (std.mem.eql(u8, value, row[0])) return .{ .code = row[0], .heading = row[1] };
            if (std.mem.eql(u8, value, "por")) return .{ .code = "pt", .heading = "Portuguese" };
            return null;
        }
    };
    const codes: LanguageCodes = .{ .namespace_catalog = &namespaces, .resolve_fn = Local.resolve };
    const raw_prefix = "{{-pt-}}\n# prefix\n";
    const link = "[[:模板:-pt-]]";
    const prefix = link ++ "\n# prefix\n";
    const source = prefix ++ "==Spanish==\n# later\n";
    const occurrences = [_]missing_dependency.Occurrence{.{ .id = 1, .title = "模板:-pt-" }};
    const ranges = [_]missing_dependency.Range{.{ .start = 0, .end = link.len, .occurrence = 1 }};
    const encoded = try missing_dependency.encode(a, .{ .bytes = source, .ranges = &ranges }, MissingText.untracked(""), &occurrences);
    var phase = try missing_dependency.decode(a, encoded, source, "");
    defer phase.deinit();
    try std.testing.expect(missingForeignLanguagePrefix(codes, phase.output(), prefix.len, &phase, raw_prefix, "es"));
    try std.testing.expect(missingForeignLanguagePrefix(codes, MissingText.untracked(source), prefix.len, null, raw_prefix, "es"));
    try std.testing.expect(missingForeignLanguagePrefix(codes, MissingText.transformed(source), prefix.len, &phase, raw_prefix, "es"));
    // Complete provenance with no matching occurrence proves this is authored
    // text. The optional-provenance fallback cannot override that evidence.
    const known_encoded = try missing_dependency.encode(a, MissingText.untracked(source), MissingText.untracked(""), &.{});
    var known = try missing_dependency.decode(a, known_encoded, source, "");
    defer known.deinit();
    try std.testing.expect(!missingForeignLanguagePrefix(codes, known.output(), prefix.len, &known, raw_prefix, "es"));
    const unknown_encoded = try missing_dependency.encode(a, MissingText.transformed(source), MissingText.transformed(""), &.{});
    var unknown = try missing_dependency.decode(a, unknown_encoded, source, "");
    defer unknown.deinit();
    try std.testing.expect(missingForeignLanguagePrefix(codes, unknown.output(), prefix.len, &unknown, raw_prefix, "es"));
    const invalid_ranges = [_]missing_dependency.Range{
        .{ .start = 0, .end = 1, .occurrence = 1 },
        .{ .start = 0, .end = prefix.len + 1, .occurrence = 1 },
        .{ .start = 0, .end = source.len + 1, .occurrence = 1 },
        .{ .start = 0, .end = link.len, .occurrence = 2 },
    };
    for (invalid_ranges) |range| {
        const one = [_]missing_dependency.Range{range};
        try std.testing.expect(!missingForeignLanguagePrefix(codes, .{ .bytes = source, .ranges = &one }, prefix.len, &phase, raw_prefix, "es"));
    }
    const cases = [_]struct { expanded: []const u8, raw: []const u8 = raw_prefix }{
        .{ .expanded = "[[:模板:-es-]]\n", .raw = "{{-es-}}\n" },
        .{ .expanded = "[[:模板:-en-]]\n" },
        .{ .expanded = "[[:Category:-pt-]]\n" },
        .{ .expanded = "[[:模板:pt]]\n" },
        .{ .expanded = "[[:模板:ordinary]]\n", .raw = "{{ordinary}}\n" },
        .{ .expanded = "[[:模板:-por-]]\n", .raw = "{{-por-}}\n" },
        .{ .expanded = "[[:模板:-pt-|label]]\n" },
        .{ .expanded = "[[:模板:-pt-]]trail\n" },
        .{ .expanded = "inline [[:模板:-pt-]]\n" },
        .{ .expanded = "<!--\n[[:模板:-pt-]]\n-->\n" },
        .{ .expanded = "<nowiki>\n[[:模板:-pt-]]\n</nowiki>\n" },
        .{ .expanded = "<pre>\n[[:模板:-pt-]]\n</pre>\n" },
        .{ .expanded = "<nowiki>\n[[:模板:-pt-]]\n" },
        .{ .expanded = "{|\n|\n[[:模板:-pt-]]\n|}\n" },
        .{ .expanded = "<table><tr><td>\n[[:模板:-pt-]]\n</td></tr></table>\n" },
        .{ .expanded = prefix, .raw = "inline {{-pt-}}\n" },
        .{ .expanded = prefix, .raw = "<!--\n{{-pt-}}\n-->\n" },
        .{ .expanded = prefix, .raw = "<nowiki>\n{{-pt-}}\n</nowiki>\n" },
        .{ .expanded = prefix, .raw = "<pre>\n{{-pt-}}\n</pre>\n" },
        .{ .expanded = prefix, .raw = "{|\n|\n{{-pt-}}\n|}\n" },
        .{ .expanded = prefix, .raw = "<table><tr><td>\n{{-pt-}}\n</td></tr></table>\n" },
        .{ .expanded = "# preserved POS context\n", .raw = "{{-adj-}}\n" },
        .{ .expanded = "# preserved raw marker context\n" },
    };
    for (cases) |row|
        try std.testing.expect(!missingForeignLanguagePrefix(codes, MissingText.untracked(row.expanded), row.expanded.len, null, row.raw, "es"));
    // A matching link after the first admitted language is not prefix evidence.
    const outside = "# prefix\n==Spanish==\n" ++ link;
    try std.testing.expect(!missingForeignLanguagePrefix(codes, MissingText.untracked(outside), "# prefix\n".len, null, raw_prefix, "es"));
}

// A prepared page owns encoded records in its caller's page arena. The only
// shared effects remain in Writer.commitPreparedPrefix/finishPrepared. Keeping
// the stats at each append boundary preserves partial-page failure semantics.
pub const PreparedPage = struct {
    pub const Record = struct {
        kind: blob_format.BlobKind,
        key: []const u8,
        title: []const u8,
        payload: []const u8,
        stats_before: BuildStats,
        language_code: []const u8 = "",
    };
    records: std.ArrayList(Record) = .empty,
    stats: BuildStats = .{},
    fallbacks: presentation_document.Fallbacks = .{},
    ns: PageNamespace,
    title: []const u8,
    extra_reasons: []const []const u8 = &.{},
    alias: bool = false,

    pub fn compileWithPhases(self: *PreparedPage, a: std.mem.Allocator, codes: LanguageCodes, source: []const u8, raw_source: []const u8, display_title: ?[]const u8, poem_metadata: ?[]const u8, missing_metadata: ?[]const u8, alias_record: ?blobs.alias_codec.Record) !void {
        return self.compileWithPhasesAndRoot(a, codes, source, raw_source, display_title, poem_metadata, missing_metadata, alias_record, .unknown);
    }

    // Only a caller holding the complete expansion may supply parser_output.
    pub fn compileWithPhasesAndRoot(self: *PreparedPage, a: std.mem.Allocator, codes: LanguageCodes, source: []const u8, raw_source: []const u8, display_title: ?[]const u8, poem_metadata: ?[]const u8, missing_metadata: ?[]const u8, alias_record: ?blobs.alias_codec.Record, content_root: @import("presentation_compile.zig").ContentRoot) !void {
        var phase_arena = std.heap.ArenaAllocator.init(a);
        defer phase_arena.deinit();
        const poem = try presentation_document.parsePoemPhaseAlloc(phase_arena.allocator(), source, display_title, poem_metadata);
        var missing: ?missing_dependency.Phase = if (missing_metadata) |bytes| try missing_dependency.decode(phase_arena.allocator(), bytes, source, display_title orelse "") else null;
        defer if (missing) |*phase| phase.deinit();
        const phase: ?*const missing_dependency.Phase = if (missing) |*value| value else null;
        if (phase) |value| if (value.occurrences().len != 0) {
            self.fallbacks.missing_template = true;
        };
        const output: PageOutput = .{ .prepared = self };
        if (alias_record) |record| {
            self.alias = true;
            self.ns = .{ .id = record.source_namespace, .kind = record.source_kind };
            self.title = record.source_title;
            const encoded = try compileAliasWithRoot(a, codes, record, source, display_title, &self.fallbacks, poem, phase, content_root);
            try output.append(a, .alias, "", encoded.key, encoded.payload);
            self.stats.alias_records += 1;
            if (record.source_namespace == 0) self.stats.main_pages += 1;
        } else if (self.ns.kind == .language) {
            try processMain(a, output, codes, self.title, source, raw_source, display_title, &self.stats, &self.fallbacks, poem, phase);
        } else {
            try processNamespace(a, output, codes.link_trail, codes.namespace_catalog, codes.behavior_switches, codes.image_options, codes.table_styles, codes.figure_sizing, codes.local_link_targets, self.ns, self.title, source, display_title, &self.stats, &self.fallbacks, poem, phase);
        }
    }
};

const PageOutput = union(enum) {
    direct: *Spools,
    prepared: *PreparedPage,

    fn appendLanguage(self: PageOutput, a: std.mem.Allocator, owner: ResolvedLanguage, title: []const u8, payload: []const u8) !void {
        return self.appendWithCode(a, .language, owner.heading, title, payload, owner.code);
    }
    fn append(self: PageOutput, a: std.mem.Allocator, kind: blob_format.BlobKind, key: []const u8, title: []const u8, payload: []const u8) !void {
        return self.appendWithCode(a, kind, key, title, payload, "");
    }
    fn appendWithCode(self: PageOutput, a: std.mem.Allocator, kind: blob_format.BlobKind, key: []const u8, title: []const u8, payload: []const u8, language_code: []const u8) !void {
        switch (self) {
            .prepared => |page| {
                // Owner headings may belong to a nested proof arena which is
                // destroyed before commit. Encoded payloads already use a.
                const owned_key = try a.dupe(u8, key);
                errdefer a.free(owned_key);
                const owned_title = try a.dupe(u8, title);
                errdefer a.free(owned_title);
                const owned_code = try a.dupe(u8, language_code);
                errdefer a.free(owned_code);
                try page.records.append(a, .{ .kind = kind, .key = owned_key, .title = owned_title, .payload = payload, .stats_before = page.stats, .language_code = owned_code });
            },
            .direct => |spools| switch (kind) {
                .language => try spools.appendLanguage(a, .{ .heading = key, .code = language_code }, title, payload),
                .thesaurus => try spools.thesaurus.append(spools.io, a, key, title, payload),
                .citations => try spools.citations.append(spools.io, a, key, title, payload),
                .reconstruction => try spools.reconstruction.append(spools.io, a, key, title, payload),
                .rhymes => try spools.rhymes.append(spools.io, a, key, title, payload),
                .sign_gloss => try spools.sign_gloss.append(spools.io, a, key, title, payload),
                .supplemental => try spools.supplemental.append(spools.io, a, key, title, payload),
                .alias => try spools.aliases.append(spools.io, a, key, title, payload),
            },
        }
    }
};

fn addPreparedStats(total: *BuildStats, before: BuildStats, after: BuildStats) void {
    inline for (@typeInfo(BuildStats).@"struct".field_names) |field|
        @field(total, field) += @field(after, field) - @field(before, field);
}

// Takes ownership of the projection on failure. Successful callers retain
// ownership alongside the prepared source for the rest of the page.
fn checkedWriterNumbering(a: std.mem.Allocator, numbered: @import("presentation_compile.zig").PreparedExternalLinks,
    fallbacks: *presentation_document.Fallbacks) error{RenderLimit}!@import("presentation_compile.zig").PreparedExternalLinks
{
    errdefer if (numbered.source_element_projection) |proof| a.free(proof.copies);
    fallbacks.merge(numbered.fallbacks);
    if (numbered.fallbacks.render_limit) return error.RenderLimit;
    return numbered;
}

fn processMain(
    page_allocator: std.mem.Allocator,
    spools: PageOutput,
    codes: LanguageCodes,
    title: []const u8,
    source_raw: []const u8,
    raw_source: ?[]const u8,
    display_title: ?[]const u8,
    stats: *BuildStats,
    fallbacks: *presentation_document.Fallbacks,
    raw_poem_phase: ?*const presentation_document.PoemPhase,
    missing_phase: ?*const missing_dependency.Phase,
) !void {
    const organization_phase = consume_diagnostics.beginConsumePhase(.organization);
    defer consume_diagnostics.endConsumePhase(organization_phase);
    const raw_missing = if (missing_phase) |phase| phase.output() else MissingText.untracked(source_raw);
    // Normal native pages have no URL/user/header or custom variant override.
    // Select the pinned core defaults explicitly; body fallback stays separate.
    const title_defaults = if (display_title == null and std.mem.indexOf(u8, source_raw, "-{T|") != null)
        @import("presentation_compile.zig").normalTitleDefaults(title, codes.namespace_catalog, .{
            .namespace_id = 0, .requested_variant = null, .configured_default_variant = null, .disable_title_conversion = false })
    else null;
    const title_precedence = if (std.mem.indexOf(u8, source_raw, "-{T|") != null)
        try presentation_document.displayTitlePrecedenceAlloc(page_allocator, title,
            if (display_title) |value| .{ .source = value, .page_title = title, .missing = if (missing_phase) |phase| phase.displayTitle() else null } else null,
            codes.link_trail, codes.namespace_catalog, codes.behavior_switches, codes.image_options, raw_poem_phase)
    else null;
    const local_targets_selected = if (codes.local_link_targets) |target|
        target.source.ptr == raw_missing.bytes.ptr and target.source.len == raw_missing.bytes.len else false;
    const numbered = try checkedWriterNumbering(page_allocator, try presentation_document.preparePageExternalLinksWithMissingAlloc(page_allocator, raw_missing, .{
        .title = title,
        .observe_source_elements = observeSourceElements(codes.figure_sizing, raw_missing.bytes) or
            local_targets_selected,
        .local_link_targets = codes.local_link_targets,
        .display_title_precedence = title_precedence,
        .normal_title_defaults = title_defaults,
        .link_trail = codes.link_trail,
        .namespace_catalog = codes.namespace_catalog,
        .behavior_switches = codes.behavior_switches,
        .image_options = codes.image_options,
        .figure_sizing = codes.figure_sizing,
        .poem_phase = raw_poem_phase,
    }), fallbacks);
    defer if (numbered.source_element_projection) |proof| page_allocator.free(proof.copies);
    const poem_phase = numbered.poem_phase;
    // MediaWiki's first body TOC is page-scoped, before language-owner regrouping.
    const may_cross_pre = preCandidate(numbered.source) or presentation_document.mayHaveFormattingScopes(numbered.source);
    const may_cross_link = presentation_document.mayHaveMultilineLinks(numbered.source);
    const body_source: presentation_document.PreparedBodySource = if (may_cross_pre or may_cross_link)
        try presentation_document.prepareBodySourceInContextWithMissingAlloc(page_allocator, numbered.missing, .{
            .title = title, .link_trail = codes.link_trail, .namespace_catalog = codes.namespace_catalog,
            .behavior_switches = codes.behavior_switches, .image_options = codes.image_options,
            .local_link_targets = codes.local_link_targets, .content_conversion = numbered.content_conversion,
            .citations = numbered.citations, .external_links_prepared = true,
            .poem_phase = poem_phase,
            .normal_title_defaults = title_defaults, .display_title_precedence = title_precedence,
        }, if (numbered.source_element_projection) |*proof| proof else null)
    else
        .{ .source = numbered.source, .missing = numbered.missing, .fallbacks = .{} };
    defer if (body_source.source.ptr != numbered.source.ptr) page_allocator.free(body_source.source);
    fallbacks.merge(body_source.fallbacks);
    const source_missing = try presentation_document.preparePageTocSourceWithMissingAlloc(page_allocator, body_source.missing orelse MissingText.transformedFrom(numbered.missing, body_source.source), codes.behavior_switches);
    const source = source_missing.bytes;
    defer if (source.ptr != body_source.source.ptr) page_allocator.free(source);
    // Only this complete final native page may issue a source class inventory.
    // Language-owner concatenation and Renderer fragment APIs cannot do so.
    const native_source_class_proof = if (codes.table_styles) |profile|
        try presentation_document.nativeSourceClassProofAlloc(page_allocator, source_missing, profile) else null;
    defer if (native_source_class_proof) |proof| proof.deinit(page_allocator);
    stats.main_pages += 1;

    if (fallbacks.expansion_error and source.len == 0) {
        // Failed expansion provides no language evidence. Keep the title and
        // diagnostic in the existing unverified bucket, never the edition owner.
        const language: ResolvedLanguage = .{ .code = "", .heading = "Unclassified" };
        const payload = try presentation_document.compileReportedWithOptionsAndPhasesAndTableStylesAlloc(
            page_allocator,
            title,
            .language,
            language.heading,
            language.code,
            MissingText.untracked(""),
            null,
            codes.link_trail,
            codes.namespace_catalog,
            codes.behavior_switches,
            codes.image_options,
            fallbacks,
            poem_phase,
            codes.table_styles,
        );
        try spools.appendLanguage(page_allocator, language, title, payload);
        stats.language_records += 1;
        return;
    }

    // Resolvers may return the supplied heading slice. Keep projections alive
    // through grouping/encoding, including failure paths with a non-arena caller.
    var owned_headings: std.ArrayList([]u8) = .empty;
    defer {
        for (owned_headings.items) |heading| page_allocator.free(heading);
        owned_headings.deinit(page_allocator);
    }
    var page_sections: std.ArrayList(language_source.Section) = .empty;
    defer page_sections.deinit(page_allocator);
    var reference_context = try presentation_document.referenceDefinitionsWithMissingAlloc(page_allocator, source_missing);
    reference_context.local_link_targets = codes.local_link_targets;
    if (body_source.body_link_continuations) |continuations| {
        if (source.ptr != continuations.source.bytes.ptr or source.len != continuations.source.bytes.len)
            return error.InvalidPreContext;
        reference_context.body_link_continuations = continuations;
    }
    reference_context.citations = numbered.citations;
    reference_context.content_conversion = numbered.content_conversion;
    reference_context.display_title_precedence = title_precedence;
    reference_context.normal_title_defaults = title_defaults;
    // Only possible HTML owners need this existing observation before splitting.
    // Other pages retain its original late position and raw-conflict early exit.
    // The precheck supplies no admission: only actual renderer scopes do that.
    var heading_arena = std.heap.ArenaAllocator.init(page_allocator);
    defer heading_arena.deinit();
    var early_heading_observation: ?presentation_document.HeadingObservation = if (language_source.mayHaveLanguageHtmlHeading(source, codes.namespace_catalog))
        try presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(
        heading_arena.allocator(),
        title,
        source_missing,
        codes.link_trail,
        codes.namespace_catalog,
        codes.behavior_switches,
        codes.image_options,
        reference_context,
        poem_phase,
        codes.source_equals_fn != null or codes.source_nom_label_fn != null or codes.source_section_fn != null or codes.source_linked_heading_fn != null or codes.source_headword_fn != null or codes.figure_sizing != null or codes.table_styles != null or local_targets_selected,
    )
    else
        null;

    // Ordinary navigation admission is established by the actual renderer,
    // before ownership cuts. The same raw-domain map later carries rendering.
    const early_observation: presentation_document.PreObservation = if (may_cross_link)
        try presentation_document.observePreScopesWithSelectedPageAndMissingAlloc(page_allocator, title, source_missing, codes.link_trail, codes.namespace_catalog, codes.behavior_switches, codes.image_options, reference_context, poem_phase, codes.table_styles, codes.figure_sizing, if (numbered.source_element_projection) |*proof| proof else null)
    else
        .{ .scopes = &.{}, .unclosed_formatting = false };
    defer freePreObservation(page_allocator, early_observation);
    const expanded_link_openings = try linkOpeningsAlloc(page_allocator, early_observation.scopes, early_observation.refused_link_openings);
    defer page_allocator.free(expanded_link_openings);
    const expanded_markers: LanguageMarkers = .{ .codes = &codes, .raw_source = raw_source, .expanded_source = source, .expanded_missing = source_missing };
    var sections = languageSections(source, &expanded_markers);
    if (early_heading_observation) |observation| {
        if (observation.page_html_source) |observed_source|
            sections.html_headings = .{ .source = observed_source, .openings = observation.page_html_openings,
                .namespace_catalog = codes.namespace_catalog, .linked_h1_filter = sections.heading_filter,
                .category_h1_filter = .{ .ctx = &expanded_markers, .accepts = sourceCategoryH1Prefix } };
    }
    if (may_cross_link) sections.link_headings = .{ .source = source, .openings = expanded_link_openings };
    while (sections.next()) |section| try appendClassifiedSection(page_allocator, codes, &page_sections, &owned_headings, section);

    var raw_conflicts: RawTemplateCodeConflicts = .{};
    var raw_sections: std.ArrayList(language_source.Section) = .empty;
    defer raw_sections.deinit(page_allocator);
    if (raw_source) |raw| {
        var represented: std.ArrayList([]const u8) = .empty;
        defer represented.deinit(page_allocator);
        var named_boundaries = page_sections.items.len != 0;
        for (page_sections.items) |section| {
            const language = boundaryLanguage(codes, section) orelse {
                named_boundaries = false;
                break;
            };
            try represented.append(page_allocator, language.code);
        }
        // POS abbreviations can also be real ISO codes (adj is Adioukrou).
        // When every rendered boundary identifies a language, only its codes
        // may supply raw language boundaries. This follows the actual page,
        // without banning a code that another edition uses as a language.
        const raw_markers: LanguageMarkers = .{ .codes = &codes, .represented = if (named_boundaries) represented.items else null, .expanded_sections = page_sections.items };
        var raw_it = languageSections(raw, &raw_markers);
        var raw_observation: presentation_document.PreObservation = .{ .scopes = &.{}, .unclosed_formatting = false };
        defer freePreObservation(page_allocator, raw_observation);
        var raw_link_openings: []const usize = &.{};
        defer if (raw_link_openings.len != 0) page_allocator.free(raw_link_openings);
        if (presentation_document.mayHaveMultilineLinks(raw)) {
            const raw_prepared = try presentation_document.prepareBodySourceAlloc(page_allocator, title, raw);
            defer if (raw_prepared.source.ptr != raw.ptr) page_allocator.free(raw_prepared.source);
            const raw_toc = try presentation_document.preparePageTocSourceAlloc(page_allocator, raw_prepared.source, codes.behavior_switches);
            defer if (raw_toc.ptr != raw_prepared.source.ptr) page_allocator.free(raw_toc);
            // Authored raw text remains the corroboration authority. A changed
            // preparation domain cannot lend offsets to the original Iterator.
            if (std.mem.eql(u8, raw, raw_toc)) {
                const raw_references = try presentation_document.referenceDefinitionsAlloc(page_allocator, raw);
                raw_observation = try presentation_document.observePreScopesWithTextPaintAlloc(page_allocator, title, raw, codes.link_trail, codes.namespace_catalog, codes.behavior_switches, codes.image_options, raw_references, null, codes.table_styles);
                raw_link_openings = try linkOpeningsAlloc(page_allocator, raw_observation.scopes, raw_observation.refused_link_openings);
                raw_it.link_headings = .{ .source = raw, .openings = raw_link_openings };
            }
        }
        const conflict_iterator = raw_it;
        while (raw_it.next()) |section| try appendClassifiedSection(page_allocator, codes, &raw_sections, &owned_headings, section);
        raw_conflicts = rawTemplateCodeConflicts(codes, conflict_iterator, raw_sections.items);
    }
