    try std.testing.expect(resolveSection(codes, .{ .heading = "Ak", .source = "==Ak==\n* alphabetical index\n" }) == null);
    try std.testing.expectEqualStrings("en", resolveSection(codes, .{ .heading = "ቋንቋ", .source = "==ቋንቋ==\nእንግሊዝኛ\n" }).?.code);
