        .{ .title = "conflicting-edit", .raw = "{{-en-}}\n# kept\n", .expanded = try std.fmt.allocPrint(a, "=={s}==\n# kept\n", .{try TranslationWarningFixture.banner(a, "English", "fr")}) },
