test "Writer AY synonym ISO collision requires the captured lower level support shape" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/ay-synonym", .{tmp.sub_path});
    var codes = TestLanguages.codes();
    const SenayaLanguages = struct {
        fn resolve(ctx: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "syn") or std.mem.eql(u8, name, "Senaya")) return .{ .code = "syn", .heading = "Senaya" };
            return TestLanguages.resolve(ctx, name);
        }
        fn get(ctx: ?*const anyopaque, name: []const u8) ?[]const u8 {
            return if (resolve(ctx, name)) |language| language.code else null;
        }
    };
    codes.resolve_fn = SenayaLanguages.resolve;
    codes.get_fn = SenayaLanguages.get;
    codes.strong_fn = struct {
        fn strong(ctx: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "Senaya")) return .{ .code = "syn", .heading = "Senaya" };
            return TestLanguages.strong(ctx, name);
        }
    }.strong;
    codes.content_fn = struct {
        fn content(_: ?*const anyopaque) ?ResolvedLanguage { return .{ .code = "ay", .heading = "Aymar aru" }; }
    }.content;
    const F = AySynonymFixture;
    const expanded = F.banner ++ "\n" ++ F.noun ++ F.noun_body ++ F.synonym ++ F.synonym_body;
    const raw = F.raw;
    const with_trans = expanded ++ F.translations ++ "\n:* preserved translation control\n";
    const no_zero_width = try AssameseSupportFixture.replaced(a, expanded, "\u{200b}naka", "naka");
    const wrong_level = try AssameseSupportFixture.replaced(a, expanded, F.synonym, "==<big>[[aru masi|Aru masi]]\u{200b}naka</big>==\n");
    const comment = try AssameseSupportFixture.replaced(a, expanded, F.synonym, "<!--" ++ F.synonym ++ "-->\n");
    const protected = try AssameseSupportFixture.replaced(a, expanded, F.synonym, "<nowiki>" ++ F.synonym ++ "</nowiki>\n");
    const cases = [_]struct { title: []const u8, source: []const u8, raw: []const u8, owner: []const u8, code: []const u8 }{
        .{ .title = "achachi excerpt", .source = expanded, .raw = raw, .owner = "Aymar aru", .code = "ay" },
        .{ .title = "synonym with translation support", .source = with_trans, .raw = raw ++ "{{-trans-}}\n:* preserved translation control\n", .owner = "Aymar aru", .code = "ay" },
        .{ .title = "synonym without ay declaration", .source = expanded, .raw = F.raw_without_ay, .owner = "Unclassified", .code = "" },
        .{ .title = "synonym changed title", .source = no_zero_width, .raw = raw, .owner = "Unclassified", .code = "" },
        .{ .title = "synonym changed depth", .source = wrong_level, .raw = raw, .owner = "Unclassified", .code = "" },
        .{ .title = "synonym comment only", .source = comment, .raw = raw, .owner = "Unclassified", .code = "" },
        .{ .title = "synonym protected only", .source = protected, .raw = raw, .owner = "Unclassified", .code = "" },
        .{ .title = "synonym extra support", .source = expanded ++ "===Unproven support===\n# kept\n", .raw = raw, .owner = "Unclassified", .code = "" },
        .{ .title = "foreign Senaya", .source = "==Senaya==\n# [[Foreign|retained foreign meaning]]\n", .raw = "{{-syn-}}\n# [[Foreign|retained foreign meaning]]\n", .owner = "Senaya", .code = "syn" },
    };
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    for (cases) |case| try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, case.title, case.source, case.raw, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(cases.len, stats.language_records);
    try std.testing.expectEqual(@as(usize, 3), stats.language_blobs);
    for (cases) |case| {
        var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, case.owner));
        defer mapped.deinit();
        const blob = try blob_format.inspect(mapped.bytes);
        var index = try blob.buildTrustedIndexAlloc(a);
        defer index.deinit(a);
        const record = (try index.find(case.title)).?;
        const decoded = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
        try std.testing.expectEqualStrings(case.code, decoded.entry.language_code);
        var report: presentation_document.Fallbacks = .{};
        const expected_payload = try presentation_document.compileReportedAlloc(a, case.title, .language, case.owner, case.code, case.source, null, &report);
        const expected = try blobs.presentation_codec.decodeAlloc(a, expected_payload, case.title, .language, .{ .code = case.code, .heading = case.owner });
        try std.testing.expectEqualDeep(expected.entry.sections, decoded.entry.sections);
        try std.testing.expectEqualDeep(expected.entry.references, decoded.entry.references);
        try std.testing.expectEqualDeep(expected.entry.media, decoded.entry.media);
    }
    // This change must not silently clear historical diagnostic carry.
    const diagnostics = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(a, &.{ root, "fallback-pages.jsonl" }), a, .limited(16384));
    var lines = std.mem.splitScalar(u8, diagnostics, '\n');
    var positive_seen = false;
    while (lines.next()) |line| {
        if (line.len == 0) continue;
        const parsed = try std.json.parseFromSlice(std.json.Value, a, line, .{});
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.object.get("title").?.string, "achachi excerpt")) continue;
        var missing = false;
        var unresolved = false;
        for (parsed.value.object.get("reasons").?.array.items) |reason| {
            if (std.mem.eql(u8, reason.string, "missing_language_heading")) missing = true;
            if (std.mem.eql(u8, reason.string, "unresolved_language_heading")) unresolved = true;
        }
        try std.testing.expect(missing and unresolved);
        positive_seen = true;
    }
    try std.testing.expect(positive_seen);
}


const LeadingRegionFixture = struct {
    const source = "== Frynkek ==\n=== Leveryans ===\n* IPA: /mɔ̃.taɲ/\n\n=== Hanow ===\n'''montagne''' ''benow'' (''liesplek'': '''[[montagnes]]''')\n# [[menydh]]\n\n== Italek ==\n=== Hanow ===\n'''montagne''' ''benow''\n# Liesplek '''[[montagna]]'''\n\n[[Klass:Frynkek]]\n[[Klass:Italek]]";
    fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
        if (std.mem.eql(u8, name, "Italek") or std.mem.eql(u8, name, "it")) return .{ .code = "it", .heading = "Italek" };
        return TestLanguages.resolve(null, name);
    }
    fn trusted(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
        if (std.mem.eql(u8, name, "Italek")) return .{ .code = "it", .heading = "Italek" };
        return TestLanguages.trusted(null, name);
    }
    fn get(ctx: ?*const anyopaque, name: []const u8) ?[]const u8 {
        return if (resolve(ctx, name)) |value| value.code else null;
    }
    fn catalog(a: std.mem.Allocator) !@import("namespace_registry").Registry {
        return @import("namespace_registry").Registry.init(a,
            "# wikidict-namespace-registry-v1\n# wiki\tkwwiktionary\n# dump-date\t20261001\n# content-language\tkw\n" ++
            "0\t\t\tcase-sensitive\t0\t1\t0\twikitext\tmain\tentries\n" ++
            "10\tSkantlyn\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\tScantlyn\n" ++
            "14\tKlass\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tcategories\n");
    }
    fn entry(a: std.mem.Allocator, root: []const u8, language: []const u8, title: []const u8) !?blobs.presentation_types.Entry {
        var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, language));
        defer mapped.deinit();
        // Decoded strings borrow the blob; retain its bytes in the test arena
        // before this helper releases the mapping.
        const retained_bytes = try a.dupe(u8, mapped.bytes);
        const blob = try blob_format.inspect(retained_bytes);
        var index = try blob.buildTrustedIndexAlloc(a);
        defer index.deinit(a);
        const record = (try index.find(title)) orelse return null;
        const stored = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
        try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, stored));
        return stored.entry;
    }
    fn contains(entry_value: blobs.presentation_types.Entry, text: []const u8) bool {
        for (entry_value.sections) |section| for (section.blocks) |block| for (block.spans) |span|
            if (std.mem.indexOf(u8, span.text, text) != null or std.mem.eql(u8, span.target, text)) return true;
        return false;
    }
};

test "Writer leading unresolved lexical region preserves full typed page regions and original anchors" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    var ns = try LeadingRegionFixture.catalog(a); defer ns.deinit();
    const codes: LanguageCodes = .{ .namespace_catalog = &ns, .get_fn = LeadingRegionFixture.get, .resolve_fn = LeadingRegionFixture.resolve, .strong_fn = LeadingRegionFixture.trusted, .trusted_fn = LeadingRegionFixture.trusted };
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/leading", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root); defer writer.deinit(); writer.language_codes = codes;
    // Exact KW p2238/r12404; this page has no authored fragment links.
    const source = LeadingRegionFixture.source;
    // Separate authored control: preserve cross-region targets and global IDs.
    const cross = "==Frynkek==\n===Hanow===\n# [[menydh]] [[#Hanow_2|later region]]\n==Italek==\n===Hanow===\n# [[montagna]] [[#Hanow|earlier region]]\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "montagne", source, source, null);
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "cross", cross, cross, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 4), stats.language_records);
    inline for (.{ .{ "montagne", source, @as(usize, 3) }, .{ "cross", cross, @as(usize, 2) } }) |row| {
        const unknown = (try LeadingRegionFixture.entry(a, root, "Unclassified", row[0])).?;
        const italian = (try LeadingRegionFixture.entry(a, root, "Italek", row[0])).?;
        try std.testing.expectEqualStrings("", unknown.language_code);
        try std.testing.expectEqualStrings("it", italian.language_code);
        // Compile the COMPLETE page to retain duplicate heading allocation.
        // Independently compiling either region would wrongly reset Hanow_2.
        const encoded = try presentation_document.compileReportedWithLinkTrailAlloc(a, row[0], .language, "Unclassified", "", row[1], null, .{}, &ns, null);
        const full = try blobs.presentation_codec.decodeAlloc(a, encoded, row[0], .language, .{ .code = "", .heading = "Unclassified" });
        try std.testing.expectEqualDeep(full.entry.sections[0..row[2]], unknown.sections);
        try std.testing.expectEqualDeep(full.entry.sections[row[2]..], italian.sections);
        try std.testing.expectEqualStrings("Hanow_2", italian.sections[1].anchor);
        try std.testing.expect(LeadingRegionFixture.contains(unknown, "menydh"));
        try std.testing.expect(!LeadingRegionFixture.contains(italian, "menydh"));
        try std.testing.expect(LeadingRegionFixture.contains(italian, "montagna"));
        try std.testing.expect(!LeadingRegionFixture.contains(unknown, "montagna"));
    }
    const actual = (try LeadingRegionFixture.entry(a, root, "Unclassified", "montagne")).?;
    try std.testing.expect(LeadingRegionFixture.contains(actual, "/mɔ̃.taɲ/"));
    var plural = false;
    for (actual.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
        if (std.mem.eql(u8, span.target, "montagnes")) { plural = true; try std.testing.expect(span.bold); }
    };
    try std.testing.expect(plural);
    const cross_unknown = (try LeadingRegionFixture.entry(a, root, "Unclassified", "cross")).?;
    const cross_known = (try LeadingRegionFixture.entry(a, root, "Italek", "cross")).?;
    // Full-page deep equality above also covers normalized fragment targets;
    // target spellings are not rewritten to compensate for regrouped owners.
    try std.testing.expect(LeadingRegionFixture.contains(cross_unknown, "later region"));
    try std.testing.expect(LeadingRegionFixture.contains(cross_known, "earlier region"));
}

test "Writer conservative leading lexical isolation preserves support and established owner policy" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const codes: LanguageCodes = .{ .get_fn = TestLanguages.get, .resolve_fn = TestLanguages.resolve, .strong_fn = TestLanguages.strong, .trusted_fn = TestLanguages.trusted };
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/controls", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root); defer writer.deinit(); writer.language_codes = codes;
    const tail = "==English==\n===Noun===\n# CURRENT\n";
    inline for (.{ "Etymology 2", "Noun", "Pronunciation 2", "Usage notes", "Alternative forms" }) |heading| {
        const text = "==" ++ heading ++ "==\n===Sense===\n# SUPPORT\n" ++ tail;
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, heading, text, text, null);
    }
    const ambiguous = "==Historical usage==\n===Noun===\n# PAST\n" ++ tail;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "ambiguous", ambiguous, ambiguous, null);
    const trailing = tail ++ "==Historical usage==\n===Noun===\n# TRAILING\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "trailing", trailing, trailing, null);
    const direct = "==Unknown topic==\n# DIRECT\n" ++ tail;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "direct", direct, direct, null);
    const protected = "==Unknown topic==\n<nowiki>===Noun===\n# PROTECTED</nowiki>\n" ++ tail;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "protected", protected, protected, null);
    const changed = "==Historical usage==\n===Noun===\n# CHANGED\n" ++ tail;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "changed", changed, ambiguous, null);
    const prefix = "unscoped prefix\n" ++ ambiguous;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "prefix", prefix, prefix, null);
    const hatnote = "<div class=\"disambig-see-also\">[[context]]</div>\n" ++ ambiguous;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "hatnote", hatnote, hatnote, null);
    _ = try writer.finish(codes);
    inline for (.{ "Etymology 2", "Noun", "Pronunciation 2", "Usage notes", "Alternative forms" }) |heading| {
        const entry_value = (try LeadingRegionFixture.entry(a, root, "English", heading)).?;
        try std.testing.expect(LeadingRegionFixture.contains(entry_value, "SUPPORT"));
        try std.testing.expect(LeadingRegionFixture.contains(entry_value, "CURRENT"));
        try std.testing.expect((try LeadingRegionFixture.entry(a, root, "Unclassified", heading)) == null);
    }
    inline for (.{ .{ "trailing", "TRAILING" }, .{ "direct", "DIRECT" }, .{ "protected", "PROTECTED" }, .{ "changed", "CHANGED" } }) |row| {
        const entry_value = (try LeadingRegionFixture.entry(a, root, "English", row[0])).?;
        try std.testing.expect(LeadingRegionFixture.contains(entry_value, row[1]));
        try std.testing.expect((try LeadingRegionFixture.entry(a, root, "Unclassified", row[0])) == null);
    }
    inline for (.{ "ambiguous", "prefix", "hatnote" }) |title| {
        const unknown = (try LeadingRegionFixture.entry(a, root, "Unclassified", title)).?;
        const known = (try LeadingRegionFixture.entry(a, root, "English", title)).?;
        try std.testing.expect(LeadingRegionFixture.contains(unknown, "PAST"));
        try std.testing.expect(!LeadingRegionFixture.contains(known, "PAST"));
        try std.testing.expect(LeadingRegionFixture.contains(known, "CURRENT"));
        try std.testing.expect(!LeadingRegionFixture.contains(unknown, "CURRENT"));
        if (std.mem.eql(u8, title, "prefix")) {
            try std.testing.expect(LeadingRegionFixture.contains(unknown, "unscoped prefix"));
            try std.testing.expect(!LeadingRegionFixture.contains(known, "unscoped prefix"));
        }
        if (std.mem.eql(u8, title, "hatnote")) {
            try std.testing.expect(LeadingRegionFixture.contains(unknown, "context"));
            try std.testing.expect(LeadingRegionFixture.contains(known, "context"));
        }
    }
}

const TrailingPeerFixture = struct {
    fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
        if (std.mem.eql(u8, name, "IsiZulu") or std.mem.eql(u8, name, "isiZulu") or std.mem.eql(u8, name, "zu")) return .{ .code = "zu", .heading = "isiZulu" };
        if (std.mem.eql(u8, name, "SiSwati") or std.mem.eql(u8, name, "ss")) return .{ .code = "ss", .heading = "isiSwati" };
        return TestLanguages.resolve(null, name);
    }
    fn trusted(ctx: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
        if (std.mem.eql(u8, name, "IsiZulu") or std.mem.eql(u8, name, "isiZulu") or std.mem.eql(u8, name, "SiSwati")) return resolve(ctx, name);
        return TestLanguages.trusted(ctx, name);
    }
    fn get(ctx: ?*const anyopaque, name: []const u8) ?[]const u8 { return if (resolve(ctx, name)) |value| value.code else null; }
    fn codes() LanguageCodes { return .{ .get_fn = get, .resolve_fn = resolve, .trusted_fn = trusted, .strong_fn = trusted }; }
};

test "Writer cross referenced unresolved trailing peer preserves exact typed regions and anchors" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const codes = TrailingPeerFixture.codes();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/trailing", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root); defer writer.deinit(); writer.language_codes = codes;
    // Literal excerpt from ZU sawubona p1948/r13301. Other template-produced
    // translation rows require the normal corpus rebuild and are not invented here.
    const source = "== IsiZulu ==\n'''IsiZulu:''' sawubona\n\nAlso see: [[sanibona]]\n\n====Ukuhunyushwa====\n* IsiSwazi: [[sawubona]] ([[:ss:sawubona|ss]])\n\n== IsiSwazi ==\n'''IsiZulu:''' [[sawubona]]\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "sawubona", source, source, null);
    // Synthetic fragment control retains global heading IDs after ownership cuts.
    const cross = "==IsiZulu==\n====Repeat====\n* IsiSwazi: [[cross]] ([[:ss:cross|ss]])\n[[#Repeat_2|later]]\n==IsiSwazi==\n====Repeat====\n[[#Repeat|earlier]]\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "cross", cross, cross, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 4), stats.language_records);
    try std.testing.expectEqual(@as(usize, 2), stats.language_blobs);
    try std.testing.expectEqual(@as(usize, 2), stats.fallback_pages);
    inline for (.{ .{ "sawubona", source }, .{ "cross", cross } }) |row| {
        const known = (try LeadingRegionFixture.entry(a, root, "isiZulu", row[0])).?;
        const unknown = (try LeadingRegionFixture.entry(a, root, "Unclassified", row[0])).?;
        try std.testing.expectEqualStrings("zu", known.language_code);
        try std.testing.expectEqualStrings("", unknown.language_code);
        const encoded = try presentation_document.compileReportedWithLinkTrailAlloc(a, row[0], .language, "Unclassified", "", row[1], null, .{}, null, null);
        const full = try blobs.presentation_codec.decodeAlloc(a, encoded, row[0], .language, .{ .code = "", .heading = "Unclassified" });
        try std.testing.expectEqualDeep(full.entry.sections[0..2], known.sections);
        try std.testing.expectEqualDeep(full.entry.sections[2..], unknown.sections);
        try std.testing.expectEqualStrings("IsiSwazi", unknown.sections[0].anchor);
        if (std.mem.eql(u8, row[0], "cross")) try std.testing.expectEqualStrings("Repeat_2", unknown.sections[1].anchor);
    }
    const actual = (try LeadingRegionFixture.entry(a, root, "Unclassified", "sawubona")).?;
    try std.testing.expect(LeadingRegionFixture.contains(actual, "IsiZulu:"));
    try std.testing.expect(LeadingRegionFixture.contains(actual, "sawubona"));
}

test "Writer trailing peer isolation requires active adjacent page bound language evidence" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const codes = TrailingPeerFixture.codes();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/trailing-controls", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root); defer writer.deinit(); writer.language_codes = codes;
    inline for (.{ "Noun", "Etymology 2", "Pronunciation 2", "Usage notes", "Alternative forms" }) |heading| {
        const text = try std.fmt.allocPrint(a, "==IsiZulu==\n* {s}: [[{s}]] ([[:ss:{s}|ss]])\n=={s}==\nSUPPORT\n", .{ heading, heading, heading, heading });
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, heading, text, text, null);
    }
    const ordinary = "==IsiZulu==\nKNOWN\n==Historical usage==\n'''IsiZulu:''' [[ordinary]]\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "ordinary", ordinary, ordinary, null);
    const after = "==IsiZulu==\nKNOWN\n==IsiSwazi==\n* IsiSwazi: [[after]] ([[:ss:after|ss]])\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "after", after, after, null);
    const unrelated = "==English==\n* IsiSwazi: [[unrelated]] ([[:ss:unrelated|ss]])\n==IsiZulu==\nKNOWN\n==IsiSwazi==\nUNRELATED\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "unrelated", unrelated, unrelated, null);
    const mismatched = "==IsiZulu==\n* IsiSwazi: [[other]] ([[:ss:mismatch|ss]])\n==IsiSwazi==\nMISMATCH\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "mismatch", mismatched, mismatched, null);
    const raw = "==IsiZulu==\nKNOWN\n==IsiSwazi==\nCHANGED\n";
    const expanded = "==IsiZulu==\n* IsiSwazi: [[changed]] ([[:ss:changed|ss]])\n==IsiSwazi==\nCHANGED\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "changed", expanded, raw, null);
    var ordinary_page: std.ArrayList(u8) = .empty;
    try ordinary_page.appendSlice(a, "==IsiZulu==\n");
    for (0..2048) |_| try ordinary_page.appendSlice(a, "ordinary prose and [[context]]\n");
    for (0..64) |index| try ordinary_page.appendSlice(a, try std.fmt.allocPrint(a, "==Unknown topic {d}==\nordinary support prose\n", .{index}));
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "long-ordinary", ordinary_page.items, ordinary_page.items, null);
    // Residual ambiguity is explicit: a complete same-page language row can
    // corroborate an unknown support label too. Preserve it as Unclassified,
    // without claiming the label names a language or assigning the row's code.
    const ambiguous = "==IsiZulu==\n* Historical usage: [[ambiguous]] ([[:ss:ambiguous|ss]])\n==Historical usage==\n'''IsiZulu:''' [[ambiguous]]\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "ambiguous", ambiguous, ambiguous, null);
    _ = try writer.finish(codes);
    inline for (.{ "Noun", "Etymology 2", "Pronunciation 2", "Usage notes", "Alternative forms", "ordinary", "after", "unrelated", "mismatch", "changed", "long-ordinary" }) |title| {
        try std.testing.expect((try LeadingRegionFixture.entry(a, root, "isiZulu", title)) != null);
        try std.testing.expect((try LeadingRegionFixture.entry(a, root, "Unclassified", title)) == null);
    }
    const known = (try LeadingRegionFixture.entry(a, root, "isiZulu", "ambiguous")).?;
    const unknown = (try LeadingRegionFixture.entry(a, root, "Unclassified", "ambiguous")).?;
    const encoded = try presentation_document.compileReportedWithLinkTrailAlloc(a, "ambiguous", .language, "Unclassified", "", ambiguous, null, .{}, null, null);
    const full = try blobs.presentation_codec.decodeAlloc(a, encoded, "ambiguous", .language, .{ .code = "", .heading = "Unclassified" });
    try std.testing.expectEqualDeep(full.entry.sections[0..1], known.sections);
    try std.testing.expectEqualDeep(full.entry.sections[1..], unknown.sections);
    try std.testing.expectEqualStrings("", unknown.language_code);
}

test "Writer plain block DIV across language cuts retains owners without false fallback" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const codes = TestLanguages.codes();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/blobs", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    const source = "==English==\n# [[visible-en|English sense]]\n<div>\n==French==\n# [[visible-fr|French sense]]<ref>anonymous</ref><ref name=x>[[citation-target|definition]]</ref>\n</div>[[suffix|suffix]]<ref name=x/>\n<references/>\n";
    const observation = try presentation_document.observePreScopesAlloc(a, "plain-div-cut", source, .{}, null, null, null, .{}, null);
    defer freePreObservation(a, observation);
    try std.testing.expectEqual(@as(usize, 1), observation.scopes.len);
    try std.testing.expectEqual(presentation_document.FragmentPreContext.Kind.layout_div, observation.scopes[0].kind);
    try std.testing.expect(observation.scopes[0].matched and !observation.unclosed_formatting);
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "plain-div-cut", source, source, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 2), stats.language_records);
    try std.testing.expectEqual(@as(usize, 0), stats.fallback_pages);
    const english = (try LeadingRegionFixture.entry(a, root, "English", "plain-div-cut")).?;
    const french = (try LeadingRegionFixture.entry(a, root, "French", "plain-div-cut")).?;
    try std.testing.expect(LeadingRegionFixture.contains(english, "visible-en"));
    try std.testing.expect(!LeadingRegionFixture.contains(english, "visible-fr"));
    try std.testing.expect(!LeadingRegionFixture.contains(english, "suffix"));
    try std.testing.expect(LeadingRegionFixture.contains(french, "visible-fr"));
    try std.testing.expect(LeadingRegionFixture.contains(french, "suffix"));
    try std.testing.expect(!LeadingRegionFixture.contains(french, "visible-en"));
    try std.testing.expectEqual(@as(usize, 2), french.references.len);
    var definition = false;
    for (french.references) |reference| for (reference.spans) |span| {
        definition = definition or (span.kind == .link and std.mem.eql(u8, span.target, "citation-target"));
    };
    try std.testing.expect(definition);
    const report = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(a, &.{ root, "fallback-pages.jsonl" }), a, .unlimited);
    try std.testing.expect(std.mem.indexOf(u8, report, "plain-div-cut") == null);
}

test "Writer nested block DIV and hidden scopes preserve owner quotes citations and closing headings" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/blobs", .{tmp.sub_path});
    const codes = TestLanguages.codes();
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    const source_format = "==English==\n# [[visible-en|English sense]]\n<div>\n<div{s}>\n==French==\n# [[hidden-fr|hidden sense]]<ref>anonymous</ref><ref name=x>[[citation-target|hidden definition]]</ref>\n''</div>[[visible-fr|suffix]]<ref name=x/>\n===Topic===</div>[[after-layout|after]]\n<references/>\n";
    for ([_]bool{ false, true }) |hidden| {
        const source = try std.fmt.allocPrint(a, source_format, .{if (hidden) " style='display:none'" else ""});
        const observation = try presentation_document.observePreScopesAlloc(a, "nested-div-observation", source, .{}, null, null, null, .{}, null);
        defer freePreObservation(a, observation);
        try std.testing.expectEqual(@as(usize, 2), observation.scopes.len);
        try std.testing.expectEqual(presentation_document.FragmentPreContext.Kind.layout_div, observation.scopes[0].kind);
        try std.testing.expectEqual(if (hidden) presentation_document.FragmentPreContext.Kind.hidden else presentation_document.FragmentPreContext.Kind.layout_div, observation.scopes[1].kind);
        try std.testing.expectEqual(@as(?usize, 0), observation.scopes[1].parent);
        try std.testing.expect(observation.scopes[0].matched and observation.scopes[1].matched and !observation.unclosed_formatting);
        const fallback_before = writer.stats.fallback_pages;
        try writer.addExpandedPageWithReasons(a, .{ .id = 0, .kind = .language }, if (hidden) "nested-hidden-cut" else "nested-visible-control", source, source, null, &.{});
        try std.testing.expectEqual(fallback_before, writer.stats.fallback_pages);
    }
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 4), stats.language_records);
    try std.testing.expectEqual(@as(usize, 2), stats.language_blobs);
    try std.testing.expectEqual(@as(usize, 0), stats.fallback_pages);
    const fallback_report = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(a, &.{ root, "fallback-pages.jsonl" }), a, .limited(8192));
    var fallback_lines = std.mem.tokenizeScalar(u8, fallback_report, '\n');
    while (fallback_lines.next()) |line| {
        const row = try std.json.parseFromSlice(std.json.Value, a, line, .{});
        defer row.deinit();
        try std.testing.expect(!std.mem.eql(u8, row.value.object.get("title").?.string, "nested-hidden-cut"));
    }
    for ([_][]const u8{ "English", "French" }) |owner| {
        var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, owner));
        defer mapped.deinit();
        const blob = try blob_format.inspect(mapped.bytes);
        const metadata = try blob.languageMetadata();
        var index = try blob.buildTrustedIndexAlloc(a);
        defer index.deinit(a);
        const english = std.mem.eql(u8, owner, "English");
        var control_italic: ?bool = null;
        var control_bold: ?bool = null;
        for ([_]bool{ false, true }) |hidden| {
            const record = (try index.find(if (hidden) "nested-hidden-cut" else "nested-visible-control")).?;
            const decoded = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
            try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, decoded));
            try std.testing.expectEqualStrings(if (english) "en" else "fr", decoded.entry.language_code);
            var english_links: usize = 0;
            var hidden_links: usize = 0;
            var suffix_links: usize = 0;
            var visible_reuses: usize = 0;
            var after_layout: usize = 0;
            var topic_headings: usize = 0;
            for (decoded.entry.sections) |section| if (std.mem.eql(u8, section.title, "Topic")) {
                try std.testing.expectEqual(@as(u8, 3), section.level);
                topic_headings += 1;
            };
            for (decoded.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
                if (std.mem.eql(u8, span.target, "after-layout")) after_layout += 1;
                if (std.mem.eql(u8, span.target, "visible-en")) english_links += 1;
                if (std.mem.eql(u8, span.target, "hidden-fr")) hidden_links += 1;
                if (std.mem.eql(u8, span.target, "visible-fr")) {
                    suffix_links += 1;
                    if (hidden) {
                        try std.testing.expectEqual(control_italic.?, span.italic);
                        try std.testing.expectEqual(control_bold.?, span.bold);
                    } else {
                        control_italic = span.italic;
                        control_bold = span.bold;
                    }
                }
                if (hidden and std.mem.eql(u8, span.target, "#reference-2")) {
                    try std.testing.expectEqualStrings("[2]", span.text);
                    visible_reuses += 1;
                }
                try std.testing.expect(!std.mem.eql(u8, span.target, "citation-target"));
            };
            try std.testing.expectEqual(@as(usize, @intFromBool(english)), english_links);
            try std.testing.expectEqual(@as(usize, @intFromBool(!english and !hidden)), hidden_links);
            try std.testing.expectEqual(@as(usize, @intFromBool(!english)), suffix_links);
            if (hidden) try std.testing.expectEqual(@as(usize, @intFromBool(!english)), visible_reuses);
            try std.testing.expectEqual(@as(usize, @intFromBool(!english)), after_layout);
            try std.testing.expectEqual(@as(usize, @intFromBool(!english)), topic_headings);
            if (!english) {
                try std.testing.expectEqual(@as(usize, 2), decoded.entry.references.len);
                try std.testing.expectEqualStrings("x", decoded.entry.references[1].name);
                try std.testing.expectEqual(@as(usize, 2), decoded.entry.references[1].number);
                var citation_targets: usize = 0;
                for (decoded.entry.references[1].spans) |span| if (std.mem.eql(u8, span.target, "citation-target")) {
                    citation_targets += 1;
                    try std.testing.expectEqualStrings("hidden definition", span.text);
                };
                try std.testing.expectEqual(@as(usize, 1), citation_targets);
            }
        }
    }
}

const CodedSpanHeadingTest = struct {
    const ns = "# wikidict-namespace-registry-v1\n# wiki\tvowiktionary\n# dump-date\t20261001\n# content-language\tvo\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\twikitext\tmain\tentries\n" ++
        "6\tMagod\tFile\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\tfiles\n" ++
        "10\tSamafomot\tTemplate\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\ttemplates\n" ++
        "14\tKlad\tCategory\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\tcategories\n";
    const heading = "<span id=vo>Volapük <small>(vo)</small></span>[[Klad:Pads valik in Volapük]]";
    fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
        if (std.mem.eql(u8, name, "vo") or std.mem.eql(u8, name, "Volapük")) return .{ .code = "vo", .heading = "Volapük" };
        return TestLanguages.resolve(null, name);
    }
    fn trusted(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
        if (std.mem.eql(u8, name, "Volapük")) return resolve(null, name);
        if (std.mem.eql(u8, name, "English") or std.mem.eql(u8, name, "French")) return TestLanguages.resolve(null, name);
        return null;
    }
    fn get(ctx: ?*const anyopaque, name: []const u8) ?[]const u8 {
        return (resolve(ctx, name) orelse return null).code;
    }
    fn codes(namespaces: *const @import("namespace_registry").Registry) LanguageCodes {
        return .{ .namespace_catalog = namespaces, .get_fn = get, .resolve_fn = resolve, .trusted_fn = trusted };
    }
};

test "coded span language heading requires matching explicit fields and trusted whole name" {
    const a = std.testing.allocator;
    var namespaces = try @import("namespace_registry").Registry.init(a, CodedSpanHeadingTest.ns);
    defer namespaces.deinit();
    const codes = CodedSpanHeadingTest.codes(&namespaces);
    try std.testing.expectEqualStrings("vo", (resolveCodedSpanHeading(codes, CodedSpanHeadingTest.heading) orelse return error.TestUnexpectedResult).code);
    try std.testing.expectEqualStrings("en", (resolveCodedSpanHeading(codes, "<span id=en>English <small>(en)</small></span>") orelse return error.TestUnexpectedResult).code);
    for ([_][]const u8{
        "Volapük (vo)",
        "<span id=vo>Volapük <small>(en)</small></span>",
        "<span id=en>Volapük <small>(en)</small></span>",
        "<span id=vo>Unknown <small>(vo)</small></span>",
        "<span id=vo>vo <small>(vo)</small></span>",
        "<span id=unknown>Volapük <small>(unknown)</small></span>",
        "<span id=vo style='display:none'>Volapük <small>(vo)</small></span>",
        "<span id=vo id=en>Volapük <small>(vo)</small></span>",
        "<span id=vo><span>Volapük</span> <small>(vo)</small></span>",
        "<span id=vo>Volapük <small class=x>(vo)</small></span>",
        "<span id=vo>Volapük <small>(vo)</small> extra</span>",
        "prefix <span id=vo>Volapük <small>(vo)</small></span>",
        "<span id=vo>Volapük <small>(vo)</small></span> extra",
        "<nowiki><span id=vo>Volapük <small>(vo)</small></span></nowiki>",
        "<span id=vo>Volapük <small>(vo)</small>",
        "<span id=vo>Volapük <small>(vo)</small></span>[[Target]]",
        "<span id=vo>Volapük <small>(vo)</small></span>[[:Klad:Volapük]]",
        "<span id=vo>Volapük <small>(vo)</small></span>[[Klad:English]]",
    }) |bad| {
        errdefer std.debug.print("coded span negative: {s}\n", .{bad});
        try std.testing.expect(resolveCodedSpanHeading(codes, bad) == null);
    }
    var untrusted = codes;
    untrusted.trusted_fn = struct {
        fn reject(_: ?*const anyopaque, _: []const u8) ?ResolvedLanguage { return null; }
    }.reject;
    try std.testing.expect(resolveCodedSpanHeading(untrusted, CodedSpanHeadingTest.heading) == null);
    var conflicting = codes;
    conflicting.trusted_fn = struct {
        fn wrong(_: ?*const anyopaque, _: []const u8) ?ResolvedLanguage { return .{ .code = "en", .heading = "English" }; }
    }.wrong;
    try std.testing.expect(resolveCodedSpanHeading(conflicting, CodedSpanHeadingTest.heading) == null);
}

test "coded span Writer retains whole visible heading body actions styles and codec" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const io = std.testing.io;
    var namespaces = try @import("namespace_registry").Registry.init(a, CodedSpanHeadingTest.ns);
    defer namespaces.deinit();
    const codes = CodedSpanHeadingTest.codes(&namespaces);
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/blobs", .{tmp.sub_path});
    var writer = try Writer.init(io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    // Exact source-instantiated pükatiäd heading; the varied body is a synthetic
    // conservation control, not a claimed captured expansion of nen.
    const body = "=" ++ CodedSpanHeadingTest.heading ++ "=\n" ++
        "===pronimag===\n:[[LFB]]: []\n" ++
        "===präpod===\n'''nen''' ''marked'' [[Target|label]]\n# sense\n#: quotation\n" ++
        "===tümolog===\norigin [[Origin]]<ref>reference [[Citation]]</ref>\n" ++
        "===[[Magod:ArieDeJong.png|30px]] tradutods rigik===\n" ++
        "===pedefom===\n" ++
        "===koboyüm===\n" ++
        "===tradutods===\n{| class=wikitable\n| bgcolor=#ffffcc | English || [[without]] || [[sem]]\n|}\n<references/>\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "synthetic-coded-nen", body, body, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);
    var mapped = try mmapPath(io, try languageBlobPathAlloc(a, root, "Volapük"));
    defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    const metadata = try blob.languageMetadata();
    try std.testing.expectEqualStrings("vo", metadata.code);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    const record = (try index.find("synthetic-coded-nen")) orelse return error.TestUnexpectedResult;
    const decoded = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
    var report: presentation_document.Fallbacks = .{};
    const reference_payload = try presentation_document.compileReportedWithLinkTrailAlloc(a, record.title, .language, "Volapük", "vo", body, null, .{}, &namespaces, &report);
    const reference = try blobs.presentation_codec.decodeAlloc(a, reference_payload, record.title, .language, metadata);
    try std.testing.expectEqualDeep(reference, decoded);
    try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, decoded));
    try std.testing.expectEqual(@as(usize, 8), decoded.entry.sections.len);
    var heading_text: std.ArrayList(u8) = .empty;
    var code_small = false;
    try std.testing.expect(decoded.entry.sections[0].blocks[0].kind == .heading);
    for (decoded.entry.sections[0].blocks[0].spans) |span| {
        try heading_text.appendSlice(a, span.text);
        if (std.mem.eql(u8, span.text, "(vo)")) {
            try std.testing.expect(!span.small);
            try std.testing.expectApproxEqAbs(@as(f32, 1.0 / 1.2), span.font_scale orelse return error.TestUnexpectedResult, 0.000001);
            code_small = true;
        }
    }
    try std.testing.expectEqualStrings("Volapük (vo)", heading_text.items);
    try std.testing.expect(code_small);
    try std.testing.expectEqual(@as(usize, 0), decoded.entry.organization.lexemes.len);
    try std.testing.expectEqual(@as(usize, 1), decoded.entry.references.len);
    try std.testing.expectEqual(@as(usize, 1), decoded.entry.media.len);
}

const FlaggedLanguageHeadingTest = struct {
    const ns = "# wikidict-namespace-registry-v1\n# wiki\ttgwiktionary\n# dump-date\t20261001\n# content-language\ttg\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\twikitext\tmain\tentries\n" ++
        "6\tImage\tFile\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\tfiles\n" ++
        "10\tШаблон\tTemplate\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\ttemplates\n" ++
        "14\tГурӯҳ\tCategory\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\tcategories\n";
    const heading = "<big>[[Image:Flag of Netherlands.svg|50px|]] Нидерландӣ</big>";
    fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
        if (std.mem.eql(u8, name, "nl") or std.mem.eql(u8, name, "Нидерландӣ") or std.mem.eql(u8, name, "ҳолландӣ")) return .{ .code = "nl", .heading = "ҳолландӣ" };
        return TestLanguages.resolve(null, name);
    }
    fn trusted(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
        if (std.mem.eql(u8, name, "Нидерландӣ") or std.mem.eql(u8, name, "ҳолландӣ")) return resolve(null, name);
        if (std.mem.eql(u8, name, "English")) return TestLanguages.resolve(null, name);
        return null;
    }
    fn get(ctx: ?*const anyopaque, name: []const u8) ?[]const u8 {
        return (resolve(ctx, name) orelse return null).code;
    }
    fn codes(namespaces: *const @import("namespace_registry").Registry) LanguageCodes {
        return .{ .namespace_catalog = namespaces, .get_fn = get, .resolve_fn = resolve, .trusted_fn = trusted };
    }
};

