            for (values, 0..) |block, block_index| {
                std.debug.print("BG may block nesting={d} index={d} kind={s} depth={d} path={s} number={s} level={d} text=", .{ nesting, block_index, @tagName(block.kind), block.depth, block.list_path, block.number, block.level });
                for (block.spans) |span| std.debug.print("{s}{s}", .{ span.text, span.trail });
                std.debug.print("\n", .{});
                if (block.table) |child_table| diagnosticTable(child_table, nesting + 1);
                if (block.container) |owner| {
                    std.debug.print("BG may Container style={any} children={d}\n", .{ owner.style, owner.blocks.len });
                    diagnosticBlocks(owner.blocks, nesting + 1);
                }
            }
        }
        fn diagnosticTable(value: blobs.presentation_types.Table, nesting: usize) void {
            std.debug.print("BG may table nesting={d} rows={d} caption=", .{ nesting, value.rows.len });
            for (value.caption) |span| std.debug.print("{s}{s}", .{ span.text, span.trail });
            std.debug.print("\n", .{});
            for (value.rows, 0..) |row, row_index| for (row.cells, 0..) |cell, cell_index| {
                std.debug.print("BG may cell row={d} col={d} background={s} text=", .{ row_index, cell_index, cell.background orelse "<null>" });
                for (cell.spans) |span| std.debug.print("{s}{s}", .{ span.text, span.trail });
                std.debug.print("\n", .{});
                if (cell.blocks) |inner| diagnosticBlocks(inner, nesting + 1)
                else if (cell.nested_table) |nested| diagnosticTable(nested, nesting + 1);
            };
        }
        fn spans(self: *@This(), allocator: std.mem.Allocator, values: []const blobs.presentation_types.Span) anyerror!void {
            for (values) |span| {
                try self.visible.appendSlice(allocator, span.text);
                if (std.mem.eql(u8, span.text, "{{Словоформи/{{{ID}}}}}")) {
                    self.literal_names += 1;
                    try std.testing.expect(span.kind == .text and span.target.len == 0);
                }
                if (span.kind == .link or span.kind == .external_link) {
                    try std.testing.expect(std.mem.indexOf(u8, span.target, "{{") == null);
                    try self.targets.append(allocator, span.target);
                }
            }
        }
        fn visitContainer(self: *@This(), allocator: std.mem.Allocator, block: blobs.presentation_types.Block) anyerror!void {
            try std.testing.expect(blobs.presentation_types.validContainerContext(block));
            const owner = block.container orelse return error.TestUnexpectedResult;
            try std.testing.expect(blobs.presentation_types.validContainerHeader(owner));
            if (owner.style.clear != null) {
                try std.testing.expectEqualDeep(blobs.presentation_types.ContainerStyle{ .clear = .both }, owner.style);
                try std.testing.expectEqual(@as(usize, 0), owner.blocks.len);
                self.clear_owners += 1;
            } else if (owner.style.background != null) {
                // The captured empty NavHead keeps its own paint/bottom border.
                try std.testing.expectEqualDeep(blobs.presentation_types.ContainerStyle{
                    .owner_font_scale = 0.95,
                    .padding = .{ .top = .{ .unit = .px, .value = 0 }, .right = .{ .unit = .px, .value = 0 },
                        .bottom = .{ .unit = .px, .value = 0 }, .left = .{ .unit = .px, .value = 10 } },
                    .min_height = .{ .unit = .em, .value = @as(f32, 1.6) * @as(f32, 0.95) },
                    .background = .{ .rgb = "#ece7ff" },
                    .border = .{ .edges = .{ .top = .none, .right = .none,
                        .bottom = .{ .solid = .{ .width = .{ .unit = .px, .value = 1 }, .color = .{ .rgb = "#b8b0d9" } } }, .left = .none } },
                }, owner.style);
                try std.testing.expectEqual(@as(usize, 0), owner.blocks.len);
                self.header_owners += 1;
            } else {
                // The matched stylesheet supplies the NavFrame font and geometry; it owns its
                // decorated header and following table without flattening either.
                try std.testing.expectEqualDeep(blobs.presentation_types.ContainerStyle{
                    .owner_font_scale = 0.95, .width = .{ .length = .{ .unit = .percent, .value = 100 } },
                    .padding = blobs.presentation_types.StyleEdges.all(.{ .unit = .px, .value = 2 }),
                    .margins = .{ .top = .{ .unit = .px, .value = 0 }, .right = .{ .unit = .px, .value = 0 },
                        .bottom = .{ .unit = .px, .value = -1 }, .left = .{ .unit = .px, .value = 0 } },
                    .border = .{ .solid = .{ .width = .{ .unit = .px, .value = 1 }, .color = .{ .rgb = "#e2e4c0" } } },
                }, owner.style);
                try std.testing.expectEqual(@as(usize, 2), owner.blocks.len);
                try std.testing.expect(owner.blocks[0].container != null and owner.blocks[1].table != null);
                self.frame_owners += 1;
            }
            try self.blocks(allocator, owner.blocks);
        }
        fn blocks(self: *@This(), allocator: std.mem.Allocator, values: []const blobs.presentation_types.Block) anyerror!void {
            for (values) |block| {
                if (block.kind == .definition) {
                    var text: std.ArrayList(u8) = .empty;
                    for (block.spans) |span| try text.appendSlice(allocator, span.text);
                    try self.definitions.append(allocator, try text.toOwnedSlice(allocator));
                }
                try self.spans(allocator, block.spans);
                if (block.table) |child_table| try self.table(allocator, child_table);
                if (block.container != null) try self.visitContainer(allocator, block);
            }
        }
        fn table(self: *@This(), allocator: std.mem.Allocator, value: blobs.presentation_types.Table) anyerror!void {
            self.tables += 1;
            // The captured unindexed "translations" class keeps typed table
            // style partial; authored table paint survives as effective cell paint.
            // Identify both exact translation grids by shape, then require every
            // authored cell color, including the inherited center background.
            if (value.rows.len == 1 and value.rows[0].cells.len == 3) {
                self.translation_tables += 1;
                const colors = [_][]const u8{ "#f7f8ff", "#fcfbff", "#f7f8ff" };
                for (value.rows[0].cells, colors) |cell, color| {
                    try std.testing.expect(!cell.header);
                    try std.testing.expectEqual(@as(u16, 1), cell.colspan);
                    try std.testing.expectEqual(@as(u16, 1), cell.rowspan);
                    try std.testing.expectEqualStrings(color, cell.background orelse return error.TestUnexpectedResult);
                }
            }
            try self.spans(allocator, value.caption);
            for (value.rows) |row| for (row.cells) |cell| {
                if (cell.blocks) |inner| try self.blocks(allocator, inner)
                else if (cell.nested_table) |nested| try self.table(allocator, nested)
                else try self.spans(allocator, cell.spans);
            };
        }
    };
    var scan: Scan = .{};
    errdefer {
        std.debug.print("BG may summary definitions={d} tables={d} translation_tables={d} literal_names={d} sections={d} lexemes={d}\n", .{ scan.definitions.items.len, scan.tables, scan.translation_tables, scan.literal_names, stored.entry.sections.len, stored.entry.organization.lexemes.len });
        for (stored.entry.sections, 0..) |section, section_index| {
            std.debug.print("BG may section index={d} level={d} title={s} anchor={s} anchor_fallback={s}\n", .{ section_index, section.level, section.title, section.anchor, section.anchor_fallback });
            Scan.diagnosticBlocks(section.blocks, 0);
        }
    }
    for (stored.entry.sections) |section| try scan.blocks(a, section.blocks);
    try std.testing.expectEqual(@as(usize, 1), scan.clear_owners);
    try std.testing.expectEqual(@as(usize, 2), scan.header_owners);
    try std.testing.expectEqual(@as(usize, 2), scan.frame_owners);
    try std.testing.expectEqual(@as(usize, 1), scan.literal_names);
    try std.testing.expectEqual(@as(usize, 2), scan.definitions.items.len);
    try std.testing.expectEqualStrings("Петият месец от календарната година.", scan.definitions.items[0]);
    try std.testing.expectEqualStrings("Израз на вероятност. (Май ще вали.)", scan.definitions.items[1]);
    try std.testing.expectEqual(@as(usize, 3), scan.tables);
    try std.testing.expectEqual(@as(usize, 2), scan.translation_tables);
    for ([_][]const u8{ "английски:", "белоруски:", "гръцки:", "есперанто:", "ирландски:", "исландски:", "испански:", "италиански:", "немски:", "осетински:", "персийски:", "полски:", "португалски:", "руски:", "словашки:", "словенски:", "сръбски:", "унгарски:", "фински:", "френски:", "хърватски:", "Прото-Индо-Европейски", "възможно е, тъй да се каже", "{{{ИЗГОВОР}}}", "{{{НАДСЛОВИЯ}}}", "{{{ПОДСЛОВИЯ}}}", "{{{ИЗТОЧНИЦИ}}}" }) |text|
        try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, text) != null);
    for ([_][]const u8{ "мая", "May#Английски", "mayo#Испански", "Mai#Немски", "май#Руски", "máj#Словашки", "svibanj#Хърватски" }) |target| {
        var found = false;
        for (scan.targets.items) |actual| if (std.mem.eql(u8, actual, target)) { found = true; break; };
        try std.testing.expect(found);
    }
    try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, "[missing parameter]") == null);
    try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, "__БЕЗ_РЕДАКТИРАНЕ_НА_РАЗДЕЛИ__") == null);
}


test "SL internal Writer preserves missing raw authority and the complete expanded body" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const io = std.testing.io;
    var namespaces = try @import("namespace_registry").Registry.init(a,
        "# wikidict-namespace-registry-v1\n# wiki\tslwiktionary\n# dump-date\t20261001\n# content-language\tsl\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\twikitext\tmain\tentries\n" ++
        "10\tPredloga\tTemplate\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\ttemplates\n" ++
        "14\tKategorija\tCategory\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\tcategories\n");
    defer namespaces.deinit();
    const Proof = struct {
        calls: usize = 0,
        fn resolve(_: ?*const anyopaque, label: []const u8) ?ResolvedLanguage {
            return if (std.mem.eql(u8, label, "slovenščina") or std.mem.eql(u8, label, "Slovenščina"))
                .{ .code = "sl", .heading = "slovenščina" } else null;
        }
        fn get(ctx: ?*const anyopaque, label: []const u8) ?[]const u8 {
            return if (resolve(ctx, label)) |value| value.code else null;
        }
        fn category(raw: ?*anyopaque, target: []const u8) !?ResolvedLanguage {
            const self: *@This() = @ptrCast(@alignCast(raw.?));
            self.calls += 1;
            return if (std.mem.eql(u8, target, "Kategorija:Slovenski samostalniki"))
                .{ .code = "sl", .heading = "slovenščina" } else null;
        }
    };
    // Finite synthetic control for the captured structural form. Full captured
    // source/category/normal-loader bodies remain covered by the tools tests.
    const raw = "''smrt'', [[samostalnik]] ženskega [[spol]]a\n\n{{Prevodi}}\n*Angleško: {{prev|en|death}}\n\n[[Kategorija:Slovenski samostalniki]]\n";
    const expanded = "''smrt'', [[samostalnik]] ženskega [[spol]]a\n\n==== Prevodi ====\n*Angleško: [[death]] <sup>[[:en:death|(en)]]</sup>\n\n[[Kategorija:Slovenski samostalniki]]\n";
    for ([_]?[]const u8{ null, raw }, 0..) |authored, i| {
        var proof: Proof = .{};
        const codes: LanguageCodes = .{ .namespace_catalog = &namespaces, .get_fn = Proof.get, .resolve_fn = Proof.resolve, .trusted_fn = Proof.resolve,
            .source_category_ctx = &proof, .source_category_fn = Proof.category };
        const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/sl-raw-{d}", .{ tmp.sub_path, i });
        var writer = try Writer.init(io, a, root);
        defer writer.deinit();
        writer.language_codes = codes;
        // Exercise the existing private optional-source path. Public addPage
        // supplies expanded bytes as raw and therefore cannot model this case.
        try writer.addPageInternal(a, .{ .id = 0, .kind = .language }, "smrt", expanded, authored, null, .{}, &.{}, null, null);
        const stats = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, 1), stats.language_records);
        const owned = authored != null;
        try std.testing.expectEqual(@as(usize, if (owned) 2 else 0), proof.calls);
        try std.testing.expectEqual(@as(usize, if (owned) 0 else 1), stats.fallback_pages);
        const heading: []const u8 = if (owned) "slovenščina" else "Unclassified";
        const code: []const u8 = if (owned) "sl" else "";
        const path = try languageBlobPathAlloc(a, root, heading);
        var mapped = try mmapPath(io, path);
        defer mapped.deinit();
        const blob = try blob_format.inspect(mapped.bytes);
        const metadata = try blob.languageMetadata();
        try std.testing.expectEqualStrings(code, metadata.code);
        var index = try blob.buildTrustedIndexAlloc(a);
        defer index.deinit(a);
        const record = (try index.find("smrt")) orelse return error.TestUnexpectedResult;
        const stored = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
        try std.testing.expectEqualStrings(heading, stored.entry.language.?);
        try std.testing.expectEqualStrings(code, stored.entry.language_code);
        try std.testing.expectEqual(@as(usize, 0), stored.entry.organization.lexemes.len);
        const direct = try presentation_document.compileReportedWithLinkTrailAlloc(a, "smrt", .language, heading, code, expanded, null, .{}, &namespaces, null);
        const complete = try blobs.presentation_codec.decodeAlloc(a, direct, "smrt", .language, metadata);
        try std.testing.expectEqualDeep(complete, stored);
        try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, stored));
        var translation_link: usize = 0;
        var italic_headword = false;
        for (stored.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
            if (std.mem.eql(u8, span.target, "death")) translation_link += 1;
            if (span.italic and std.mem.eql(u8, span.text, "smrt")) italic_headword = true;
        };
        try std.testing.expectEqual(@as(usize, 1), translation_link);
        try std.testing.expect(italic_headword);
        const report = try std.Io.Dir.cwd().readFileAlloc(io, try std.fs.path.join(a, &.{ root, "fallback-pages.jsonl" }), a, .limited(65536));
        try std.testing.expectEqual(!owned, std.mem.indexOf(u8, report, "missing_language_heading") != null);
    }
}


test "captured alarmowac retains bordered Polish flag occurrence and complete Polish body codec" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // Complete retained p164655/r3372809; no re-expansion.
    const raw = "== {{-pl-}} ==\n{{-verb-|pl}}\n{{Pn}}\n# [[allarmare]], [[dare]] [[l']] [[allarme]]\n# {{Fig}} [[allarmare]], [[mettere]] [[in]] [[apprensione]] <[[in]] [[allarme]]>, [[suscitare]] [[l']] [[allarme]]";
    const expanded = "==  [[File:Flag_of_Poland.svg|border|40px]] [[polacco|Polacco]] ==\n===[[Image:Open_book_01.svg|30px|]]''[[verbo|Verbo]]''===\n[[Categoria:Verbi in polacco]] \n\n'''alarmować'''<small></small>\n# [[allarmare]], [[dare]] [[l']] [[allarme]]\n# <small>(''senso figurato'')</small> [[allarmare]], [[mettere]] [[in]] [[apprensione]] <[[in]] [[allarme]]>, [[suscitare]] [[l']] [[allarme]]";
    const namespace_source = "# wikidict-namespace-registry-v1\n# wiki\titwiktionary\n# dump-date\t20261001\n# content-language\tit\n-2\tMedia\tMedia\tcase-sensitive\t0\t0\t0\t\tcompile_only\tvirtual_namespace\n-1\tSpeciale\tSpecial\tfirst-letter\t0\t0\t0\t\tcompile_only\tvirtual_namespace\n0\t\t\tcase-sensitive\t0\t1\t0\t\tmain\tdictionary_entries\n1\tDiscussione\tTalk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n2\tUtente\tUser\tfirst-letter\t1\t0\t0\t\tcompile_only\tstandard_build_input\n3\tDiscussioni utente\tUser talk\tfirst-letter\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n4\tWikizionario\tProject\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\tWT\tWZ\tWiktionary\n5\tDiscussioni Wikizionario\tProject talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\tWiktionary talk\n6\tFile\tFile\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\tImage\tImmagine\n7\tDiscussioni file\tFile talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\tDiscussioni immagine\tImage talk\n8\tMediaWiki\tMediaWiki\tfirst-letter\t1\t0\t0\t\tcompile_only\tstandard_build_input\n9\tDiscussioni MediaWiki\tMediaWiki talk\tfirst-letter\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n10\tTemplate\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n11\tDiscussioni template\tTemplate talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n12\tAiuto\tHelp\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n13\tDiscussioni aiuto\tHelp talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n14\tCategoria\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\n15\tDiscussioni categoria\tCategory talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n100\tAppendice\tAppendice\tcase-sensitive\t1\t0\t0\t\tsupplemental\tunclassified_subject_retained\n101\tDiscussioni appendice\tDiscussioni appendice\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n710\tTimedText\tTimedText\tcase-sensitive\t0\t0\t0\t\tcompile_only\tancillary_site_input\n711\tTimedText talk\tTimedText talk\tcase-sensitive\t0\t0\t0\t\tcompile_only\tdiscussion_namespace\n828\tModulo\tModule\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n829\tDiscussioni modulo\tModule talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n1728\tEvento\tEvent\tcase-sensitive\t1\t0\t0\t\tcompile_only\tancillary_site_input\n1729\tDiscussioni evento\tEvent talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n";
    try std.testing.expectEqual(@as(usize, 195), raw.len);
    try std.testing.expectEqual(@as(usize, 377), expanded.len);
    var source_hash: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(raw, &source_hash, .{});
    try std.testing.expectEqualStrings("29a5d76bc461af34eed4922e0cf6cbf0e2bc0a0da420361c4ba09b67aecfcc26", &std.fmt.bytesToHex(source_hash, .lower));
    std.crypto.hash.sha2.Sha256.hash(expanded, &source_hash, .{});
    try std.testing.expectEqualStrings("5797eebb84b5d22dfa6f212e1b147e5b78109d80848c9da11bccc0437a092a97", &std.fmt.bytesToHex(source_hash, .lower));
    var namespaces = try @import("namespace_registry").Registry.init(a, namespace_source);
    defer namespaces.deinit();
    const Authority = struct {
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            // Exact installed pl/polacco/Polacco row, not the edition's language.
            for ([_][]const u8{ "polacco", "Polacco", "Polski", "polski", "pl", "Polish", "pol" }) |label|
                if (std.mem.eql(u8, value, label)) return .{ .code = "pl", .heading = "polacco" };
            return null;
        }
        fn get(ctx: ?*const anyopaque, value: []const u8) ?[]const u8 {
            return (resolve(ctx, value) orelse return null).code;
        }
    };
    const codes: LanguageCodes = .{ .namespace_catalog = &namespaces, .get_fn = Authority.get, .resolve_fn = Authority.resolve, .trusted_fn = Authority.resolve };
    const reference = try std.mem.replaceOwned(u8, a, expanded, "<[[in]]", "&lt;[[in]]");
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/actual", .{tmp.sub_path});
    const reference_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/reference", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    var reference_writer = try Writer.init(std.testing.io, a, reference_root);
    defer reference_writer.deinit();
    reference_writer.language_codes = codes;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "alarmować", expanded, raw, null);
    try reference_writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "alarmować", reference, raw, null);
    const stats = try writer.finish(codes);
    const expected_stats = try reference_writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);
    try std.testing.expectEqual(@as(usize, 1), stats.language_blobs);
    try std.testing.expectEqual(stats.language_records, expected_stats.language_records);
    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "polacco"));
    defer mapped.deinit();
    var expected_mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, reference_root, "polacco"));
    defer expected_mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    const expected_blob = try blob_format.inspect(expected_mapped.bytes);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    var expected_index = try expected_blob.buildTrustedIndexAlloc(a);
    defer expected_index.deinit(a);
    const record = (try index.find("alarmować")).?;
    const expected_record = (try expected_index.find("alarmować")).?;
    try std.testing.expectEqualSlices(u8, expected_record.payload, record.payload);
    const stored = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
    try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, stored));
    try std.testing.expectEqualStrings("pl", stored.entry.language_code);
    try std.testing.expectEqualStrings("polacco", stored.entry.language.?);
    try std.testing.expectEqual(@as(usize, 1), stored.entry.organization.lexemes.len);
    const lexeme = stored.entry.organization.lexemes[0];
    try std.testing.expectEqualStrings("Verb", lexeme.kind);
    try std.testing.expectEqual(@as(usize, 2), lexeme.definitions.len);
    try std.testing.expectEqualStrings("Verbo", stored.entry.sections[lexeme.section].title);
    try std.testing.expectEqual(@as(u8, 3), stored.entry.sections[lexeme.section].level);
    try std.testing.expectEqual(@as(usize, 2), stored.entry.media.len);
    var flag_image = false;
    var book_image = false;
    for (stored.entry.media) |item| {
        flag_image = flag_image or std.mem.eql(u8, item.file, "Flag of Poland.svg");
        book_image = book_image or std.mem.eql(u8, item.file, "Open book 01.svg");
    }
    try std.testing.expect(flag_image and book_image);
    try std.testing.expectEqualStrings("DPRD", record.payload[0..4]);
    var flag_occurrences: usize = 0;
    var book_occurrences: usize = 0;
    var definitions: usize = 0;
    var figurative = false;
    var headword = false;
    var in_actions: usize = 0;
    var alarm_actions: usize = 0;
    for (stored.entry.sections) |section| for (section.blocks) |block| {
        var text: std.ArrayList(u8) = .empty;
        for (block.spans) |span| {
            if (span.image) |image| {
                try std.testing.expectEqualStrings("", span.text);
                try std.testing.expectEqualStrings("", span.trail);
                try std.testing.expect(image.height_px == null and image.alt == null and image.tooltip == null);
                if (std.mem.eql(u8, image.file, "Flag of Poland.svg")) {
                    flag_occurrences += 1;
                    try std.testing.expect(image.border);
                    try std.testing.expectEqual(@as(?u32, 40), image.width_px);
                    try std.testing.expectEqual(@as(u8, 2), section.level);
                    try std.testing.expectEqualStrings("Polacco", section.title);
                    try std.testing.expectEqual(blobs.presentation_types.InlineKind.link, span.kind);
                    try std.testing.expectEqualStrings("File:Flag of Poland.svg", span.target);
                } else if (std.mem.eql(u8, image.file, "Open book 01.svg")) {
                    book_occurrences += 1;
                    try std.testing.expect(!image.border);
                    try std.testing.expectEqual(@as(?u32, 30), image.width_px);
                } else return error.TestUnexpectedResult;
            }
            try text.appendSlice(a, span.text);
            if (span.bold and std.mem.eql(u8, span.text, "alarmować")) headword = true;
            if (span.italic and std.mem.eql(u8, span.text, "senso figurato")) {
                try std.testing.expectEqual(@as(?f32, 1.0 / 1.2), span.font_scale);
                figurative = true;
            }
            if (block.kind == .definition and span.kind == .link) {
                if (std.mem.eql(u8, span.target, "in")) in_actions += 1;
                if (std.mem.eql(u8, span.target, "allarme")) alarm_actions += 1;
            }
        }
        if (block.kind == .definition) {
            const expected: []const u8 = if (definitions == 0) "allarmare, dare l' allarme" else "(senso figurato) allarmare, mettere in apprensione <in allarme>, suscitare l' allarme";
            try std.testing.expectEqualStrings(expected, std.mem.trim(u8, text.items, " \t\r\n"));
            definitions += 1;
        }
    };
    try std.testing.expectEqual(@as(usize, 1), flag_occurrences);
    try std.testing.expectEqual(@as(usize, 1), book_occurrences);
    try std.testing.expectEqual(@as(usize, 2), definitions);
    try std.testing.expectEqual(@as(usize, 2), in_actions);
    try std.testing.expectEqual(@as(usize, 3), alarm_actions);
    try std.testing.expect(headword and figurative);
}


test "complete Finnish morphology appendix preserves supplemental body tables actions references and codec" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const title = "Liite:Viron kielen kielioppi/Sanamuotojen muodostaminen";
    const source = "'''LUONNOS'''\n\nTämä esitys perustuu teoksen \"Eesti keele käsiraamat\" ['''EKKR'''] <sup>[http://www.eki.ee/books/ekk09/ EKI / ekk09]</sup> näkemykseen asiasta. Monia muitakin tapoja on.\n\nViron kirjakielen normin, \"Eesti õigekekeelsussõnaraamat\" esitys teemamuodoista ja analogiamuodoista: [http://www.eki.ee/dict/qs2013/qs2013.html '''ÕS 2013''' / PÕHIVORMID]\n\n== Työkaluja ==\n\n* '''Eesti keele süntesaator / EKI''' [http://www.filosoft.ee/gene_et/]\n: Viron sanojen taivutusmuotojen luonti.\n* '''Eesti keele morfanalüsaator / EKI''' [http://www.filosoft.ee/html_morf_et/]\n: Viron sanojen taivutusmuotojen rakenteen analysointi.\n\n== Sanamuotojen rakenne ==\n\n=== Alkumuoto ===\n\nViron kielen sana voi eri taivutusmuodoissa muuttua monin eri tavoin. Sanamuotojen perustaksi täytyy valita yksi kiinteä sanan tai sanan vartalon muoto, jonka perusteella esitetään säännöt sanan muiden muotojen muodostamiseksi. Tämä on '''alkumuoto'''  (''algvorm'')\n\n* Nominien alkumuoto on yksikön nominatiivi, esimerkiksi ''siil, mõte, kirjanik, .tantsijatar''\n\n* Verbien alkumuoto  on ''ma''-infinitiivin vartalo ennen infinitiivin tunnusta: ''ela(ma), näge(ma)'')\n\n; Lähteet\n* [http://www.eki.ee/books/ekk09/index.php?p=3&p1=2&id=120 EKKR M 18 Algvorm]\n* [[EKG]] osa 1, § 93 s.121\n\n=== Teemamuodot ja analogiamuodot ===\n \nMonet sanan taivutusmuodoista muodostuvat kaikissa sanoissa samojen perusteiden mukaan. Näiden \"johdettujen\" muotojen muodostamiseen ei kuitenkaan pelkkä sanan alkumuoto riitä. Lisäksi täytyy tietää  sanan '''teemamuodot''' (''põhivorm'') [\"perusmuoto\"]. \n\nSanojen kaikki taivutusmuodot koostuvat näistä teemamuodoista ja niiden perusteella johdettavista '''analogiamuodoista''' (''analoogiavorm'').\n\nAnalogiamuotojen johtamiseksi teemamuodoista täytyy tuntea kyseisen sanan tai sanan taivutustyypin muotojen muodostamiseen liittyvät '''säännöt''' ja tuntea '''poikkeukset'''.\n\n\n; Lähteet\n\n* [http://www.eki.ee/books/ekk09/index.php?p=3&p1=2&id=122 EKKR M 20 Põhivormid ja analoogiavormid]\n\n==== Nominien teemamuodot ====\n* yksikön nominatiivi (''ainsuse nimetav'')\n* yksikön genetiivi (''ainsuse omastav''\n* yksikön partitiivi (''ainsuse osastav'')\n* yksikön lyhyt illatiivi, aditiivi (''lühike ainsuse sisseütlev'')\n* monikon genetiivi (''mitmuse omastav'')\n* monikon partitiivi (''mitmuse osastav'')\n \nTeemamuotojen ja niiden vartaloiden perusteella voidaan muodostaa sanan kaikki sijamuodot:\n\n:: Yksikön nominatiivi → yksilöllinen\n:: Yksikön partitiivi → yksilöllinen\n:: Yksikön lyhyt illatiivi → yksilöllinen\n:: Yksikön genetiivi → yksikön sijamuodot ''sse''-illatiivista alkaen ja monikon nominatiivi\n:: Monikon genetiivi → ''de''-monikon muodot illatiivista alkaen\n:: Monikon partitiivi → vokaalimonikon muodot, muunnoksia voi esiintyä\n\nYksilöllisten teemamuotojen perusteella ei voi muodostaa muita muotoja.\n\n; Lähteet \n# [http://www.eki.ee/books/ekk09/index.php?p=3&p1=5&id=226 EKKR M 111 Analoogiaseosed käändsõna paradigmas]\n\n==== Verbien teemamuodot ====\n* Verbin taivutusmuodot, katso [http://www.eki.ee/dict/qs2013/qs2013.html ÕS 2013 Käändsõna vormistik]\n\n'''TEEMAMUODOT'''\n* ''ma''-infinitiivi [esim. '''lugema''']\n* ''da''-infinitiivi ['''lugeda''']\n* indikatiivin preesensin yksikön 3. persoona ['''loeb''']<sup>SVSSK</sup>\n* indikatiivin preesensin passiivi (kindla kõneviisi umbisikulise tegumoe olevik) ['''loetakse'''\n\n; Esimerkkejä\n\nTämän esityksen esimerkkiverbi '''lubama'''<br />\n: rakennesimerkkejä ''<elama, kinkima, vestlema, hüppama>''<br />\n\n\n* ''ma''-infinitiivi (''ma''-tegevusnimi) '''lubama'''\n: <esim. ''ela/ma, kinki/ma, vestle/ma>\n\n* ''da''-infinitiivi (''da''-tegevusnimi) '''lubada'''\n: <''ela/da, kinki/da, vestel/da, hüpa/ta''>\n\n* indikatiivin preesensin yksikön 3. persoonan muoto (kindla kõneviisi oleviku ainsuse 3. pööre) '''loeb'''\n: <''ela/b, kinki/b, vestle/b, hüppa/b''>\n\n* indikatiivin preesensin passiivi (kindla kõneviisi umbisikulise tegumoe olevik) '''lubatakse'''\n: <ela/takse, kingi/takse, veste/dakse'' > <br />[aikaisemmin passiivin partisiipin preesens, ''tud''-partisiippi '''lubatud'''>]\n\nTeemamuotojen ja niiden vartaloiden perusteella voidaan muodostaa verbien muut muodot:\n\n''' ''ma''-infinitiivi →'''\n:: ''ma''-infinitiivin sijamuodot (''käändevormid'')\n::: <''luba/mas, ela/mas, kinki/mas, vestle/mas>\n::: <''luba/mast, ela/mast, kinki/mast, vestle/mast''>\n::: <''luba/maks, ela/maks, kinki/maks, vestle/maks''>\n::: <''luba/mata, ela/mata, kinki/mata, vestle/mata''>\n:: aktiivin indikatiivin imperfekti (''isikulise tegumoe kindla kõneviisi lihtminevik'')<br />\n:::<''luba/sin, ela/sin, kinki/sin, vestle/sin''<\n:: kvotatiivin preesens (''kaudse kõneviisi olevik'') [epäsuoran tapaluokan preesens]<br />\n:::<''ela/vat, kinki/vat, vestle/vat'')\n:: aktiivin partisiipin preesens (''isikulise tegumoe oleviku kesksõna'') [''v''-partisiippi]\n:::<''ela/v, kinki/v, vestle/v''> <br />\n''' ''da''-infinitiivi →'''\n:: ''des''-muoto (''des''-vorm)\n::: <''ela/des, kinki/des, vestel/des''>\n:: imperatiivin yksikön 3. persoona (''käskiva kõneviisi ainsuse 3. pööre'')\n:: imperatiivin monikko (''käskiva kõneviisi mitmus'')\n:: jussiivin preesens (''möönva kõneviisi olevik'') [epäsuoran imperatiivin preesens]\n:: aktiivin partisiipin perfekti (''isikulise tegumoe mineviku kesksõna) [''nud''-partisiippi]\n:: konditionaalin perfekti (''tingiva kõneviisi minevik'')\n:: kvotatiivin perfekti (''kaudse kõneviisi minevik'')\n\n'''indikatiivin preesensin yksikön 3. persoona →'''\n:: muut indikatiivin preesensin muodot (''kindla kõneviisi oleviku pöörded'')\n:: imperatiivin yksikön 2. persoona (''käskiva kõneviisi ainsuse 2. pööre'')\n:: konditionaalin preesens (''tingiva kõneviisi olevik'')\n\n''' preesensin passiivi →'''\n:: muut passiivin muodot (''umbisikulise tegumoe vormid'')\n\nLisäksi on 27 epäsäännöllstä verbiä, joiden muodostamiseen edelläolevat teema- ja analogiamuodot eivät riitä: [[laskma]], [[pidama]], [[pesema]], [[kusema]], [[tegema]], [[nägema]], [[tulema]], [[panema]], [[sure­ma]], [[olema]], [[minema]] sekä 16 [[võima]]-, [[saama]]-, [[käima]]- ja [[jooma]]-tyyppien  verbiä.\n\n\n; Lähteet\n* [http://www.eki.ee/books/ekk09/index.php?p=3&p1=5&id=227 EKKR M 112 Analoogiaseosed pöördsõna paradigmas]\n\n== Esimerkkejä ==\n\n====== Nominien teemamuodot ja analogiamuodot ======\n\n;Lähde:\nEesti keele Käsiraamat '''[[:Liite:Lähteet#EKKR|EKKR]]'''\n\n; Selityksiä\n* [.] esimerkiksi [.jalg],  piste tavun edessä = III kestoaste\n\n{| class=\"wikitable\"\n|-\n| '''yksikön nominatiivi''' || '''.jalg''' || '''saabas''' || '''kala'''\n|}\n\n{| class=\"wikitable\"\n|-\n| '''yksikön genetiivi''' || '''jala''' || '''.saapa''' || '''kala'''\n|-\n| yksikön illatiivi || jala/sse || .saapa/sse || kala/sse\n|-\n| yksikön inessiivi || jala/s || .saapa/s || kala/s\n|-\n| yksikön elatiivi  || jala/st || .saapa/st || kala/st\n|-\n| yksikön allatiivi || jala/le || .saapa/le || kala/le\n|-\n| yksikön adessiivi || jala/l || .saapa/l || kala/l\n|-\n| yksikön ablatiivi || jala/lt  || .saapa/lt || kala/lt\n|-\n| yksikön translatiivi || jala /ks || .saapa/ks ||kala/ks\n|-\n| yksikön terminatiivi || jala/ni || .saapa/ni || kala/ni\n|-\n| yksikön essiivi || jala/na  || .saapa/na || kala/na\n|-\n| yksikön abessiivi || jala/ta || .saapa/ta || kala/ta\n|-\n| yksikön komitatiivi || jala/ga  || .saapa/ga || kala/ga\n|-\n| monikon nominatiivi || jala/d || .saapad ||kala/d\n|}\n\n{| class=\"wikitable\"\n|-\n| '''yksikön partitiivi''' || '''.jalga''' || '''saabast''' || '''kala'''\n|}\n\n{| class=\"wikitable\"\n|-\n| '''yksikön lyhyt illatiivi''' || '''.jalga''' ||   x  ||  x   \n|}\n\n{| class=\"wikitable\"\n|-\n| '''monikon genetiivi''' || .jalga/de || saabas/te || kala/de\n|-\n| monikon illatiivi || .jalga/desse || saabas/tesse ||kala/desse\n|-\n| monikon inessiivi || .jalga/des || saabas/tes || kala/des\n|-\n| monikon elatiivi || .jalga/dest || saabas/test ||kala/dest\n|-\n| monikon allatiivi || .jalga.dele || saabas/tele || kala/dele\n|-\n| monikon adessiivi || .jalga/del || saabas/tel || kala/del\n|-\n| monikon monikon ablatiivi || .jalga/delt || saabas/telt || kala/delt\n|-\n| monikon translatiivi || .jalga/deks || saabas/teks || kala/deks\n|-\n| monikon terminatiivi || .jalga/deni || saabas/teni || kala/deni\n|-\n| monikon essiivi || .jalga/dena || saabas/tena || kala/dena\n|-\n| monikon abessiivi || .jalga/deta || saabas/teta || kala/deta \n|-\n| monikon komitatiivi || .jalga/dega || saabas/tega || kala/dega\n|}\n\n{| class=\"wikitable\"\n|-\n| '''monikon partitiivi''' || '''.jalga''' <br /> '''.jalga/sid''' || '''.saapa/id''' || '''kalu''' <br /> '''kala/sid'''\n|-\n| vokaalimonikon illatiivi ||  x || .saapa/isse ||  x\n|-\n| vokaalimonikon inessiivi ||  x || .saapa/is ||  x\n|-\n| vokaalimonikon elatiivi ||   x || .saapa/ist ||  x\n|-\n| vokaalimonikon allatiivi ||  x || .saapa/ile ||  x\n|-\n| vokaalimonikon adessiivi ||  x || .saappa/il ||  x\n|-\n| vokaalimoniko ablatiivi ||  x || .saapa/ilt ||  x\n|-\n| vokaalimonikon translatiivi ||  x || .saapa/iks ||  x\n|-\n| vokaalimonikon terminatiivi ||  x || .saapa/ini ||  x\n|-\n| vokaalimonikon essiivi ||  x || .saapa/ina  ||  x\n|}\n\n===== Verbien teemamuodot ja analogiamuodot =====\n* Katso [https://docs.google.com/document/d/1rqPfqNBO7aRQPHTpG1KGaHvNMcA06iydtqdd_4omTRU/edit#heading=h.q56y9lhx2il3 Viron verbien teemamuodot ja analogiamuotojen muodostaminen]\n\n== Kirjallisuus ==\n* [[EKG]] '''Eesti keele grammatika'''. 1, Morfoloogia ; Sõnamoodustus / Mati Erelt ... [et al.] ; trükki toimetanud Mati Erelt ... [et al.]. – Tallinn : Eesti Teaduste Akadeemia Keele ja Kirjanduse Instituut, 1995. 659 s. – ISBN 9985-9002-2-7\n\n\n* [[:Liite:Lähteet#EKKR|EKKR]] '''Eesti keele käsiraamat''' / Mati Erelt, Tiiu Erelt, Kristiina Ross Tallinn : Eesti Keele Sihtasutus, 2007 (Tallinn : Pakett) 726 lk. – 21 cm ISBN/ISSN: 9789985792100<br />\n::Verkkoversio [http://www.eki.ee/books/ekk09/ Eesti keele käsiraamat]\n* '''Viron kielioppi''' / Hannu Remes : Werner Söderström Osakeyhtiö, Porvoo 1983 : ISBN 951-0-11982-2\n* [http://herkules.oulu.fi/isbn9789514291500/isbn9789514291500.pdf '''Muodot kontrastissa'''. Suomen ja viron vertailevaa taivutusmorfologiaa / Hannu Remes 2009 ISBN 978-951-42-9150-0 (PDF)] ladattava PDF";
    const namespace_source = "# wikidict-namespace-registry-v1\n# wiki\tfiwiktionary\n# dump-date\t20261001\n# content-language\tfi\n-2\tMedia\tMedia\tcase-sensitive\t0\t0\t0\t\tcompile_only\tvirtual_namespace\n-1\tToiminnot\tSpecial\tfirst-letter\t0\t0\t0\t\tcompile_only\tvirtual_namespace\n0\t\t\tcase-sensitive\t0\t1\t0\t\tmain\tdictionary_entries\n1\tKeskustelu\tTalk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n2\tKäyttäjä\tUser\tfirst-letter\t1\t0\t0\t\tcompile_only\tstandard_build_input\n3\tKeskustelu käyttäjästä\tUser talk\tfirst-letter\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n4\tWikisanakirja\tProject\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\tWT\tWiktionary\n5\tKeskustelu Wikisanakirjasta\tProject talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\tWiktionary talk\n6\tTiedosto\tFile\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\tImage\tKuva\n7\tKeskustelu tiedostosta\tFile talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\tImage talk\tKeskustelu kuvasta\n8\tJärjestelmäviesti\tMediaWiki\tfirst-letter\t1\t0\t0\t\tcompile_only\tstandard_build_input\n9\tKeskustelu järjestelmäviestistä\tMediaWiki talk\tfirst-letter\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n10\tMalline\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n11\tKeskustelu mallineesta\tTemplate talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n12\tOhje\tHelp\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n13\tKeskustelu ohjeesta\tHelp talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n14\tLuokka\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\n15\tKeskustelu luokasta\tCategory talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n100\tLiite\tLiite\tcase-sensitive\t1\t0\t0\t\tsupplemental\tunclassified_subject_retained\n101\tKeskustelu liitteestä\tKeskustelu liitteestä\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n710\tTimedText\tTimedText\tcase-sensitive\t0\t0\t0\t\tcompile_only\tancillary_site_input\n711\tTimedText talk\tTimedText talk\tcase-sensitive\t0\t0\t0\t\tcompile_only\tdiscussion_namespace\n828\tModuuli\tModule\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n829\tKeskustelu moduulista\tModule talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n1728\tEvent\tEvent\tcase-sensitive\t1\t0\t0\t\tcompile_only\tancillary_site_input\n1729\tEvent talk\tEvent talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n";
    try std.testing.expectEqual(@as(usize, 10225), source.len);
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(source, &digest, .{});
    try std.testing.expectEqualStrings("aaf2e0d65bec4ae0436cd1691a9d592aaac864ac7a4511a95149dd59b50f0b1e", &std.fmt.bytesToHex(digest, .lower));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, source, "<esim. ''ela/ma, kinki/ma, vestle/ma>"));
    const reference = try std.mem.replaceOwned(u8, a, source, "<esim.", "&lt;esim.");
    var namespaces = try @import("namespace_registry").Registry.init(a, namespace_source);
    defer namespaces.deinit();
    const codes: LanguageCodes = .{ .namespace_catalog = &namespaces };
    var payloads: [2][]const u8 = undefined;
    for ([_][]const u8{ source, reference }, 0..) |body, i| {
        const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/fi-morphology-{d}", .{ tmp.sub_path, i });
        var writer = try Writer.init(std.testing.io, a, root);
        defer writer.deinit();
        writer.language_codes = codes;
        try writer.addExpandedPage(a, .{ .id = 100, .kind = .supplemental }, title, body, source, null);
        const stats = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, 1), stats.supplemental_records);
        try std.testing.expectEqual(@as(usize, 0), stats.language_records);
        var mapped = try mmapPath(std.testing.io, try std.fs.path.join(a, &.{ root, "supplemental.wikblb" }));
        defer mapped.deinit();
        const blob = try blob_format.inspect(mapped.bytes);
        try std.testing.expect(blob.kind == .supplemental);
        var index = try blob.buildTrustedIndexAlloc(a);
        defer index.deinit(a);
        const record = (try index.find(title)) orelse return error.TestUnexpectedResult;
        payloads[i] = try a.dupe(u8, record.payload);
    }
    try std.testing.expectEqualSlices(u8, payloads[1], payloads[0]);
    const stored = try blobs.presentation_codec.decodeAlloc(a, payloads[0], title, .supplemental, null);
    try std.testing.expectEqualSlices(u8, payloads[0], try blobs.presentation_codec.encodeAlloc(a, stored));
    try std.testing.expectEqualStrings(title, stored.entry.title);
    try std.testing.expect(stored.entry.language == null and stored.entry.language_code.len == 0);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.references.len);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.media.len);
    const Scan = struct {
        tables: usize = 0,
        rows: usize = 0,
        cells: usize = 0,
        visible: std.ArrayList(u8) = .empty,
        targets: std.ArrayList([]const u8) = .empty,
        italic_example: bool = false,
        bold_draft: bool = false,
        fn spans(self: *@This(), allocator: std.mem.Allocator, values: []const blobs.presentation_types.Span) !void {
            for (values) |span| {
                try self.visible.appendSlice(allocator, span.text);
                if (span.kind == .line_break) try self.visible.append(allocator, '\n');
                if (span.kind == .link or span.kind == .external_link) try self.targets.append(allocator, span.target);
                self.italic_example = self.italic_example or (span.italic and std.mem.indexOf(u8, span.text, "ela/ma, kinki/ma, vestle/ma") != null);
                self.bold_draft = self.bold_draft or (span.bold and std.mem.eql(u8, span.text, "LUONNOS"));
            }
        }
        fn blocks(self: *@This(), allocator: std.mem.Allocator, values: []const blobs.presentation_types.Block) anyerror!void {
            for (values) |block| {
                if (block.table) |table_value| {
                    self.tables += 1;
                    self.rows += table_value.rows.len;
                    for (table_value.rows) |row| for (row.cells) |cell| {
                        self.cells += 1;
                        if (cell.blocks) |children| try self.blocks(allocator, children) else try self.spans(allocator, cell.spans);
                    };
                } else try self.spans(allocator, block.spans);
                try self.visible.append(allocator, '\n');
            }
        }
    };
    var scan: Scan = .{};
    for (stored.entry.sections) |section| try scan.blocks(a, section.blocks);
    try std.testing.expectEqual(@as(usize, 6), scan.tables);
    try std.testing.expectEqual(@as(usize, 38), scan.rows);
    try std.testing.expectEqual(@as(usize, 152), scan.cells);
    try std.testing.expect(scan.italic_example and scan.bold_draft);
    for ([_][]const u8{ "<esim. ela/ma, kinki/ma, vestle/ma>", "<elama, kinkima, vestlema, hüppama>", "<ela/da, kinki/da, vestel/da, hüpa/ta>", "Verkkoversio", "978-951-42-9150-0" }) |text|
        try std.testing.expect(std.mem.indexOf(u8, scan.visible.items, text) != null);
    for ([_][]const u8{ "laskma", "pidama", "pesema", "kusema", "tegema", "nägema", "tulema", "panema", "olema", "minema", "võima", "saama", "käima", "jooma", "EKG", "Liite:Lähteet#EKKR", "http://www.eki.ee/books/ekk09/" }) |target| {
        var found = false;
        for (scan.targets.items) |actual| if (std.mem.eql(u8, actual, target)) { found = true; break; };
        try std.testing.expect(found);
    }
}


test "captured alarmowac preserves Polish owner verb senses both linked angles and complete codec body" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // Complete retained p164655/r3372809; no re-expansion.
    const raw = "== {{-pl-}} ==\n{{-verb-|pl}}\n{{Pn}}\n# [[allarmare]], [[dare]] [[l']] [[allarme]]\n# {{Fig}} [[allarmare]], [[mettere]] [[in]] [[apprensione]] <[[in]] [[allarme]]>, [[suscitare]] [[l']] [[allarme]]";
    const expanded = "==  [[File:Flag_of_Poland.svg|border|40px]] [[polacco|Polacco]] ==\n===[[Image:Open_book_01.svg|30px|]]''[[verbo|Verbo]]''===\n[[Categoria:Verbi in polacco]] \n\n'''alarmować'''<small></small>\n# [[allarmare]], [[dare]] [[l']] [[allarme]]\n# <small>(''senso figurato'')</small> [[allarmare]], [[mettere]] [[in]] [[apprensione]] <[[in]] [[allarme]]>, [[suscitare]] [[l']] [[allarme]]";
    const namespace_source = "# wikidict-namespace-registry-v1\n# wiki\titwiktionary\n# dump-date\t20261001\n# content-language\tit\n-2\tMedia\tMedia\tcase-sensitive\t0\t0\t0\t\tcompile_only\tvirtual_namespace\n-1\tSpeciale\tSpecial\tfirst-letter\t0\t0\t0\t\tcompile_only\tvirtual_namespace\n0\t\t\tcase-sensitive\t0\t1\t0\t\tmain\tdictionary_entries\n1\tDiscussione\tTalk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n2\tUtente\tUser\tfirst-letter\t1\t0\t0\t\tcompile_only\tstandard_build_input\n3\tDiscussioni utente\tUser talk\tfirst-letter\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n4\tWikizionario\tProject\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\tWT\tWZ\tWiktionary\n5\tDiscussioni Wikizionario\tProject talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\tWiktionary talk\n6\tFile\tFile\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\tImage\tImmagine\n7\tDiscussioni file\tFile talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\tDiscussioni immagine\tImage talk\n8\tMediaWiki\tMediaWiki\tfirst-letter\t1\t0\t0\t\tcompile_only\tstandard_build_input\n9\tDiscussioni MediaWiki\tMediaWiki talk\tfirst-letter\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n10\tTemplate\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n11\tDiscussioni template\tTemplate talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n12\tAiuto\tHelp\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n13\tDiscussioni aiuto\tHelp talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n14\tCategoria\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\n15\tDiscussioni categoria\tCategory talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n100\tAppendice\tAppendice\tcase-sensitive\t1\t0\t0\t\tsupplemental\tunclassified_subject_retained\n101\tDiscussioni appendice\tDiscussioni appendice\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n710\tTimedText\tTimedText\tcase-sensitive\t0\t0\t0\t\tcompile_only\tancillary_site_input\n711\tTimedText talk\tTimedText talk\tcase-sensitive\t0\t0\t0\t\tcompile_only\tdiscussion_namespace\n828\tModulo\tModule\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n829\tDiscussioni modulo\tModule talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n1728\tEvento\tEvent\tcase-sensitive\t1\t0\t0\t\tcompile_only\tancillary_site_input\n1729\tDiscussioni evento\tEvent talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n";
    try std.testing.expectEqual(@as(usize, 195), raw.len);
    try std.testing.expectEqual(@as(usize, 377), expanded.len);
    var namespaces = try @import("namespace_registry").Registry.init(a, namespace_source);
    defer namespaces.deinit();
    const Authority = struct {
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            // Exact installed pl/polacco/Polacco row, not the edition's language.
            for ([_][]const u8{ "polacco", "Polacco", "Polski", "polski", "pl", "Polish", "pol" }) |label|
                if (std.mem.eql(u8, value, label)) return .{ .code = "pl", .heading = "polacco" };
            return null;
        }
        fn get(ctx: ?*const anyopaque, value: []const u8) ?[]const u8 {
            return (resolve(ctx, value) orelse return null).code;
        }
    };
    const codes: LanguageCodes = .{ .namespace_catalog = &namespaces, .get_fn = Authority.get, .resolve_fn = Authority.resolve, .trusted_fn = Authority.resolve };
    const reference = try std.mem.replaceOwned(u8, a, expanded, "<[[in]]", "&lt;[[in]]");
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/actual", .{tmp.sub_path});
    const reference_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/reference", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    var reference_writer = try Writer.init(std.testing.io, a, reference_root);
    defer reference_writer.deinit();
    reference_writer.language_codes = codes;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "alarmować", expanded, raw, null);
    try reference_writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "alarmować", reference, raw, null);
    const stats = try writer.finish(codes);
    const expected_stats = try reference_writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);
    try std.testing.expectEqual(@as(usize, 1), stats.language_blobs);
    try std.testing.expectEqual(stats.language_records, expected_stats.language_records);
    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "polacco"));
    defer mapped.deinit();
    var expected_mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, reference_root, "polacco"));
    defer expected_mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    const expected_blob = try blob_format.inspect(expected_mapped.bytes);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    var expected_index = try expected_blob.buildTrustedIndexAlloc(a);
    defer expected_index.deinit(a);
    const record = (try index.find("alarmować")).?;
    const expected_record = (try expected_index.find("alarmować")).?;
    try std.testing.expectEqualSlices(u8, expected_record.payload, record.payload);
    const stored = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
    try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, stored));
    try std.testing.expectEqualStrings("pl", stored.entry.language_code);
    try std.testing.expectEqualStrings("polacco", stored.entry.language.?);
    try std.testing.expectEqual(@as(usize, 1), stored.entry.organization.lexemes.len);
    const lexeme = stored.entry.organization.lexemes[0];
    try std.testing.expectEqualStrings("Verb", lexeme.kind);
    try std.testing.expectEqual(@as(usize, 2), lexeme.definitions.len);
    try std.testing.expectEqualStrings("Verbo", stored.entry.sections[lexeme.section].title);
    try std.testing.expectEqual(@as(u8, 3), stored.entry.sections[lexeme.section].level);
    try std.testing.expectEqual(@as(usize, 2), stored.entry.media.len);
    var flag_image = false;
    var book_image = false;
    for (stored.entry.media) |item| {
        flag_image = flag_image or std.mem.eql(u8, item.file, "Flag of Poland.svg");
        book_image = book_image or std.mem.eql(u8, item.file, "Open book 01.svg");
    }
    try std.testing.expect(flag_image and book_image);
    var definitions: usize = 0;
    var figurative: usize = 0;
    var headword = false;
    var in_actions: usize = 0;
    var alarm_actions: usize = 0;
    for (stored.entry.sections) |section| for (section.blocks) |block| {
        var text: std.ArrayList(u8) = .empty;
        for (block.spans) |span| {
            try text.appendSlice(a, span.text);
            if (span.bold and std.mem.eql(u8, span.text, "alarmować")) headword = true;
            if (std.mem.eql(u8, span.text, "senso figurato")) {
                // Authored <small> uses the numeric size contract, not the legacy flag.
                try std.testing.expect(span.italic);
                try std.testing.expect(!span.small);
                try std.testing.expectApproxEqAbs(@as(f32, 1.0 / 1.2), span.font_scale orelse return error.TestUnexpectedResult, 0.000001);
                figurative += 1;
            }
            if (block.kind == .definition and span.kind == .link) {
                if (std.mem.eql(u8, span.target, "in")) in_actions += 1;
                if (std.mem.eql(u8, span.target, "allarme")) alarm_actions += 1;
            }
        }
        if (block.kind == .definition) {
            const expected: []const u8 = if (definitions == 0) "allarmare, dare l' allarme" else "(senso figurato) allarmare, mettere in apprensione <in allarme>, suscitare l' allarme";
            try std.testing.expectEqualStrings(expected, std.mem.trim(u8, text.items, " \t\r\n"));
            definitions += 1;
        }
    };
    try std.testing.expectEqual(@as(usize, 2), definitions);
    try std.testing.expectEqual(@as(usize, 2), in_actions);
    try std.testing.expectEqual(@as(usize, 3), alarm_actions);
    try std.testing.expect(headword);
    try std.testing.expectEqual(@as(usize, 1), figurative);
}

test "normal Writer retained Tswana nnyaa preserves complete body and explicit owner" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // Complete p1963/r7738; original local XML source SHA1 445687e4..., no templates.
    const source = "'''Tswana:''' nnyaa\n<br>\n<br>\n'''''Translations'''''\n<br>\n'''English:''' no\n<br>\n'''Afrikaans:''' nee\n\n[[Category:Setswana]]";
    try std.testing.expectEqual(@as(usize, 124), source.len);
    var source_digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(source, &source_digest, .{});
    try std.testing.expectEqualStrings("b110bef6c1fe6e306ca94d88c2ff5dde11a0eb41e74c8f36aeaaee52f09cac2f", &std.fmt.bytesToHex(source_digest, .lower));
    const namespace_source = "# wikidict-namespace-registry-v1\n# wiki\ttnwiktionary\n# dump-date\t20261001\n# content-language\ttn\n-2\tPego\tMedia\tcase-sensitive\t0\t0\t0\t\tcompile_only\tvirtual_namespace\n-1\tFaphegileng\tSpecial\tfirst-letter\t0\t0\t0\t\tcompile_only\tvirtual_namespace\n0\t\t\tcase-sensitive\t0\t1\t0\t\tmain\tdictionary_entries\n1\tPuisano\tTalk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n2\tModirisi\tUser\tfirst-letter\t1\t0\t0\t\tcompile_only\tstandard_build_input\n3\tPuisano ya modirisi\tUser talk\tfirst-letter\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n4\tWiktionary\tProject\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\tWT\n5\tPuisano ya Wiktionary\tProject talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\tWiktionary talk\n6\tSetshwantsho\tFile\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\tImage\n7\tPuisano ya setshwantsho\tFile talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\tImage talk\n8\tMediaWiki\tMediaWiki\tfirst-letter\t1\t0\t0\t\tcompile_only\tstandard_build_input\n9\tPuisano ya MediaWiki\tMediaWiki talk\tfirst-letter\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n10\tTempolete\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n11\tPuisano ya tempolete\tTemplate talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n12\tThuso\tHelp\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n13\tPuisano ya thuso\tHelp talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n14\tKarolo\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\n15\tPuisano ya karolo\tCategory talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n710\tTimedText\tTimedText\tcase-sensitive\t0\t0\t0\t\tcompile_only\tancillary_site_input\n711\tTimedText talk\tTimedText talk\tcase-sensitive\t0\t0\t0\t\tcompile_only\tdiscussion_namespace\n828\tModule\tModule\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n829\tModule talk\tModule talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n1728\tEvent\tEvent\tcase-sensitive\t1\t0\t0\t\tcompile_only\tancillary_site_input\n1729\tEvent talk\tEvent talk\tcase-sensitive\t1\t0\t0\t\tcompile_only\tdiscussion_namespace\n";
    var namespace_digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(namespace_source, &namespace_digest, .{});
    try std.testing.expectEqualStrings("4e2a809d7d4e448524b6e526c8f37d24201efc2e5813155be781ba421c4ee2ec", &std.fmt.bytesToHex(namespace_digest, .lower));
    var namespaces = try @import("namespace_registry").Registry.init(a, namespace_source);
    defer namespaces.deinit();
    const Fixture = struct {
        // Exact rows from published registry ffb51dab...; names are not edition defaults.
        const rows = [_][]const u8{ "af\tSeburu\tAfrikaans\taf\tafr", "en\tSekgoa\tEnglish\ten\teng", "tn\tSetswana\ttn\tTswana\ttsn" };
        fn resolve(_: ?*const anyopaque, label_text: []const u8) ?ResolvedLanguage {
            for (rows) |row| {
                var fields = std.mem.splitScalar(u8, row, '\t');
                const code_value = fields.next().?;
                const preferred = fields.next().?;
                if (std.mem.eql(u8, label_text, code_value) or std.mem.eql(u8, label_text, preferred))
                    return .{ .code = code_value, .heading = preferred };
                while (fields.next()) |alias_name| if (std.mem.eql(u8, label_text, alias_name))
                    return .{ .code = code_value, .heading = preferred };
            }
            return null;
        }
        // Exact normal-loader02 outcomes: Tswana and tn are ordinary only.
        fn trusted(ctx: ?*const anyopaque, label_text: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, label_text, "Setswana") or std.mem.eql(u8, label_text, "English") or std.mem.eql(u8, label_text, "Afrikaans"))
                return resolve(ctx, label_text);
            return null;
        }
        fn get(ctx: ?*const anyopaque, label_text: []const u8) ?[]const u8 {
            return if (resolve(ctx, label_text)) |language| language.code else null;
        }
    };
    const codes: LanguageCodes = .{ .namespace_catalog = &namespaces, .get_fn = Fixture.get, .resolve_fn = Fixture.resolve, .trusted_fn = Fixture.trusted };
    try std.testing.expect(codes.resolveStrong("Tswana") == null);
    try std.testing.expect(codes.resolveTrusted("Tswana") == null);
    try std.testing.expectEqualStrings("tn", codes.resolve("Tswana").?.code);
    try std.testing.expectEqualStrings("tn", codes.resolveTrusted("Setswana").?.code);
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/blobs", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "nnyaa", source, source, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);
    try std.testing.expectEqual(@as(usize, 1), stats.language_blobs);
    try std.testing.expectEqual(@as(usize, 0), stats.fallback_pages);
    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "Setswana"));
    defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    const metadata = try blob.languageMetadata();
    try std.testing.expectEqualStrings("tn", metadata.code);
    try std.testing.expectEqualStrings("Setswana", metadata.heading);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    const record = (try index.find("nnyaa")).?;
    const stored = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
    try std.testing.expectEqualStrings("tn", stored.entry.language_code);
    try std.testing.expectEqualStrings("Setswana", stored.entry.language.?);
    try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, stored));
    // Whole original source under an independently explicit owner is the body oracle.
    const reference_bytes = try presentation_document.compileReportedWithOptionsAlloc(a, "nnyaa", .language, "Setswana", "tn", source, null, .{}, &namespaces, null, null, null);
    const reference = try blobs.presentation_codec.decodeAlloc(a, reference_bytes, "nnyaa", .language, .{ .code = "tn", .heading = "Setswana" });
    try std.testing.expectEqualDeep(reference, stored);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.organization.lexemes.len);
    try std.testing.expectEqualSlices(usize, &.{0}, stored.entry.organization.other_sections);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.references.len);
    try std.testing.expectEqual(@as(usize, 0), stored.entry.media.len);
    try std.testing.expectEqual(@as(usize, 1), stored.entry.sections.len);
    const section = stored.entry.sections[0];
    try std.testing.expectEqual(@as(usize, 1), section.blocks.len);
    const block = section.blocks[0];
    try std.testing.expect(block.kind == .paragraph and block.table == null);
    var visible: std.ArrayList(u8) = .empty;
    var breaks: usize = 0;
    var bold_runs: usize = 0;
    var italic_runs: usize = 0;
    for (block.spans) |span| {
        try std.testing.expect(span.kind == .text or span.kind == .line_break);
        try std.testing.expect(span.target.len == 0 and span.trail.len == 0 and span.image == null);
        try visible.appendSlice(a, span.text);
        if (span.kind == .line_break) breaks += 1;
        const bold_expected = std.mem.eql(u8, span.text, "Tswana:") or std.mem.eql(u8, span.text, "Translations") or std.mem.eql(u8, span.text, "English:") or std.mem.eql(u8, span.text, "Afrikaans:");
        const italic_expected = std.mem.eql(u8, span.text, "Translations");
        try std.testing.expectEqual(bold_expected, span.bold);
        try std.testing.expectEqual(italic_expected, span.italic);
        if (span.bold) bold_runs += 1;
        if (span.italic) italic_runs += 1;
    }
    try std.testing.expectEqualStrings("Tswana: nnyaa \n \n Translations \n English: no \n Afrikaans: nee", visible.items);
    try std.testing.expectEqual(@as(usize, 4), breaks);
    try std.testing.expectEqual(@as(usize, 4), bold_runs);
    try std.testing.expectEqual(@as(usize, 1), italic_runs);
}

test "Tsonga labelled headwords keep the complete ordinary Writer body under the corroborated owner" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var namespaces = try @import("namespace_registry").Registry.init(a,
        "# wikidict-namespace-registry-v1\n# wiki\ttswiktionary\n# dump-date\t20261001\n# content-language\tts\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\t\tmain\tdictionary_entries\n" ++
        "10\tTemplate\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n" ++
        "14\tCategory\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\n");
    defer namespaces.deinit();
    const Local = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "Xitsonga")) return .{ .code = "ts", .heading = "Xitsonga" };
            return null;
        }
    };
    const codes: LanguageCodes = .{ .namespace_catalog = &namespaces, .trusted_fn = Local.resolve, .resolve_fn = Local.resolve };
    const category = "[[Category:Marito a Xitsonga]]";
    const call = "{{-vuhundzuluxi-}}";
    const provider = "\n=====[[vuhundzuluxi|Vuhundzuluxi]]=====";
    const cases = [_]struct { title: []const u8, raw: []const u8 }{
        .{ .title = "ina", .raw = "'''Xitsonga:''' ina\n<br />\n<br />\n''{{-vuhundzuluxi-}}\n''\n<br />\n'''English:''' yes\n\n[[Category:Marito a Xitsonga]]" },
        .{ .title = "xuxa", .raw = "''Xitsonga:'' \txuxa\t<br /> <br /> {{-vuhundzuluxi-}}\n <br /> '''English:''' \tchat\n\n[[Category:Marito a Xitsonga]]" },
        .{ .title = "chava", .raw = "''Xitsonga: ku'' chava <br /> <br /> verb <br /> <br /> {{-vuhundzuluxi-}}\n  <br /> '''English/Xinghezi: ''' <br />1 fear, be afraid of, be or get frightened, dread, stand in awe of, panic. <br />2 respect, show respect for. Chava! look out! stand aside! make way! (Idiom) ~ malebvu ya nghala, -chavela ekule, be apprehensive of something from mere speculation. <br /> <br /> ---------------------------------------------------------------- <br /> return to:''  http://ts.wiktionary.org/wiki/Special:Allpages\n\n[[Category:Marito a Xitsonga]]" },
    };
    const baseline_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/before", .{tmp.sub_path});
    const fixed_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/after", .{tmp.sub_path});
    var baseline = try Writer.init(std.testing.io, a, baseline_root);
    defer baseline.deinit();
    var fixed = try Writer.init(std.testing.io, a, fixed_root);
    defer fixed.deinit();
    baseline.language_codes = codes;
    fixed.language_codes = codes;
    for (cases) |case| {
        const expanded = try std.mem.replaceOwned(u8, a, case.raw, call, provider);
        const without_category = try std.mem.replaceOwned(u8, a, case.raw, category, "");
        const owner = tsongaLabelledHeadword(codes, case.title, case.raw, .{ .bytes = expanded }) orelse return error.ExpectedLabelledOwner;
        try std.testing.expectEqualStrings("ts", owner.code);
        try std.testing.expect(tsongaLabelledHeadword(codes, "different", case.raw, .{ .bytes = expanded }) == null);
        try std.testing.expect(tsongaLabelledHeadword(codes, case.title, without_category, .{ .bytes = expanded }) == null);
        try std.testing.expect(tsongaLabelledHeadword(codes, case.title, case.raw, .{ .bytes = expanded, .unknown = true }) == null);
        try std.testing.expect(tsongaLabelledHeadword(codes, case.title, case.raw, .{ .bytes = expanded, .lost_missing_range = true }) == null);
        try std.testing.expect(tsongaLabelledHeadword(codes, case.title, case.raw, .{ .bytes = expanded, .generated_source = expanded }) == null);
        // Insert before the terminal category so each independently exercises its own refusal.
        for ([_][]const u8{ "==English==", "[[Category:English]]", provider, "{{unresolved}}" }) |extra| {
            const replacement = try std.mem.concat(a, u8, &.{ extra, "\n", category });
            const altered = try std.mem.replaceOwned(u8, a, expanded, category, replacement);
            try std.testing.expect(tsongaLabelledHeadword(codes, case.title, case.raw, .{ .bytes = altered }) == null);
        }
        try baseline.addExpandedPage(a, .{ .id = 0, .kind = .language }, case.title, expanded, without_category, null);
        try fixed.addExpandedPage(a, .{ .id = 0, .kind = .language }, case.title, expanded, case.raw, null);
    }
    _ = try baseline.finish(codes);
    _ = try fixed.finish(codes);
    var old = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, baseline_root, "Unclassified"));
    defer old.deinit();
    var new = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, fixed_root, "Xitsonga"));
    defer new.deinit();
    const old_blob = try blob_format.inspect(old.bytes);
    const new_blob = try blob_format.inspect(new.bytes);
    var old_index = try old_blob.buildTrustedIndexAlloc(a);
    defer old_index.deinit(a);
    var new_index = try new_blob.buildTrustedIndexAlloc(a);
    defer new_index.deinit(a);
    for (cases) |case| {
        const before = (try old_index.find(case.title)).?;
        const after = (try new_index.find(case.title)).?;
        const previous = try blobs.presentation_codec.decodeAlloc(a, before.payload, case.title, .language, try old_blob.languageMetadata());
        const current = try blobs.presentation_codec.decodeAlloc(a, after.payload, case.title, .language, try new_blob.languageMetadata());
        try std.testing.expectEqualStrings("ts", current.entry.language_code);
        try std.testing.expectEqualStrings("Xitsonga", current.entry.sections[0].title);
        try std.testing.expectEqualStrings("Unclassified", previous.entry.sections[0].title);
        try std.testing.expect(current.entry.sections.len >= 2);
        try std.testing.expectEqualStrings("Vuhundzuluxi", current.entry.sections[1].title);
        try std.testing.expectEqualDeep(previous.entry.sections[0].blocks, current.entry.sections[0].blocks);
        try std.testing.expectEqualDeep(previous.entry.sections[1..], current.entry.sections[1..]);
        try std.testing.expectEqualSlices(u8, after.payload, try blobs.presentation_codec.encodeAlloc(a, current));
    }
}

test "unsectioned plain bold prefix needs independent literal language authority" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var namespaces = try @import("namespace_registry").Registry.init(a,
        "# wikidict-namespace-registry-v1\n# wiki\totherwiktionary\n# dump-date\t20261001\n# content-language\ten\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\twikitext\tmain\tentries\n" ++
        "10\tTemplate\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n" ++
        "14\tKarolo\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tcategories\n");
    defer namespaces.deinit();
    const Local = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "Tswana") or std.mem.eql(u8, name, "Setswana")) return .{ .code = "tn", .heading = "Setswana" };
            if (std.mem.eql(u8, name, "English") or std.mem.eql(u8, name, "EnglishAlias")) return .{ .code = "en", .heading = "English" };
            if (std.mem.eql(u8, name, "Afrikaans")) return .{ .code = "af", .heading = "Afrikaans" };
            return null;
        }
        fn trusted(ctx: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "Setswana") or std.mem.eql(u8, name, "English") or std.mem.eql(u8, name, "Afrikaans"))
                return resolve(ctx, name);
            return null;
        }
        fn get(ctx: ?*const anyopaque, name: []const u8) ?[]const u8 {
            return if (resolve(ctx, name)) |owner| owner.code else null;
        }
    };
    const body = "'''Tswana:''' nnyaa\n<br>\n<br>\n'''''Translations'''''\n<br>\n'''English:''' no\n<br>\n'''Afrikaans:''' nee\n\n[[Category:Setswana]]";
    var codes: LanguageCodes = .{ .namespace_catalog = &namespaces, .get_fn = Local.get, .resolve_fn = Local.resolve, .trusted_fn = Local.trusted };
    try std.testing.expect(codes.resolveStrong("Tswana") == null and codes.resolveTrusted("Tswana") == null);
    try std.testing.expectEqualStrings("tn", unsectionedPlainBoldPrefixLanguage(codes, body, body).?.code);
    codes.trusted_fn = null;
    try std.testing.expect(unsectionedPlainBoldPrefixLanguage(codes, body, body) == null);
    codes.strong_fn = Local.trusted;
    try std.testing.expectEqualStrings("tn", unsectionedPlainBoldPrefixLanguage(codes, body, body).?.code);
    codes.strong_fn = null;
    codes.trusted_fn = Local.trusted;
    codes.resolve_fn = null;
    try std.testing.expect(unsectionedPlainBoldPrefixLanguage(codes, body, body) == null);
    codes.resolve_fn = Local.resolve;
    codes.namespace_catalog = null;
    try std.testing.expect(unsectionedPlainBoldPrefixLanguage(codes, body, body) == null);
    codes.namespace_catalog = &namespaces;
    try std.testing.expect(unsectionedPlainBoldPrefixLanguage(codes, null, body) == null);
    const negatives = [_][]const u8{
        "'''Unknown:''' word\n[[Category:Setswana]]",
        "'''Tswana:''' nnyaa",
        "'''Tswana:''' \n[[Category:Setswana]]",
        "'''Tswana:''' nnyaa\n[[Category:Unknown|Setswana]]",
        "'''Tswana:''' nnyaa\n[[Category:English|Setswana]]",
        "'''Tswana:''' nnyaa\n[[:Category:Setswana]]",
        "'''Tswana:''' nnyaa\n<!--[[Category:Setswana]]-->",
        "'''Tswana:''' nnyaa\n<nowiki>[[Category:Setswana]]</nowiki>",
        "'''Tswana:''' nnyaa\n<pre>[[Category:Setswana]]</pre>",
        "'''Tswana:''' nnyaa\n{{x|[[Category:Setswana]]}}",
        "'''Tswana:''' nnyaa\n[[Other:Setswana]]",
        "'''Tswana:''' nnyaa\n[[Category:Set]][[Category:swana]]",
        "'''Translations:''' words\n'''Tswana:''' nnyaa\n[[Category:Setswana]]",
        "prose\n" ++ body,
        "<!--note-->" ++ body,
        "\n" ++ body,
        "<nowiki>" ++ body ++ "</nowiki>",
        "<code>" ++ body ++ "</code>",
        "{{x|" ++ body ++ "}}",
        "'''''Tswana:''''' nnyaa\n[[Category:Setswana]]",
        "'''Ts<span>wa</span>na:''' nnyaa\n[[Category:Setswana]]",
        "'''Tswana:''' <b>nnyaa</b>\n[[Category:Setswana]]",
        "'''Tswana:''' {{word}}\n[[Category:Setswana]]",
        body ++ "\n[[Category:English]]",
        "'''Tswana:''' nnyaa\n[[Category:Tswana]]",
        body ++ "\n[[Category:EnglishAlias]]",
        body ++ "\n=Unknown=\nbody",
        body ++ "\n==Unknown==\nbody",
        body ++ "\n===Unknown===\nbody",
        body ++ "\n======Unknown======\nbody",
    };
    for (negatives) |uncertain| {
        try std.testing.expect(unsectionedPlainBoldPrefixLanguage(codes, uncertain, body) == null);
        try std.testing.expect(unsectionedPlainBoldPrefixLanguage(codes, body, uncertain) == null);
    }
    const foreign = "'''English:''' no\n[[Category:English]]";
    try std.testing.expect(unsectionedPlainBoldPrefixLanguage(codes, body, foreign) == null);
    try std.testing.expect(unsectionedPlainBoldPrefixLanguage(codes, foreign, body) == null);
    const alias_category = "'''Tswana:''' nnyaa\n[[Karolo:Setswana|English]]";
    try std.testing.expectEqualStrings("tn", unsectionedPlainBoldPrefixLanguage(codes, alias_category, alias_category).?.code);
}

test "Writer wiki-list DIV fragment kinds preserve owner cuts styles actions references and codec" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const codes = TestLanguages.codes();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/blobs", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    const cases = [_]struct { title: []const u8, attrs: []const u8, kind: presentation_document.FragmentPreContext.Kind, bold: bool }{
        .{ .title = "list-plain-div-cut", .attrs = "", .kind = .layout_div, .bold = false },
        .{ .title = "list-class-div-cut", .attrs = " class='Scope' style='font-weight:bold'", .kind = .css_block, .bold = true },
        .{ .title = "list-aligned-div-cut", .attrs = " align='center' style='font-weight:bold'", .kind = .css_block, .bold = true },
    };
    for (cases) |case| {
        const source = try std.fmt.allocPrint(a, "==English==\n# [[visible-en|English sense]]\n**<div{s}>\n==French==\n# ''[[visible-fr|French sense]]''<ref name=x>[[citation-target|definition]]</ref>\n</div>[[suffix|suffix]]<ref name=x/>\n<references/>\n", .{case.attrs});
        const observation = try presentation_document.observePreScopesAlloc(a, case.title, source, .{}, null, null, null, .{}, null);
        defer freePreObservation(a, observation);
        const opening = std.mem.indexOf(u8, source, "<div").?;
        var matched: usize = 0;
        for (observation.scopes) |scope| {
            if (scope.opening_start != opening) continue;
            matched += 1;
            try std.testing.expectEqual(case.kind, scope.kind);
            try std.testing.expect(scope.matched);
            try std.testing.expectEqual(case.bold, scope.formatting.bold);
            if (case.kind == .css_block) try std.testing.expectEqualStrings("div", scope.tag_name);
            if (std.mem.indexOf(u8, case.attrs, "class=") != null)
                try std.testing.expect(std.mem.indexOf(u8, scope.attributes.css_ancestor_classes, "Scope") != null);
        }
        try std.testing.expectEqual(@as(usize, 1), matched);
        try std.testing.expect(!observation.unclosed_formatting);
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, case.title, source, source, null);
    }
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 6), stats.language_records);
    try std.testing.expectEqual(@as(usize, 2), stats.language_blobs);
    try std.testing.expectEqual(@as(usize, 0), stats.fallback_pages);
    for ([_][]const u8{ "English", "French" }) |owner| {
        var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, owner));
        defer mapped.deinit();
        const blob = try blob_format.inspect(mapped.bytes);
        const metadata = try blob.languageMetadata();
        var index = try blob.buildTrustedIndexAlloc(a);
        defer index.deinit(a);
        const english = std.mem.eql(u8, owner, "English");
        for (cases) |case| {
            const record = (try index.find(case.title)).?;
            const decoded = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
            try std.testing.expectEqualStrings(if (english) "en" else "fr", decoded.entry.language_code);
            try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, decoded));
            var english_links: usize = 0;
            var french_links: usize = 0;
            var suffix_links: usize = 0;
            for (decoded.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
                if (std.mem.eql(u8, span.target, "visible-en")) {
                    english_links += 1;
                    try std.testing.expectEqualStrings("English sense", span.text);
                    try std.testing.expect(!span.bold and !span.italic);
                }
                if (std.mem.eql(u8, span.target, "visible-fr")) {
                    french_links += 1;
                    try std.testing.expectEqualStrings("French sense", span.text);
                    try std.testing.expect(span.kind == .link and span.italic);
                    try std.testing.expectEqual(case.bold, span.bold);
                }
                if (std.mem.eql(u8, span.target, "suffix")) {
                    suffix_links += 1;
                    try std.testing.expectEqualStrings("suffix", span.text);
                    try std.testing.expect(span.kind == .link and !span.bold and !span.italic);
                }
                try std.testing.expect(!std.mem.eql(u8, span.target, "citation-target"));
            };
            try std.testing.expectEqual(@as(usize, @intFromBool(english)), english_links);
            try std.testing.expectEqual(@as(usize, @intFromBool(!english)), french_links);
            try std.testing.expectEqual(@as(usize, @intFromBool(!english)), suffix_links);
            try std.testing.expectEqual(@as(usize, @intFromBool(!english)), decoded.entry.references.len);
            if (!english) {
                const reference = decoded.entry.references[0];
                try std.testing.expectEqualStrings("x", reference.name);
                try std.testing.expectEqual(@as(usize, 1), reference.number);
                var citation_links: usize = 0;
                for (reference.spans) |span| if (std.mem.eql(u8, span.target, "citation-target")) {
                    citation_links += 1;
                    try std.testing.expectEqualStrings("definition", span.text);
                    try std.testing.expect(span.kind == .link);
                };
                try std.testing.expectEqual(@as(usize, 1), citation_links);
            }
        }
    }
}

test "appendix icon language boundaries require captured namespace and two trusted complete names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Fixture = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "Inglese") or std.mem.eql(u8, name, "en") or std.mem.eql(u8, name, "Ambiguous")) return .{ .code = "en", .heading = "inglese" };
            if (std.mem.eql(u8, name, "Italiano") or std.mem.eql(u8, name, "it")) return .{ .code = "it", .heading = "italiano" };
            if (std.mem.eql(u8, name, "Lombardo") or std.mem.eql(u8, name, "lmo")) return .{ .code = "lmo", .heading = "lombardo" };
            if (std.mem.eql(u8, name, "Spagnolo") or std.mem.eql(u8, name, "spagnolo") or std.mem.eql(u8, name, "es")) return .{ .code = "es", .heading = "spagnolo" };
            if (std.mem.eql(u8, name, "finlandese") or std.mem.eql(u8, name, "Finlandese")) return .{ .code = "fi", .heading = "finlandese" };
            return null;
        }
        fn denyTrusted(_: ?*const anyopaque, _: []const u8) ?ResolvedLanguage {
            return null;
        }
        fn boundary(_: ?*const anyopaque, name: []const u8) bool {
            return std.mem.eql(u8, name, "Appendice:Ambiguous") or std.mem.eql(u8, name, "Ambiguous");
        }
        fn check(codes: LanguageCodes, line: []const u8) ?ResolvedLanguage {
            const heading = blobs.wikitext_syntax.controlHeading(line, null) orelse return null;
            return supplementalIconLanguage(codes, .{ .heading = heading.title, .source = line });
        }
    };
    const ns_source = "# wikidict-namespace-registry-v1\n# wiki\titwiktionary\n# dump-date\t20261001\n# content-language\tit\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\t\tmain\tdictionary_entries\n" ++
        "6\tFile\tFile\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\tImage\n" ++
        "10\tTemplate\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\n" ++
        "14\tCategoria\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\n" ++
        "100\tAppendice\tAppendice\tcase-sensitive\t1\t0\t0\t\tsupplemental\tunclassified_subject_retained\n";
    var ns = try @import("namespace_registry").Registry.init(a, ns_source);
    defer ns.deinit();
    const codes: LanguageCodes = .{ .namespace_catalog = &ns, .resolve_fn = Fixture.resolve, .trusted_fn = Fixture.resolve, .boundary_fn = Fixture.boundary };
    for ([_]struct { source: []const u8, code: []const u8 }{
        .{ .source = "== [[File:Flag of Italy.svg|40px|border|bandiera italiana]] [[Appendice:Italiano|Italiano]] ==", .code = "it" },
        .{ .source = "== [[Categoria:Parole in inglese]][[File:Flag_of_the_United_Kingdom.svg|40px]] [[Appendice:Inglese|Inglese]] ==", .code = "en" },
        .{ .source = "== [[File:Flag of Lombardy.svg|40px]] [[Appendice:Lombardo|Lombardo]] ==", .code = "lmo" },
        .{ .source = "== [[File:Flag_of_Finland.svg|40px|border|bandiera finlandese]] [[finlandese|Finlandese]] ==", .code = "fi" },
        .{ .source = "== [[File:Flag of Spain.svg|40px|bandiera multilinguistica spagnola|border]] [[spagnolo|Spagnolo]] ==", .code = "es" },
        .{ .source = "== [[File:Flag of Spain.svg|bandiera multilinguistica spagnola|border|40px]] [[spagnolo|Spagnolo]] ==", .code = "es" },
        .{ .source = "== [[File:Flag of Spain.svg|border|bandiera multilinguistica spagnola|40px]] [[spagnolo|Spagnolo]] ==", .code = "es" },
    }) |case| {
        const resolved = Fixture.check(codes, case.source) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(case.code, resolved.code);
        const heading = blobs.wikitext_syntax.controlHeading(case.source, null).?.title;
        try std.testing.expectEqualStrings(case.code, resolveSection(codes, .{ .heading = heading, .source = case.source }).?.code);
        try std.testing.expectEqualStrings(case.code, boundaryLanguage(codes, .{ .heading = heading, .source = case.source }).?.code);
        try std.testing.expect(supplementalIconLanguage(codes, .{ .heading = heading, .source = "" }) == null);
        try std.testing.expect(supplementalIconLanguage(codes, .{ .heading = heading, .source = case.source, .hyphen_marker = true }) == null);
    }
    for ([_][]const u8{
        "=== [[File:F.svg|40px]] [[Appendice:Inglese|Inglese]] ===",
        "== [[File:F.svg|40px]] [[Appendice:Italiano|Inglese]] ==",
        "== [[File:F.svg|40px]] [[Appendice:Unknown|Inglese]] ==",
        "== [[File:F.svg|40px]] [[Appendice:Inglese|Unknown]] ==",
        "== [[File:F.svg|40px]] [[Categoria:Inglese|Inglese]] ==",
        "== [[File:F.svg|40px]] [[Unknown:Inglese|Inglese]] ==",
        "== [[File:F.svg|40px]] [[Appendice:Ambiguous|Inglese]] ==",
        "== [[File:F.svg|40px]] [[Appendice:Inglese|Inglese]] extra ==",
        "== [[File:Inglese.svg|40px|Inglese]] [[Appendice:Unknown|Unknown]] ==",
        "== [[File:F.svg|40px|link=Elsewhere]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|40px|thumb]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|40px|left]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|40px|[[Inglese]]]] [[Appendice:Inglese|Inglese]] ==",
        "== [[:File:F.svg|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[:Categoria:Inglese]][[File:F.svg|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[Categoria:Inglese|sort]][[File:F.svg|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|40px|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|40px|caption|border|second caption]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|caption|border|border|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|caption|40px|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|caption|link=Elsewhere|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|caption|thumb|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|caption|left|40px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|Inglese|border|40px]] [[spagnolo|Spagnolo]] extra ==",
        "== [[File:F.svg|Spagnolo|border|40px]] [[Appendice:Unknown|Unknown]] ==",
        "== [[File:F.svg|Spagnolo|border|40px]] [[Appendice:Inglese|Italiano]] ==",
        "== [[File:F.svg|0px]] [[Appendice:Inglese|Inglese]] ==",
        "== [[File:F.svg|40px]] [[Appendice:Inglese#fragment|Inglese]] ==",
        "=== [[File:F.svg|40px|border|tooltip]] [[finlandese|Finlandese]] ===",
        "== [[File:F.svg|40px|border|tooltip]] [[finlandese|Inglese]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[Unknown|Finlandese]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[finlandese|Unknown]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[Categoria:finlandese|Finlandese]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[Template:finlandese|Finlandese]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[Unknown:finlandese|Finlandese]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[Ambiguous|Inglese]] ==",
        "== [[File:F.svg|40px|link=Elsewhere]] [[finlandese|Finlandese]] ==",
        "== [[File:F.svg|40px|thumb]] [[finlandese|Finlandese]] ==",
        "== [[File:F.svg|40px|left]] [[finlandese|Finlandese]] ==",
        "== [[File:F.svg|40px|[[Finlandese]]]] [[finlandese|Finlandese]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[finlandese#fragment|Finlandese]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[finlandese|<b>Finlandese</b>]] ==",
        "== [[File:F.svg|40px|border|tooltip]] [[finlandese|Finlandese]] extra ==",
    }) |line| try std.testing.expect(Fixture.check(codes, line) == null);
    var wrong_ns = ns;
    wrong_ns.content_language = "en";
    var wrong_codes = codes;
    wrong_codes.namespace_catalog = &wrong_ns;
    try std.testing.expect(Fixture.check(wrong_codes, "== [[File:F.svg|40px]] [[Appendice:Inglese|Inglese]] ==") == null);
    const local_heading = "== [[File:F.svg|40px|border|tooltip]] [[finlandese|Finlandese]] ==";
    try std.testing.expect(Fixture.check(wrong_codes, local_heading) == null);
    var untrusted = codes;
    untrusted.trusted_fn = null;
    // An absent callback deliberately uses the ordinary resolver.
    try std.testing.expectEqualStrings("fi", untrusted.resolveTrusted("finlandese").?.code);
    untrusted.trusted_fn = Fixture.denyTrusted;
    try std.testing.expect(untrusted.resolveTrusted("finlandese") == null);
    try std.testing.expect(untrusted.resolveTrusted("Finlandese") == null);
    try std.testing.expect(Fixture.check(untrusted, local_heading) == null);
}

test "categorized decorated language links require independent trusted agreement and conflict veto" {
    var namespaces = try @import("namespace_registry").Registry.init(std.testing.allocator, @import("namespace_registry").english_test_fixture);
    defer namespaces.deinit();
    try namespaces.attachInterwikiMap("# interwiki-magic\t1\nw\t1\t0\t0\t0\thttps://en.wikipedia.org/wiki/$1\t0\nfr\t1\t1\t0\t0\thttps://fr.wiktionary.org/wiki/$1\t1\n");
    var codes = TestLanguages.codes();
    codes.namespace_catalog = &namespaces;
    const cap = "<span style=\"text-transform: capitalize\">French</span>";
    const heading = "[[w:French language|" ++ cap ++ "]][[Category:French]]";
    try std.testing.expectEqualStrings("fr", resolveCategorizedHeading(codes, heading).?.code);
    try std.testing.expectEqualStrings("fr", resolveCategorizedHeading(codes, "[[Article|French]][[Category:French|sort]]").?.code);
    for ([_][]const u8{
        "[[w:French language|" ++ cap ++ "]]",
        "[[w:French language|" ++ cap ++ "]][[Category:English]]",
        "[[w:French language|" ++ cap ++ "]][[Category:unrelated topic]]",
        "[[w:French language|" ++ cap ++ "]][[:Category:French]]",
        "[[w:French language|" ++ cap ++ "]][[Category:French]] prose",
        "[[w:French language|" ++ cap ++ "]][[Category:French]][[Category:English]]",
        "[[English|" ++ cap ++ "]][[Category:French]]",
        "[[w:English|" ++ cap ++ "]][[Category:French]]",
        "[[fr:Article|" ++ cap ++ "]][[Category:French]]",
        "[[unknown:Article|" ++ cap ++ "]][[Category:French]]",
        "[[w:fr:Article|" ++ cap ++ "]][[Category:French]]",
        "[[File:French.svg|" ++ cap ++ "]][[Category:French]]",
        "[[Article|<span lang=fr>French</span>]][[Category:French]]",
        "[[Article|<span style=\"display:none\">French</span>]][[Category:French]]",
        "[[Article|<span style=\"text-transform: capitalize\" hidden>French</span>]][[Category:French]]",
        "[[Article|<nowiki>French</nowiki>]][[Category:French]]",
        "[[Article|<span style=\"text-transform: capitalize\">French</span> caption]][[Category:French]]",
        "[[Article|fr]][[Category:French]]",
        "[[Article|Unknown]][[Category:French]]",
        "[[Article|French]][[Category:French]]__NOTOC__",
    }) |value| try std.testing.expect(resolveCategorizedDecoratedLinkHeading(codes, value) == null);
    const Conflicts = struct {
        fn resolve(ctx: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, value, "w:English")) return .{ .code = "fr", .heading = "French" };
            return TestLanguages.resolve(ctx, value);
        }
        fn boundary(_: ?*const anyopaque, value: []const u8) bool {
            return std.mem.eql(u8, value, "Ambiguous");
        }
        fn untrusted(_: ?*const anyopaque, _: []const u8) ?ResolvedLanguage { return null; }
    };
    codes.resolve_fn = Conflicts.resolve;
    codes.boundary_fn = Conflicts.boundary;
    try std.testing.expect(resolveCategorizedDecoratedLinkHeading(codes, "[[w:English|" ++ cap ++ "]][[Category:French]]") == null);
    try std.testing.expect(resolveCategorizedDecoratedLinkHeading(codes, "[[w:Ambiguous|" ++ cap ++ "]][[Category:French]]") == null);
    codes.trusted_fn = Conflicts.untrusted;
    codes.strong_fn = Conflicts.untrusted;
    try std.testing.expect(resolveCategorizedDecoratedLinkHeading(codes, heading) == null);
    codes.namespace_catalog = null;
    try std.testing.expect(resolveCategorizedDecoratedLinkHeading(codes, heading) == null);
}

// Append to private src/encoder/blob_builder.zig after the ordered patches.
