    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "Unclassified"));
    defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    const metadata = try blob.languageMetadata();
    try std.testing.expectEqualStrings("", metadata.code);
    try std.testing.expectEqualStrings("Unclassified", metadata.heading);
    var rows = blob.iterator();
    const row = (try rows.next()) orelse return error.TestUnexpectedResult;
    try std.testing.expect((try rows.next()) == null);
    const actual = try blobs.presentation_codec.decodeAlloc(a, row.payload, row.title, .language, metadata);
    try std.testing.expectEqualDeep(expected.entry, actual.entry);
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualSlices(u8, row.payload, try blobs.presentation_codec.encodeAlloc(a, actual));
    try F.witness(a, actual.entry);
    for ([_][]const u8{ "Known text before changed boundary", "Unknown text after changed boundary", "Tail action" }) |text|
        try std.testing.expect(std.mem.indexOf(u8, row.payload, text) != null);
    const report = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(a, &.{ root, "fallback-pages.jsonl" }), a, .limited(16 * 1024));
    try std.testing.expect(std.mem.indexOf(u8, report, "unresolved_language_heading") != null);
    // The same whole-page route must still reject missing provider authority.
    const denied_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/unpaired-figure-denied", .{tmp.sub_path});
    var denied = try Writer.init(std.testing.io, a, denied_root);
    defer denied.deinit();
    var absent = codes;
    absent.figure_sizing = null;
    denied.language_codes = absent;
    try std.testing.expectError(error.UncompiledPresentation, denied.addExpandedPage(a, .{ .id = 0, .kind = .language }, "unpaired-figure", expanded, raw, null));
}

test "complete alias expansion root preserves full records and keeps unbound conditional and provider refusals" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const F = RetainedAliasFigureContextTest;
    var ns = try @import("namespace_registry").Registry.init(a, ControlledFigureFixture.namespace_bytes);
    defer ns.deinit();
    var plain = try @import("table_style_profile.zig").parseAlloc(a, "");
    defer plain.deinit();
    var styles = try @import("table_style_profile.zig").parseAlloc(a, ".Ahom, .Ahom * { font-style: normal; }");
    defer styles.deinit();
    const fixture: ControlledFigureFixture = .{ .file = "Ср-рд.png", .width = 250 };
    const codes: LanguageCodes = .{ .namespace_catalog = &ns, .table_styles = &styles, .figure_sizing = F.source(&fixture, &ns) };
    var reference_codes = codes;
    reference_codes.table_styles = &plain;
    var reference_report: presentation_document.Fallbacks = .{};
    const expected = try compileAlias(a, reference_codes, F.record, F.explicit_tail, null, &reference_report, null, null);
    try std.testing.expect(!reference_report.any());
    var unbound_report: presentation_document.Fallbacks = .{};
    try std.testing.expectError(error.UncompiledPresentation, compileAlias(a, codes, F.record, F.tail, null, &unbound_report, null, null));
    var unbound_prepared: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "др" };
    try std.testing.expectError(error.UncompiledPresentation, unbound_prepared.compileWithPhases(a, codes, F.tail, F.tail, null, null, null, F.record));
    var prepared: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "др" };
    try prepared.compileWithPhasesAndRoot(a, codes, F.tail, F.tail, null, null, null, F.record, .parser_output);
    try std.testing.expectEqual(@as(usize, 1), prepared.records.items.len);
    try std.testing.expectEqual(@as(usize, 1), prepared.stats.alias_records);
    try std.testing.expectEqualSlices(u8, expected.payload, prepared.records.items[0].payload);
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/complete-alias-root", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    // All legacy entry points retain unknown outer ancestry, even with phases.
    try std.testing.expectError(error.UncompiledPresentation, writer.addAliasExpanded(a, F.record, F.tail, null, .{}, &.{}));
    try std.testing.expectError(error.UncompiledPresentation, writer.addAliasExpandedWithPhases(a, F.record, F.tail, null, .{}, &.{}, null, null));
    writer.stats.pages_seen += 1;
    try writer.namespace_coverage.input(a, 0, "", .language, true);
    try writer.addAliasExpandedWithPhasesAndRoot(a, F.record, F.tail, null, .{}, &.{}, null, null, .parser_output);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.pages_seen);
    try std.testing.expectEqual(@as(usize, 1), stats.alias_records);
    try std.testing.expectEqual(@as(usize, 0), stats.language_records);
    try std.testing.expectEqual(@as(usize, 0), stats.fallback_pages);
    var mapped = try mmapPath(std.testing.io, try std.fs.path.join(a, &.{ root, "aliases.wikblb" }));
    defer mapped.deinit();
    var rows = (try blob_format.inspect(mapped.bytes)).iterator();
    const row = (try rows.next()) orelse return error.TestUnexpectedResult;
    try std.testing.expect((try rows.next()) == null);
    try std.testing.expectEqualSlices(u8, expected.payload, row.payload);
    const actual_alias = try blobs.alias_codec.decode(row.payload);
    const expected_alias = try blobs.alias_codec.decode(expected.payload);
    try blobs.alias_codec.validateKey(row.title, actual_alias);
    try std.testing.expectEqualDeep(expected_alias, actual_alias);
    try std.testing.expectEqualSlices(u8, row.payload, try blobs.alias_codec.encodeAlloc(a, actual_alias));
    const actual = try blobs.presentation_codec.decodeAlloc(a, actual_alias.presentation, "др", .alias, null);
    const expected_stored = try blobs.presentation_codec.decodeAlloc(a, expected_alias.presentation, "др", .alias, null);
    try std.testing.expectEqualDeep(expected_stored.entry, actual.entry);
    try std.testing.expectEqualDeep(expected_stored, actual);
    try std.testing.expectEqualSlices(u8, actual_alias.presentation, try blobs.presentation_codec.encodeAlloc(a, actual));
    try F.witness(a, actual.entry);
    try std.testing.expect(actual.entry.language == null and actual.entry.language_code.len == 0);
    try std.testing.expectEqualStrings("др.", actual.entry.preamble_spans[0].target);
    // Complete content does not supply an outer language, resolve a conditional
    // rule, or authorize a direction-dependent inherited cascade.
    for ([_][]const u8{
        "@media screen{.mw-content-rtl figure{margin-top:1px}}",
        "div[lang=de] figcaption a{color:red}",
        ".mw-content-rtl{font-size:80%}",
    }) |css| {
        var dependent = try @import("table_style_profile.zig").parseAlloc(a, css);
        defer dependent.deinit();
        var dependent_codes = codes;
        dependent_codes.table_styles = &dependent;
        var dependent_report: presentation_document.Fallbacks = .{};
        try std.testing.expectError(error.UncompiledPresentation, compileAliasWithRoot(a, dependent_codes, F.record, F.tail, null, &dependent_report, null, null, .parser_output));
    }
    // Actual authored ancestors survive the transport and still affect layout.
    var authored_style = try @import("table_style_profile.zig").parseAlloc(a, ".Ahom figure{margin-top:9px}");
    defer authored_style.deinit();
    var authored_codes = codes;
    authored_codes.table_styles = &authored_style;
    const authored_source = "<div class=Ahom>" ++ F.tail ++ "</div>";
    var authored_report: presentation_document.Fallbacks = .{};
    var authored_reference_report: presentation_document.Fallbacks = .{};
    const authored = try compileAliasWithRoot(a, authored_codes, F.record, authored_source, null, &authored_report, null, null, .parser_output);
    const authored_reference = try compileAlias(a, authored_codes, F.record, authored_source, null, &authored_reference_report, null, null);
    try std.testing.expect(!authored_report.any() and !authored_reference_report.any());
    try std.testing.expectEqualSlices(u8, authored_reference.payload, authored.payload);
    const authored_alias = try blobs.alias_codec.decode(authored.payload);
    const authored_stored = try blobs.presentation_codec.decodeAlloc(a, authored_alias.presentation, "др", .alias, null);
    const authored_figure = for (authored_stored.entry.sections) |section| {
        if (F.firstFigure(section.blocks)) |figure| break figure;
    } else return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(f32, 9), authored_figure.margins.top.value);
    try std.testing.expectEqualSlices(u8, authored_alias.presentation, try blobs.presentation_codec.encodeAlloc(a, authored_stored));
    const wrong: ControlledFigureFixture = .{ .file = "Other.png", .width = 250 };
    var wrong_namespace = F.source(&fixture, &ns);
    wrong_namespace.source_context.?.namespace_sha256[0] ^= 1;
    for ([_]?presentation_document.FigureSizingSource{ null, F.source(&wrong, &ns), wrong_namespace }) |source| {
        var denied = codes;
        denied.figure_sizing = source;
        var report: presentation_document.Fallbacks = .{};
        try std.testing.expectError(error.UncompiledPresentation, compileAliasWithRoot(a, denied, F.record, F.tail, null, &report, null, null, .parser_output));
    }
}

test "owner root table witness retains original page coordinates and refuses borrowed copies" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const table = "{| style=\"margin-left:0.5em\"\n| value\n|}\n";
    const page = table ++ "==English==\n# meaning\n==French==\n# autre\n";
    const cut = std.mem.indexOf(u8, page, "==French==") orelse return error.TestUnexpectedResult;
    const observed = try presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(a, "table owner", MissingText.untracked(page), .{}, null, null, null, .{}, null, true);
    try std.testing.expectEqualSlices(usize, &.{0}, observed.page_root_wiki_table_openings);
    var fragment: presentation_document.SourceFragment = .{ .source = page[0..cut], .original_start = 0 };
    bindOwnerRootTableSource(page, page, observed, &fragment);
    const proof = fragment.parser_output_range orelse return error.TestUnexpectedResult;
    try std.testing.expect(proof.page.ptr == page.ptr and proof.prepared.ptr == fragment.source.ptr);
    try std.testing.expectEqualSlices(usize, &.{0}, proof.root_wiki_table_openings);
    const copied = try a.dupe(u8, page);
    // Original expansion equality is byte semantics, not a pointer inference;
    // the existing observed source/range/prepared pointer checks still apply.
    bindOwnerRootTableSource(page, copied, observed, &fragment);
    try std.testing.expectEqualSlices(usize, &.{0}, fragment.parser_output_range.?.root_wiki_table_openings);
    const removed_prefix = "<div id=\"mw-revision-info\">\n" ++ page;
    bindOwnerRootTableSource(page, removed_prefix, observed, &fragment);
    try std.testing.expect(fragment.parser_output_range != null);
    try std.testing.expectEqual(@as(usize, 0), fragment.parser_output_range.?.root_wiki_table_openings.len);
    // Clearing the new proof does not revoke/change preexisting Figure roots.
    try std.testing.expect(fragment.parser_output_range.?.page.ptr == page.ptr);
    bindOwnerRootTableSource(copied, page, observed, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
    fragment = .{ .source = copied[0..cut], .original_start = 0 };
    bindOwnerRootTableSource(page, page, observed, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
    fragment = .{ .source = page[0..cut], .original_start = 0 };
    var incomplete = observed;
    incomplete.page_wiki_scope_complete = false;
    bindOwnerRootTableSource(page, page, incomplete, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
    const wrapped = "<div id=\"mw-revision-info\">\n" ++ table ++ "==English==\n# meaning\n==French==\n# autre\n</div>\n";
    const nested = try presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(a, "wrapped owner", MissingText.untracked(wrapped), .{}, null, null, null, .{}, null, true);
    try std.testing.expectEqual(@as(usize, 0), nested.page_root_wiki_table_openings.len);
    const begin = std.mem.indexOf(u8, wrapped, "==English==") orelse return error.TestUnexpectedResult;
    const end = std.mem.indexOf(u8, wrapped, "==French==") orelse return error.TestUnexpectedResult;
    fragment = .{ .source = wrapped[begin..end], .original_start = begin };
    bindOwnerRootTableSource(wrapped, wrapped, nested, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
}

test "Writer root table fragments prepare exact quote cuts without observed HTML scopes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    const title = "root quote cuts";
    const table = "{|\n| ''prefix cell''\n|}\n";
    const page = table ++ "==English==\n===Noun===\n# ''English body''.\n" ++
        "==French==\n===Noun===\n# '''French body'''.\n";
    const en_start = std.mem.indexOf(u8, page, "==English==") orelse return error.TestUnexpectedResult;
    const fr_start = std.mem.indexOf(u8, page, "==French==") orelse return error.TestUnexpectedResult;
    const sections = [_]language_source.Section{
        .{ .heading = "English", .source = page[en_start..fr_start] },
        .{ .heading = "French", .source = page[fr_start..] },
    };
    const observed = try presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(a, title, MissingText.untracked(page), .{}, null, null, null, .{}, null, true);
    try std.testing.expectEqualSlices(usize, &.{0}, observed.page_root_wiki_table_openings);
    const pre = try presentation_document.observePreScopesAlloc(a, title, page, .{}, null, null, null, .{}, null);
    defer freePreObservation(a, pre);
    try std.testing.expectEqual(@as(usize, 0), pre.scopes.len);
    const cuts = try pageQuoteCutsAlloc(a, page, &sections, pre.scopes, .{ .title = title });
    defer cuts.deinit(a);
    try std.testing.expectEqualSlices(usize, &.{ 0, en_start, fr_start, page.len }, cuts.outer.positions);
    try std.testing.expectError(error.InvalidPreContext, cuts.outer.at(1));
    const empty: PageQuoteCuts = .{};
    try std.testing.expectError(error.InvalidPreContext, fragmentPreContextAlloc(a, 0, en_start, pre.scopes, empty));
    const tracked: MissingText = .{ .bytes = page, .ranges = &.{.{ .start = @intCast(en_start), .end = @intCast(en_start + 2), .occurrence = 7 }} };
    const fragments = try ownerSourceFragmentsWithMissingAlloc(a, tracked, &.{.{ .source = page[en_start..fr_start], .original_start = en_start }}, "", pre.scopes, cuts);
    try std.testing.expectEqual(@as(usize, 1), fragments.len);
    try std.testing.expectEqual(@as(?usize, en_start), fragments[0].original_start);
    try std.testing.expectEqualStrings(page[en_start..fr_start], fragments[0].source);
    try std.testing.expectEqual(@as(usize, 1), fragments[0].missing.?.ranges.len);
    try std.testing.expectEqual(@as(u32, 0), fragments[0].missing.?.ranges[0].start);
    try std.testing.expectEqual(@as(u32, 2), fragments[0].missing.?.ranges[0].end);
    try std.testing.expectEqual(@as(u32, 7), fragments[0].missing.?.ranges[0].occurrence);
    try std.testing.expectEqualDeep(try cuts.outer.at(en_start), fragments[0].pre.quote orelse return error.TestUnexpectedResult);
    // An empty authored stylesheet changes no paint. It does exercise the
    // normal root-table fragment route that the null-profile arm does not use.
    var profile = try @import("table_style_profile.zig").parseAlloc(a, ""); defer profile.deinit();
    var roots: [2][]const u8 = undefined;
    var stats: [2]BuildStats = undefined;
    var reports: [2][]const u8 = undefined;
    for (0..2) |arm| {
        var codes = TestLanguages.codes();
        if (arm == 0) codes.table_styles = &profile;
        roots[arm] = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/quote-root-{d}", .{tmp.sub_path, arm});
        var writer = try Writer.init(std.testing.io, a, roots[arm]); defer writer.deinit();
        writer.language_codes = codes; writer.stats.pages_seen += 1;
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, title, page, page, null);
        stats[arm] = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, 1), stats[arm].pages_seen);
        try std.testing.expectEqual(@as(usize, 3), stats[arm].language_records);
        reports[arm] = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(a, &.{ roots[arm], "fallback-pages.jsonl" }), a, .limited(64 * 1024));
    }
    try std.testing.expectEqualDeep(stats[1], stats[0]);
    try std.testing.expectEqualSlices(u8, reports[1], reports[0]);
    var table_count: usize = 0; var prefix_cells: usize = 0; var english: usize = 0; var french: usize = 0;
    for ([_]struct { heading: []const u8, code: []const u8 }{
        .{ .heading = "Unclassified", .code = "" }, .{ .heading = "English", .code = "en" }, .{ .heading = "French", .code = "fr" },
    }) |owner| {
        const actual = (try LeadingRegionFixture.entry(a, roots[0], owner.heading, title)) orelse return error.TestUnexpectedResult;
        const expected = (try LeadingRegionFixture.entry(a, roots[1], owner.heading, title)) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(owner.code, actual.language_code);
        try std.testing.expectEqualDeep(expected, actual);
        for (actual.sections) |section| {
          for (section.blocks) |block| {
            if (block.table) |value| {
                table_count += 1; try std.testing.expectEqualStrings("", owner.code);
                try std.testing.expectEqual(@as(usize, 1), value.rows.len);
                try std.testing.expectEqual(@as(usize, 1), value.rows[0].cells.len);
                const cell = value.rows[0].cells[0];
                if (cell.blocks) |children| {
                    for (children) |child| {
                      for (child.spans) |span| {
                        if (std.mem.eql(u8, span.text, "prefix cell")) {
                            prefix_cells += 1; try std.testing.expect(span.italic and !span.bold and span.target.len == 0);
                        }
                      }
                    }
                } else {
                  for (cell.spans) |span| {
                    if (std.mem.eql(u8, span.text, "prefix cell")) {
                        prefix_cells += 1; try std.testing.expect(span.italic and !span.bold and span.target.len == 0);
                    }
                  }
                }
            }
            for (block.spans) |span| {
                if (std.mem.eql(u8, span.text, "English body")) { english += 1; try std.testing.expectEqualStrings("en", owner.code); try std.testing.expect(span.italic and !span.bold); }
                if (std.mem.eql(u8, span.text, "French body")) { french += 1; try std.testing.expectEqualStrings("fr", owner.code); try std.testing.expect(span.bold and !span.italic); }
                try std.testing.expectEqual(@as(usize, 0), span.target.len);
            }
          }
        }
        const stored: blobs.presentation_types.Stored = .{ .entry = actual };
        const bytes = try blobs.presentation_codec.encodeAlloc(a, stored);
        const decoded = try blobs.presentation_codec.decodeAlloc(a, bytes, title, .language, .{ .code = owner.code, .heading = owner.heading });
        try std.testing.expectEqualDeep(stored, decoded); try std.testing.expectEqualSlices(u8, bytes, try blobs.presentation_codec.encodeAlloc(a, decoded));
    }
    try std.testing.expectEqual(@as(usize, 1), table_count);
    try std.testing.expectEqual(@as(usize, 1), prefix_cells);
    try std.testing.expectEqual(@as(usize, 1), english); try std.testing.expectEqual(@as(usize, 1), french);
}

test "original completed table prefix survives only disjoint ordinary citation preparation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var ns = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").english_test_fixture); defer ns.deinit();
    const table = "{| style=\"margin-left:0.5em;margin-bottom:0.5em\"\n| ''[[Before|before]]''\n|}\n";
    const prefix = "==English==\n[[Category:Example]]\n\n";
    const source = prefix ++ table ++ "# after\n<references group=\"\" responsive=\"1\"></references>\n";
    const prepared = try presentation_document.preparePageExternalLinksWithMissingAlloc(a, MissingText.untracked(source), .{ .title = "citation tail", .namespace_catalog = &ns });
    try std.testing.expect(!std.mem.eql(u8, source, prepared.source));
    try std.testing.expectEqualStrings(source[0 .. prefix.len + table.len], prepared.source[0 .. prefix.len + table.len]);
    const context = try presentation_document.referenceDefinitionsWithMissingAlloc(a, prepared.missing);
    var references = context; references.citations = prepared.citations; references.content_conversion = prepared.content_conversion;
    const observed = try presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(a, "citation tail", prepared.missing, .{}, &ns, null, null, references, prepared.poem_phase, true);
    try std.testing.expectEqualSlices(usize, &.{prefix.len}, observed.page_top_level_wiki_table_openings);
    var fragment: presentation_document.SourceFragment = .{ .source = prepared.source, .missing = prepared.missing, .original_start = 0 };
    bindOwnerRootTableSource(prepared.source, source, observed, &fragment);
    const proof = fragment.parser_output_range orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(usize, &.{prefix.len}, proof.top_level_wiki_table_openings);
    try std.testing.expectEqual(@as(usize, 0), proof.root_wiki_table_openings.len);
    try std.testing.expect(proof.page.ptr == prepared.source.ptr and proof.prepared.ptr == prepared.missing.bytes.ptr);
    const two = prefix ++ table ++ table ++ "old tail";
    const second = prefix.len + table.len;
    const both = [_]usize{ prefix.len, second };
    try std.testing.expectEqualSlices(usize, &both, originalTopLevelTablePrefix(two, prefix ++ table ++ table ++ "new tail", &both));
    try std.testing.expectEqualSlices(usize, &.{prefix.len}, originalTopLevelTablePrefix(two, prefix ++ table ++ "changed second table", &both));
    for ([_][]const u8{
        "<div id=\"mw-revision-info\">\n" ++ two,
        "==French==\n[[Category:Example]]\n\n" ++ table ++ table,
        prefix ++ "{| style=\"margin-left:9em\"\n| value\n|}\n",
        prefix ++ "{| style=\"margin-left:0.5em;margin-bottom:0.5em\"\n| changed\n|}\n",
        prefix ++ "{| style=\"margin-left:0.5em;margin-bottom:0.5em\"\n| ''[[Before|before]]''\n|}changed\n",
        source[0 .. prefix.len + table.len - 2],
    }) |changed| try std.testing.expectEqual(@as(usize, 0), originalTopLevelTablePrefix(two, changed, &both).len);
    const copied = try a.dupe(u8, prepared.source);
    fragment = .{ .source = copied, .original_start = 0 };
    bindOwnerRootTableSource(prepared.source, source, observed, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
    fragment = .{ .source = prepared.source, .original_start = 0 };
    var incomplete = observed; incomplete.page_wiki_scope_complete = false;
    bindOwnerRootTableSource(prepared.source, source, incomplete, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
}

test "normal Writer keeps complete table geometry and codec before annotated citation tail" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var ns = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").english_test_fixture); defer ns.deinit();
    var styles = try @import("table_style_profile.zig").parseAlloc(a, "small{font-size:85%}#mw-revision-info{font-size:110%}"); defer styles.deinit();
    // Both arms use the complete table-style projection. A null profile uses
    // the separate geometry-only inline projection and intentionally omits paint.
    var empty_styles = try @import("table_style_profile.zig").parseAlloc(a, ""); defer empty_styles.deinit();
    const title = "original table citation tail";
    const page = "==English==\n[[Category:Example]]\n\n{| style=\"float:right;border:1px solid #aaaaaa;border-collapse:collapse;margin-left:0.5em;margin-bottom:0.5em\"\n| ''[[Before|before]]''\n|}\n# '''after''' [[Later]]\n<references group=\"\" responsive=\"1\"></references>\n";
    var roots: [2][]const u8 = undefined; var stats: [2]BuildStats = undefined;
    for (0..2) |arm| {
        var codes = TestLanguages.codes(); codes.namespace_catalog = &ns;
        codes.table_styles = if (arm == 0) &styles else &empty_styles;
        roots[arm] = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/original-table-{d}", .{tmp.sub_path, arm});
        var writer = try Writer.init(std.testing.io, a, roots[arm]); defer writer.deinit(); writer.language_codes = codes; writer.stats.pages_seen += 1;
        try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, title, page, page, null);
        stats[arm] = try writer.finish(codes);
    }
    try std.testing.expectEqualDeep(stats[1], stats[0]);
    try std.testing.expectEqual(@as(usize, 1), stats[0].language_records);
    const actual = (try LeadingRegionFixture.entry(a, roots[0], "English", title)) orelse return error.TestUnexpectedResult;
    const expected = (try LeadingRegionFixture.entry(a, roots[1], "English", title)) orelse return error.TestUnexpectedResult;
    errdefer {
        for ([_]blobs.presentation_types.Entry{ actual, expected }, 0..) |entry, arm| {
            const stored: blobs.presentation_types.Stored = .{ .entry = entry };
            if (std.json.Stringify.valueAlloc(a, stored, .{})) |bytes| {
                std.debug.print("original table citation complete decoded Stored arm={d} bytes={d}: {s}\n", .{ arm, bytes.len, bytes });
            } else |err| std.debug.print("original table citation diagnostic serialization arm={d}: {s}\n", .{ arm, @errorName(err) });
        }
        for (roots, 0..) |root, arm| {
            if (std.fs.path.join(a, &.{ root, "fallback-pages.jsonl" })) |report_path| {
                if (std.Io.Dir.cwd().readFileAlloc(std.testing.io, report_path, a, .limited(64 * 1024))) |bytes| {
                    std.debug.print("original table citation complete report arm={d} bytes={d}: {s}\n", .{ arm, bytes.len, bytes });
                } else |err| std.debug.print("original table citation diagnostic report arm={d}: {s}\n", .{ arm, @errorName(err) });
            } else |err| std.debug.print("original table citation diagnostic report path: {s}\n", .{@errorName(err)});
        }
    }
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualStrings("en", actual.language_code);
    var tables: usize = 0; var before: usize = 0; var later: usize = 0; var after: usize = 0;
    for (actual.sections) |section| for (section.blocks) |block| {
        if (block.table) |table| {
            tables += 1; try std.testing.expectEqual(@as(usize, 1), table.rows.len); try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            const style = table.style orelse return error.TestUnexpectedResult;
            try std.testing.expect(style.float_side == .right and style.collapse == .collapse);
            const border = style.border orelse return error.TestUnexpectedResult;
            switch (border) {
                .solid => |line| {
                    try std.testing.expect(line.width.unit == .px and line.width.value == 1);
                    try std.testing.expectEqualStrings("#aaaaaa", line.color);
                },
                .none, .edges, .resolved_edges => return error.TestUnexpectedResult,
            }
            const edges = style.margins orelse return error.TestUnexpectedResult;
            try std.testing.expect(edges.left.unit == .em and edges.left.value == 0.5 and edges.bottom.unit == .em and edges.bottom.value == 0.5);
            const cell = table.rows[0].cells[0];
            if (cell.blocks) |children| {
                for (children) |child| for (child.spans) |span| {
                    if (std.mem.eql(u8, span.target, "Before")) { before += 1; try std.testing.expectEqualStrings("before", span.text); try std.testing.expect(span.italic and !span.bold); }
                };
            } else {
                for (cell.spans) |span| {
                    if (std.mem.eql(u8, span.target, "Before")) { before += 1; try std.testing.expectEqualStrings("before", span.text); try std.testing.expect(span.italic and !span.bold); }
                }
            }
        }
        for (block.spans) |span| {
            if (std.mem.eql(u8, span.target, "Later")) { later += 1; try std.testing.expectEqualStrings("Later", span.text); }
            if (std.mem.eql(u8, span.text, "after")) { after += 1; try std.testing.expect(span.bold and !span.italic); }
        }
    };
    try std.testing.expectEqual(@as(usize, 1), tables); try std.testing.expectEqual(@as(usize, 1), before);
    try std.testing.expectEqual(@as(usize, 1), later); try std.testing.expectEqual(@as(usize, 1), after);
    const stored: blobs.presentation_types.Stored = .{ .entry = actual };
    const encoded = try blobs.presentation_codec.encodeAlloc(a, stored);
    const decoded = try blobs.presentation_codec.decodeAlloc(a, encoded, title, .language, .{ .heading = "English", .code = "en" });
    try std.testing.expectEqualDeep(stored, decoded); try std.testing.expectEqualSlices(u8, encoded, try blobs.presentation_codec.encodeAlloc(a, decoded));
}


test "owner observed text scope retains exact original identity only after normal root binding" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const page = "==English==\n<span>[[Target|visible]]</span>\n==French==\nautre\n";
    const cut = std.mem.indexOf(u8, page, "==French==").?;
    const observed = try presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(a, "text source", MissingText.untracked(page), .{}, null, null, null, .{}, null, true);
    var fragment: presentation_document.SourceFragment = .{ .source = page[0..cut], .original_start = 0 };
    bindOwnerRootTableSource(page, page, observed, &fragment);
    const proof = fragment.parser_output_range orelse return error.TestUnexpectedResult;
    try std.testing.expect(proof.original_page.?.ptr == page.ptr and proof.original_page.?.len == page.len);
    try std.testing.expect(proof.page.ptr == page.ptr and proof.prepared.ptr == fragment.source.ptr);
    const copied = try a.dupe(u8, page);
    bindOwnerRootTableSource(page, copied, observed, &fragment);
    // Byte equality admits the normal source provenance pair, but retains the
    // actual original pointer. The document requires that pointer to match Book.
    try std.testing.expect(fragment.parser_output_range.?.original_page.?.ptr == copied.ptr);
    const changed = "different original\n" ++ page;
    bindOwnerRootTableSource(page, changed, observed, &fragment);
    try std.testing.expect(fragment.parser_output_range != null);
    try std.testing.expect(fragment.parser_output_range.?.original_page == null);
    try std.testing.expect(fragment.parser_output_range.?.page.ptr == page.ptr);
    fragment = .{ .source = copied[0..cut], .original_start = 0 };
    bindOwnerRootTableSource(page, page, observed, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
    fragment = .{ .source = page[0..cut], .original_start = 0 };
    var incomplete = observed;
    incomplete.page_wiki_scope_complete = false;
    bindOwnerRootTableSource(page, page, incomplete, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
}


test "normal issued numeric link transition preserves observed text scope through owner source and full codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const raw = "==English==\n===Noun===\n# <span>[[Target|visible]] [https://example.test/]</span>\n";
    const numbered = try presentation_document.preparePageExternalLinksWithMissingAlloc(a, MissingText.untracked(raw), .{ .title = "numbered scope" });
    const transition = numbered.class_scope_transition orelse return error.TestUnexpectedResult;
    try std.testing.expect(transition.original.ptr == raw.ptr and transition.original.len == raw.len);
    try std.testing.expect(transition.prepared.ptr == numbered.source.ptr and transition.prepared.len == numbered.source.len);
    try std.testing.expect(!std.mem.eql(u8, raw, numbered.source));
    try std.testing.expect(std.mem.indexOf(u8, numbered.source, " <nowiki>[1]</nowiki>") != null);
    const observed = try presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(a, "numbered scope", numbered.missing, .{}, null, null, null, .{}, null, true);
    const observed_source = observed.page_html_source orelse return error.TestUnexpectedResult;
    try std.testing.expect(observed_source.ptr == numbered.source.ptr and observed_source.len == numbered.source.len);
    // Heading coordinates belong to the complete numbered page, not the raw class-scope source.
    const identity_projection = [_]presentation_document.HeadingSourceRange{.{ .owner_start = 0, .page_start = 0, .len = numbered.source.len }};
    var fragment: presentation_document.SourceFragment = .{ .source = numbered.source, .original_start = 0, .missing = numbered.missing };
    bindOwnerRootTableSource(numbered.source, raw, observed, &fragment);
    try std.testing.expect(fragment.parser_output_range != null and fragment.parser_output_range.?.original_page == null);
    bindOwnerTextClassTransition(numbered.source, raw, numbered.source, transition, &fragment);
    try std.testing.expect(fragment.parser_output_range.?.original_page.?.ptr == raw.ptr);
    const ScopeControl = struct {
        fn sizing(_: ?*const anyopaque, _: std.mem.Allocator, _: []const u8, _: blobs.presentation_types.FigureFormat, _: ?u32, _: ?u32) std.mem.Allocator.Error!?blobs.presentation_types.FigureSizingPolicy { return null; }
    };
    const scope: @import("table_style_profile.zig").BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "mw-parser-output external autonumber", .complete_ancestor_class_superset = "mw-parser-output external autonumber" };
    const figure: presentation_document.FigureSizingSource = .{ .resolve_fn = ScopeControl.sizing, .text_class_scope = .{ .source = raw, .scope = &scope } };
    var profile = try @import("table_style_profile.zig").parseAlloc(a, ".etymology > .NavContent > ul > li:only-child > span:not(.relationship){font-weight:bold}");
    defer profile.deinit();
    var report: presentation_document.Fallbacks = .{};
    const bytes = try presentation_document.compileClassifiedWithHeadingAnchorsAndSourceMediaRootAlloc(a, "numbered scope", .language, "English", "en", numbered.missing, null,
        .{}, null, null, null, .{ .citations = numbered.citations, .content_conversion = numbered.content_conversion }, &report, numbered.poem_phase,
        &.{fragment}, &observed, &identity_projection, null, &profile, figure, .unknown);
    try std.testing.expectEqualDeep(presentation_document.Fallbacks{}, report);
    var reference_report: presentation_document.Fallbacks = .{};
    const reference = try presentation_document.compileClassifiedWithHeadingAnchorsAndSourceMediaRootAlloc(a, "numbered scope", .language, "English", "en", numbered.missing, null,
        .{}, null, null, null, .{ .citations = numbered.citations, .content_conversion = numbered.content_conversion }, &reference_report, numbered.poem_phase,
        &.{fragment}, &observed, &identity_projection, null, null, figure, .unknown);
    try std.testing.expectEqualDeep(presentation_document.Fallbacks{}, reference_report);
    const codec = blobs.presentation_codec;
    const stored = try codec.decodeAlloc(a, bytes, "numbered scope", .language, .{ .code = "en", .heading = "English" });
    try std.testing.expectEqualDeep(try codec.decodeAlloc(a, reference, "numbered scope", .language, .{ .code = "en", .heading = "English" }), stored);
    var internal: usize = 0;
    var external: usize = 0;
    for (stored.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
        if (std.mem.eql(u8, span.target, "Target")) {
            try std.testing.expectEqualStrings("visible", span.text);
            internal += 1;
        } else if (std.mem.eql(u8, span.target, "https://example.test/")) {
            try std.testing.expectEqualStrings("[1]", span.text);
            external += 1;
        }
    };
    try std.testing.expectEqual(@as(usize, 1), internal);
    try std.testing.expectEqual(@as(usize, 1), external);
    try std.testing.expectEqualStrings("en", stored.entry.language_code);
    try std.testing.expectEqual(@as(usize, 1), stored.entry.organization.lexemes.len);
    try std.testing.expectEqual(@as(usize, 1), stored.entry.organization.lexemes[0].definitions.len);
    try blobs.presentation_types.validateStored(a, stored, "numbered scope", .language, .{ .code = "en", .heading = "English" });
    const again = try codec.encodeAlloc(a, stored);
    try std.testing.expectEqualSlices(u8, bytes, again);
    try std.testing.expectEqualDeep(stored, try codec.decodeAlloc(a, again, "numbered scope", .language, .{ .code = "en", .heading = "English" }));
    const raw_copy = try a.dupe(u8, raw);
    const numbered_copy = try a.dupe(u8, numbered.source);
    for (0..5) |which| {
        errdefer std.debug.print("numbered scope refused identity={d}\n", .{which});
        bindOwnerRootTableSource(numbered.source, raw, observed, &fragment);
        var claimed: ?presentation_document.ClassScopeSourceTransition = transition;
        var claimed_raw: []const u8 = raw;
        var claimed_numbered = numbered.source;
        switch (which) {
            0 => claimed = null,
            1 => claimed.?.original = raw_copy,
            2 => claimed.?.prepared = numbered_copy,
            3 => claimed_raw = raw_copy,
            else => claimed_numbered = numbered_copy,
        }
        bindOwnerTextClassTransition(numbered.source, claimed_raw, claimed_numbered, claimed, &fragment);
        try std.testing.expect(fragment.parser_output_range.?.original_page == null);
    }
    // A valid root proof on a later changed source cannot borrow the earlier
    // numbering transition, even when its original page is the same.
    const changed = try std.fmt.allocPrint(a, "{s}changed\n", .{numbered.source});
    const changed_observed = try presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(a, "numbered scope", MissingText.untracked(changed), .{}, null, null, null, .{}, null, true);
    var changed_fragment: presentation_document.SourceFragment = .{ .source = changed, .original_start = 0 };
    bindOwnerRootTableSource(changed, raw, changed_observed, &changed_fragment);
    try std.testing.expect(changed_fragment.parser_output_range != null);
    bindOwnerTextClassTransition(changed, raw, numbered.source, transition, &changed_fragment);
    try std.testing.expect(changed_fragment.parser_output_range.?.original_page == null);
    fragment.parser_output_range = null;
    bindOwnerTextClassTransition(numbered.source, raw, numbered.source, transition, &fragment);
    try std.testing.expect(fragment.parser_output_range == null);
}

test "page raw heading proof is lazy keeps fatal errors unpublished and reuses same-page storage" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var failing = std.testing.FailingAllocator.init(arena.allocator(), .{ .fail_index = 0 });
    const raw = "== Noun ==\n# Meaning [[target]].\n";
    var proof: PageRawHeadingProof = .{ .a = failing.allocator(), .codes = .{}, .title = "first", .raw = raw };
    try std.testing.expect(!proof.evaluated and proof.observation == null);
    try std.testing.expectEqual(@as(usize, 0), failing.alloc_index);
    try std.testing.expect(!failing.has_induced_failure);
    try std.testing.expectError(error.OutOfMemory, proof.get());
    try std.testing.expect(!proof.evaluated and proof.observation == null);
    try std.testing.expect(failing.has_induced_failure);
    failing.fail_index = std.math.maxInt(usize);
    const first = (try proof.get()) orelse return error.TestUnexpectedResult;
    try std.testing.expect(proof.evaluated and first.page_wiki_scope_complete);
    try std.testing.expectEqualSlices(usize, &.{0}, first.page_wiki_openings);
    const allocations = failing.alloc_index;
    failing.fail_index = allocations;
    const second = (try proof.get()) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(allocations, failing.alloc_index);
    try std.testing.expect(first.items.ptr == second.items.ptr);
    try std.testing.expect(first.page_wiki_openings.ptr == second.page_wiki_openings.ptr);
    try std.testing.expect(second.page_html_source.?.ptr == raw.ptr);
    try std.testing.expectEqualDeep(first, second);

    // A different page has independent state even within the same live arena.
    var next: PageRawHeadingProof = .{ .a = failing.allocator(), .codes = .{}, .title = "second", .raw = "== Verb ==\n# Other.\n" };
    try std.testing.expectError(error.OutOfMemory, next.get());
    try std.testing.expect(!next.evaluated and next.observation == null);
    try std.testing.expectEqualStrings("Noun", first.items[0].anchor);
    var absent: PageRawHeadingProof = .{ .a = failing.allocator(), .codes = .{}, .title = "absent", .raw = null };
    try std.testing.expect((try absent.get()) == null and absent.evaluated);
}

test "page raw heading proof caches null refusals without hiding later rejected-field capture" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var failing = std.testing.FailingAllocator.init(arena.allocator(), .{});
    const raw = "==[https:// raw-probe==\nbody";
    const terminal = "==[https:// terminal-field==\nbody";
    var proof: PageRawHeadingProof = .{ .a = failing.allocator(), .codes = .{}, .title = "probe", .raw = raw };
    var evidence: presentation_document.RejectedFieldCapture = .{};
    {
        const scope = evidence.begin();
        defer scope.deinit();
        try std.testing.expect((try proof.get()) == null);
        try std.testing.expect(proof.evaluated);
        try std.testing.expect(evidence.snapshot(error.UncompiledPresentation) == null);
        const allocations = failing.alloc_index;
        failing.fail_index = allocations;
        try std.testing.expect((try proof.get()) == null);
        try std.testing.expectEqual(allocations, failing.alloc_index);
        try std.testing.expect(presentation_document.rejectedFieldCaptureActive());
        try std.testing.expectError(error.UncompiledPresentation, presentation_document.observeHeadingAnchorsWithWikiScopeAlloc(arena.allocator(), "probe", MissingText.untracked(terminal), .{}, null, null, null, .{}, null, true));
        const rejected = evidence.snapshot(error.UncompiledPresentation) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("5b68747470733a2f2f207465726d696e616c2d6669656c64", rejected.window_hex);
    }
    try std.testing.expect(!presentation_document.rejectedFieldCaptureActive());
    // The separate SIMPLE fallback still owns its strict error policy.
    try std.testing.expectError(error.UncompiledPresentation, simpleRawHeadingProof(arena.allocator(), .{}, "probe", raw));
}

test "page raw heading proof retains real soft-limit refusal and page-owned lifetime" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var deep: std.ArrayList(u8) = .empty;
    try deep.appendSlice(a, "== Noun ==\n# Meaning.\n");
    for (0..64) |_| try deep.appendSlice(a, "<div>\n");
    try deep.appendSlice(a, "inside\n");
    for (0..64) |_| try deep.appendSlice(a, "</div>\n");
    var totals: consume_diagnostics.ConsumePhaseTotals = .{};
    const prior = consume_diagnostics.setParentConsumeProfile(.{ .io = std.testing.io, .totals = &totals });
    defer _ = consume_diagnostics.setParentConsumeProfile(prior);
    var proof: PageRawHeadingProof = .{ .a = a, .codes = .{}, .title = "deep", .raw = deep.items };
