    const raw = @embedFile("testdata/fr-named-owner/raw.wikitext");
    const source = @embedFile("testdata/fr-named-owner/expanded.wikitext");
    const raw_at = std.mem.indexOf(u8, raw, "== {{langue|conv}} ==").?;
    const at = std.mem.indexOf(u8, source, "== <span class='sectionlangue' id='conv'>").?;
    const authored = F.section(raw[raw_at..]); const emitted = F.section(source[at..]);
    const owner = sourceNomHeadingOwner(codes, .untracked(source), authored, emitted) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("conv", owner.code);
    try std.testing.expectEqualStrings("Conventions internationales", owner.heading);
    try std.testing.expect(sourceNomHeadingOwner(codes, .untracked(source), F.section(raw), F.section(source)) == null);
    var old_mode = codes; old_mode.source_nom_name_format = false;
    try std.testing.expect(sourceNomHeadingOwner(old_mode, .untracked(source), authored, emitted) == null);
    var absent = codes; absent.source_nom_label_fn = null;
    try std.testing.expect(sourceNomHeadingOwner(absent, .untracked(source), authored, emitted) == null);
    var no_root = emitted; no_root.root_wiki_heading = false;
    try std.testing.expect(sourceNomHeadingOwner(codes, .untracked(source), authored, no_root) == null);
    no_root = authored; no_root.root_wiki_heading = false;
    try std.testing.expect(sourceNomHeadingOwner(codes, .untracked(source), no_root, emitted) == null);
    const copied = try a.dupe(u8, source[at..]);
    try std.testing.expect(sourceNomHeadingOwner(codes, .untracked(source), authored, F.section(copied)) == null);
    var unknown: MissingText = .untracked(source); unknown.unknown = true;
    try std.testing.expect(sourceNomHeadingOwner(codes, unknown, authored, emitted) == null);
    const offset: u32 = @intCast(at);
    var missing: MissingText = .untracked(source); missing.ranges = &.{.{ .start = offset, .end = offset + 1, .occurrence = 1 }};
    try std.testing.expect(sourceNomHeadingOwner(codes, missing, authored, emitted) == null);
    var literal: MissingText = .untracked(source); literal.literal_curly_ranges = &.{.{ .start = offset, .end = offset + 1 }};
    try std.testing.expect(sourceNomHeadingOwner(codes, literal, authored, emitted) == null);
    const generated: missing_dependency.generated_link.Bound = .{ .root = source, .start = offset, .end = offset + 1,
        .value = .{ .token = "fixture", .argument = "fixture", .target = "fixture", .label = "fixture" } };
    var overlap: MissingText = .untracked(source); overlap.generated_links = &.{.{ .start = offset, .end = offset + 1, .bound = &generated }};
    try std.testing.expect(sourceNomHeadingOwner(codes, overlap, authored, emitted) == null);
    for ([_][]const u8{
        "== <span class='sectionlangue' id='mul'>Conventions internationales</span> ==\n",
        "== <span class='other' id='conv'>Conventions internationales</span> ==\n",
        "== <span class=\"sectionlangue\" id=\"conv\">Conventions internationales</span> ==\n",
        "== <span class='sectionlangue' id='conv'>Conventions internationales</span>[[Catégorie:other]] ==\n",
        "== <span class='sectionlangue' id='conv'>[[Portail:Conventions internationales|Conventions internationales]]</span> ==\n",
        "== <span class='sectionlangue' id='conv'>Conventions internationales[[Catégorie:conventions internationales]]</span> ==\n",
        "=== <span class='sectionlangue' id='conv'>Conventions internationales</span> ===\n",
    }) |bad| try std.testing.expect(sourceNomHeadingOwner(codes, .untracked(bad), authored, F.section(bad)) == null);
    for ([_][]const u8{ "=={{langue|mul}}==\n", "=={{langue|CONV}}==\n", "=={{langue|conv|nocat=1}}==\n", "=={{other|conv}}==\n" }) |bad|
        try std.testing.expect(sourceNomHeadingOwner(codes, .untracked(source), F.section(bad), emitted) == null);
    // The retained complete output remains an independent body/codec oracle.
    // This test does not relabel its old single Unclassified record as a newly
    // produced split page or claim new Figure/style execution.
    const T = blobs.presentation_types;
    const parsed = try std.json.parseFromSlice(struct { entries: []const T.Entry }, a, @embedFile("testdata/fr-named-owner/reader.json"), .{ .ignore_unknown_fields = true });
    defer parsed.deinit();
    try std.testing.expectEqual(@as(usize, 1), parsed.value.entries.len);
    const before = parsed.value.entries[0];
    try std.testing.expectEqualStrings("", before.language_code);
    try std.testing.expectEqual(@as(usize, 5), before.sections.len);
    inline for (.{ "Caractère", "Références", "Conventions internationales", "Symbole", "Voir aussi" }, 0..) |title, i|
        try std.testing.expectEqualStrings(title, before.sections[i].title);
    const stored: T.Stored = .{ .entry = before };
    const bytes = try blobs.presentation_codec.encodeAlloc(a, stored);
    const decoded = try blobs.presentation_codec.decodeAlloc(a, bytes, before.title, .language, .{ .code = before.language_code, .heading = before.language.? });
    try std.testing.expectEqualDeep(stored, decoded);
    try std.testing.expectEqualSlices(u8, bytes, try blobs.presentation_codec.encodeAlloc(a, decoded));
}

test "named formatter isolates only an owned ordered root lexical prefix without assigning its language" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const F = struct {
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            return if (std.mem.eql(u8, value, "conv")) .{ .code = "conv", .heading = "Conventions internationales" } else null;
        }
        fn label(_: ?*const anyopaque, value: []const u8) ?[]const u8 {
            return if (std.mem.eql(u8, value, "conv")) "conventions internationales" else null;
        }
        fn sections(allocator: std.mem.Allocator, codes: LanguageCodes, source: []const u8) ![]language_source.Section {
            var items: std.ArrayList(language_source.Section) = .empty;
            var iterator = language_source.Iterator.init(source);
            while (iterator.next()) |section| try items.append(allocator, section);
            const proof = (try simpleRawHeadingProof(allocator, codes, "owned-boundary", source)) orelse return &.{};
            simpleApplyRootScope(source, items.items, proof.page_wiki_openings);
            return try items.toOwnedSlice(allocator);
        }
        fn accepts(allocator: std.mem.Allocator, codes: LanguageCodes, raw: []const u8, source: []const u8) !bool {
            return SourceNomLeadingRegion.boundary(allocator, "owned-boundary", codes, raw, .untracked(source),
                try sections(allocator, codes, raw), try sections(allocator, codes, source));
        }
    };
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/fr-named-owner/namespace-registry.tsv")); defer ns.deinit();
    const codes: LanguageCodes = .{ .namespace_catalog = &ns, .resolve_fn = F.resolve,
        .source_nom_label_fn = F.label, .source_nom_name_format = true };
    const prefix_header = "== <span id=\"caract\">Caractère</span>[[Catégorie:Caractères]] ==\n";
    const prefix = prefix_header ++ "# [[Unicode|CHARACTER]].\n";
    const raw_prefix = "== {{caractère}} ==\n# [[Unicode|CHARACTER]].\n";
    const owned = "== <span class='sectionlangue' id='conv'>Conventions internationales</span>[[Catégorie:conventions internationales]] ==\n# [[Jupiter|CONVENTION]].\n";
    const raw_owned = "== {{langue|conv}} ==\n# [[Jupiter|CONVENTION]].\n";
    const raw = raw_prefix ++ raw_owned;
    const source = prefix ++ owned;
    const raw_sections = try F.sections(a, codes, raw);
    const sections = try F.sections(a, codes, source);
    try std.testing.expect(try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, .untracked(source), raw_sections, sections));
    // The complete retained page has the same unchanged lexical prefix. Its
    // independent normal root/media qualification is not fabricated here.
    const actual_raw = @embedFile("testdata/fr-named-owner/raw.wikitext");
    const actual_source = @embedFile("testdata/fr-named-owner/expanded.wikitext");
    const actual_raw_end = std.mem.indexOf(u8, actual_raw, "== {{langue|conv}} ==").?;
    const actual_end = std.mem.indexOf(u8, actual_source, "== <span class='sectionlangue' id='conv'>").?;
    const original_prefix = SourceNomLeadingRegion.lexicalPrefix(.{ .heading = "", .source = actual_raw[0..actual_raw_end] }).?;
    const emitted_prefix = SourceNomLeadingRegion.lexicalPrefix(.{ .heading = "", .source = actual_source[0..actual_end] }).?;
    try std.testing.expectEqualStrings(original_prefix, emitted_prefix);
    try std.testing.expect(std.mem.endsWith(u8, emitted_prefix, "# [[Jupiter]]. [[Unicode]] : U+2643."));
    const support = "== Local support ==\n* [[Related]].\n";
    try std.testing.expect(try F.accepts(a, codes, raw_prefix ++ support ++ raw_owned ++ raw_owned, prefix ++ support ++ owned ++ owned));

    var page: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "♃" };
    try page.compileWithPhases(a, codes, source, raw, null, null, null, null);
    try std.testing.expectEqual(@as(usize, 2), page.records.items.len);
    for (page.records.items, 0..) |record, i| {
        const language: ResolvedLanguage = if (i == 0) .{ .code = "", .heading = "Unclassified" } else .{ .code = "conv", .heading = "Conventions internationales" };
        try std.testing.expectEqualStrings(language.heading, record.key);
        const actual = try blobs.presentation_codec.decodeAlloc(a, record.payload, "♃", .language, .{ .code = language.code, .heading = language.heading });
        const reference_bytes = try presentation_document.compileReportedWithLinkTrailAlloc(a, "♃", .language, language.heading, language.code,
            if (i == 0) prefix else owned, null, codes.link_trail, &ns, null);
        const expected = try blobs.presentation_codec.decodeAlloc(a, reference_bytes, "♃", .language, .{ .code = language.code, .heading = language.heading });
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, actual));
    }
    try std.testing.expect(try F.accepts(a, codes,
        "== {{caractère}} ==\n# [[Catégorie:Only]] [[Unicode|VISIBLE]].\n" ++ raw_owned,
        prefix_header ++ "# [[Catégorie:Only]] [[Unicode|VISIBLE]].\n" ++ owned));
    // A run longer than five retains its literal extra apostrophe; only
    // genuinely empty formatting and hidden categories fail this evidence.
    try std.testing.expect(try F.accepts(a, codes,
        "== {{caractère}} ==\n# ''''''\n" ++ raw_owned,
        prefix_header ++ "# ''''''\n" ++ owned));
    var absent = codes; absent.source_nom_label_fn = null;
    try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", absent, raw, .untracked(source), raw_sections, sections));
    absent = codes; absent.source_nom_name_format = false;
    try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", absent, raw, .untracked(source), raw_sections, sections));
    try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, try a.dupe(u8, raw), .untracked(source), raw_sections, sections));
    try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, .untracked(try a.dupe(u8, source)), raw_sections, sections));
    try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, .untracked(source), raw_sections[0..1], sections));
    const reversed = [_]language_source.Section{ sections[1], sections[0] };
    try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, .untracked(source), raw_sections, &reversed));
    for (raw_sections) |*section| {
        section.root_wiki_heading = false;
        try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, .untracked(source), raw_sections, sections));
        section.root_wiki_heading = true;
    }
    for (sections) |*section| {
        section.root_wiki_heading = false;
        try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, .untracked(source), raw_sections, sections));
        section.root_wiki_heading = true;
    }
    var unknown: MissingText = .untracked(source); unknown.unknown = true;
    try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, unknown, raw_sections, sections));
    for ([_]u32{ 0, @intCast(prefix_header.len), @intCast(prefix.len) }) |offset| {
        var missing: MissingText = .untracked(source); missing.ranges = &.{.{ .start = offset, .end = offset + 1, .occurrence = 1 }};
        try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, missing, raw_sections, sections));
        var literal: MissingText = .untracked(source); literal.literal_curly_ranges = &.{.{ .start = offset, .end = offset + 1 }};
        try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, literal, raw_sections, sections));
        const bound: missing_dependency.generated_link.Bound = .{ .root = source, .start = offset, .end = offset + 1,
            .value = .{ .token = "fixture", .argument = "fixture", .target = "fixture", .label = "fixture" } };
        var generated: MissingText = .untracked(source); generated.generated_links = &.{.{ .start = offset, .end = offset + 1, .bound = &bound }};
        try std.testing.expect(!try SourceNomLeadingRegion.boundary(a, "owned-boundary", codes, raw, generated, raw_sections, sections));
    }
    // These are independently observed full source domains, not fabricated root
    // flags. Support, nested/protected meanings and changed source stay unknown.
    for ([_][]const u8{
        "* [[Unicode|CHARACTER]].\n", "# \n", "#: [[Unicode|CHARACTER]].\n", "## [[Unicode|CHARACTER]].\n",
        "# [[Catégorie:Only]]\n", "# ''\n", "# '''\n",
        "<nowiki>\n# [[Unicode|CHARACTER]].\n</nowiki>\n", "{{opaque|\n# [[Unicode|CHARACTER]].\n}}\n",
        "{|\n|\n# [[Unicode|CHARACTER]].\n|}\n", "<div>\n# [[Unicode|CHARACTER]].\n</div>\n",
    }) |body| {
        const unproved_raw = try std.mem.concat(a, u8, &.{ "== {{caractère}} ==\n", body, raw_owned });
        const unproved_source = try std.mem.concat(a, u8, &.{ prefix_header, body, owned });
        try std.testing.expect(!try F.accepts(a, codes, unproved_raw, unproved_source));
    }
    try std.testing.expect(!try F.accepts(a, codes, raw, prefix_header ++ "# [[Unicode|CHANGED]].\n" ++ owned));
    try std.testing.expect(!try SourceNomLeadingRegion.hasMeaning(a, "owned-boundary", codes, "# [[Image:Example.png|20px]]"));
    var failed = std.testing.FailingAllocator.init(a, .{ .fail_index = 0 });
    try std.testing.expectError(error.OutOfMemory, SourceNomLeadingRegion.hasMeaning(failed.allocator(), "owned-boundary", codes, "# [[Unicode|VISIBLE]]."));
    try std.testing.expect(!try F.accepts(a, codes, raw_owned ++ raw_prefix, owned ++ prefix));
    try std.testing.expect(!try F.accepts(a, codes, raw_prefix ++ "== {{langue|unknown}} ==\n# PEER\n", prefix ++ "== Unknown ==\n# PEER\n"));
    try std.testing.expect(!try F.accepts(a, codes, "== {{caractère|arg}} ==\n# [[Unicode|CHARACTER]].\n" ++ raw_owned, source));
    try std.testing.expect(!try F.accepts(a, codes, "== {{References}} ==\n# [[Unicode|CHARACTER]].\n" ++ raw_owned,
        "== <span id=\"ref\">References</span> ==\n# [[Unicode|CHARACTER]].\n" ++ owned));
    try std.testing.expect(!try F.accepts(a, codes, "<div>\n" ++ raw ++ "</div>\n", "<div>\n" ++ source ++ "</div>\n"));
}

test "installed named formatter cannot recover a rejected declaration from raw template arguments" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const F = struct {
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            return if (std.mem.eql(u8, value, "conv")) .{ .code = "conv", .heading = "Conventions internationales" } else null;
        }
        fn label(_: ?*const anyopaque, value: []const u8) ?[]const u8 {
            return if (std.mem.eql(u8, value, "conv")) "conventions internationales" else null;
        }
        fn noLabel(_: ?*const anyopaque, _: []const u8) ?[]const u8 { return null; }
        fn section(source: []const u8) language_source.Section {
            const line = source[0 .. std.mem.indexOfScalar(u8, source, '\n') orelse source.len];
            return .{ .heading = blobs.wikitext_syntax.controlHeading(line, null).?.title, .source = source, .root_wiki_heading = true };
        }
        fn check(allocator: std.mem.Allocator, codes: LanguageCodes, raw: []const u8, source: []const u8, language: ResolvedLanguage) !void {
            var page: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "formatter boundary" };
            try page.compileWithPhases(allocator, codes, source, raw, null, null, null, null);
            try std.testing.expectEqual(@as(usize, 1), page.records.items.len);
            const record = page.records.items[0];
            try std.testing.expectEqualStrings(language.heading, record.key);
            const actual = try blobs.presentation_codec.decodeAlloc(allocator, record.payload, page.title, .language,
                .{ .code = language.code, .heading = language.heading });
            const reference_bytes = try presentation_document.compileReportedWithLinkTrailAlloc(allocator, page.title, .language,
                language.heading, language.code, source, null, codes.link_trail, codes.namespace_catalog, null);
            const expected = try blobs.presentation_codec.decodeAlloc(allocator, reference_bytes, page.title, .language,
                .{ .code = language.code, .heading = language.heading });
            try std.testing.expectEqualDeep(expected, actual);
            try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(allocator, actual));
        }
    };
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/fr-named-owner/namespace-registry.tsv")); defer ns.deinit();
    const codes: LanguageCodes = .{ .namespace_catalog = &ns, .resolve_fn = F.resolve,
        .source_nom_label_fn = F.label, .source_nom_name_format = true };
    const unknown: ResolvedLanguage = .{ .code = "", .heading = "Unclassified" };
    const owner: ResolvedLanguage = .{ .code = "conv", .heading = "Conventions internationales" };
    const prefix = "== <span id=\"caract\">Caractère</span>[[Catégorie:Caractères]] ==\n# [[Unicode|CHARACTER]].\n";
    const raw_prefix = "== {{caractère}} ==\n# [[Unicode|CHARACTER]].\n";
    const owned = "== <span class='sectionlangue' id='conv'>Conventions internationales</span>[[Catégorie:conventions internationales]] ==\n# [[Jupiter|CONVENTION]].\n";
    const raw_owned = "== {{langue|conv}} ==\n# [[Jupiter|CONVENTION]].\n";
    var old_mode = codes; old_mode.source_nom_name_format = false;
    // Exercise the same normal negative as the genuine normal-loader control;
    // both complete regions and their actions remain in the unknown record.
    try F.check(a, old_mode, raw_prefix ++ raw_owned, prefix ++ owned, unknown);
    var no_label = codes; no_label.source_nom_label_fn = F.noLabel;
    try F.check(a, no_label, raw_prefix ++ raw_owned, prefix ++ owned, unknown);
    for ([_][]const u8{
        "== {{langue|conv|nocat=1}} ==\n# [[Jupiter|CONVENTION]].\n",
        "== {{langue|1=conv}} ==\n# [[Jupiter|CONVENTION]].\n",
        "== {{langue|unknown}} ==\n# [[Jupiter|CONVENTION]].\n",
    }) |raw_peer| try F.check(a, codes, try std.mem.concat(a, u8, &.{ raw_prefix, raw_peer }), prefix ++ owned, unknown);
    const wrong = "== <span class='sectionlangue' id='other'>Conventions internationales</span> ==\n# [[Jupiter|CONVENTION]].\n";
    try F.check(a, codes, raw_prefix ++ raw_owned, prefix ++ wrong, unknown);

    // Each existing paired grammar still owns only its proved declaration.
    try F.check(a, codes, raw_owned, owned, owner);
    const legacy = "== <span class=\"sectionlangue\" id=\"conv\">Conventions internationales[[Catégorie:conventions internationales]]</span> ==\n# [[Jupiter|CONVENTION]].\n";
    try F.check(a, old_mode, raw_owned, legacy, owner);
    // The refusal is specific to the installed role. Other template candidates
    // and an independent rendered code retain their ordinary routes.
    var no_role = codes; no_role.source_nom_label_fn = null;
    try std.testing.expectEqualStrings("conv", resolveTemplateCandidates(no_role, "{{langue|conv}}").?.code);
    try std.testing.expectEqualStrings("conv", resolveTemplateCandidates(codes, "{{other|conv}}").?.code);
    try F.check(a, old_mode, raw_owned, "== conv ==\n# [[Jupiter|CONVENTION]].\n", owner);
    for ([_][]const u8{ "{{langue|conv}}", "{{ langue |conv}}", "{{langue|conv|extra}}", "{{langue|1=conv}}" }) |raw_heading|
        try std.testing.expect(resolveTemplateCandidates(codes, raw_heading) == null);
    var tainted: MissingText = .untracked(owned); tainted.unknown = true;
    try std.testing.expect(sourceNomHeadingOwner(codes, tainted, F.section(raw_owned), F.section(owned)) == null);
    try std.testing.expect(resolveSection(codes, F.section(raw_owned)) == null);
    var unowned_root = F.section(owned); unowned_root.root_wiki_heading = false;
    try std.testing.expect(sourceNomHeadingOwner(codes, .untracked(owned), F.section(raw_owned), unowned_root) == null);
    try std.testing.expect(resolveSection(codes, F.section(raw_owned)) == null);
}

test "unaligned literal language regions require unique rooted matching raw corroboration" {
    const F = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "Middle English") or std.mem.eql(u8, name, "enm")) return .{ .code = "enm", .heading = "Средњи Енглески" };
            if (std.mem.eql(u8, name, "Czech") or std.mem.eql(u8, name, "cs")) return .{ .code = "cs", .heading = "Чешки" };
            return null;
        }
        fn noTrust(_: ?*const anyopaque, _: []const u8) ?ResolvedLanguage { return null; }
    };
    const codes: LanguageCodes = .{ .resolve_fn = F.resolve, .trusted_fn = F.noTrust };
    const raw = "==Middle English==\n===Noun===\n{{enm-noun|women}}\n# {{alt form|enm|womman}}\n";
    const expanded = "==Middle English==\n===Noun===\n'''woman'''\n# [[womman]]\n==Generated support==\nbody\n";
    const split = std.mem.indexOf(u8, expanded, "==Generated support==").?;
    const raw_sections = [_]language_source.Section{.{ .heading = "Middle English", .source = raw }};
    const sections = [_]language_source.Section{
        .{ .heading = "Middle English", .source = expanded[0..split] },
        .{ .heading = "Generated support", .source = expanded[split..] },
    };
    const source = MissingText.untracked(expanded);
    try std.testing.expect(literalAliasPairCandidate(codes, &sections));
    const actual = pairedLiteralAliasOwner(codes, raw, source, &raw_sections, &sections, sections[0], &.{0}, &.{ 0, split }, false) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("enm", actual.code);
    try std.testing.expectEqualStrings("Средњи Енглески", actual.heading);
    try std.testing.expect(pairedLiteralAliasOwner(codes, raw, source, &raw_sections, &sections, sections[0], &.{}, &.{ 0, split }, false) == null);
    try std.testing.expect(pairedLiteralAliasOwner(codes, raw, source, &raw_sections, &sections, sections[0], &.{0}, &.{split}, false) == null);
    const duplicate_raw = [_]language_source.Section{ raw_sections[0], raw_sections[0] };
    try std.testing.expect(pairedLiteralAliasOwner(codes, raw, source, &duplicate_raw, &sections, sections[0], &.{0}, &.{ 0, split }, false) == null);
    const duplicate_output = [_]language_source.Section{ sections[0], sections[0], sections[1] };
    try std.testing.expect(pairedLiteralAliasOwner(codes, raw, source, &raw_sections, &duplicate_output, sections[0], &.{0}, &.{ 0, split }, false) == null);
    for ([_][]const u8{
        "==Middle English==\n===Noun===\n{{cs-noun}}\n# foreign\n",
        "==Middle English==\n===Noun===\n'''woman'''\n# no raw language declaration\n",
        "==Middle English==\n<nowiki>{{enm-noun}}</nowiki>\n# protected\n",
        "== Middle English ==\n{{enm-noun}}\n# changed physical heading\n",
    }) |bad| {
        const bad_sections = [_]language_source.Section{.{ .heading = "Middle English", .source = bad }};
        try std.testing.expect(pairedLiteralAliasOwner(codes, bad, source, &bad_sections, &sections, sections[0], &.{0}, &.{ 0, split }, false) == null);
    }
    const tainted: MissingText = .{ .bytes = expanded, .ranges = &.{.{ .start = 2, .end = 16, .occurrence = 1 }} };
    try std.testing.expect(pairedLiteralAliasOwner(codes, raw, tainted, &raw_sections, &sections, sections[0], &.{0}, &.{ 0, split }, false) == null);
    const protected: MissingText = .{ .bytes = expanded, .literal_curly_ranges = &.{.{ .start = 2, .end = 16 }} };
    try std.testing.expect(pairedLiteralAliasOwner(codes, raw, protected, &raw_sections, &sections, sections[0], &.{0}, &.{ 0, split }, false) == null);
    const lost: MissingText = .{ .bytes = expanded, .lost_missing_range = true };
    try std.testing.expect(pairedLiteralAliasOwner(codes, raw, lost, &raw_sections, &sections, sections[0], &.{0}, &.{ 0, split }, false) == null);
    const unknown = [_]language_source.Section{.{ .heading = "Unowned", .source = "==Unowned==\n{{enm-noun}}\n" }};
    try std.testing.expect(!literalAliasPairCandidate(codes, &unknown));
}


test "Writer preserves resolved owner lifetime and rejects conflicting final headings" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/owners", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, std.testing.allocator, root); defer writer.deinit();
    var page_arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer page_arena.deinit();
    const pa = page_arena.allocator();
    const payload = try presentation_document.compileAlloc(a, "first", .language, "Source name", "project-code", "# [[target|sense]]", null);
    var page: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "first" };
    const prepared: PageOutput = .{ .prepared = &page };
    var heading = [_]u8{'S','o','u','r','c','e',' ','n','a','m','e'};
    var code_value = [_]u8{'p','r','o','j','e','c','t','-','c','o','d','e'};
    try prepared.appendLanguage(pa, .{ .heading = &heading, .code = &code_value }, "first", payload);
    @memset(&heading, 'x'); @memset(&code_value, 'x');
    try std.testing.expectEqualStrings("project-code", page.records.items[0].language_code);
    try writer.commitPreparedPrefix(pa, &page);
    _ = page_arena.reset(.free_all);
    const direct: PageOutput = .{ .direct = &writer.spools };
    try direct.appendLanguage(a, .{ .heading = "Source name", .code = "project-code" }, "second", payload);
    try std.testing.expectError(error.ConflictingLanguageOwner,
        direct.appendLanguage(a, .{ .heading = "Source name", .code = "other" }, "collision", payload));
    try std.testing.expectError(error.ConflictingLanguageOwner,
        direct.appendLanguage(a, .{ .heading = "Source name", .code = "" }, "unknown-collision", payload));
    try direct.appendLanguage(a, .{ .heading = "Unclassified", .code = "" }, "unknown", payload);
    try std.testing.expectError(error.ConflictingLanguageOwner,
        direct.appendLanguage(a, .{ .heading = "Unclassified", .code = "project-code" }, "borrowed", payload));
    var failing = std.testing.FailingAllocator.init(a, .{ .fail_index = 0 });
    const bucket: usize = @intCast(std.hash.Wyhash.hash(0, "Retry name") % language_bucket_count);
    const prior_offset = writer.spools.language[bucket].offset;
    try std.testing.expectError(error.OutOfMemory,
        direct.appendLanguage(failing.allocator(), .{ .heading = "Retry name", .code = "failed-code" }, "failed", payload));
    try std.testing.expect(!writer.spools.language_owners.contains("Retry name"));
    try std.testing.expectEqual(prior_offset, writer.spools.language[bucket].offset);
    try direct.appendLanguage(a, .{ .heading = "Retry name", .code = "retry-code" }, "retry", payload);
    const stats = try writer.finish(.{});
    try std.testing.expectEqual(@as(usize, 3), stats.language_blobs);
    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "Source name")); defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    try std.testing.expectEqualStrings("project-code", (try blob.languageMetadata()).code);
    var records = blob.iterator();
    const first = (try records.next()).?; const second = (try records.next()).?;
    try std.testing.expectEqualStrings("first", first.title); try std.testing.expectEqualStrings("second", second.title);
    try std.testing.expectEqualSlices(u8, payload, first.payload); try std.testing.expectEqualSlices(u8, payload, second.payload);
    try std.testing.expect((try records.next()) == null);
    var unknown = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "Unclassified")); defer unknown.deinit();
    try std.testing.expectEqualStrings("", (try (try blob_format.inspect(unknown.bytes)).languageMetadata()).code);
}

test "wrapped equals language declarations retain code and reject partial or deeper headings" {
    const F = struct {
        fn section(source: []const u8, heading: []const u8) language_source.Section {
            return .{ .source = source, .heading = heading };
        }
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            return if (std.mem.eql(u8, value, "nb")) .{ .code = "nb", .heading = "Bokmal" } else null;
        }
    };
    const codes: LanguageCodes = .{ .resolve_fn = F.resolve };
    const actual = F.section("=={{=roa-nor=}}==\n# ankizivavy", "{{=roa-nor=}}");
    try std.testing.expectEqualStrings("roa-nor", equalsSectionDeclaration(actual).?);
    try std.testing.expect(hasExplicitLanguageDeclaration(codes, actual));
    try std.testing.expect(resolveSection(codes, actual) == null);
    const argument = F.section("=={{=roa-nor=|nb|display=[[Bokmal]]}}==\n# body", "{{=roa-nor=|nb|display=[[Bokmal]]}}");
    try std.testing.expectEqualStrings("roa-nor", equalsSectionDeclaration(argument).?);
    try std.testing.expect(resolveSection(codes, argument) == null);
    const known = F.section("=={{=nb=|roa-nor}}==\n# body", "{{=nb=|roa-nor}}");
    try std.testing.expectEqualStrings("nb", resolveSection(codes, known).?.code);
    for ([_]language_source.Section{
        F.section("==={{=roa-nor=}}===\n# body", "{{=roa-nor=}}"),
        F.section("=={{=roa-nor=}} trailing==\n# body", "{{=roa-nor=}} trailing"),
        F.section("=={{=roa-nor=}}==\n# body", "{{=nb=}}"),
        F.section("==<nowiki>{{=roa-nor=}}</nowiki>==\n# body", "<nowiki>{{=roa-nor=}}</nowiki>"),
        F.section("=={{-roa-nor-}}==\n# body", "{{-roa-nor-}}"),
        F.section("=={{=roa-nor=}}{{=nb=}}==\n# body", "{{=roa-nor=}}{{=nb=}}"),
        F.section("<!--=={{=roa-nor=}}==-->\n# body", "{{=roa-nor=}}"),
    }) |section| try std.testing.expect(equalsSectionDeclaration(section) == null);
}

test "wrapped unknown equals region preserves complete body and cannot inherit prior or rendered owner" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const F = struct {
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            inline for (.{ .{ "frm", "Middle French" }, .{ "nb", "Bokmal" } }) |row|
                if (std.mem.eql(u8, value, row[0]) or std.mem.eql(u8, value, row[1]))
                    return .{ .code = row[0], .heading = row[1] };
            return null;
        }
    };
    const codes: LanguageCodes = .{ .resolve_fn = F.resolve };
    // The selected fille declaration and all three definition strings are
    // retained verbatim. Only the bounded surrounding test regions are synthetic;
    // this is not an expanded whole-page reconstruction or a Norwegian alias.
    const body = "===Anarana iombonana===\n# ankizivavy\n# lamba rongony\n# zanakao vavy\n" ++
        "====Tsiahy====\n* [https://example.test/NAOB/fille_2 NAOB] [[fille|fille]]\n";
    const first = "==Middle French==\n# '''FIRST''' [[avant|before]]\n";
    const last = "==Bokmal==\n# ''LAST'' [[etter|after]]\n";
    const raw = "=={{=frm=}}==\n# FIRST\n=={{=roa-nor=}}==\n" ++ body ++ "=={{=nb=}}==\n# LAST\n";
    inline for (.{ "Nôrmana", "Bokmal" }) |label| {
        const middle = "==" ++ label ++ "==\n" ++ body;
        const source = first ++ middle ++ last;
        var page: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "fille" };
        try page.compileWithPhases(a, codes, source, raw, null, null, null, null);
        try std.testing.expectEqual(@as(usize, 3), page.records.items.len);
        for (page.records.items, 0..) |record, i| {
            const owner: ResolvedLanguage = switch (i) {
                0 => .{ .code = "frm", .heading = "Middle French" },
                1 => .{ .code = "", .heading = "Unclassified" },
                else => .{ .code = "nb", .heading = "Bokmal" },
            };
            try std.testing.expectEqualStrings(owner.heading, record.key);
            const actual = try blobs.presentation_codec.decodeAlloc(a, record.payload, "fille", .language, .{ .code = owner.code, .heading = owner.heading });
            const reference = try presentation_document.compileReportedWithLinkTrailAlloc(a, "fille", .language, owner.heading, owner.code,
                switch (i) { 0 => first, 1 => middle, else => last }, null, codes.link_trail, null, null);
            const expected = try blobs.presentation_codec.decodeAlloc(a, reference, "fille", .language, .{ .code = owner.code, .heading = owner.heading });
            // Duplicate rendered headings retain their original global anchors.
            if (i == 2 and std.mem.eql(u8, label, "Bokmal")) {
                var adjusted = expected;
                const sections = try a.dupe(blobs.presentation_types.Section, expected.entry.sections);
                sections[0].anchor = "Bokmal_2";
                adjusted.entry.sections = sections;
                try std.testing.expectEqualDeep(adjusted, actual);
            } else try std.testing.expectEqualDeep(expected, actual);
            try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, actual));
        }
    }
}

test "complete retained fille raw keeps ten corresponding language regions and nine known owners" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const raw = @embedFile("testdata/mg-fille-boundary/raw.wikitext");
    const F = struct {
        const rows = [_]struct { raw: []const u8, code: []const u8, owner: []const u8, rendered: []const u8 }{
            .{ .raw = "fr", .code = "fr", .owner = "French", .rendered = "Frantsay" },
            .{ .raw = "nb", .code = "nb", .owner = "Norwegian Bokmål", .rendered = "Norveziana (Bokmal)" },
            .{ .raw = "ga", .code = "gaa", .owner = "Ga", .rendered = "Gaelita irlandey" },
            .{ .raw = "enm", .code = "enm", .owner = "Middle English", .rendered = "Anglisy Tafovoany" },
            .{ .raw = "frm", .code = "frm", .owner = "Middle French", .rendered = "Romantsa" },
            .{ .raw = "roa-nor", .code = "", .owner = "Unclassified", .rendered = "Nôrmana" },
            .{ .raw = "nn", .code = "nn", .owner = "Norwegian Nynorsk", .rendered = "Norvejiana (Nynorsk)" },
            .{ .raw = "fro", .code = "fro", .owner = "Old French", .rendered = "Frantsay taloha" },
            .{ .raw = "pdc", .code = "pdc", .owner = "Pennsylvania German", .rendered = "Alemànin'i Pensilvania" },
            .{ .raw = "stq", .code = "stq", .owner = "Saterland Frisian", .rendered = "Frizianin'I Saterland" },
        };
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            for (rows) |row| {
                if (row.code.len == 0) continue;
                if (std.mem.eql(u8, value, row.raw) or std.mem.eql(u8, value, row.code) or std.mem.eql(u8, value, row.owner))
                    return .{ .code = row.code, .heading = row.owner };
            }
            return null;
        }
    };
    // These existing owners are retained as selected, including the independent
    // ga/gaa registry alias; this test does not introduce or endorse a new alias.
    const codes: LanguageCodes = .{ .resolve_fn = F.resolve };
    const markers: LanguageMarkers = .{ .codes = &codes };
    var iterator = languageSections(raw, &markers);
    for (F.rows) |row| {
        const section = iterator.next() orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(row.raw, equalsSectionDeclaration(section).?);
    }
    try std.testing.expect(iterator.next() == null);
    // Full raw is genuine. The ten displayed root labels come from the actual
    // complete Reader, while these body lines are deliberate representative
    // controls; no missing full expansion or page replay is fabricated.
    var source: std.ArrayList(u8) = .empty;
    var regions: [F.rows.len][]const u8 = undefined;
    for (F.rows, 0..) |row, i| {
        regions[i] = try std.fmt.allocPrint(a, "=={s}==\n# '''REGION_{d}''' [[target-{d}|action-{d}]]\n", .{ row.rendered, i, i, i });
        try source.appendSlice(a, regions[i]);
    }
    var page: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "fille" };
    try page.compileWithPhases(a, codes, source.items, raw, null, null, null, null);
    try std.testing.expectEqual(F.rows.len, page.records.items.len);
    for (page.records.items, F.rows, regions) |record, row, region| {
        try std.testing.expectEqualStrings(row.owner, record.key);
        const actual = try blobs.presentation_codec.decodeAlloc(a, record.payload, "fille", .language, .{ .code = row.code, .heading = row.owner });
        const reference = try presentation_document.compileReportedWithLinkTrailAlloc(a, "fille", .language, row.owner, row.code, region, null, codes.link_trail, null, null);
        const expected = try blobs.presentation_codec.decodeAlloc(a, reference, "fille", .language, .{ .code = row.code, .heading = row.owner });
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, actual));
    }
}

test "supplemental namespace Writer binds complete source projection while retaining foreign and missing proof refusals" {
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const styles = @import("table_style_profile.zig");
    const syntax = blobs.wikitext_syntax;
    const title = "Pêvek:Source projection";
    const source = "==Section==\n[https://example.org]\n<div style=\"clear:both\"></div>\n[[Kept#part|complete body]]\n";
    var ns = try @import("namespace_registry").Registry.init(a,
        "# wikidict-namespace-registry-v1\n# wiki\tkuwiktionary\n# dump-date\t20261001\n# content-language\tku\n" ++
        "0\t\t\tcase-sensitive\t0\t1\t0\t\tmain\tdictionary_entries\n" ++
        "10\tŞablon\tTemplate\tcase-sensitive\t1\t0\t0\t\tcompile_only\tstandard_build_input\tداڕێژە\n" ++
        "14\tKategorî\tCategory\tcase-sensitive\t0\t0\t0\t\tcompile_only\tstandard_build_input\tپۆل\n" ++
        "100\tPêvek\tAppendix\tcase-sensitive\t1\t0\t0\t\tsupplemental\tunclassified_subject_retained\n");
    defer ns.deinit();
    var global = try styles.parseForTargetAlloc(a, "", .screen); defer global.deinit();
    // The custody positive independently refutes this entire page rule using
    // the complete absent-class certificate. Physical DIV parent proof alone
    // does not certify all possible page descendants for root preflight.
    var selected = try styles.joinPageSourcesAlloc(a, &global, &.{}, &.{.{ .css = ".absent blockquote > :last-child{margin-bottom:0}", .base_url = "" }}); defer selected.deinit();
    // Retain the original potentially active page rule as an explicit refusal.
    var unproved = try styles.joinPageSourcesAlloc(a, &global, &.{}, &.{.{ .css = ".mw-body blockquote > :last-child{margin-bottom:0}", .base_url = "" }}); defer unproved.deinit();
    var roots = [_]styles.TextElement{
        .{ .tag = "html", .ancestry_complete = true, .physical_ancestry_complete = true },
        .{ .tag = "body", .classes = "mw-body", .ancestry_complete = true, .physical_ancestry_complete = true },
        .{ .tag = "div", .classes = "mw-parser-output", .ancestry_complete = true, .physical_ancestry_complete = true },
    };
    roots[1].parent = &roots[0]; roots[2].parent = &roots[1];
    const start = std.mem.indexOf(u8, source, "<div").?;
    const tag = syntax.tagAt(source, start).?;
    const proof = [_]styles.SourceLiteralDivProof{.{ .range = .{
        .anchor_start = start, .anchor_end = syntax.matchingTag(source, tag).?.end,
        .name_start = start + 1, .name_len = tag.name.len,
        .attrs_start = @intFromPtr(tag.attrs.ptr) - @intFromPtr(source.ptr), .attrs_len = tag.attrs.len,
    }, .parent_start = null }};
    const base_scope: styles.BoundedTextClassScope = .{
        .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "",
        .complete_ancestor_class_superset = "mw-body mw-parser-output", .complete_ancestor_id_superset = "",
        .page_styles = &selected, .page_style_root = &roots[2], .page_style_complete_root = &roots[2],
        .source_literal_divs_source = source, .source_literal_divs = &proof,
    };
    const Control = struct {
        fn sizing(_: ?*const anyopaque, _: std.mem.Allocator, _: []const u8, _: blobs.presentation_types.FigureFormat, _: ?u32, _: ?u32) std.mem.Allocator.Error!?blobs.presentation_types.FigureSizingPolicy { return null; }
    };
    var complete_payload: ?[]const u8 = null;
    for (0..6) |mode| {
        var scope = base_scope;
        var selected_source: []const u8 = source;
        switch (mode) {
            0 => {},
            1 => selected_source = try a.dupe(u8, source),
            2 => scope.source_literal_divs = &.{},
            3 => scope.page_style_complete_root = null,
            4 => {}, // Independent empty-sheet rendering of the same complete page.
            5 => scope.page_styles = &unproved,
            else => unreachable,
        }
        // Keep the original root-uncertain sheet in every custody negative.
        // The absent-class sheet is the independent custody positive only.
        if (mode != 0 and mode != 4) scope.page_styles = &unproved;
        const figure: presentation_document.FigureSizingSource = .{ .resolve_fn = Control.sizing,
            .text_class_scope = .{ .source = selected_source, .scope = &scope } };
        const codes: LanguageCodes = .{ .namespace_catalog = &ns, .table_styles = if (mode == 4) &global else if (mode == 0) &selected else &unproved, .figure_sizing = if (mode == 4) null else figure };
        const output = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/namespace-projection-{d}", .{ tmp.sub_path, mode });
        var writer = try Writer.init(std.testing.io, a, output); defer writer.deinit();
        writer.language_codes = codes;
        try writer.addExpandedPage(a, .{ .id = 100, .kind = .supplemental }, title, source, source, null);
        const stats = try writer.finish(codes);
        try std.testing.expectEqual(@as(usize, 1), stats.supplemental_records);
        try std.testing.expectEqual(@as(usize, 0), stats.language_records);
        const report = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, try std.fs.path.join(a, &.{ output, "fallback-pages.jsonl" }), a, .limited(64 * 1024));
        if (mode == 0 or mode == 4) try std.testing.expectEqualStrings("", report) else if (mode == 5) {
            try std.testing.expect(std.mem.indexOf(u8, report, "unresolved_table_style") != null);
            try std.testing.expect(std.mem.indexOf(u8, report, "unsupported_element") == null);
        } else {
            try std.testing.expect(std.mem.indexOf(u8, report, "unresolved_table_style") != null);
            try std.testing.expect(std.mem.indexOf(u8, report, "unsupported_element") != null);
        }
        var mapped = try mmapPath(std.testing.io, try std.fs.path.join(a, &.{ output, "supplemental.wikblb" })); defer mapped.deinit();
        const blob = try blob_format.inspect(mapped.bytes);
        var index = try blob.buildTrustedIndexAlloc(a); defer index.deinit(a);
        const record = (try index.find(title)) orelse return error.TestUnexpectedResult;
        if (mode == 0) complete_payload = try a.dupe(u8, record.payload);
        if (mode == 4 or mode == 5) try std.testing.expectEqualSlices(u8, complete_payload.?, record.payload);
        const stored = try blobs.presentation_codec.decodeAlloc(a, record.payload, title, .supplemental, null);
        try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, stored));
        try std.testing.expectEqualStrings(title, stored.entry.title);
        try std.testing.expect(stored.entry.language == null and stored.entry.language_code.len == 0);
        try std.testing.expect(LeadingRegionFixture.contains(stored.entry, "complete body"));
        try std.testing.expect(LeadingRegionFixture.contains(stored.entry, "https://example.org"));
        var internal: usize = 0; var numbered: usize = 0;
        for (stored.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
            if (span.kind == .link and std.mem.eql(u8, span.target, "Kept#part") and span.target_fragment == null) internal += 1;
            if (std.mem.eql(u8, span.target, "https://example.org") and std.mem.eql(u8, span.text, "[1]")) numbered += 1;
        };
        try std.testing.expectEqual(@as(usize, 1), internal);
        try std.testing.expectEqual(@as(usize, 1), numbered);
    }
}

test "language group fragment allocation failure preserves provenance and permits retry" {
    const a = std.testing.allocator;
    const source = "prefixfirstsecond";
    const first: PageSourceFragment = .{ .source = source[6..11], .original_start = 6 };
    const second: PageSourceFragment = .{ .source = source[11..], .original_start = 11 };
    var group: PageLanguageGroup = .{ .language = .{ .code = "en", .heading = "English" } };
    defer group.fragments.deinit(a);
    try group.fragments.ensureTotalCapacityPrecise(a, 1);
    try group.appendSource(a, first);
    var failing = std.testing.FailingAllocator.init(a, .{ .fail_index = 0, .resize_fail_index = 0 });
    try std.testing.expectError(error.OutOfMemory, group.appendSource(failing.allocator(), second));
    try std.testing.expectEqual(@as(usize, 1), group.fragments.items.len);
    try std.testing.expectEqual(first.original_start, group.fragments.items[0].original_start);
    try std.testing.expect(group.fragments.items[0].source.ptr == first.source.ptr);
    try std.testing.expectEqualStrings("first", group.fragments.items[0].source);
    try group.appendSource(a, second);
    try std.testing.expectEqual(@as(usize, 2), group.fragments.items.len);
    try std.testing.expect(group.fragments.items[1].source.ptr == second.source.ptr);

    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    const tracked: MissingText = .{ .bytes = source, .ranges = &.{.{ .start = 6, .end = 11, .occurrence = 1 }},
        .unknown = true, .lost_missing_range = true };
    const owner = try missingOwnerSourceAlloc(arena.allocator(), tracked, group.fragments.items, source[0..6]);
    try std.testing.expectEqualStrings(source, owner.bytes);
    try std.testing.expectEqualDeep(tracked.ranges, owner.ranges);
    try std.testing.expect(owner.unknown and owner.lost_missing_range);
    const projection = try ownerHeadingSourceRangesAlloc(arena.allocator(), group.fragments.items, 6);
    const expected_projection: []const presentation_document.HeadingSourceRange = &.{
        .{ .owner_start = 0, .page_start = 0, .len = 6 },
        .{ .owner_start = 6, .page_start = 6, .len = 5 },
        .{ .owner_start = 11, .page_start = 11, .len = 6 },
    };
    try std.testing.expectEqualDeep(expected_projection, projection);
    var invalid = second;
    invalid.original_start = source.len + 1;
    try std.testing.expectError(error.InvalidPreContext,
        missingOwnerSourceAlloc(arena.allocator(), tracked, &.{invalid}, ""));
    try std.testing.expectEqualStrings(source, tracked.bytes);
}

test "normal page preparation retains selected nested Table source custody through final Document and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const compiler = @import("presentation_compile.zig");
    const styles = @import("table_style_profile.zig");
    const T = blobs.presentation_types;
    var phase: []const u8 = "initialize nested custody fixture";
    var phase_source = @src();
    errdefer std.debug.print("RU_NESTED_CUSTODY_PHASE={s} source={s}:{d}:{d}\n", .{ phase, phase_source.file, phase_source.line, phase_source.column });
    const F = struct {
        const source = "==English==\n===Noun===\nbefore [[Before|first action]]\n<div align=\"center\">\n{| style='margin:0 auto;width:70%'\n| [[Target|complete cell]]\n|}\n</div>\nafter [[After|last action]]\n";
        const opening = std.mem.indexOf(u8, source, "{|").?;
        const parent_start = std.mem.indexOf(u8, source, "<div").?;
        const parent_end = parent_start + "<div align=\"center\">".len;
        const Bound = struct {
            source: []const u8,
            contexts: []const styles.TableContainingDirectionContext,
            parents: []const []const u8,
            accepted: usize = 0,
            opening_offset: usize = opening,
            wrong_offset: bool = false,
            fn observe(raw: ?*const anyopaque, _: std.mem.Allocator, whole: []const u8, at: usize) std.mem.Allocator.Error!?compiler.TableContainingDirectionObservation {
                const self: *@This() = @ptrCast(@alignCast(@constCast(raw orelse return null)));
                if (whole.ptr != self.source.ptr or whole.len != self.source.len or
                    at != self.opening_offset + @intFromBool(self.wrong_offset)) return null;
                self.accepted += 1;
                return .{ .contexts = self.contexts, .parents = self.parents };
            }
        };
        fn sizing(_: ?*const anyopaque, _: std.mem.Allocator, _: []const u8, _: T.FigureFormat, _: ?u32, _: ?u32) std.mem.Allocator.Error!?T.FigureSizingPolicy { return null; }
        fn table(entry: *T.Entry) !*T.Table {
            var found: ?*T.Table = null;
            const sections = @constCast(entry.sections);
            for (sections) |*section| try findTable(@constCast(section.blocks), &found);
            return found orelse error.ExpectedNestedSourceTable;
        }
        fn findTable(blocks: []T.Block, found: *?*T.Table) anyerror!void {
            for (blocks) |*block| {
                if (block.table) |*value| { try std.testing.expect(found.* == null); found.* = value; }
                if (block.container) |container| try findTable(@constCast(container.blocks), found);
            }
        }
        fn actions(spans: []const T.Span, counts: *[3]usize) !void {
            for (spans) |span| if (span.kind == .link) {
                const targets = [_][]const u8{ "Before", "Target", "After" };
                const labels = [_][]const u8{ "first action", "complete cell", "last action" };
                var found = false;
                for (targets, labels, 0..) |target, label, index| if (std.mem.eql(u8, span.target, target)) {
                    try std.testing.expectEqualStrings(label, span.text); counts[index] += 1; found = true;
                };
                try std.testing.expect(found);
            };
        }
        fn bodyActions(blocks: []const T.Block, counts: *[3]usize) anyerror!void {
            for (blocks) |block| {
                try actions(block.spans, counts);
                if (block.table) |value| for (value.rows) |row| for (row.cells) |cell| try actions(cell.spans, counts);
                if (block.container) |container| try bodyActions(container.blocks, counts);
            }
        }
        fn compile(allocator: std.mem.Allocator, codes: LanguageCodes, input: []const u8, metadata: ?[]const u8) !PreparedPage {
            var page: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "nested source custody" };
            try page.compileWithPhases(allocator, codes, input, input, null, null, metadata, null);
            try std.testing.expectEqual(@as(usize, 1), page.records.items.len);
            try std.testing.expectEqual(@as(usize, 1), page.stats.language_records);
            return page;
        }
        fn decode(allocator: std.mem.Allocator, page: PreparedPage) !T.Stored {
            const record = page.records.items[0];
            try std.testing.expectEqualStrings("English", record.key);
            try std.testing.expectEqualStrings("en", record.language_code);
            return blobs.presentation_codec.decodeAlloc(allocator, record.payload, page.title, .language, .{ .heading = "English", .code = "en" });
        }
    };
    var plain = try styles.parseForTargetAlloc(a, "", .screen); defer plain.deinit();
    var captured = try styles.parseForTargetAlloc(a, "html{direction:rtl}table{direction:ltr}", .screen); defer captured.deinit();
    const nodes = [_]styles.ObservedStyleNode{
        .{ .tag = "html", .parent = null, .attributes = &.{} },
        .{ .tag = "body", .parent = 0, .attributes = &.{} },
        .{ .tag = "div", .parent = 1, .attributes = &.{.{ .name = "class", .value = "mw-parser-output" }} },
        .{ .tag = "div", .parent = 2, .attributes = &.{.{ .name = "align", .value = "center" }} },
        .{ .tag = "table", .parent = 3, .attributes = &.{.{ .name = "style", .value = "margin:0 auto;width:70%" }} },
    };
    const contexts = [_]styles.TableContainingDirectionContext{.{ .styles = &captured, .nodes = &nodes, .root = 2, .table = 4 }};
    var bound: F.Bound = .{ .source = F.source, .contexts = &contexts, .parents = &.{F.source[F.parent_start..F.parent_end]} };
    var codes = TestLanguages.codes(); codes.table_styles = &plain;
    // The independent old path owns the same complete body and actions, but
    // cannot resolve the source TABLE's automatic margins without its parent.
    const baseline_page = try F.compile(a, codes, F.source, null);
    try std.testing.expect(baseline_page.fallbacks.unresolved_table_style);
    var expected = try F.decode(a, baseline_page);
    const expected_table = try F.table(&expected.entry);
    try std.testing.expect(expected_table.style != null and expected_table.style.?.margin_values == null and
        expected_table.style.?.containing_direction == null);
    const zero: T.ContainerMargin = .{ .length = .{ .unit = .px, .value = 0 } };
    expected_table.style.?.margin_values = .{ .top = zero, .right = .auto, .bottom = zero, .left = .auto };
    expected_table.style.?.containing_direction = .rtl;
    const selected: compiler.TableContainingDirectionSource = .{ .root_only = true, .source = F.source,
        .context = &bound, .observe = F.Bound.observe };
    codes.figure_sizing = .{ .resolve_fn = F.sizing, .table_containing_direction = selected };
    try std.testing.expect(codes.figure_sizing.?.text_class_scope == null);
    phase = "independent captured parent and table geometry preflight"; phase_source = @src();
    const captured_geometry = (try styles.resolveObservedRootTableContainingDirection(a, &contexts, null, expected_table.style.?, true)) orelse return error.ExpectedCapturedNestedTableGeometry;
    try std.testing.expectEqual(T.TableContainingDirection.rtl, captured_geometry.direction);
    try std.testing.expect(captured_geometry.responsive_geometry_accounted);
    phase = "compile nested source through final Document"; phase_source = @src();
    const page = try F.compile(a, codes, F.source, null);
    errdefer std.debug.print("RU_NESTED_CUSTODY_ACTUAL accepted={d} report={any}\n", .{ bound.accepted, page.fallbacks });
    phase = "verify callback received original source and offset"; phase_source = @src();
    try std.testing.expect(bound.accepted != 0);
    phase = "verify complete final report"; phase_source = @src();
    try std.testing.expectEqualDeep(presentation_document.Fallbacks{}, page.fallbacks);
    const actual = try F.decode(a, page);
    phase = "verify complete Stored body and style"; phase_source = @src();
    try std.testing.expectEqualDeep(expected, actual);
    var actions: [3]usize = .{ 0, 0, 0 };
    for (actual.entry.sections) |section| try F.bodyActions(section.blocks, &actions);
    try std.testing.expectEqualDeep([3]usize{ 1, 1, 1 }, actions);
    try std.testing.expectEqualSlices(u8, page.records.items[0].payload, try blobs.presentation_codec.encodeAlloc(a, actual));
    // Preserve the original unquoted-parent spelling as a refusal. This
    // root-only route deliberately admits the exact quoted plain-parent shape;
    // the captured geometry query alone cannot authorize a different spelling.
    phase = "verify original unquoted parent refusal"; phase_source = @src();
    const unquoted_opening = "<div align=center>";
    const unquoted_source = try std.mem.concat(a, u8, &.{ F.source[0..F.parent_start], unquoted_opening, F.source[F.parent_end..] });
    var unquoted_bound: F.Bound = .{ .source = unquoted_source, .contexts = &contexts,
        .parents = &.{unquoted_source[F.parent_start .. F.parent_start + unquoted_opening.len]},
        .opening_offset = std.mem.indexOf(u8, unquoted_source, "{|").? };
    var unquoted_codes = codes;
    unquoted_codes.figure_sizing.?.table_containing_direction = .{ .root_only = true, .source = unquoted_source,
        .context = &unquoted_bound, .observe = F.Bound.observe };
    const unquoted_page = try F.compile(a, unquoted_codes, unquoted_source, null);
    try std.testing.expect(unquoted_bound.accepted != 0);
    try std.testing.expect(unquoted_page.fallbacks.unresolved_table_style);
    var unquoted_plain = unquoted_codes; unquoted_plain.figure_sizing = null;
    const unquoted_baseline = try F.compile(a, unquoted_plain, unquoted_source, null);
    const unquoted_stored = try F.decode(a, unquoted_page);
    try std.testing.expectEqualDeep(try F.decode(a, unquoted_baseline), unquoted_stored);
    try std.testing.expectEqualSlices(u8, unquoted_page.records.items[0].payload,
        try blobs.presentation_codec.encodeAlloc(a, unquoted_stored));
    // Detached/equal bytes, tainted current ownership and a foreign callback
    // retain the original complete output; none may borrow source authority.
    phase = "verify original six custody refusals"; phase_source = @src();
    for (0..6) |mode| {
        errdefer std.debug.print("RU_NESTED_CUSTODY_REFUSAL mode={d}\n", .{mode});
        bound.accepted = 0; bound.source = F.source; bound.wrong_offset = false;
        var refused_codes = codes;
        const input = if (mode == 0) try a.dupe(u8, F.source) else F.source;
        var metadata: ?[]const u8 = null;
        if (mode == 1 or mode == 2) {
            var tracked = MissingText.untracked(input);
            if (mode == 1) tracked.unknown = true else {
                // lost_missing_range is deliberately in-process only. A real
                // discarded range also makes the transformed source unknown;
                // that existing coordinate flag survives the metadata boundary.
                tracked = MissingText.transformedFrom(.{ .bytes = input,
                    .ranges = &.{.{ .start = 0, .end = 1, .occurrence = 1 }} }, input);
                try std.testing.expect(tracked.unknown and tracked.lost_missing_range);
                var copy: [1]presentation_document.SourceElementProjection.Copy = undefined;
                try std.testing.expect(unchangedTableSourceProjection(refused_codes.figure_sizing,
                    tracked, MissingText.untracked(input), &copy) == null);
            }
            metadata = try missing_dependency.encode(a, tracked, MissingText.untracked(""), &.{});
            var decoded = try missing_dependency.decode(a, metadata.?, input, ""); defer decoded.deinit();
            try std.testing.expect(decoded.output().unknown and !decoded.output().lost_missing_range);
            try std.testing.expectEqual(@as(usize, 0), decoded.output().ranges.len);
        }
        if (mode == 3) bound.wrong_offset = true;
        if (mode == 4) bound.source = try a.dupe(u8, F.source);
        if (mode == 5) refused_codes.figure_sizing.?.table_containing_direction = null;
        const refused_page = try F.compile(a, refused_codes, input, metadata);
        try std.testing.expectEqual(@as(usize, 0), bound.accepted);
        try std.testing.expect(refused_page.fallbacks.unresolved_table_style);
        try std.testing.expectEqualDeep(try F.decode(a, baseline_page), try F.decode(a, refused_page));
        const refused = try F.decode(a, refused_page);
        try std.testing.expectEqualSlices(u8, refused_page.records.items[0].payload, try blobs.presentation_codec.encodeAlloc(a, refused));
    }
}

test "ordinary Writer retains issued local targets through language and supplemental source preparation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); const io = std.testing.io;
    const C = @import("presentation_compile.zig");
    const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    const Proof = struct {
        source: []const u8,
        calls: usize = 0,
        accepted: usize = 0,
        last_guard: []const u8 = "none",
        fn resolve(context: ?*const anyopaque, _: std.mem.Allocator, operation: C.TableSourceAnchorOperation) C.Error!?[]const u8 {
            const self: *@This() = @ptrCast(@alignCast(@constCast(context orelse return null)));
            self.calls += 1; self.last_guard = "source";
            if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len) return null;
            self.last_guard = "token_offset";
            const at = std.math.sub(usize, @intFromPtr(operation.token.ptr), @intFromPtr(self.source.ptr)) catch return null;
            self.last_guard = "token_range_and_target";
            if (at > self.source.len or operation.token.len > self.source.len - at or !std.mem.eql(u8, operation.target, "gh")) return null;
            self.accepted += 1; self.last_guard = "accepted";
            return "Resolved";
        }
        fn language(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            return if (std.mem.eql(u8, name, "English")) .{ .code = "en", .heading = "English" } else null;
        }
        fn code(context: ?*const anyopaque, name: []const u8) ?[]const u8 {
            return if (language(context, name)) |value| value.code else null;
        }
    };
    for ([_]bool{ false, true }) |supplemental| for (0..3) |mode| {
        const source = try a.dupe(u8, if (supplemental)
            "==Section==\nbefore [[gh|visible]]a after\n[https://example.org]\n"
        else "==English==\nbefore [[gh|visible]]a after\n[https://example.org]\n");
        var proof = Proof{ .source = source };
        var phase: []const u8 = "configure source capability";
        var phase_source = @src();
        errdefer std.debug.print("LOCAL_TARGET_WRITER supplemental={any} mode={d} phase={s} source={s}:{d}:{d} callback_calls={d} accepted={d} last_guard={s}\n",
            .{ supplemental, mode, phase, phase_source.file, phase_source.line, phase_source.column, proof.calls, proof.accepted, proof.last_guard });
        var codes: LanguageCodes = .{ .namespace_catalog = &ns, .get_fn = Proof.code,
            .resolve_fn = Proof.language, .strong_fn = Proof.language, .trusted_fn = Proof.language };
        if (mode != 2) codes.local_link_targets = .{
            .source = if (mode == 1) try a.dupe(u8, source) else source,
            .namespace_sha256 = ns.source_sha256, .context = &proof, .resolve = Proof.resolve,
        };
        const output = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/{s}-{d}", .{ tmp.sub_path, if (supplemental) "supplemental" else "main", mode });
        var writer = try Writer.init(io, a, output); defer writer.deinit();
        writer.language_codes = codes;
        const title = if (supplemental) "Appendix:Entry" else "Entry";
        phase = "ordinary addExpandedPage"; phase_source = @src();
        try writer.addExpandedPage(a, .{ .id = if (supplemental) 100 else 0, .kind = if (supplemental) .supplemental else .language }, title, source, source, null);
        phase = "finish Writer"; phase_source = @src();
        _ = try writer.finish(codes);
        const path = if (supplemental) try std.fs.path.join(a, &.{ output, "supplemental.wikblb" }) else try languageBlobPathAlloc(a, output, "English");
        var mapped = try mmapPath(io, path); defer mapped.deinit();
        const blob = try blob_format.inspect(mapped.bytes);
        var index = try blob.buildTrustedIndexAlloc(a); defer index.deinit(a);
        const record = (try index.find(title)) orelse return error.TestUnexpectedResult;
        phase = "decode stored entry"; phase_source = @src();
        const stored = try blobs.presentation_codec.decodeAlloc(a, record.payload, title,
            if (supplemental) .supplemental else .language,
            if (supplemental) null else .{ .code = "en", .heading = "English" });
        phase = "stored codec parity"; phase_source = @src();
        try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, stored));
        try std.testing.expect(LeadingRegionFixture.contains(stored.entry, "before"));
        try std.testing.expect(LeadingRegionFixture.contains(stored.entry, "after"));
        var internal: usize = 0; var external: usize = 0;
        var label: std.ArrayList(u8) = .empty;
        for (stored.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
            if (span.kind == .link) {
                phase = "assert internal action target"; phase_source = @src();
                try std.testing.expectEqualStrings(if (mode == 0) "Resolved" else "gh", span.target);
                try label.appendSlice(a, span.text); internal += 1;
            }
            if (span.kind == .external_link and std.mem.eql(u8, span.target, "https://example.org")) {
                try std.testing.expectEqualStrings("[1]", span.text); external += 1;
            }
        };
        try std.testing.expect(internal != 0);
        try std.testing.expectEqualStrings("visiblea", label.items);
        try std.testing.expectEqual(@as(usize, 1), external);
    };
}


test "unchanged selected Table page retains direct source custody without numbering projection" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const compiler = @import("presentation_compile.zig");
    const styles = @import("table_style_profile.zig");
    const T = blobs.presentation_types;
    const F = struct {
        const source = "==English==\n===Noun===\nbefore [[Before|first action]]\n{| style='margin:0 auto;width:70%'\n| [[Target#part|complete cell]]\n|}\nafter [[After|last action]]\n";
        const opening = std.mem.indexOf(u8, source, "{|").?;
        const Bound = struct {
            source: []const u8,
            contexts: []const styles.TableContainingDirectionContext,
            accepted: usize = 0,
            fn observe(raw: ?*const anyopaque, _: std.mem.Allocator, whole: []const u8, at: usize) std.mem.Allocator.Error!?compiler.TableContainingDirectionObservation {
                const self: *@This() = @ptrCast(@alignCast(@constCast(raw orelse return null)));
                if (whole.ptr != self.source.ptr or whole.len != self.source.len or at != opening) return null;
                self.accepted += 1;
                return .{ .contexts = self.contexts, .parents = &.{} };
            }
        };
        fn sizing(_: ?*const anyopaque, _: std.mem.Allocator, _: []const u8, _: T.FigureFormat, _: ?u32, _: ?u32) std.mem.Allocator.Error!?T.FigureSizingPolicy { return null; }
        fn compile(allocator: std.mem.Allocator, codes: LanguageCodes, input: []const u8, phase: ?*const presentation_document.PoemPhase) !PreparedPage {
            var page: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "unchanged phase custody" };
            try processMain(allocator, .{ .prepared = &page }, codes, page.title, input, input, null,
                &page.stats, &page.fallbacks, phase, null);
            try std.testing.expectEqual(@as(usize, 1), page.records.items.len);
            return page;
        }
        fn decode(allocator: std.mem.Allocator, page: PreparedPage) !T.Stored {
            const record = page.records.items[0];
            try std.testing.expectEqualStrings("English", record.key);
            try std.testing.expectEqualStrings("en", record.language_code);
            return blobs.presentation_codec.decodeAlloc(allocator, record.payload, page.title, .language,
                .{ .heading = "English", .code = "en" });
        }
    };
    var plain = try styles.parseForTargetAlloc(a, "", .screen); defer plain.deinit();
    var captured = try styles.parseForTargetAlloc(a, "html{direction:rtl}table{direction:ltr}", .screen); defer captured.deinit();
    const nodes = [_]styles.ObservedStyleNode{
        .{ .tag = "html", .parent = null, .attributes = &.{} },
        .{ .tag = "body", .parent = 0, .attributes = &.{} },
        .{ .tag = "div", .parent = 1, .attributes = &.{.{ .name = "class", .value = "mw-parser-output" }} },
        .{ .tag = "table", .parent = 2, .attributes = &.{.{ .name = "style", .value = "margin:0 auto;width:70%" }} },
    };
    const contexts = [_]styles.TableContainingDirectionContext{.{ .styles = &captured, .nodes = &nodes, .root = 2, .table = 3 }};
    var bound: F.Bound = .{ .source = F.source, .contexts = &contexts };
    var codes = TestLanguages.codes(); codes.table_styles = &plain;
    codes.figure_sizing = .{ .resolve_fn = F.sizing, .table_containing_direction = .{
        .root_only = true, .source = F.source, .context = &bound, .observe = F.Bound.observe } };
    const phase: presentation_document.PoemPhase = .{ .full_output = F.source, .items = &.{} };
    const numbered = try presentation_document.preparePageExternalLinksWithMissingAlloc(a, MissingText.untracked(F.source),
        .{ .observe_source_elements = true, .figure_sizing = codes.figure_sizing, .poem_phase = &phase });
    try std.testing.expect(numbered.source_element_projection == null and numbered.poem_phase != null);
    try std.testing.expectEqualStrings(F.source, numbered.source);
    const baseline = try F.compile(a, codes, F.source, null);
    try std.testing.expectEqualDeep(presentation_document.Fallbacks{}, baseline.fallbacks);
    const expected = try F.decode(a, baseline);
    bound.accepted = 0;
    const actual = try F.compile(a, codes, F.source, &phase);
    try std.testing.expect(bound.accepted != 0);
    try std.testing.expectEqualDeep(presentation_document.Fallbacks{}, actual.fallbacks);
    try std.testing.expectEqualDeep(expected, try F.decode(a, actual));
    try std.testing.expectEqualSlices(u8, baseline.records.items[0].payload, actual.records.items[0].payload);
    var tables: usize = 0; var actions: [3]usize = .{ 0, 0, 0 };
    for (expected.entry.sections) |section| for (section.blocks) |block| {
        for (block.spans) |span| if (span.kind == .link) {
            if (std.mem.eql(u8, span.target, "Before")) { try std.testing.expectEqualStrings("first action", span.text); actions[0] += 1; }
            else if (std.mem.eql(u8, span.target, "After")) { try std.testing.expectEqualStrings("last action", span.text); actions[2] += 1; }
            else return error.UnexpectedOuterAction;
        };
        if (block.table) |table| {
            tables += 1;
            try std.testing.expectEqual(@as(?T.TableContainingDirection, .rtl), table.style.?.containing_direction);
            try std.testing.expect(table.style.?.margin_values.?.left == .auto and table.style.?.margin_values.?.right == .auto);
            try std.testing.expectEqualDeep(T.StyleWidth{ .unit = .percent, .value = 70 }, table.style.?.width.?);
            for (table.rows) |row| for (row.cells) |cell| for (cell.spans) |span| if (span.kind == .link) {
                try std.testing.expectEqualStrings("Target#part", span.target);
                try std.testing.expectEqualStrings("complete cell", span.text);
                actions[1] += 1;
            };
        }
    };
    try std.testing.expectEqual(@as(usize, 1), tables);
    try std.testing.expectEqualDeep([3]usize{ 1, 1, 1 }, actions);
    try std.testing.expectEqualSlices(u8, actual.records.items[0].payload, try blobs.presentation_codec.encodeAlloc(a, expected));
    var copy: [1]presentation_document.SourceElementProjection.Copy = undefined;
    const original = MissingText.untracked(F.source);
    const prepared = MissingText.untracked(try a.dupe(u8, F.source));
    const direct = unchangedTableSourceProjection(codes.figure_sizing, original, prepared, &copy) orelse return error.ExpectedDirectSource;
    try std.testing.expect(direct.observed_source == null and direct.original.bytes.ptr == F.source.ptr);
    try std.testing.expect(direct.prepared.ptr == prepared.bytes.ptr and direct.prepared.ptr != F.source.ptr);
    try std.testing.expectEqual(@as(?usize, F.opening), direct.originalRange(F.opening, 2));
    for (0..10) |mode| {
        var old = original; var next = prepared; var figure = codes.figure_sizing.?;
        switch (mode) {
            0 => old.bytes = try a.dupe(u8, F.source),
            1 => old.unknown = true,
            2 => next.unknown = true,
            3 => old.lost_missing_range = true,
            4 => next.lost_missing_range = true,
            5 => old.ranges = &.{.{ .start = 0, .end = 1, .occurrence = 1 }},
            6 => next.literal_curly_ranges = &.{.{ .start = 0, .end = 1 }},
            7 => next.bytes = next.bytes[1..],
            8 => figure.table_containing_direction.?.source = try a.dupe(u8, F.source),
            9 => figure.table_containing_direction = null,
            else => unreachable,
        }
        try std.testing.expect(unchangedTableSourceProjection(figure, old, next, &copy) == null);
    }
    const detached = try a.dupe(u8, F.source);
    bound.accepted = 0;
    const refused = try F.compile(a, codes, detached, &.{ .full_output = detached, .items = &.{} });
    try std.testing.expectEqual(@as(usize, 0), bound.accepted);
    try std.testing.expect(refused.fallbacks.unresolved_table_style);
    var absent = codes; absent.figure_sizing = null;
    const refused_reference = try F.compile(a, absent, detached, null);
    try std.testing.expectEqualDeep(try F.decode(a, refused_reference), try F.decode(a, refused));
}


