test "actual AS bare language support retains full assamese body and binds both source POS roles" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = AssameseSupportFixture;
    const T = blobs.presentation_types;
    const codec = blobs.presentation_codec;
    // The fixture instantiates the three exact retained static template bodies;
    // the independent Reader below is the newly executed ordinary AS result.
    const saved = try std.json.parseFromSlice(struct { entries: []T.Entry }, a,
        @embedFile("testdata/as-source-pos/assamese-normal-reader01.json"), .{ .ignore_unknown_fields = true });
    defer saved.deinit();
    try std.testing.expectEqual(@as(usize, 1), saved.value.entries.len);
    const before = saved.value.entries[0];
    try std.testing.expectEqualStrings("assamese", before.title);
    try std.testing.expectEqualStrings("ইংৰাজী", before.language.?);
    try std.testing.expectEqualStrings("en", before.language_code);
    try std.testing.expectEqual(@as(usize, 0), before.organization.lexemes.len);
    try std.testing.expectEqualSlices(usize, &.{0, 1, 2}, before.organization.other_sections);
    try std.testing.expectEqual(@as(usize, 3), before.sections.len);
    const Resolver = struct {
        fn resolve(ctx: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            var owner = AssameseSupportFixture.resolve(ctx, name) orelse return null;
            if (std.mem.eql(u8, owner.code, "en")) owner.heading = "ইংৰাজী";
            return owner;
        }
    };
    var ns = try F.catalog(a, "as"); defer ns.deinit();
    var codes = F.codes(&ns); codes.resolve_fn = Resolver.resolve; codes.strong_fn = Resolver.resolve; codes.trusted_fn = Resolver.resolve;
    const owner: blob_format.LanguageMetadata = .{ .heading = "ইংৰাজী", .code = "en" };
    for ([_][2]bool{ .{false, false}, .{true, false}, .{false, true}, .{true, true} }) |providers| {
        codes.source_numbered_pos = providers;
        var page: PreparedPage = .{ .ns = .{ .id = 0, .kind = .language }, .title = "assamese" };
        try page.compileWithPhases(a, codes, F.expanded, F.raw, null, null, null, null);
        try std.testing.expectEqual(@as(usize, 1), page.records.items.len);
        const result = try codec.decodeAlloc(a, page.records.items[0].payload, "assamese", .language, owner);
        const expected_count: usize = @intFromBool(providers[0]) + @as(usize, @intFromBool(providers[1]));
        try std.testing.expectEqual(expected_count, result.entry.organization.lexemes.len);
        var lexeme_index: usize = 0;
        for (providers, 0..) |present, role| if (present) {
            const lexeme = result.entry.organization.lexemes[lexeme_index]; lexeme_index += 1;
            try std.testing.expectEqualStrings(if (role == 0) "Noun" else "Adjective", lexeme.kind);
            try std.testing.expectEqualStrings("ইংৰাজী", lexeme.language);
            try std.testing.expectEqual(role + 1, lexeme.section);
            try std.testing.expectEqual(@as(usize, 1), lexeme.definitions.len);
            try std.testing.expectEqual(@as(usize, 1), lexeme.definitions[0].block);
            const definition = result.entry.sections[role + 1].blocks[1];
            try std.testing.expectEqualStrings(":#", definition.list_path);
            try std.testing.expectEqualStrings("অসমীয়া ", definition.spans[0].text);
            try std.testing.expectEqualStrings("অসমীয়া", definition.spans[0].target);
        };
        var expected_other: [3]usize = undefined; var other_count: usize = 1; expected_other[0] = 0;
        for (providers, 0..) |present, role| if (!present) { expected_other[other_count] = role + 1; other_count += 1; };
        try std.testing.expectEqualSlices(usize, expected_other[0..other_count], result.entry.organization.other_sections);
        var restored = result.entry; restored.organization = before.organization;
        try std.testing.expectEqualDeep(before, restored);
        const encoded = try codec.encodeAlloc(a, result);
        try std.testing.expectEqualDeep(result, try codec.decodeAlloc(a, encoded, "assamese", .language, owner));
        try std.testing.expectEqualSlices(u8, page.records.items[0].payload, encoded);
    }
}


test "source banner partition requires complete ordered physical pairs and refuses unknown or tainted regions" {
    const raw_source = "{{-eo-}}\n# first\n{{-es-}}\n# second";
    const source = "== ''[[EO]]'' ==\n# first\n== ''[[ES]]'' ==\n# second";
    const raw_second = std.mem.indexOf(u8, raw_source, "{{-es-}}").?;
    const second = std.mem.indexOf(u8, source, "== ''[[ES]]'' ==").?;
    const Resolver = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "eo")) return .{ .code = "eo", .heading = "Esperanto" };
            if (std.mem.eql(u8, name, "es")) return .{ .code = "es", .heading = "Spanish" };
            return null;
        }
        fn matches(_: ?*const anyopaque, code: []const u8, heading: []const u8, level: u8) bool {
            return level == 2 and ((std.mem.eql(u8, code, "eo") and std.mem.eql(u8, heading, "''[[EO]]''")) or
                (std.mem.eql(u8, code, "es") and std.mem.eql(u8, heading, "''[[ES]]''")));
        }
    };
    const codes: LanguageCodes = .{ .resolve_fn = Resolver.resolve, .source_banner_fn = Resolver.matches };
    var raw = [_]language_source.Section{
        .{ .heading = "eo", .source = raw_source[0..raw_second], .hyphen_marker = true },
        .{ .heading = "es", .source = raw_source[raw_second..], .hyphen_marker = true },
    };
    var rendered = [_]language_source.Section{
        .{ .heading = "''[[EO]]''", .source = source[0..second] },
        .{ .heading = "''[[ES]]''", .source = source[second..] },
    };
    const tracked = MissingText.untracked(source);
    try std.testing.expect(sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered));
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, raw[0..1], &rendered));
    const saved = raw[0]; raw[0] = raw[1];
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered)); raw[0] = saved;
    raw[0].heading = "iu";
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered)); raw[0] = saved;
    raw[0].hyphen_marker = false;
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered)); raw[0] = saved;
    const previous = rendered[1]; rendered[1] = rendered[0];
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered)); rendered[1] = previous;
    rendered[1].source = rendered[1].source[0 .. rendered[1].source.len - 1];
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered)); rendered[1] = previous;
    var missing = tracked; missing.unknown = true;
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, missing, &raw, &rendered));
    missing = tracked; missing.lost_missing_range = true;
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, missing, &raw, &rendered));
    missing = tracked; missing.ranges = &.{.{ .start = @intCast(second), .end = @intCast(second + 1), .occurrence = 1 }};
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, missing, &raw, &rendered));
    missing = tracked; missing.literal_curly_ranges = &.{.{ .start = 1, .end = 2 }};
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, missing, &raw, &rendered));
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const copied = try a.dupe(u8, source);
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, MissingText.untracked(copied), &raw, &rendered));
    const copied_raw = try a.dupe(u8, raw_source);
    try std.testing.expect(!sourceBannerPartition(codes, copied_raw, tracked, &raw, &rendered));
    var absent = codes; absent.source_banner_fn = null;
    try std.testing.expect(!sourceBannerPartition(absent, raw_source, tracked, &raw, &rendered));
    try std.testing.expect(sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered));
}


test "source banner boundary keeps a conflicting first region unknown without borrowing a later owner" {
    const raw_source = "{{-iu-}}\n# first\n{{-fr-}}\n# second";
    const source = "== ''[[CONFLICT]]'' ==\n# first\n== ''[[French]]'' ==\n# second";
    const raw_cut = std.mem.indexOf(u8, raw_source, "{{-fr-}}").?;
    const cut = std.mem.indexOf(u8, source, "== ''[[French]]'' ==").?;
    const Resolver = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "iu")) return .{ .code = "iu", .heading = "Inuktitut" };
            if (std.mem.eql(u8, name, "fr") or std.mem.eql(u8, name, "French")) return .{ .code = "fr", .heading = "French" };
            if (std.mem.eql(u8, name, "CONFLICT")) return .{ .code = "ike-cans", .heading = "CONFLICT" };
            return null;
        }
        fn owner(_: ?*const anyopaque, code: []const u8, heading: []const u8, level: u8) bool {
            return level == 2 and std.mem.eql(u8, code, "fr") and std.mem.eql(u8, heading, "''[[French]]''");
        }
        fn boundary(_: ?*const anyopaque, code: []const u8, heading: []const u8, level: u8) bool {
            return level == 2 and std.mem.eql(u8, code, "iu") and std.mem.eql(u8, heading, "''[[CONFLICT]]''");
        }
    };
    var codes: LanguageCodes = .{ .resolve_fn = Resolver.resolve, .source_banner_fn = Resolver.owner, .source_banner_boundary_fn = Resolver.boundary };
    const raw = [_]language_source.Section{ .{ .heading = "iu", .source = raw_source[0..raw_cut], .hyphen_marker = true }, .{ .heading = "fr", .source = raw_source[raw_cut..], .hyphen_marker = true } };
    var rendered = [_]language_source.Section{ .{ .heading = "''[[CONFLICT]]''", .source = source[0..cut] }, .{ .heading = "''[[French]]''", .source = source[cut..] } };
    const tracked = MissingText.untracked(source);
    try std.testing.expect(sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered));
    try std.testing.expect(sourceBannerBoundaryOnly(codes, raw[0], rendered[0]));
    try std.testing.expect(!sourceBannerBoundaryOnly(codes, raw[1], rendered[1]));
    codes.source_banner_boundary_fn = null;
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered));
    codes.source_banner_boundary_fn = Resolver.boundary;
    const saved = rendered[0]; rendered[0] = rendered[1];
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered)); rendered[0] = saved;
    var tainted = tracked; tainted.unknown = true;
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tainted, &raw, &rendered));
    tainted = tracked; tainted.ranges = &.{.{ .start = 1, .end = 2, .occurrence = 1 }};
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tainted, &raw, &rendered));
    try std.testing.expect(sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered));
}


test "literal H1 banner partition retains exact category BR prefix and refuses emitted or tainted prefixes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var ns = try @import("namespace_registry").Registry.init(a, "# wikidict-namespace-registry-v1\n# wiki\tenwiktionary\n# dump-date\t20261001\n# content-language\ten\n0\t\t\tcase-sensitive\t0\t1\t0\twikitext\tmain\tentries\n10\tTemplate\tTemplate\tcase-sensitive\t1\t0\t0\twikitext\tcompile_only\tinput\n14\tCategory\tCategory\tcase-sensitive\t0\t0\t0\twikitext\tcompile_only\tcategories\n"); defer ns.deinit();
    const Resolver = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "es")) return .{ .code = "es", .heading = "Spanish" };
            if (std.mem.eql(u8, name, "pt")) return .{ .code = "pt", .heading = "Portuguese" };
            return null;
        }
        fn matches(_: ?*const anyopaque, code: []const u8, heading: []const u8, level: u8) bool {
            return level == 1 and ((std.mem.eql(u8, code, "es") and std.mem.eql(u8, heading, "ES")) or
                (std.mem.eql(u8, code, "pt") and std.mem.eql(u8, heading, "PT")));
        }
    };
    const codes: LanguageCodes = .{ .namespace_catalog = &ns, .resolve_fn = Resolver.resolve, .source_banner_fn = Resolver.matches };
    const raw = "{{-es-}}\nfirst\n{{-pt-}}\nsecond";
    const raw_cut = std.mem.indexOf(u8, raw, "{{-pt-}}").?;
    const authored = [_]language_source.Section{ .{ .heading = "es", .source = raw[0..raw_cut], .hyphen_marker = true }, .{ .heading = "pt", .source = raw[raw_cut..], .hyphen_marker = true } };
    const good = "[[Category:ES]]__NOEDITSECTION__\n<br>\n";
    for ([_]struct { prefix: []const u8, accepted: bool }{
        .{ .prefix = good, .accepted = true },
        .{ .prefix = "", .accepted = true },
        .{ .prefix = "__NOEDITSECTION__\n", .accepted = true },
        .{ .prefix = "[[Category:ES]]__NOEDITSECTION__\n<br>visible\n", .accepted = false },
        .{ .prefix = "[[:Category:ES]]__NOEDITSECTION__\n<br>\n", .accepted = false },
        .{ .prefix = "[[Unknown:ES]]__NOEDITSECTION__\n<br>\n", .accepted = false },
        .{ .prefix = "[[Category:ES|sort]]__NOEDITSECTION__\n<br>\n", .accepted = false },
        .{ .prefix = "[[Category:ES]]__TOC__\n<br>\n", .accepted = false },
        .{ .prefix = "[[Category:ES]]__NOEDITSECTION__\n<br style=\"display:none\">\n", .accepted = false },
        .{ .prefix = "[[Category:ES]]__NOEDITSECTION__\n<br><br>\n", .accepted = false },
        .{ .prefix = "<div>\n", .accepted = false },
        .{ .prefix = "<ref>\n", .accepted = false },
        .{ .prefix = "{{outer|\n", .accepted = false },
    }) |case| {
        const source = try std.mem.concat(a, u8, &.{case.prefix, "=ES=\nfirst\n=PT=\nsecond"});
        const cut = std.mem.indexOf(u8, source, "=PT=").?;
        const rendered = [_]language_source.Section{ .{ .heading = "ES", .source = source[case.prefix.len..cut] }, .{ .heading = "PT", .source = source[cut..] } };
        const tracked = MissingText.untracked(source);
        try std.testing.expectEqual(case.accepted, sourceBannerPartition(codes, raw, tracked, &authored, &rendered));
        try std.testing.expectEqual(case.accepted and std.mem.startsWith(u8, case.prefix, "[["), sourceBannerRetainsBreak(codes, sourceBannerPartition(codes, raw, tracked, &authored, &rendered), case.prefix));
        try std.testing.expect(!sourceBannerRetainsBreak(codes, false, case.prefix));
        if (case.accepted and case.prefix.len != 0) {
            var tainted = tracked; tainted.ranges = &.{.{ .start = 0, .end = 1, .occurrence = 1 }};
            try std.testing.expect(!sourceBannerPartition(codes, raw, tainted, &authored, &rendered));
            try std.testing.expect(!sourceBannerRetainsBreak(codes, sourceBannerPartition(codes, raw, tainted, &authored, &rendered), case.prefix));
            tainted = tracked; tainted.literal_curly_ranges = &.{.{ .start = 0, .end = 1 }};
            try std.testing.expect(!sourceBannerPartition(codes, raw, tainted, &authored, &rendered));
            try std.testing.expect(!sourceBannerRetainsBreak(codes, sourceBannerPartition(codes, raw, tainted, &authored, &rendered), case.prefix));
            var absent = codes; absent.namespace_catalog = null;
            if (std.mem.startsWith(u8, case.prefix, "[[")) try std.testing.expect(!sourceBannerPartition(absent, raw, tracked, &authored, &rendered));
        }
    }
}

test "ordinary whole-page Writer preserves estoire's planned citation and later Greek link" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, @embedFile("testdata/zh-gugli176/namespace-registry.tsv"));
    defer ns.deinit();
    try ns.attachLanguageConversion(@embedFile("testdata/zh-gugli176/namespace-siteinfo.raw.json"));
    ns.manual_conversion_context = try std.json.parseFromSliceLeaky(NS.ManualConversionContext, a,
        @embedFile("testdata/zh-nested-attributes229/manual-context.json"), .{ .allocate = .alloc_always, .duplicate_field_behavior = .@"error" });
    var behavior = try NS.behavior_switches.Registry.init(a, @embedFile("testdata/zh-piasu381-pitch/behavior-switches.tsv"),
        ns.wiki, ns.dump_date, ns.content_language, ns.source_sha256);
    defer behavior.deinit();

    // Exercise the whole-page ownership fallback with an unresolved heading.
    // Language resolution is independent of the page's existing citation plan.
    const codes: LanguageCodes = .{ .namespace_catalog = &ns, .behavior_switches = &behavior };
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/estoire", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    const raw = @embedFile("testdata/zh-estoire383/whole.raw.wikitext");
    const expanded = @embedFile("testdata/zh-estoire383/whole.expanded.wikitext");
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "estoire", expanded, raw, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);

    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "Unclassified"));
    defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    const record = (try index.find("estoire")) orelse return error.TestUnexpectedResult;
    const stored = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
    try std.testing.expectEqualSlices(u8, record.payload, try blobs.presentation_codec.encodeAlloc(a, stored));
    try std.testing.expectEqualStrings("", stored.entry.language_code);
    try std.testing.expectEqual(@as(usize, 1), stored.entry.references.len);
    const note = stored.entry.references[0];
    try std.testing.expect(note.kind == .note and note.number == 1);
    const page_url = "https://www.google.ca/books/edition/%C3%89tude_sur_l_r_fran%C3%A7ais/0wkTAAAAYAAJ?hl=en&gbpv=1&pg=PA22";
    var cited_page = false;
    var note_text: std.ArrayList(u8) = .empty;
    for (note.spans) |span| {
        try note_text.appendSlice(a, span.text);
        if (std.mem.eql(u8, span.target, page_url)) cited_page = true;
    }
    try std.testing.expect(cited_page and std.mem.indexOf(u8, note_text.items, "Euren, S. F.") != null);

    var markers: usize = 0;
    var greek_actions: usize = 0;
    var history = false;
    var story = false;
    for (stored.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
        const target = if (span.target_fragment) |fragment|
            try std.mem.concat(a, u8, &.{ span.target, "#", fragment }) else span.target;
        if (std.mem.eql(u8, target, "#reference-1")) {
            try std.testing.expect(span.kind == .link and span.role == .reference and span.superscript);
            try std.testing.expectEqualStrings("[1]", span.text);
            markers += 1;
        }
        if (std.mem.eql(u8, target, "στολή#古希臘語")) {
            try std.testing.expectEqual(@as(usize, 1), markers);
            try std.testing.expectEqualStrings("στολή", span.text);
            try std.testing.expectEqualStrings("grc", span.language);
            greek_actions += 1;
        }
        if (std.mem.eql(u8, target, "历史")) history = true;
        if (std.mem.eql(u8, target, "故事")) story = true;
    };
    try std.testing.expect(history and story);
    try std.testing.expectEqual(@as(usize, 1), markers);
    try std.testing.expectEqual(@as(usize, 1), greek_actions);
}

test "source banner category prelude requires the exact first provider receipt and complete clean partition" {
    const raw_source = "{{-fr-}}\n# first\n{{-en-}}\n# second";
    const prefix = "[[category:French]]\n[[Category:French]]";
    const source = prefix ++ "\n== French (fr) ==\n# first\n== English (en) ==\n# second";
    const raw_cut = std.mem.indexOf(u8, raw_source, "{{-en-}}").?;
    const start = prefix.len + 1;
    const cut = std.mem.indexOf(u8, source, "== English").?;
    const Resolver = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "fr")) return .{ .code = "fr", .heading = "French" };
            if (std.mem.eql(u8, name, "en")) return .{ .code = "en", .heading = "English" };
            return null;
        }
        fn matches(_: ?*const anyopaque, code: []const u8, heading: []const u8, level: u8) bool {
            return level == 2 and ((std.mem.eql(u8, code, "fr") and std.mem.eql(u8, heading, "French (fr)")) or
                (std.mem.eql(u8, code, "en") and std.mem.eql(u8, heading, "English (en)")));
        }
        fn first(ctx: ?*const anyopaque, code: []const u8, heading: []const u8, level: u8, emitted: []const u8) bool {
            return matches(ctx, code, heading, level) and std.mem.eql(u8, code, "fr") and
                std.mem.eql(u8, emitted, "[[category:French]]\n[[Category:French]]");
        }
    };
    const codes: LanguageCodes = .{ .resolve_fn = Resolver.resolve, .source_banner_fn = Resolver.matches, .source_banner_prefix_fn = Resolver.first };
    var raw = [_]language_source.Section{
        .{ .heading = "fr", .source = raw_source[0..raw_cut], .hyphen_marker = true },
        .{ .heading = "en", .source = raw_source[raw_cut..], .hyphen_marker = true },
    };
    var rendered = [_]language_source.Section{
        .{ .heading = "French (fr)", .source = source[start..cut] },
        .{ .heading = "English (en)", .source = source[cut..] },
    };
    const tracked = MissingText.untracked(source);
    try std.testing.expect(sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered));
    var absent = codes; absent.source_banner_prefix_fn = null;
    try std.testing.expect(!sourceBannerPartition(absent, raw_source, tracked, &raw, &rendered));
    absent = codes; absent.source_banner_fn = null;
    try std.testing.expect(!sourceBannerPartition(absent, raw_source, tracked, &raw, &rendered));
    const saved_raw = raw[0]; raw[0] = raw[1];
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered)); raw[0] = saved_raw;
    const saved = rendered[1]; rendered[1].source = rendered[1].source[0 .. rendered[1].source.len - 1];
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, &raw, &rendered)); rendered[1] = saved;
    var missing = tracked; missing.unknown = true;
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, missing, &raw, &rendered));
    missing = tracked; missing.lost_missing_range = true;
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, missing, &raw, &rendered));
    missing = tracked; missing.ranges = &.{.{ .start = 2, .end = 3, .occurrence = 1 }};
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, missing, &raw, &rendered));
    missing = tracked; missing.literal_curly_ranges = &.{.{ .start = 2, .end = 3 }};
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, missing, &raw, &rendered));
    try std.testing.expect(!sourceBannerDeclaredPrelude(codes, raw[0], rendered[0], prefix ++ " visible"));
    try std.testing.expect(!sourceBannerDeclaredPrelude(codes, raw[0], rendered[0], "[[Category:English]]"));
    try std.testing.expect(!sourceBannerDeclaredPrelude(codes, raw[1], rendered[1], prefix));
    try std.testing.expect(!sourceBannerPartition(codes, raw_source, tracked, raw[0..1], rendered[0..1]));
    // Hidden categories alone do not invent a retained visible break or row.
    try std.testing.expect(!sourceBannerRetainsBreak(codes, true, prefix));
}

test "source static support veto affects only proved hyphen markers and leaves explicit language codes intact" {
    const Resolver = struct {
        fn resolve(_: ?*const anyopaque, name: []const u8) ?ResolvedLanguage {
            if (std.mem.eql(u8, name, "es")) return .{ .code = "es", .heading = "Spanish" };
            if (std.mem.eql(u8, name, "it")) return .{ .code = "it", .heading = "Italian" };
            if (std.mem.eql(u8, name, "num")) return .{ .code = "num", .heading = "Niuafo'ou" };
            return null;
        }
        fn support(_: ?*const anyopaque, name: []const u8) bool { return std.mem.eql(u8, name, "num"); }
    };
    const raw = "{{-es-}}\n{{-num-}}\n'''unu'''\n# [[un]]\n\n{{-it-}}\n{{-num-}}\n'''unu'''\n# [[un]]";
    const cut = std.mem.indexOf(u8, raw, "{{-it-}}").?;
    const codes: LanguageCodes = .{ .resolve_fn = Resolver.resolve, .source_static_support_fn = Resolver.support };
    const markers: LanguageMarkers = .{ .codes = &codes };
    var good = languageSections(raw, &markers);
    const first = good.next().?; const second = good.next().?;
    try std.testing.expectEqualStrings("es", first.heading);
    try std.testing.expectEqualStrings(raw[0..cut], first.source);
    try std.testing.expectEqualStrings("it", second.heading);
    try std.testing.expectEqualStrings(raw[cut..], second.source);
    try std.testing.expect(good.next() == null);
    var absent = codes; absent.source_static_support_fn = null;
    const incomplete: LanguageMarkers = .{ .codes = &absent };
    var bad = languageSections(raw, &incomplete); var count: usize = 0;
    while (bad.next()) |_| count += 1;
    try std.testing.expectEqual(@as(usize, 4), count);
    try std.testing.expectEqualStrings("num", codes.resolve("num").?.code);
    const explicit = "{{=num=}}\n# language";
    var equals = languageSections(explicit, &markers);
    const declared = equals.next().?;
    try std.testing.expectEqualStrings("num", declared.heading);
    try std.testing.expect(!declared.hyphen_marker and equals.next() == null);
}

test "Pa'O Kayan head declarations agree with their emitted POS owners" {
    const raw = "==ကယန်း(ပတောင်ႏ)==\n===နာမဝိသေသန===\n{{head|pdu|နာမဝိသေသန}}\n# မင်ႏဂလာႏကအဝ်ႏဒါႏ။";
    const expanded = "==ကယန်း(ပတောင်ႏ)==\n===နာမဝိသေသန===\n<span class=\"headword-line\"><strong class=\"Latn headword\" lang=\"pdu\">abataraò̌rî</strong></span>[[Category:ကယန်းငဝ်းတဲႏဖုံႏ|ABATARAÒ̌RÎ]]\n# မင်ႏဂလာႏကအဝ်ႏဒါႏ။";
